/**
 * Console Silencer
 *
 * Filters out noise from browser extensions (Grammarly, LastPass, etc.)
 * that frequently spam the console during React navigation. These errors
 * (like FrameDoesNotExistError) are external to our app logic and safe
 * to ignore.
 */

const IGNORED_PATTERNS = [
  'FrameDoesNotExistError',
  'message port closed',
  'Could not establish connection',
  'browsing-topics',
  'google.maps.Marker is deprecated',
];

export function initConsoleSilencer() {
  if (import.meta.env.PROD) return;

  const originalWarn = console.warn;
  const originalError = console.error;

  console.warn = (...args: any[]) => {
    const msg = args.map(String).join(' ');
    if (IGNORED_PATTERNS.some((p) => msg.includes(p))) return;
    originalWarn(...args);
  };

  console.error = (...args: any[]) => {
    const msg = args.map(String).join(' ');
    if (IGNORED_PATTERNS.some((p) => msg.includes(p))) return;
    originalError(...args);
  };

  // Catch unhandled rejections from extension background scripts
  window.addEventListener('unhandledrejection', (event) => {
    const msg = String(event.reason);
    if (IGNORED_PATTERNS.some((p) => msg.includes(p))) {
      event.stopImmediatePropagation();
      event.preventDefault();
    }
  });
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { RouterProvider } from 'react-router-dom';

import './index.css';
import 'leaflet/dist/leaflet.css';
import '@/shared/i18n';

import { Providers } from './providers';
import { router } from './router';
import { initConsoleSilencer } from './console-silencer';
import { prefetchAnimations } from '@/shared/lib/prefetch';

initConsoleSilencer();

// Safely prefetch all lottie animations & engine in the background
prefetchAnimations();

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error('Root element #root not found');
}

createRoot(rootElement).render(
  <StrictMode>
    <Providers>
      <RouterProvider router={router} />
    </Providers>
  </StrictMode>,
);

import * as React from 'react';
import { QueryClientProvider } from '@tanstack/react-query';
import { ThemeProvider } from 'next-themes';
import { queryClient } from '@/shared/api/query';
import { TooltipProvider } from '@/shared/ui/tooltip';
import { Toaster } from '@/shared/ui/toaster';
import { setLogoutHandler } from '@/shared/api/client';
import { useAuthStore, syncLegacyStorage } from '@/shared/auth/store';
import { STORAGE_KEYS } from '@/shared/config/constants';
import { prefetchAnimations } from '@/shared/lib/prefetch';

interface ProvidersProps {
  children: React.ReactNode;
}

export function Providers({ children }: ProvidersProps) {
  // Register the logout handler with the API client so 401s clear auth state
  React.useEffect(() => {
    setLogoutHandler(() => {
      useAuthStore.getState().clearSession();
      queryClient.clear();
      if (!window.location.pathname.includes('/login')) {
        window.location.href = '/login';
      }
    });
    // Mirror persisted auth into the legacy localStorage keys so the
    // axios interceptor finds the JWT under `jwt` on first request.
    syncLegacyStorage();
    useAuthStore.getState().markInitialized();
    prefetchAnimations();
  }, []);

  return (
    <ThemeProvider
      attribute="class"
      defaultTheme="system"
      enableSystem
      disableTransitionOnChange
      storageKey={STORAGE_KEYS.THEME}
    >
      <QueryClientProvider client={queryClient}>
        <TooltipProvider delayDuration={200}>
          {children}
          <Toaster />
        </TooltipProvider>
      </QueryClientProvider>
    </ThemeProvider>
  );
}

import * as React from 'react';
import { createBrowserRouter, Navigate, Outlet } from 'react-router-dom';
import { ProtectedRoute } from './protected-route';
import { Layout } from '@/widgets/layout/layout';
import LoginPage from '@/pages/auth/login';
import { Skeleton } from '@/shared/ui/skeleton';
import { PERMISSION_LEVELS } from '@/shared/config/constants';

/* -------------------------------------------------------------------------- */
/* Lazy loaders                                                                */
/*                                                                             */
/* Every page below `/` is code-split. The `lazyNamed` helper handles the     */
/* placeholder file's named-export shape — all eleven placeholder pages live  */
/* in one module so they share a single chunk, which is fine.                 */
/* -------------------------------------------------------------------------- */

const lazyNamed = <K extends string>(
  loader: () => Promise<Record<K, React.ComponentType>>,
  name: K,
) => React.lazy(() => loader().then((m) => ({ default: m[name] })));

// Default-exported pages
const DashboardPage = React.lazy(() => import('@/pages/dashboard/dashboard'));
const FuelEventsPage = React.lazy(() => import('@/pages/fuel-events/fuel-events'));
const FleetExpensesPage = React.lazy(
  () => import('@/pages/fleet-expenses/fleet-expenses'),
);
const FleetExpenseNewPage = React.lazy(
  () => import('@/pages/fleet-expenses/fleet-expense-new'),
);
const FleetExpenseEditPage = React.lazy(
  () => import('@/pages/fleet-expenses/fleet-expense-edit'),
);
const FleetExpensesMessagesPage = React.lazy(
  () => import('@/pages/fleet-expenses/fleet-expenses-messages'),
);
const FuelEventNewPage = React.lazy(() => import('@/pages/fuel-events/fuel-event-new'));
const FuelEventEditPage = React.lazy(() => import('@/pages/fuel-events/fuel-event-edit'));
const FuelEventDetailsPage = React.lazy(
  () => import('@/pages/fuel-events/fuel-event-details'),
);
const DriversListPage = React.lazy(() => import('@/pages/drivers/drivers'));
const CarsPage = React.lazy(() => import('@/pages/cars/cars'));
const DriverDetailPage = React.lazy(() => import('@/pages/driver-detail/driver-detail'));
const DriverExpensesPage = React.lazy(
  () => import('@/pages/driver-expenses/driver-expenses'),
);
const AddDriverExpensePage = React.lazy(
  () => import('@/pages/driver-expenses/driver-expense-new'),
);
const DriverLoansPage = React.lazy(() => import('@/pages/driver-loans/driver-loans'));
const AddDriverLoanPage = React.lazy(() => import('@/pages/driver-loans/driver-loan-new'));
const NotFoundPage = React.lazy(() => import('@/pages/error/not-found'));
const TripsPage = React.lazy(() => import('@/pages/trips/trips'));
const TripNewPage = React.lazy(() => import('@/pages/trips/trip-new'));
const TripEditPage = React.lazy(() => import('@/pages/trips/trip-edit'));
const RouteErrorPage = React.lazy(() => import('@/pages/error/route-error'));

const OilChangesPage = React.lazy(() => import('@/pages/oil-changes/oil-changes'));
const OilChangeNewPage = React.lazy(() => import('@/pages/oil-changes/oil-change-new'));
const OilChangeEditPage = React.lazy(() => import('@/pages/oil-changes/oil-change-edit'));
const OilChangeHistoryPage = React.lazy(
  () => import('@/pages/oil-changes/oil-change-history'),
);
const FeeMappingsPage = React.lazy(() => import('@/pages/fee-mappings/fee-mappings'));
const UsersPage = React.lazy(() => import('@/pages/users/users'));
const ServiceInvoicesPage = React.lazy(() => import('@/pages/service-invoices/service-invoices'));
const ServiceInvoiceNewPage = React.lazy(() => import('@/pages/service-invoices/service-invoice-new'));
const ServiceInvoiceEditPage = React.lazy(() => import('@/pages/service-invoices/service-invoice-edit'));
const ServiceInvoiceDetailsPage = React.lazy(() => import('@/pages/service-invoices/service-invoice-details'));

const TrackingPage = React.lazy(() => import('@/features/tracking/tracking-page'));
const ZonesPage = React.lazy(() => import('@/pages/zones/zones'));
const LocationsPage = React.lazy(() => import('@/pages/locations/locations'));
const TripAuditPage = React.lazy(() => import('@/pages/trip-audit/trip-audit'));
const TripReplayPage = React.lazy(() => import('@/pages/trip-replay/trip-replay'));

// Named exports — placeholder file. All resolve to the same chunk; the
// browser fetches it once and React picks the right component per route.
const placeholderLoader = () => import('@/pages/placeholder/placeholder');
const TrucksPage = lazyNamed(placeholderLoader, 'TrucksPage');
const TiresPage = lazyNamed(() => import('@/pages/tires/tires'), 'TiresPage');
const VendorsPage = lazyNamed(placeholderLoader, 'VendorsPage');
const LogsPage = lazyNamed(placeholderLoader, 'LogsPage');
const SettingsPage = React.lazy(() => import('@/pages/settings/settings'));
const TabletsPage = lazyNamed(placeholderLoader, 'TabletsPage');
const SpeedViolationsPage = lazyNamed(placeholderLoader, 'SpeedViolationsPage');


/* -------------------------------------------------------------------------- */
/* Suspense fallback                                                           */
/* -------------------------------------------------------------------------- */

/**
 * Lightweight skeleton shown while a route chunk is being fetched. Uses
 * the same outer paddings as `PageShell` so the layout doesn't reflow when
 * the real page mounts.
 */
function PageLoadingFallback() {
  return (
    <div className="flex flex-1 flex-col gap-6 p-4 md:p-6 lg:p-8">
      <div className="flex items-start justify-between gap-4">
        <div className="space-y-2">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-4 w-64" />
        </div>
        <Skeleton className="h-9 w-24" />
      </div>
      <Skeleton className="h-10 w-full max-w-md" />
      <div className="grid grid-cols-2 gap-2.5 md:grid-cols-4">
        {Array.from({ length: 4 }, (_, i) => (
          <Skeleton key={i} className="h-20" />
        ))}
      </div>
      <Skeleton className="h-96 w-full" />
    </div>
  );
}

/**
 * Layout-route element — wraps every authenticated page in a Suspense
 * boundary. We use a layout-route (not a wrapping element on Layout)
 * because the sidebar/header are inside <Layout /> and we don't want to
 * re-suspend them on every navigation.
 */
function SuspendedRoute() {
  return (
    <React.Suspense fallback={<PageLoadingFallback />}>
      <Outlet />
    </React.Suspense>
  );
}

/* -------------------------------------------------------------------------- */
/* Route definitions                                                           */
/* -------------------------------------------------------------------------- */

export const router = createBrowserRouter([
  {
    path: '/login',
    element: <LoginPage />,
    errorElement: <RouteErrorPage />,
  },
  {
    path: '/',
    element: (
      <ProtectedRoute>
        <Layout />
      </ProtectedRoute>
    ),
    errorElement: <RouteErrorPage />,
    children: [
      {
        element: <SuspendedRoute />,
        children: [
          { index: true, element: <DashboardPage /> },

          // Fuel events
          { path: 'fuel-events', element: <FuelEventsPage /> },
          {
            path: 'fuel-events/new',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <FuelEventNewPage />
              </ProtectedRoute>
            ),
          },
          { path: 'fuel-events/:id', element: <FuelEventDetailsPage /> },
          {
            path: 'fuel-events/:id/edit',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <FuelEventEditPage />
              </ProtectedRoute>
            ),
          },

          // Trips
          { path: 'trips', element: <TripsPage /> },
          { path: 'trips/new', element: <TripNewPage /> },
          { path: 'trips/multi-container/:parentId/edit', element: <TripEditPage /> },
          { path: 'trips/parent/:parentId/route-summary', element: <TrackingPage /> },

          // Oil changes
          { path: 'oil-changes', element: <OilChangesPage /> },
          { path: 'oil-changes/new', element: <OilChangeNewPage /> },
          { path: 'oil-changes/:id/edit', element: <OilChangeEditPage /> },
          { path: 'oil-changes/car/:carId', element: <OilChangeHistoryPage /> },

          // Service Invoices
          { path: 'service-invoices', element: <ServiceInvoicesPage /> },
          { path: 'service-invoices/new', element: <ServiceInvoiceNewPage /> },
          { path: 'service-invoices/:id', element: <ServiceInvoiceDetailsPage /> },
          { path: 'service-invoices/:id/edit', element: <ServiceInvoiceEditPage /> },

          // Placeholder domains
          { path: 'trucks', element: <TrucksPage /> },
          { path: 'cars', element: <CarsPage /> },
          {
            path: 'tires',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.ADMIN}>
                <TiresPage />
              </ProtectedRoute>
            ),
          },
          { path: 'tablets', element: <TabletsPage /> },
          { path: 'speed-violations', element: <SpeedViolationsPage /> },
          { path: 'drivers', element: <DriversListPage /> },
          { path: 'drivers/:id', element: <DriverDetailPage /> },
          { path: 'drivers/:id/expenses', element: <DriverExpensesPage /> },
          {
            path: 'drivers/:id/expenses/new',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <AddDriverExpensePage />
              </ProtectedRoute>
            ),
          },
          { path: 'drivers/:id/loans', element: <DriverLoansPage /> },
          {
            path: 'drivers/:id/loans/new',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <AddDriverLoanPage />
              </ProtectedRoute>
            ),
          },
          { path: 'vendors', element: <VendorsPage /> },
          // Fleet expenses — reads banksms.transactions; the legacy
          // fleet_expenses table is never touched.
          {
            path: 'fleet-expenses',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.ADMIN}>
                <FleetExpensesPage />
              </ProtectedRoute>
            ),
          },
          {
            path: 'fleet-expenses/messages',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.ADMIN}>
                <FleetExpensesMessagesPage />
              </ProtectedRoute>
            ),
          },
          // The old review queue is gone; keep its URL working.
          {
            path: 'fleet-expenses/review',
            element: <Navigate to="/fleet-expenses/messages" replace />,
          },
          {
            path: 'fleet-expenses/new',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.ADMIN}>
                <FleetExpenseNewPage />
              </ProtectedRoute>
            ),
          },
          {
            path: 'fleet-expenses/:id/edit',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.ADMIN}>
                <FleetExpenseEditPage />
              </ProtectedRoute>
            ),
          },
          {
            path: 'fee-mappings',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <FeeMappingsPage />
              </ProtectedRoute>
            ),
          },
          { path: 'etit', element: <TrackingPage /> },
          {
            path: 'zones',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <ZonesPage />
              </ProtectedRoute>
            ),
          },
          {
            path: 'locations',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <LocationsPage />
              </ProtectedRoute>
            ),
          },
          {
            path: 'trip-audit',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <TripAuditPage />
              </ProtectedRoute>
            ),
          },
          {
            // Full-screen replay takeover — deep-linkable.
            path: 'trip-audit/:id/replay',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <TripReplayPage />
              </ProtectedRoute>
            ),
          },
          {
            path: 'users',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.MANAGER}>
                <UsersPage />
              </ProtectedRoute>
            ),
          },
          {
            path: 'logs',
            element: (
              <ProtectedRoute minPermissionLevel={PERMISSION_LEVELS.ADMIN}>
                <LogsPage />
              </ProtectedRoute>
            ),
          },
          { path: 'settings', element: <SettingsPage /> },
        ],
      },
    ],
  },
  { path: '/404', element: <NotFoundPage /> },
  { path: '*', element: <Navigate to="/404" replace /> },
]);

import { useMutation } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { login } from './api';
import type { LoginInput } from './schemas';
import { useAuthStore } from '@/shared/auth/store';
import { queryClient } from '@/shared/api/query';
import { toast } from '@/shared/ui/toaster';
import { extractErrorMessage } from '@/shared/api/errors';

export function useLogin() {
  const setSession = useAuthStore((s) => s.setSession);
  const navigate = useNavigate();
  const { t } = useTranslation();

  return useMutation({
    mutationFn: (input: LoginInput) => login(input),
    onSuccess: (data, variables) => {
      setSession({
        token: data.jwt,
        user: {
          name: data.name ?? variables.email,
          email: variables.email,
          permission: data.permission,
        },
      });
      navigate('/', { replace: true });
    },
    onError: (error) => {
      toast.error(extractErrorMessage(error, t('auth.loginError')));
    },
  });
}

export function useLogout() {
  const clearSession = useAuthStore((s) => s.clearSession);
  const navigate = useNavigate();
  const { t } = useTranslation();

  return () => {
    // Deferred by a tick on purpose.
    //
    // This runs from inside a dropdown item's click handler. Clearing the
    // session makes UserMenu render null, which unmounts the still-open Radix
    // menu mid-event, and the navigate then unmounts the whole layout — and on
    // mobile the open drawer with it. Tearing down a Radix portal from inside
    // its own event is the classic source of "Failed to execute 'removeChild'
    // on 'Node'", which is what was crashing the sidebar on a phone.
    //
    // Yielding first lets the menu close and release its portal before any of
    // this happens.
    setTimeout(() => {
      clearSession();
      queryClient.clear();
      toast.success(t('auth.loggedOut'));
      navigate('/login', { replace: true });
    }, 0);
  };
}

import { apiGet, apiPost, apiClient } from '@/shared/api/client';
import {
  carsResponseSchema,
  paginatedCarsResponseSchema,
  type Car,
  type CarFormValues
} from './schemas';

export async function getCars(): Promise<Car[]>;
export async function getCars(page: number, limit: number): Promise<{ data: Car[]; pagination: any }>;
export async function getCars(page?: number, limit?: number): Promise<any> {
  const isPaginated = page !== undefined && limit !== undefined;
  const url = isPaginated
    ? `/api/cars?page=${page}&limit=${limit}`
    : '/api/cars';

  const data = await apiGet<unknown>(url);

  if (isPaginated) {
    return paginatedCarsResponseSchema.parse(data);
  }

  // Backwards compatibility: ensure we return a flat array
  const array = Array.isArray(data) ? data : (data as { data?: unknown })?.data;
  return carsResponseSchema.parse(array ?? []);
}

export async function createCar(data: CarFormValues): Promise<Car> {
  return apiPost<Car>('/api/cars/', data);
}

export async function updateCar(id: number, data: Partial<CarFormValues>): Promise<Car> {
  const formData = new FormData();
  formData.append('request', JSON.stringify({ ID: id, ...data }));

  const response = await apiClient.put<Car>(`/api/cars/${id}`, formData, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  });
  return response.data;
}

export async function setCarDriver(carId: number, driverId: number): Promise<void> {
  await apiClient.patch('/api/protected/SetCarDriverPair', {
    car_id: carId,
    driver_id: driverId,
  });
}

import { useInfiniteQuery, useQuery, type QueryClient } from '@tanstack/react-query';
import { currentScopeSlice } from '@/shared/scope';
import { dashboardApi, etitApi, type DashboardScope } from './api';
import type {
  FuelDrawer,
  AdvancesDrawer,
  CashOutDrawer,
  RevenueDrawer,
  TripsDrawer,
} from './schemas';

/** What any drawer can hold — the component narrows by `kind`. */
export type DrawerData = RevenueDrawer | CashOutDrawer | TripsDrawer | AdvancesDrawer | FuelDrawer;

/* -------------------------------------------------------------------------- */
/* Keys                                                                        */
/*                                                                            */
/* Exported because the prefetchers must warm EXACTLY these keys — a prefetch  */
/* against a near-miss key is a wasted request that the page refetches anyway. */
/* -------------------------------------------------------------------------- */

function scopeKeyOf(scope?: DashboardScope): string {
  if (!scope) return 'current';
  return `${scope.from ?? ''}..${scope.to ?? ''}@${scope.company ?? 'all'}`;
}

export const dashboardKeys = {
  all: ['dashboard'] as const,
  main: (scope?: DashboardScope) => [...dashboardKeys.all, 'main', scopeKeyOf(scope)] as const,
  drawer: (kind: string, scope?: DashboardScope) =>
    [...dashboardKeys.all, 'drawer', kind, scopeKeyOf(scope)] as const,
  truckDay: (vehicleId: string, date: string) =>
    [...dashboardKeys.all, 'truck', vehicleId, date] as const,
};

/**
 * The scope a bare navigation to `/` mounts with: dates from the global URL
 * scope (the header bar), company from `?co=`. Warmers without a scope in
 * hand (the sidebar) call this — it is exactly what the page will read.
 */
export function currentDashboardScope(): DashboardScope {
  const { range } = currentScopeSlice();
  const co =
    typeof window !== 'undefined'
      ? new URLSearchParams(window.location.search).get('co')
      : null;
  return { from: range.from, to: range.to, company: co || null };
}

/* ─── The one payload that paints the page ─── */

export function useDashboard(scope?: DashboardScope) {
  return useQuery({
    queryKey: dashboardKeys.main(scope),
    queryFn: () => dashboardApi.get(scope),
    staleTime: 30_000,
  });
}

/* ─── Drawers — fetched when a card opens, or warmed on hover ─── */

const DRAWER_FETCHERS: Record<string, (scope?: DashboardScope) => Promise<DrawerData>> = {
  revenue: (scope?: DashboardScope) => dashboardApi.revenue(scope),
  'cash-out': (scope?: DashboardScope) => dashboardApi.cashOut(scope),
  trips: (scope?: DashboardScope) => dashboardApi.trips(scope),
  advances: () => dashboardApi.advances(),
  fuel: (scope?: DashboardScope) => dashboardApi.fuel(scope),
};
export type DrawerKind = 'revenue' | 'cash-out' | 'trips' | 'advances' | 'fuel';

export function useDrawer(kind: DrawerKind, scope: DashboardScope | undefined, enabled: boolean) {
  return useQuery({
    queryKey: dashboardKeys.drawer(kind, scope),
    queryFn: () => DRAWER_FETCHERS[kind](scope),
    staleTime: 60_000,
    enabled,
  });
}

/// The dashboard's infinite fuel list: pages of the window's events,
/// flattened by the panel as the user scrolls.
export function useInfiniteFuelEvents(scope: DashboardScope | undefined, enabled: boolean) {
  return useInfiniteQuery({
    queryKey: [...dashboardKeys.all, 'fuel-events', scopeKeyOf(scope)] as const,
    queryFn: ({ pageParam }) => dashboardApi.fuelEvents(scope, pageParam, 15),
    initialPageParam: 1,
    getNextPageParam: (last) =>
      last.page * last.limit < last.total ? last.page + 1 : undefined,
    staleTime: 30_000,
    enabled,
  });
}

export function useTruckDay(vehicleId: string | null, date: string) {
  return useQuery({
    queryKey: dashboardKeys.truckDay(vehicleId ?? 'none', date),
    queryFn: () => etitApi.daySummary(vehicleId!, date),
    staleTime: 60_000,
    enabled: vehicleId !== null,
    retry: 1,
  });
}

/* -------------------------------------------------------------------------- */
/* Optimistic prefetch                                                         */
/*                                                                            */
/* The Madar pattern: warm on INTENT (hover / focus / touchstart), against the */
/* exact key the component will read, so opening renders from cache instead of */
/* showing a spinner. prefetchQuery dedupes in-flight requests and respects    */
/* staleTime, so calling these repeatedly costs nothing. Callers without a     */
/* scope in hand (the sidebar) omit it and get the current URL's scope.        */
/* -------------------------------------------------------------------------- */

export function prefetchDashboard(qc: QueryClient, scope?: DashboardScope): void {
  const s = scope ?? currentDashboardScope();
  void qc.prefetchQuery({
    queryKey: dashboardKeys.main(s),
    queryFn: () => dashboardApi.get(s),
    staleTime: 30_000,
  });
}

export function prefetchDrawer(qc: QueryClient, kind: DrawerKind, scope?: DashboardScope): void {
  const s = scope ?? currentDashboardScope();
  void qc.prefetchQuery({
    queryKey: dashboardKeys.drawer(kind, s),
    queryFn: () => DRAWER_FETCHERS[kind](s),
    staleTime: 60_000,
  });
}

export function prefetchTruckDay(qc: QueryClient, vehicleId: string, date: string): void {
  void qc.prefetchQuery({
    queryKey: dashboardKeys.truckDay(vehicleId, date),
    queryFn: () => etitApi.daySummary(vehicleId, date),
    staleTime: 60_000,
    retry: 1,
  });
}

import { apiGet, apiPost, apiClient } from '@/shared/api/client';
import {
  driversResponseSchema,
  driverSchema,
  type Driver,
  type RegisterDriverPayload,
  type UpdateDriverPayload,
  type UpdateDriverDocumentsPayload,
} from './schemas';

/* ─── List all drivers (simple — used by fuel-event form dropdown too) ─── */
export async function getDrivers(): Promise<Driver[]> {
  const data = await apiGet<unknown>('/api/drivers');
  const array = Array.isArray(data) ? data : (data as { data?: unknown })?.data;
  return driversResponseSchema.parse(array ?? []);
}

/* ─── List drivers with full profile data ─── */
export async function getDriverProfiles(): Promise<Driver[]> {
  const data = await apiPost<unknown>('/api/GetDriverProfileData', {});
  const array = Array.isArray(data) ? data : (data as { data?: unknown })?.data;
  return driversResponseSchema.parse(array ?? []);
}

/* ─── Get single driver ─── */
export async function getDriver(id: number | string): Promise<Driver> {
  const fd = new FormData();
  fd.append('id', String(id));
  const res = await apiClient.post('/api/GetDriver', fd);
  return driverSchema.parse(res.data);
}

/* ─── Register (create) driver ─── */
export async function registerDriver(payload: RegisterDriverPayload): Promise<void> {
  const fd = new FormData();
  fd.append('request', JSON.stringify(payload));
  await apiClient.post('/api/protected/RegisterDriver', fd, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
}

/* ─── Update driver basic info ─── */
export async function updateDriver(payload: UpdateDriverPayload): Promise<void> {
  const fd = new FormData();
  fd.append('request', JSON.stringify(payload));
  await apiClient.post('/api/protected/UpdateDriver', fd, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
}

/* ─── Update driver documents (dates + images) ─── */
export async function updateDriverDocuments(
  id: number,
  payload: UpdateDriverDocumentsPayload,
  files: Record<string, File>,
): Promise<void> {
  const fd = new FormData();
  fd.append('request', JSON.stringify(payload));
  Object.entries(files).forEach(([key, file]) => {
    if (file) fd.append(key, file);
  });
  await apiClient.put(`/api/drivers/${id}`, fd, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
}

/* ─── Delete driver ─── */
export async function deleteDriver(id: number): Promise<void> {
  // The legacy POST /api/DeleteDriver RPC no longer exists in FalconGo;
  // DELETE /api/drivers/:id is the surviving route.
  await apiClient.delete(`/api/drivers/${id}`);
}

/* ─── Approve / Reject ─── */
export async function approveDriver(id: number): Promise<void> {
  await apiPost<unknown>('/api/ApproveRequest', {
    TableName: 'users',
    ColumnIdName: 'id',
    Id: id,
  });
}

export async function rejectDriver(id: number): Promise<void> {
  await apiPost<unknown>('/api/RejectRequest', {
    TableName: 'users',
    ColumnIdName: 'id',
    Id: id,
  });
}

/* ─── Regenerate PIN ─── */
export interface RegeneratePinResponse {
  success: boolean;
  data: { pin: string; message?: string };
}

export async function regeneratePin(id: number): Promise<RegeneratePinResponse> {
  const res = await apiClient.put(`/api/drivers/${id}/regenerate-pin`);
  return res.data as RegeneratePinResponse;
}

/* ─── Download document image (blob) ─── */
export async function getDocumentImage(path: string): Promise<string> {
  const res = await apiClient.get(path, { responseType: 'blob' });
  return URL.createObjectURL(res.data as Blob);
}

