/* Intent prefetch                                                             */
/* Warmed on hover/focus/touch by surfaces that know the click is coming.      */
/* MUST mirror the hook above key-for-key — a near-miss key is a wasted        */
/* request the page refetches anyway.                                          */
/* -------------------------------------------------------------------------- */

export function prefetchDrivers(qc: QueryClient): void {
  // The drivers page (and useDriver, which derives from it) reads the
  // PROFILES key, not the plain list — warm what is actually read.
  void qc.prefetchQuery({
    queryKey: [...QUERY_KEYS.drivers, 'profiles'],
    queryFn: getDriverProfiles,
    staleTime: 5 * 60_000,
  });
}

/** Forms' dropdown list — the plain `['drivers']` key useDrivers() reads. */
export function prefetchDriversList(qc: QueryClient): void {
  void qc.prefetchQuery({
    queryKey: QUERY_KEYS.drivers,
    queryFn: getDrivers,
    staleTime: 5 * 60_000,
  });
}

export function prefetchDriver(qc: QueryClient, _id?: number | string): void {
  // useDriver(id) reads the profiles cache — there is no per-id query to warm.
  prefetchDrivers(qc);
}

import { z } from 'zod';
import { apiClient, apiClientEtit } from '@/shared/api/client';
import {
  locationsInboxSchema,
  parseDropOffsPage,
  pinSuggestionSchema,
  receiptPatternSchema,
  resolveTerminalResponseSchema,
  terminalSchema,
  type DropOffsPage,
  type LocationsInbox,
  type PinSuggestion,
  type ReceiptPattern,
  type ResolveTerminalPayload,
  type ResolveTerminalResponse,
  type SuggestionAckStatus,
  type Terminal,
  type UpdateDropoffPayload,
  type UpdateTerminalPayload,
  type UpsertReceiptPatternPayload,
} from './schemas';

/**
 * Locations live on FalconGo (same base + auth as fee-mappings — the JWT
 * interceptor on `apiClient` covers the Verify(3) requirement for writes).
 * The GPS pin suggestions live on the etit proxy (`apiClientEtit`), same
 * base as the zones entity.
 *
 * Terminals moved to the new picked-by-id endpoints under `/api/terminals`
 * (per-company allowlists + receipt patterns); pin/radius/address edits stay
 * on the older `/api/locations/terminals/:id` endpoint.
 */

const BASE = '/api/locations';
const TERMINALS_BASE = '/api/terminals';
const ETIT_PREFIX = 'api/v1/trip-audit';

/* ---- Envelopes ----------------------------------------------------------- */

/** The backend sometimes wraps lists in `{ data: [...] }` — accept both. */
function unwrapList(payload: unknown): unknown[] {
  if (Array.isArray(payload)) return payload;
  if (payload && typeof payload === 'object') {
    const data = (payload as { data?: unknown }).data;
    if (Array.isArray(data)) return data;
  }
  return [];
}

/* ---- FalconGo: inbox ------------------------------------------------------ */

async function getInbox(): Promise<LocationsInbox> {
  const res = await apiClient.get(`${BASE}/inbox`);
  return locationsInboxSchema.parse(res.data);
}

/* ---- FalconGo: terminals -------------------------------------------------- */

/**
 * List terminals. With `company`, returns the terminals allowed for that
 * company (each with its resolved `receipt_pattern`); without, returns all
 * terminals with their `allowed_companies`.
 */
async function listTerminals(company?: string): Promise<Terminal[]> {
  const qs = company?.trim() ? `?company=${encodeURIComponent(company.trim())}` : '';
  const res = await apiClient.get(`${TERMINALS_BASE}${qs}`);
  return z.array(terminalSchema).parse(unwrapList(res.data));
}

/**
 * Resolve-or-create-or-extend: if a terminal with this name exists, `company`
 * is added to its allowlist (`created: false, extended: true`); otherwise a
 * new pinless terminal is created (`created: true`).
 */
async function resolveTerminal(
  payload: ResolveTerminalPayload,
): Promise<ResolveTerminalResponse> {
  const res = await apiClient.post(TERMINALS_BASE, payload);
  return resolveTerminalResponseSchema.parse(res.data);
}

async function updateTerminal(id: number, payload: UpdateTerminalPayload): Promise<void> {
  await apiClient.put(`${BASE}/terminals/${encodeURIComponent(id)}`, payload);
}

/* ---- FalconGo: receipt patterns ------------------------------------------- */

async function listReceiptPatterns(terminalId: number): Promise<ReceiptPattern[]> {
  const res = await apiClient.get(
    `${TERMINALS_BASE}/${encodeURIComponent(terminalId)}/receipt-patterns`,
  );
  return z.array(receiptPatternSchema).parse(unwrapList(res.data));
}

/** Upsert keyed on (terminal, company) — empty company = "all companies". */
async function upsertReceiptPattern(
  terminalId: number,
  payload: UpsertReceiptPatternPayload,
): Promise<void> {
  await apiClient.put(
    `${TERMINALS_BASE}/${encodeURIComponent(terminalId)}/receipt-patterns`,
    payload,
  );
}

async function deleteReceiptPattern(terminalId: number, company: string): Promise<void> {
  await apiClient.delete(
    `${TERMINALS_BASE}/${encodeURIComponent(terminalId)}/receipt-patterns?company=${encodeURIComponent(company)}`,
  );
}

/* ---- FalconGo: drop-off points -------------------------------------------- */

export interface DropoffFilters {
  q?: string;
  missing?: boolean;
  /** 1-based page. */
  page?: number;
  per_page?: number;
}

/**
 * Paginated drop-off list — `{ items, total, page, per_page }`. Creation no
 * longer has a standalone endpoint: drop-off points are created implicitly
 * when a fee mapping references a new name.
 */
async function listDropoffs(filters: DropoffFilters = {}): Promise<DropOffsPage> {
  const params = new URLSearchParams();
  if (filters.q?.trim()) params.set('q', filters.q.trim());
  if (filters.missing) params.set('missing', 'true');
  if (filters.page != null) params.set('page', String(filters.page));
  if (filters.per_page != null) params.set('per_page', String(filters.per_page));
  const qs = params.toString();
  const res = await apiClient.get(`${BASE}/dropoffs${qs ? `?${qs}` : ''}`);
  return parseDropOffsPage(res.data);
}

async function updateDropoff(id: number, payload: UpdateDropoffPayload): Promise<void> {
  await apiClient.put(`${BASE}/dropoffs/${encodeURIComponent(id)}`, payload);
}

async function deleteDropoff(id: number): Promise<void> {
  await apiClient.delete(`${BASE}/dropoffs/${encodeURIComponent(id)}`);
}

/* ---- Etit proxy: GPS pin suggestions --------------------------------------- */

async function listSuggestions(status = 'pending'): Promise<PinSuggestion[]> {
  const res = await apiClientEtit.get(
    `${ETIT_PREFIX}/suggestions?status=${encodeURIComponent(status)}`,
  );
  return z.array(pinSuggestionSchema).parse(res.data ?? []);
}

async function ackSuggestion(id: number, status: SuggestionAckStatus): Promise<void> {
  await apiClientEtit.post(`${ETIT_PREFIX}/suggestions/${encodeURIComponent(id)}/ack`, {
    status,
  });
}

export const locationApi = {
  getInbox,
  listTerminals,
  resolveTerminal,
  updateTerminal,
  listReceiptPatterns,
  upsertReceiptPattern,
  deleteReceiptPattern,
  listDropoffs,
  updateDropoff,
  deleteDropoff,
  listSuggestions,
  ackSuggestion,
} as const;

import {
  keepPreviousData,
  type QueryClient,
  useMutation,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';
import { toast } from 'sonner';
import { useTranslation } from 'react-i18next';
import { ApiError } from '@/shared/api/errors';
import { locationApi, type DropoffFilters } from './api';
import type {
  ResolveTerminalPayload,
  SuggestionAckStatus,
  UpdateDropoffPayload,
  UpdateTerminalPayload,
  UpsertReceiptPatternPayload,
} from './schemas';

export const locationKeys = {
  all: ['locations'] as const,
  inbox: () => [...locationKeys.all, 'inbox'] as const,
  terminalsRoot: () => [...locationKeys.all, 'terminals'] as const,
  terminals: (company?: string) =>
    [...locationKeys.terminalsRoot(), company?.trim() || 'all'] as const,
  receiptPatterns: (terminalId: number) =>
    [...locationKeys.all, 'receipt-patterns', terminalId] as const,
  dropoffs: () => [...locationKeys.all, 'dropoffs'] as const,
  dropoffList: (filters: DropoffFilters) => [...locationKeys.dropoffs(), filters] as const,
  suggestions: (status: string) => [...locationKeys.all, 'suggestions', status] as const,
};

/* -------------------------------------------------------------------------- */
/* Queries                                                                     */
/* -------------------------------------------------------------------------- */

export function useLocationsInbox() {
  return useQuery({
    queryKey: locationKeys.inbox(),
    queryFn: () => locationApi.getInbox(),
  });
}

/**
 * Terminals list. With `company`, only the terminals allowed for that company
 * (each carrying its resolved `receipt_pattern`); without, all terminals with
 * their `allowed_companies`.
 */
export function useTerminals(company?: string, options: { enabled?: boolean } = {}) {
  return useQuery({
    queryKey: locationKeys.terminals(company),
    queryFn: () => locationApi.listTerminals(company),
    enabled: options.enabled ?? true,
  });
}

export function useReceiptPatterns(terminalId: number | null) {
  return useQuery({
    queryKey: locationKeys.receiptPatterns(terminalId ?? 0),
    queryFn: () => locationApi.listReceiptPatterns(terminalId ?? 0),
    enabled: terminalId != null,
  });
}

/** Paginated drop-off list — `{ items, total, page, per_page }`. */
export function useDropoffs(filters: DropoffFilters = {}) {
  return useQuery({
    queryKey: locationKeys.dropoffList(filters),
    queryFn: () => locationApi.listDropoffs(filters),
    // Keep the previous page rendered while the next one loads.
    placeholderData: keepPreviousData,
  });
}

/**
 * GPS-derived pin suggestions from the etit proxy. This service may not be
 * deployed yet — consumers must treat `isError` as "no suggestions" and keep
 * rendering the DB-derived inbox items. `retry: 1` keeps the failure fast.
 */
export function usePinSuggestions(status = 'pending') {
  return useQuery({
    queryKey: locationKeys.suggestions(status),
    queryFn: () => locationApi.listSuggestions(status),
    retry: 1,
    staleTime: 30_000,
  });
}

/* -------------------------------------------------------------------------- */
/* Mutations                                                                   */
/* -------------------------------------------------------------------------- */

export function useUpdateTerminal() {
  const queryClient = useQueryClient();
  const { t } = useTranslation();

