    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: locationKeys.terminalsRoot() });
      queryClient.invalidateQueries({ queryKey: locationKeys.inbox() });
      toast.success(t('locations.toast.terminalUpdated', 'Terminal updated'));
    },
