import { apiClientRust } from '@/shared/api/client';
import { cairoInstantFromInputs } from '@/shared/lib/cairo';
import {
  splitSetSchema,
  statisticsSchema,
  transactionPageSchema,
  transactionSchema,
  type SplitPartInput,
  type SplitSet,
  type Transaction,
  type TransactionFilters,
  type TransactionFormValues,
  type TransactionPage,
  type TransactionStatistics,
  type TransactionWriteExtras,
} from './schemas';

const BASE = '/api/v1/transactions';

/** Drop empty strings so they don't become `?category=` and match nothing. */
function toParams(filters: TransactionFilters): Record<string, string> {
  const params: Record<string, string> = {};
  for (const [key, value] of Object.entries(filters)) {
    if (value === undefined || value === null || value === '') continue;
    params[key] = String(value);
  }
  return params;
}

/* ─── List (cursor-paginated, occurred_at DESC keyset) ─── */
export async function getTransactions(
  filters: TransactionFilters,
  cursor?: string | null,
  limit = 100,
): Promise<TransactionPage> {
  const response = await apiClientRust.get(BASE, {
    params: { ...toParams(filters), ...(cursor ? { cursor } : {}), limit },
  });
  return transactionPageSchema.parse(response.data);
}

/* ─── Single (carries raw_body/raw_wa_timestamp for whatsapp rows) ─── */
export async function getTransaction(id: number): Promise<Transaction> {
  const response = await apiClientRust.get(`${BASE}/${id}`);
  return transactionSchema.parse(response.data);
}

/* ─── Aggregates — the only place totals come from ─── */
export async function getTransactionStatistics(
  filters: TransactionFilters,
): Promise<TransactionStatistics> {
  const response = await apiClientRust.get(`${BASE}/statistics`, {
    params: toParams(filters),
  });
  return statisticsSchema.parse(response.data);
}

/* ─── Export — the server renders the workbook over the whole filtered set ─── */
export async function exportTransactions(
  filters: TransactionFilters,
): Promise<{ blob: Blob; filename: string }> {
  const response = await apiClientRust.get(`${BASE}/export`, {
    // The workbook mirrors the ledger, and the ledger is cash-out only.
    params: { ...toParams(filters), direction: 'out' },
    responseType: 'blob',
    // A wide range takes longer than an API call; don't trip the 15s default.
    timeout: 60_000,
  });

  const blob = new Blob([response.data as BlobPart], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  });

  let filename = 'expenses.xlsx';
  const disposition = response.headers?.['content-disposition'];
  if (typeof disposition === 'string') {
    const match = disposition.match(/filename="?([^";]+)"?/i);
    if (match?.[1]) filename = match[1];
  }
  return { blob, filename };
}

/* ─── Payload assembly ─── */

/**
 * Form values → wire body. The amount goes through VERBATIM as a string;
 * date + time inputs (Cairo wall clock) combine into one RFC3339 instant.
 * `nullEmpty` controls what happens to cleared optional text: POST omits it,
 * PATCH sends null so the server actually clears the column.
 */
function toPayload(
  values: Partial<TransactionFormValues> & TransactionWriteExtras,
  nullEmpty: boolean,
): Record<string, unknown> {
  const payload: Record<string, unknown> = {};

  const text = (key: keyof TransactionFormValues) => {
    const v = values[key];
    if (v === undefined) return;
    const trimmed = String(v).trim();
    if (trimmed === '') {
      if (nullEmpty) payload[key] = null;
      return;
    }
    payload[key] = trimmed;
  };

  if (values.direction !== undefined) payload.direction = values.direction;
  if (values.amount !== undefined) payload.amount = values.amount.trim();
  text('currency');
  if (values.occurred_date) {
    payload.occurred_at = cairoInstantFromInputs(values.occurred_date, values.occurred_time);
  }
  text('category');
  text('account');
  text('counterparty');
  text('reference');
  text('description');
  text('payment_method');
  text('company');
  text('paid_by');

  if (values.car_id !== undefined) payload.car_id = values.car_id;
  if (values.driver_id !== undefined) payload.driver_id = values.driver_id;
  if (values.employee_id !== undefined) payload.employee_id = values.employee_id;
  if (values.raw_message_id !== undefined) payload.raw_message_id = values.raw_message_id;

  return payload;
}

/* ─── Create (raw_message_id present = promotion of an ignored message) ─── */
export async function createTransaction(
  values: TransactionFormValues & TransactionWriteExtras,
): Promise<Transaction> {
  const response = await apiClientRust.post(BASE, toPayload(values, false));
  return transactionSchema.parse(response.data);
}

/* ─── Update (If-Match; 409 = concurrent edit or settled loan) ─── */
export async function updateTransaction(
  id: number,
  version: number,
  values: Partial<TransactionFormValues> & TransactionWriteExtras,
): Promise<Transaction> {
  const response = await apiClientRust.patch(`${BASE}/${id}`, toPayload(values, true), {
    headers: { 'If-Match': String(version) },
  });
  return transactionSchema.parse(response.data);
}

/* ─── Soft delete (also soft-deletes a linked unpaid loan) ─── */
export async function deleteTransaction(id: number, version: number): Promise<void> {
  await apiClientRust.delete(`${BASE}/${id}`, {
    headers: { 'If-Match': String(version) },
  });
}

/* -------------------------------------------------------------------------- */
/* Splits                                                                      */
/*                                                                            */
/* The parent's `version` is ALWAYS the If-Match token — a split is an edit of  */
/* the parent, whichever row the sheet was opened from. Part amounts travel    */
/* verbatim as strings and must sum exactly to the parent amount; the server   */
/* is the arbiter and its 400/409 messages are surfaced to the user as-is.     */
/* -------------------------------------------------------------------------- */

/** Drop undefined fields so the wire body carries only what was set. */
function toPartsBody(parts: SplitPartInput[]): { parts: Record<string, unknown>[] } {
  return {
    parts: parts.map((part) => {
      const out: Record<string, unknown> = { amount: part.amount.trim() };
      if (part.category !== undefined) out.category = part.category;
      if (part.description !== undefined) out.description = part.description;
      if (part.driver_id !== undefined) out.driver_id = part.driver_id;
      if (part.employee_id !== undefined) out.employee_id = part.employee_id;
      if (part.paid_by !== undefined) out.paid_by = part.paid_by;
      if (part.car_id !== undefined) out.car_id = part.car_id;
      return out;
    }),
  };
}

/* ─── Read the set — id may be the parent OR any child ─── */
export async function getTransactionSplit(id: number): Promise<SplitSet> {
  const response = await apiClientRust.get(`${BASE}/${id}/split`);
  return splitSetSchema.parse(response.data);
}

/* ─── Create a split of an unsplit cash-out row ─── */
export async function createTransactionSplit(
  id: number,
  version: number,
  parts: SplitPartInput[],
): Promise<SplitSet> {
  const response = await apiClientRust.post(`${BASE}/${id}/split`, toPartsBody(parts), {
    headers: { 'If-Match': String(version) },
  });
  return splitSetSchema.parse(response.data);
}

/* ─── Replace an existing part set (id = parent) ─── */
export async function replaceTransactionSplit(
  id: number,
  version: number,
  parts: SplitPartInput[],
): Promise<SplitSet> {
  const response = await apiClientRust.put(`${BASE}/${id}/split`, toPartsBody(parts), {
    headers: { 'If-Match': String(version) },
  });
  return splitSetSchema.parse(response.data);
}

/* ─── Dissolve — 409 if any part's registered loan is already settled ─── */
export async function unsplitTransaction(id: number, version: number): Promise<void> {
  await apiClientRust.post(`${BASE}/${id}/unsplit`, undefined, {
    headers: { 'If-Match': String(version) },
  });
}

import { z } from 'zod';
import { apiClientEtit } from '@/shared/api/client';
import {
  parseTripMatchesPage,
  scanResponseSchema,
  scanRunSchema,
  tripAuditSummarySchema,
  tripMatchDetailSchema,
  tripMatchReplayDetailSchema,
  type ScanResponse,
  type ScanRun,
  type TripAuditSummary,
  type TripMatchDetail,
  type TripMatchReplayDetail,
  type TripMatchStatus,
  type TripMatchesPage,
} from './schemas';

/**
 * GPS trip-audit endpoints on the etit proxy — same base + auth as the
 * zones entity (`apiClientEtit`, all under `/api/v1`).
 */

const PREFIX = 'api/v1/trip-audit';

export type TripMatchSort = 'severity' | 'date';

export interface TripMatchFilters {
  /** 'YYYY-MM-DD' inclusive. */
  from?: string;
  /** 'YYYY-MM-DD' inclusive. */
  to?: string;
  status?: TripMatchStatus | '';
  company?: string;
  /**
   * NEW: free-text search, matched server-side against plate / driver /
   * terminal. Sent as `q=<text>` alongside the existing params.
   */
  q?: string;
  flagged?: boolean;
  /** Only trips not yet marked reviewed. */
  unreviewed?: boolean;
  /** 'severity' = critical flags first, then excess km; 'date' = newest first. */
  sort?: TripMatchSort;
  /** 1-based page. */
  page?: number;
  /** Max 200 (proxy-enforced). */
  per_page?: number;
}

async function listMatches(filters: TripMatchFilters = {}): Promise<TripMatchesPage> {
  const params = new URLSearchParams();
  if (filters.from) params.set('from', filters.from);
  if (filters.to) params.set('to', filters.to);
  if (filters.status) params.set('status', filters.status);
  if (filters.company?.trim()) params.set('company', filters.company.trim());
  if (filters.q?.trim()) params.set('q', filters.q.trim());
  if (filters.flagged) params.set('flagged', 'true');
  if (filters.unreviewed) params.set('unreviewed', 'true');
  if (filters.sort) params.set('sort', filters.sort);
  if (filters.page != null) params.set('page', String(filters.page));
  if (filters.per_page != null) params.set('per_page', String(filters.per_page));
  const qs = params.toString();
  const res = await apiClientEtit.get(`${PREFIX}/matches${qs ? `?${qs}` : ''}`);
  return parseTripMatchesPage(res.data);
}

export interface TripAuditSummaryFilters {
  /** 'YYYY-MM-DD' inclusive. */
  from?: string;
  /** 'YYYY-MM-DD' inclusive. */
  to?: string;
  company?: string;
}

/** Whole-window aggregates for the KPI strip — exact regardless of paging. */
async function getSummary(filters: TripAuditSummaryFilters = {}): Promise<TripAuditSummary> {
  const params = new URLSearchParams();
  if (filters.from) params.set('from', filters.from);
  if (filters.to) params.set('to', filters.to);
  if (filters.company?.trim()) params.set('company', filters.company.trim());
  const qs = params.toString();
  const res = await apiClientEtit.get(`${PREFIX}/summary${qs ? `?${qs}` : ''}`);
  return tripAuditSummarySchema.parse(res.data ?? {});
}

async function getMatch(id: number): Promise<TripMatchDetail> {
  const res = await apiClientEtit.get(`${PREFIX}/matches/${encodeURIComponent(id)}`);
  return tripMatchDetailSchema.parse(res.data);
}

async function reviewMatch(id: number, note?: string): Promise<void> {
  await apiClientEtit.post(
    `${PREFIX}/matches/${encodeURIComponent(id)}/review`,
    note?.trim() ? { note: note.trim() } : {},
  );
}

async function listRuns(): Promise<ScanRun[]> {
  const res = await apiClientEtit.get(`${PREFIX}/runs`);
  return z.array(scanRunSchema).parse(res.data ?? []);
}

/**
 * Kick off a scan. The proxy runs it synchronously and can take minutes,
 * so the default 15s axios timeout is overridden; the caller toasts "scan
 * started" immediately and refetches runs/matches when this resolves.
 */
async function runScan(dates?: string[]): Promise<ScanResponse> {
  const res = await apiClientEtit.post(
    `${PREFIX}/scan`,
    dates && dates.length > 0 ? { dates } : {},
    { timeout: 600_000 },
  );
  return scanResponseSchema.parse(res.data ?? {});
}

/**
 * NEW export for the trip-replay page: same `GET /matches/:id` endpoint,
 * parsed through the replay schema so `off_route_pct` (when the proxy
 * sends it) survives parsing. Kept separate from `tripAuditApi.getMatch`
 * so the existing detail dialog contract is untouched.
 */
export async function getTripMatchReplay(id: number): Promise<TripMatchReplayDetail> {
  const res = await apiClientEtit.get(`${PREFIX}/matches/${encodeURIComponent(id)}`);
  return tripMatchReplayDetailSchema.parse(res.data);
}

export const tripAuditApi = {
  listMatches,
  getSummary,
  getMatch,
  reviewMatch,
  listRuns,
  runScan,
} as const;

/**
 * The audit queue's bare-navigation mount filters, extracted so the sidebar's
 * data warmer reproduces the EXACT first query keys. trip-audit.tsx imports
 * these same helpers for its initial state — one source, no drift.
 */

import { toDateOnly } from '@/shared/lib/format';
import { currentScopeSlice, readScopeCompany } from '@/shared/scope';
import type { TripAuditSummaryFilters, TripMatchFilters } from './api';

export const AUDIT_STORAGE_KEY_LIMIT = 'apex:tripAudit:limit';
export const AUDIT_LIMIT_OPTIONS = [10, 25, 50, 100];

/** The queue's mount range — the GLOBAL scope's, exactly as the page reads it. */
export function defaultAuditRange(): { from: string; to: string } {
  return currentScopeSlice().range;
}

export function loadStoredAuditLimit(): number {
  if (typeof window === 'undefined') return 25;
  const n = Number(window.localStorage.getItem(AUDIT_STORAGE_KEY_LIMIT));
  return AUDIT_LIMIT_OPTIONS.includes(n) ? n : 25;
}

/** Mount filters of a bare navigation (the needs_review queue view). */
export function defaultTripMatchFilters(): TripMatchFilters {
  const range = defaultAuditRange();
  return {
    from: toDateOnly(range.from),
    to: toDateOnly(range.to),
    q: undefined,
    company: readScopeCompany() ?? undefined,
    status: '',
    flagged: true,
    unreviewed: true,
    sort: 'severity',
    page: 1,
    per_page: loadStoredAuditLimit(),
  };
}

export function defaultAuditSummaryFilters(): TripAuditSummaryFilters {
  const range = defaultAuditRange();
  return {
    from: toDateOnly(range.from),
    to: toDateOnly(range.to),
    company: readScopeCompany() ?? undefined,
  };
}

import {
  type QueryClient,
  keepPreviousData,
  useMutation,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';
import { defaultAuditSummaryFilters, defaultTripMatchFilters } from './defaults';
import { toast } from 'sonner';
import { useTranslation } from 'react-i18next';
import {
  getTripMatchReplay,
  tripAuditApi,
  type TripAuditSummaryFilters,
  type TripMatchFilters,
} from './api';

export const tripAuditKeys = {
  all: ['trip-audit'] as const,
  matches: () => [...tripAuditKeys.all, 'matches'] as const,
  matchList: (filters: TripMatchFilters) => [...tripAuditKeys.matches(), filters] as const,
  summaries: () => [...tripAuditKeys.all, 'summary'] as const,
  summary: (filters: TripAuditSummaryFilters) =>
    [...tripAuditKeys.summaries(), filters] as const,
  details: () => [...tripAuditKeys.all, 'detail'] as const,
  detail: (id: number) => [...tripAuditKeys.details(), id] as const,
  runs: () => [...tripAuditKeys.all, 'runs'] as const,
};

/* -------------------------------------------------------------------------- */
/* Queries                                                                     */
/* -------------------------------------------------------------------------- */

export function useTripMatches(filters: TripMatchFilters = {}) {
  return useQuery({
    queryKey: tripAuditKeys.matchList(filters),
    queryFn: () => tripAuditApi.listMatches(filters),
    // Keep the previous page rendered while the next one loads so the
    // pagination controls don't jump.
    placeholderData: keepPreviousData,
  });
}

/** Whole-window KPI aggregates — same from/to/company as the list. */
export function useTripAuditSummary(filters: TripAuditSummaryFilters = {}) {
  return useQuery({
    queryKey: tripAuditKeys.summary(filters),
    queryFn: () => tripAuditApi.getSummary(filters),
    placeholderData: keepPreviousData,
    staleTime: 30_000,
    retry: 1,
  });
}

export function useTripMatch(id: number | null) {
  return useQuery({
    queryKey: tripAuditKeys.detail(id ?? -1),
    queryFn: () => tripAuditApi.getMatch(id as number),
    enabled: id != null,
  });
}

/**
 * NEW export for the trip-replay page — same endpoint as `useTripMatch`
 * but parsed with the replay schema (keeps `off_route_pct`). Separate
 * query key so the two parsed shapes never collide in the cache.
 */
export function useTripMatchReplay(id: number | null) {
  return useQuery({
    queryKey: [...tripAuditKeys.details(), 'replay', id ?? -1] as const,
    queryFn: () => getTripMatchReplay(id as number),
    enabled: id != null,
    staleTime: 60_000,
  });
}

export function useTripAuditRuns() {
  return useQuery({
    queryKey: tripAuditKeys.runs(),
    queryFn: () => tripAuditApi.listRuns(),
    staleTime: 30_000,
    retry: 1,
  });
}

/* -------------------------------------------------------------------------- */
/* Mutations                                                                   */
/* -------------------------------------------------------------------------- */

export function useReviewMatch() {
  const queryClient = useQueryClient();
  const { t } = useTranslation();

  return useMutation({
    mutationFn: ({ id, note }: { id: number; note?: string }) =>
      tripAuditApi.reviewMatch(id, note),
    onSuccess: (_data, { id }) => {
      queryClient.invalidateQueries({ queryKey: tripAuditKeys.matches() });
      queryClient.invalidateQueries({ queryKey: tripAuditKeys.summaries() });
      queryClient.invalidateQueries({ queryKey: tripAuditKeys.detail(id) });
      toast.success(t('tripAudit.toast.reviewSuccess', 'Marked as reviewed'));
    },
    onError: (err) => {
      console.error(err);
      toast.error(t('tripAudit.toast.reviewError', 'Failed to mark as reviewed'));
    },
  });
}

/**
 * Fire-and-wait scan: toasts "scan started" immediately (the proxy runs the
 * scan synchronously and the request can take minutes), then refetches runs
 * and matches when the request resolves.
 */
export function useRunScan() {
  const queryClient = useQueryClient();
  const { t } = useTranslation();

  return useMutation({
    mutationFn: (dates?: string[]) => tripAuditApi.runScan(dates),
    onMutate: () => {
      toast.info(t('tripAudit.toast.scanStarted', 'Scan started'), {
        description: t(
          'tripAudit.toast.scanStartedDesc',
          'This can take a few minutes — results will refresh automatically.',
        ),
      });
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: tripAuditKeys.all });
      if (data.error) {
        toast.error(t('tripAudit.toast.scanError', 'Scan finished with an error'), {
          description: data.error,
        });
      } else {
        toast.success(t('tripAudit.toast.scanComplete', 'Scan complete'), {
          description: t('tripAudit.toast.scanSummary', {
            scanned: data.trips_scanned ?? 0,
            matched: data.trips_matched ?? 0,
            flags: data.flags_raised ?? 0,
            defaultValue:
              '{{scanned}} trips scanned, {{matched}} matched, {{flags}} flags raised',
          }),
        });
      }
    },
    onError: (err) => {
      console.error(err);
      queryClient.invalidateQueries({ queryKey: tripAuditKeys.all });
      toast.error(t('tripAudit.toast.scanRequestError', 'Failed to run scan'));
    },
  });
}

/* -------------------------------------------------------------------------- */
/* Intent prefetch                                                             */
/* Warmed on hover/focus/touch by surfaces that know the click is coming.      */
/* MUST mirror the hooks above key-for-key.                                    */
/* -------------------------------------------------------------------------- */

export function prefetchTripAudit(qc: QueryClient): void {
  const filters = defaultTripMatchFilters();
  void qc.prefetchQuery({
    queryKey: tripAuditKeys.matchList(filters),
    queryFn: () => tripAuditApi.listMatches(filters),
  });
  const summary = defaultAuditSummaryFilters();
  void qc.prefetchQuery({
    queryKey: tripAuditKeys.summary(summary),
    queryFn: () => tripAuditApi.getSummary(summary),
  });
  void qc.prefetchQuery({
    queryKey: tripAuditKeys.runs(),
    queryFn: () => tripAuditApi.listRuns(),
  });
}

import { decode as msgpackDecode } from '@msgpack/msgpack';
import { apiClient, apiClientRust } from '@/shared/api/client';
import {
  tripListResponseSchema,
  tripDetailsResponseSchema,
  parentContainersResponseSchema,
  duplicateDetectionResponseSchema,
  type TripListResponse,
  type TripDetailsResponse,
  type ParentContainersResponse,
  type TripListParams,
  type MultiContainerTripInput,
  type DuplicateDetectionResponse,
} from './schemas';

/**
 * Build query params for the trips list.
 *
 * The Go backend split this three ways — /api/trips, /api/trips/company/:c and
 * /api/trips/date — because each grew its own handler over time. The Rust
 * endpoint takes company and date range as ordinary optional filters, so all
 * three collapse into one call.
 *
 * The date range is not only a row filter: it also scopes the window the
 * allocated revenue is divided over. See `allocated_*` on the Trip schema.
 */
function listParams(params: TripListParams): Record<string, string | number> {
  const { page, limit, search, missingData, receiptStatus, company, startDate, endDate } = params;

  const query: Record<string, string | number> = { page, limit };
  if (search) query.search = search;
  if (missingData) query.missing_data = missingData;
  if (receiptStatus) query.receipt_status = receiptStatus;
  if (company) query.company = company;
  if (startDate) query.from = startDate;
  if (endDate) query.to = endDate;
  return query;
}

export const tripApi = {
  /**
   * List trips with filters, pagination, and optional full-text search.
   *
   * Served by apex-rust, which is where the revenue formulas live — that is the
   * whole reason this one call moved off Go while its siblings below did not.
   * Rows carry `revenue` and the `allocated_*` fields for permission 4 and
   * omit them entirely otherwise.
   *
   * MessagePack rather than JSON: every row nests its receipt steps and, for a
   * container, its parent header with that parent's scanned receipts, so the
   * keys repeat heavily and the binary encoding is markedly smaller. It also
   * round-trips floats exactly, where JSON loses the last bit of an f64 —
   * which matters for money.
   */
  async list(params: TripListParams): Promise<TripListResponse> {
    const response = await apiClientRust.get('/api/v1/trips', {
      params: { ...listParams(params), format: 'msgpack' },
      responseType: 'arraybuffer',
      headers: { Accept: 'application/msgpack' },
    });
    const decoded = msgpackDecode(new Uint8Array(response.data as ArrayBuffer));
    return tripListResponseSchema.parse(decoded);
  },

  /** Fetch a single trip + its route/terminal coordinates for the map dialog. */
  async details(id: number): Promise<TripDetailsResponse> {
    const { data } = await apiClient.get(`/api/trips/${id}/details`);
    return tripDetailsResponseSchema.parse(data);
  },

  /** Fetch the parent trip + all its containers. */
  async parentContainers(parentId: number): Promise<ParentContainersResponse> {
    const { data } = await apiClient.get(`/api/trips/parent/${parentId}/containers`);
    return parentContainersResponseSchema.parse(data);
  },

  /** Delete a single (standalone or container) trip. */
  async delete(id: number): Promise<void> {
    await apiClient.delete(`/api/trips/${id}`);
  },

  /** Delete a parent trip and all its containers. */
  async deleteParent(parentId: number): Promise<void> {
    await apiClient.delete(`/api/trips/parent/${parentId}`);
  },

  /**
   * Create a multi-container trip.
   *
   * If the backend detects receipt-number collisions it returns 409 with a
   * `DuplicateDetectionResponse` body. Callers should catch that, present the
   * conflict, and retry with `force_create: true` if the user confirms.
   */
  async createMultiContainer(
    input: MultiContainerTripInput,
  ): Promise<ParentContainersResponse> {
    const { data } = await apiClient.post('/api/trips/multi-container', input);
    const payload = data?.data ?? data?.trip ?? data;
    return parentContainersResponseSchema.passthrough().parse(payload);
  },

  /**
   * Update an existing multi-container trip.
   * Supports the same 409/force_update conflict flow as creation.
   */
  async updateMultiContainer(
    parentId: number,
    input: MultiContainerTripInput,
  ): Promise<ParentContainersResponse> {
    const { data } = await apiClient.put(`/api/trips/parent/${parentId}`, input);
    const payload = data?.data ?? data?.trip ?? data;
    return parentContainersResponseSchema.passthrough().parse(payload);
  },

  /**
   * Parse a 409 duplicate-detection response. Call this inside a mutation's
   * error handler before surfacing the error to the user.
   *
   * Returns null if the error is not a duplicate-detection 409, so the caller
   * can fall back to generic error handling.
   */
  parseDuplicateError(error: unknown): DuplicateDetectionResponse | null {
    if (!error || typeof error !== 'object') return null;

    // Handle transformed ApiError (from our axios interceptor)
    const apiErr = error as { status?: number; payload?: any };
    if (apiErr.status === 409 && apiErr.payload) {
      const payload = apiErr.payload?.data ?? apiErr.payload?.trip ?? apiErr.payload;
      const parsed = duplicateDetectionResponseSchema.safeParse(payload);
      return parsed.success ? parsed.data : null;
    }

    // Handle raw Axios error
    const axErr = error as { response?: { status?: number; data?: any } };
    if (axErr.response?.status === 409 && axErr.response.data) {
      const payload = axErr.response.data?.data ?? axErr.response.data?.trip ?? axErr.response.data;
      const parsed = duplicateDetectionResponseSchema.safeParse(payload);
      return parsed.success ? parsed.data : null;
    }

    return null;
  },

  /**
   * Download the Watanya report as an Excel blob.
   * Permission-gated on the backend (requires permission level >= 3).
   */
  async exportWatanyaReport(params: {
    start_date: string;
    end_date: string;
  }): Promise<{ blob: Blob; filename: string }> {
    const response = await apiClient.post('/api/trips/watanya/export_report', params, {
      responseType: 'blob',
    });
    const blob = new Blob([response.data as BlobPart], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });

    // Pull filename out of Content-Disposition if the server sets one.
    let filename = 'watanya_report.xlsx';
    const disposition = response.headers?.['content-disposition'];
    if (typeof disposition === 'string') {
      const match = disposition.match(/filename="?([^"]+)"?/i);
      if (match?.[1]) filename = match[1];
    }

    return { blob, filename };
  },

  /**
   * Server-rendered trips export.
   *
   * The workbook is built in Go and returned as the response body. Two reasons
   * it is not built here any more: the client had to cap the fetch at 10,000
   * rows, so a wide filter silently produced a partial spreadsheet; and building
   * it in the browser meant downloading every row only to write it back out.
   *
   * Filters go on the query string so they match the list endpoints exactly.
   * The translated labels go in the body -- the server has no i18n bundle, and
   * a second set of English strings there would drift from these.
   */
  async exportExcel(
    params: Omit<TripListParams, 'page' | 'limit'>,
    labels: Record<string, string>,
  ): Promise<{ blob: Blob; filename: string }> {
    const query: Record<string, string> = {};
    if (params.search) query.search = params.search;
    if (params.missingData) query.missing_data = params.missingData;
    if (params.receiptStatus) query.receipt_status = params.receiptStatus;
    if (params.company) query.company = params.company;
    if (params.startDate) query.start_date = params.startDate;
    if (params.endDate) query.end_date = params.endDate;

    const response = await apiClient.post('/api/trips/export', labels, {
      params: query,
      responseType: 'blob',
    });

    const blob = new Blob([response.data as BlobPart], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });

    let filename = 'trips.xlsx';
    const disposition = response.headers?.['content-disposition'];
    if (typeof disposition === 'string') {
      const match = disposition.match(/filename="?([^";]+)"?/i);
      if (match?.[1]) filename = match[1];
    }

    return { blob, filename };
  },
};

