                      aria-label={t('tracking.focus', 'Focus on map')}
                      className="grid h-7 w-7 shrink-0 place-items-center rounded-md text-muted-foreground hover:bg-primary/10 hover:text-primary"
                    >
                      <Crosshair className="h-3.5 w-3.5" />
