                );
              })}
            </React.Fragment>
          );
        })}
      </div>
    </aside>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { X } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from '@/shared/ui/button';
import {
  CairoRangeCalendar,
  cairoTodayParts,
  dayIso,
  partsOfDay,
  toNum,
  tzDate,
  type DayParts,
} from '@/shared/ui/cairo-range-calendar';
import { CAIRO_TZ } from '@/shared/lib/cairo';
import { cairoWall } from '../api';

/* -------------------------------------------------------------------------- */
/* The history range picker — the old datetime-range's ideas rebuilt in the   */
/* global scope picker's visual language: quick presets (Last hour, 3h,       */
/* Today, Yesterday, 7 days), the shared Cairo two-tap calendar, and time     */
/* fields so a range can start and end mid-day. Emits Cairo wall strings      */
/* (`YYYY-MM-DDTHH:mm`).                                                       */
/* -------------------------------------------------------------------------- */

const TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;

function wallOf(day: DayParts, time: string): string {
  return `${dayIso(day)}T${time}`;
}

function splitWall(wall: string | null): { day: DayParts; time: string } | null {
  if (!wall) return null;
  const [d, t] = wall.split('T');
  return { day: partsOfDay(d), time: t?.slice(0, 5) ?? '00:00' };
}

export function TrackingRangePicker({
  initialFrom,
  initialTo,
  onLoad,
  onIntendLoad,
  onCancel,
}: {
  initialFrom: string | null;
  initialTo: string | null;
  onLoad: (fromWall: string, toWall: string) => void;
  onIntendLoad?: (fromWall: string, toWall: string) => void;
  onCancel: () => void;
}) {
  const { t, i18n } = useTranslation();
  const locale = i18n.language.startsWith('ar') ? 'ar-EG' : 'en-GB';
  const today = cairoTodayParts();

  const seedFrom = splitWall(initialFrom);
  const seedTo = splitWall(initialTo);
  const [selected, setSelected] = React.useState<{ from?: DayParts; to?: DayParts }>({
    from: seedFrom?.day ?? today,
    to: seedTo?.day ?? today,
  });
  const [hovered, setHovered] = React.useState<DayParts | undefined>();
  const [fromTime, setFromTime] = React.useState(seedFrom?.time ?? '00:00');
  const [toTime, setToTime] = React.useState(seedTo?.time ?? '23:59');
  const [month, setMonth] = React.useState((seedFrom?.day ?? today).m);
  const [year, setYear] = React.useState((seedFrom?.day ?? today).y);

  const fmtDay = React.useCallback(
    (p: DayParts) =>
      new Intl.DateTimeFormat(locale, {
        day: 'numeric',
        month: 'short',
        timeZone: CAIRO_TZ,
      }).format(tzDate(p.y, p.m, p.d)),
    [locale],
  );

  const handleSelect = (p: DayParts) => {
    if (!selected.from || (selected.from && selected.to)) {
      setSelected({ from: p, to: undefined });
    } else {
      const f = toNum(selected.from)!;
      if (toNum(p)! >= f) setSelected({ from: selected.from, to: p });
      else setSelected({ from: p, to: selected.from });
    }
  };

  const range = React.useMemo((): [string, string] | null => {
    const from = selected.from;
    const to = selected.to ?? selected.from;
    if (!from || !to) return null;
    const ft = TIME_RE.test(fromTime) ? fromTime : '00:00';
    const tt = TIME_RE.test(toTime) ? toTime : '23:59';
    const a = wallOf(from, ft);
    const b = wallOf(to, tt);
    return a <= b ? [a, b] : [b, a];
  }, [selected, fromTime, toTime]);

  /** Preset = a range producer, exactly the old picker's idea. */
  const applyPreset = (hours: number | 'today' | 'yesterday' | '7d') => {
    const now = new Date();
    if (hours === 'today') {
      setSelected({ from: today, to: today });
      setFromTime('00:00');
      setToTime('23:59');
      return;
    }
    if (hours === 'yesterday') {
      const y = partsOfDay(
        new Date(Date.UTC(today.y, today.m, today.d - 1, 12)).toISOString().slice(0, 10),
      );
      setSelected({ from: y, to: y });
      setFromTime('00:00');
      setToTime('23:59');
      return;
    }
    if (hours === '7d') {
      const s = partsOfDay(
        new Date(Date.UTC(today.y, today.m, today.d - 6, 12)).toISOString().slice(0, 10),
      );
      setSelected({ from: s, to: today });
      setFromTime('00:00');
      setToTime('23:59');
      return;
    }
    const startWall = cairoWall(new Date(now.getTime() - hours * 3_600_000));
    const endWall = cairoWall(now);
    setSelected({ from: partsOfDay(startWall.slice(0, 10)), to: partsOfDay(endWall.slice(0, 10)) });
    setFromTime(startWall.slice(11, 16));
    setToTime(endWall.slice(11, 16));
  };

  /* Paired HH / MM selects instead of the browser's time widget — same
     control on every platform, styled like the rest of the picker. */
  const timeSelect = (value: string, onChange: (v: string) => void, label: string) => {
    const [hh, mm] = value.split(':');
    const set = (h: string, m: string) => onChange(`${h}:${m}`);
    const cls =
      'h-7 appearance-none rounded-md border bg-background px-1.5 text-center font-mono ' +
      'text-[11px] font-semibold tabular-nums outline-none transition-colors hover:bg-muted ' +
      'focus-visible:ring-2 focus-visible:ring-ring';
    return (
      <div className="flex items-center gap-0.5" dir="ltr">
        <select
          value={hh}
          onChange={(e) => set(e.target.value, mm)}
          aria-label={`${label} — ${t('tracking.hour', 'hour')}`}
          className={cls}
        >
          {Array.from({ length: 24 }, (_, i) => String(i).padStart(2, '0')).map((h) => (
            <option key={h} value={h}>
              {h}
            </option>
          ))}
        </select>
        <span className="font-mono text-[11px] font-semibold text-muted-foreground">:</span>
        <select
          value={mm}
          onChange={(e) => set(hh, e.target.value)}
          aria-label={`${label} — ${t('tracking.minute', 'minute')}`}
          className={cls}
        >
          {Array.from({ length: 60 }, (_, i) => String(i).padStart(2, '0')).map((m) => (
            <option key={m} value={m}>
              {m}
            </option>
          ))}
        </select>
      </div>
    );
  };

  return (
    <div className="pointer-events-auto w-full rounded-t-2xl border border-b-0 bg-card/95 p-3 shadow-2xl backdrop-blur md:mx-auto md:max-w-md">
      {/* Quick presets — the old picker's set */}
      <div className="mb-3 flex flex-wrap items-center gap-1.5">
        {(
          [
            [t('tracking.range.lastHour', 'Last hour'), 1],
            [t('tracking.range.last3h', 'Last 3 hours'), 3],
            [t('tracking.range.today', 'Today'), 'today'],
            [t('tracking.range.yesterday', 'Yesterday'), 'yesterday'],
            [t('tracking.range.7d', 'Last 7 days'), '7d'],
          ] as Array<[string, number | 'today' | 'yesterday' | '7d']>
        ).map(([label, preset]) => (
          <Button
            key={label}
            variant="outline"
            size="sm"
            className="h-7 text-xs"
            onClick={() => applyPreset(preset)}
          >
            {label}
          </Button>
        ))}
        <button
          type="button"
          onClick={onCancel}
          aria-label={t('common.close', 'Close')}
          className="ms-auto grid h-7 w-7 place-items-center rounded-md text-muted-foreground hover:bg-muted"
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>

      <div className="mb-3 border-t" />

      {/* From / To summary with the time fields inline */}
      <div className="mb-3 flex items-center gap-3 rounded-lg bg-muted p-2.5 text-xs">
        <div className="flex flex-1 flex-col items-center gap-1">
          <p className="text-muted-foreground">{t('common.from', 'From')}</p>
          <p className="font-semibold">{selected.from ? fmtDay(selected.from) : '—'}</p>
          {timeSelect(fromTime, setFromTime, t('common.from', 'From'))}
        </div>
        <div className="h-12 w-px bg-border" />
        <div className="flex flex-1 flex-col items-center gap-1">
          <p className="text-muted-foreground">{t('common.to', 'To')}</p>
          <p className="font-semibold">
            {selected.to ? fmtDay(selected.to) : hovered ? fmtDay(hovered) : '—'}
          </p>
          {timeSelect(toTime, setToTime, t('common.to', 'To'))}
        </div>
      </div>

      <CairoRangeCalendar
        selected={selected}
        onSelect={handleSelect}
        hovered={hovered}
        onHover={setHovered}
        month={month}
        year={year}
        onMonthChange={(m, y) => {
          setMonth(m);
          setYear(y);
        }}
      />

      <div className="mt-3 flex justify-end gap-2 border-t pt-3">
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onCancel}>
          {t('common.cancel', 'Cancel')}
        </Button>
        <Button
          size="sm"
          className={cn('h-7 text-xs')}
          disabled={!range}
          onClick={() => range && onLoad(range[0], range[1])}
          onPointerEnter={() => range && onIntendLoad?.(range[0], range[1])}
          onFocus={() => range && onIntendLoad?.(range[0], range[1])}
        >
          {t('tracking.load', 'Load history')}
        </Button>
      </div>
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Flag, Pause, Play, RotateCcw } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { sampleAt, SPEEDS, type ReplaySample } from '../playback';
import type { ReplayTrack } from '../use-history';
import { createCursorStore } from './time-deck';

/* -------------------------------------------------------------------------- */
/* A reusable transport bar over a ReplayTrack — the same rAF-clock pattern    */
/* as the tracking page, packaged for embedding (the trip-audit dialog).       */
/*                                                                            */
/* Optionally races an "optimal ghost" track on the same clock: the race      */
/* toggle appears when `ghost` is provided, and the delta chip reads how far  */
/* ahead/behind the optimal runner is at the cursor.                          */
/* -------------------------------------------------------------------------- */

export interface TransportTick {
  ms: number;
  sample: ReplaySample;
  ghost: ReplaySample | null;
}

const timeFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Africa/Cairo',
  hour12: false,
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
});

function fmtDelta(ms: number): string {
  const mins = Math.round(Math.abs(ms) / 60_000);
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  const span = h > 0 ? `${h}h ${m}m` : `${m}m`;
  return ms >= 0 ? `−${span}` : `+${span}`;
}

export interface ReplayTransportHandle {
  /** Jump the clock (a leg preview seeks here). */
  seek: (ms: number) => void;
}

export const ReplayTransport = React.forwardRef<
  ReplayTransportHandle,
  {
    track: ReplayTrack;
    /** Stop intervals to tick on the scrubber. */
    stopTimes?: Array<{ from: Date }>;
    /** The optimal route's synthetic track — enables the race control. */
    ghost?: ReplayTrack | null;
    onTick: (tick: TransportTick) => void;
    className?: string;
  }
>(function ReplayTransport({ track, stopTimes = [], ghost = null, onTick, className }, ref) {
  const { t } = useTranslation();
  const cursor = React.useMemo(() => createCursorStore(track.startMs), [track]);
  const [playing, setPlaying] = React.useState(false);
  const [speed, setSpeed] = React.useState(16);
  const [racing, setRacing] = React.useState(false);

  const playingRef = React.useRef(false);
  const speedRef = React.useRef(speed);
  const racingRef = React.useRef(false);
  playingRef.current = playing;
  speedRef.current = speed;
  racingRef.current = racing && !!ghost;

  const onTickRef = React.useRef(onTick);
  React.useEffect(() => {
    onTickRef.current = onTick;
  });

  const emit = React.useCallback(
    (ms: number) => {
      onTickRef.current({
        ms,
        sample: sampleAt(track, ms),
        ghost:
          racingRef.current && ghost && ms >= ghost.startMs
            ? sampleAt(ghost, Math.min(ms, ghost.endMs))
            : null,
      });
    },
    [track, ghost],
  );

  // The race can extend past the truck's arrival (a slower optimal keeps
  // running); the clock's end is the later of the two.
  const endMs = racing && ghost ? Math.max(track.endMs, ghost.endMs) : track.endMs;

  React.useEffect(() => {
    let raf = 0;
    let last = performance.now();
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = now - last;
      last = now;
      if (!playingRef.current) return;
      const limit = racingRef.current && ghost ? Math.max(track.endMs, ghost.endMs) : track.endMs;
      const next = Math.min(limit, cursor.get() + dt * speedRef.current);
      cursor.set(next);
      emit(next);
      if (next >= limit) setPlaying(false);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [cursor, emit, ghost, track]);

  // Seed on track change.
  React.useEffect(() => {
    cursor.set(track.startMs);
    setPlaying(false);
    emit(track.startMs);
  }, [track, cursor, emit]);

  const seek = React.useCallback(
    (ms: number) => {
      const clamped = Math.min(Math.max(ms, track.startMs), endMs);
      cursor.set(clamped);
      emit(clamped);
    },
    [cursor, emit, track.startMs, endMs],
  );
  React.useImperativeHandle(ref, () => ({ seek }), [seek]);

  const value = React.useSyncExternalStore(cursor.subscribe, cursor.get);
  const span = Math.max(1, endMs - track.startMs);
  const pct = Math.min(100, Math.max(0, ((value - track.startMs) / span) * 100));

  // Race delta at the cursor: how much earlier the ghost reaches its current
  // milestone — approximated by arrival-time difference, the honest headline.
  const arrivalDeltaMs = ghost ? track.endMs - ghost.endMs : 0;

  return (
    <div className={cn('space-y-2 p-2.5', className)}>
      <div className="flex items-center gap-3">
        <span className="w-[70px] shrink-0 text-end font-mono text-[11px] font-semibold tabular-nums">
          {timeFmt.format(new Date(value))}
        </span>
        <div className="relative min-w-0 flex-1">
          <div className="pointer-events-none absolute inset-x-0 top-1/2 h-2 -translate-y-1/2">
            {stopTimes.map((s, i) => {
              const p = ((s.from.getTime() - track.startMs) / span) * 100;
              if (p < 0 || p > 100) return null;
              return (
                <span
                  key={i}
                  className="absolute top-0 h-2 w-[3px] rounded-sm bg-amber-500/80"
                  style={{ insetInlineStart: `${p}%` }}
                />
              );
            })}
          </div>
          <input
            type="range"
            min={track.startMs}
            max={endMs}
            step={1000}
            value={value}
            onChange={(e) => seek(Number(e.target.value))}
            aria-label={t('tracking.scrub', 'Playback position')}
            className="relative z-10 h-2 w-full cursor-pointer appearance-none rounded-full accent-primary"
            style={{
              background: `linear-gradient(to right, hsl(var(--primary)) ${pct}%, hsl(var(--muted)) ${pct}%)`,
            }}
          />
        </div>
        <span className="w-[70px] shrink-0 font-mono text-[10px] text-muted-foreground tabular-nums">
          {timeFmt.format(new Date(endMs))}
        </span>
      </div>

      <div className="flex flex-wrap items-center gap-1.5">
        <button
          type="button"
          onClick={() => {
            seek(track.startMs);
            setPlaying(false);
          }}
          aria-label={t('tracking.restart', 'Restart')}
          className="grid h-8 w-8 place-items-center rounded-lg border bg-background hover:bg-muted"
        >
          <RotateCcw className="h-3.5 w-3.5" />
        </button>
        <button
          type="button"
          onClick={() => setPlaying((p) => !p)}
          aria-label={playing ? t('tracking.pause', 'Pause') : t('tracking.play', 'Play')}
          className="grid h-8 w-12 place-items-center rounded-lg bg-primary text-primary-foreground shadow hover:bg-primary/90"
        >
          {playing ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
        </button>
        <div className="flex items-center gap-1 ps-1">
          {SPEEDS.map((s) => (
            <button
              key={s}
              type="button"
              aria-pressed={speed === s}
              onClick={() => setSpeed(s)}
              className={cn(
                'rounded-md border px-1.5 py-1 font-mono text-[10px] font-semibold tabular-nums',
                speed === s
                  ? 'border-primary/50 bg-primary/10 text-primary'
                  : 'bg-background text-muted-foreground hover:bg-muted',
              )}
            >
              {s}×
            </button>
          ))}
        </div>

        {ghost && (
          <div className="ms-auto flex items-center gap-2">
            <button
              type="button"
              aria-pressed={racing}
              onClick={() => {
                setRacing((r) => !r);
                emit(cursor.get());
              }}
              className={cn(
                'flex h-8 items-center gap-1.5 rounded-lg border px-2.5 text-[11px] font-semibold',
                racing
                  ? 'border-emerald-600/50 bg-emerald-600/10 text-emerald-600'
                  : 'bg-background text-muted-foreground hover:bg-muted',
              )}
            >
              <Flag className="h-3.5 w-3.5" />
              {t('tracking.raceOptimal', 'Race optimal')}
            </button>
            {racing && (
              <span
                className={cn(
                  'rounded-md px-2 py-1 font-mono text-[10.5px] font-bold tabular-nums',
                  arrivalDeltaMs >= 0
                    ? 'bg-emerald-600/10 text-emerald-600'
                    : 'bg-destructive/10 text-destructive',
                )}
                title={t(
                  'tracking.raceDeltaHint',
                  'Optimal arrival vs actual arrival',
                )}
              >
                {fmtDelta(arrivalDeltaMs)}
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
});

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { cn } from '@/shared/lib/cn';
import {
  STATUS_COLOR,
  STATUS_ORDER,
  statusGroup,
  type LiveStatus,
  type StatusGroup,
  type Vehicle,
} from '../schemas';

/* -------------------------------------------------------------------------- */
/* Floating status bar — the fleet at a glance, and the map's filter. Tap a   */
/* chip to isolate that group; tap again to clear.                             */
/* -------------------------------------------------------------------------- */

export function groupOf(vehicle: Vehicle, live: LiveStatus | null): StatusGroup {
  return statusGroup(live?.status ?? vehicle.status);
}

export function StatusChips({
  vehicles,
  live,
  activeGroup,
  onToggleGroup,
}: {
  vehicles: Vehicle[];
  live: Map<string, LiveStatus>;
  activeGroup: StatusGroup | null;
  onToggleGroup: (g: StatusGroup | null) => void;
}) {
  const { t } = useTranslation();

  const counts = React.useMemo(() => {
    const m = new Map<StatusGroup, number>();
    for (const v of vehicles) {
      const g = groupOf(v, live.get(v.id) ?? null);
      m.set(g, (m.get(g) ?? 0) + 1);
    }
    return m;
  }, [vehicles, live]);

  return (
    <div className="pointer-events-auto flex items-center gap-1.5 overflow-x-auto pb-0.5 [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden sm:flex-wrap sm:overflow-visible">
      {STATUS_ORDER.map((g) => {
        const count = counts.get(g) ?? 0;
        if (count === 0) return null;
        const active = activeGroup === g;
        return (
          <button
            key={g}
            type="button"
            aria-pressed={active}
            onClick={() => onToggleGroup(active ? null : g)}
            className={cn(
              'flex shrink-0 items-center gap-1.5 rounded-full border px-2 py-1 font-mono text-[11px] font-semibold shadow-sm backdrop-blur transition-colors sm:px-2.5',
              active
                ? 'border-transparent text-white'
                : 'border-border bg-card/90 text-foreground hover:bg-card',
            )}
            style={active ? { background: STATUS_COLOR[g] } : undefined}
          >
            <span
              className="h-2 w-2 rounded-full"
              style={{ background: active ? '#fff' : STATUS_COLOR[g] }}
            />
            <span className="hidden sm:inline">{t(`tracking.group.${g}`, g)}</span>
            <span className={cn('tabular-nums', active ? 'opacity-90' : 'text-muted-foreground')}>
              {count}
            </span>
          </button>
        );
      })}
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import {
  Flame,
  LocateFixed,
  MapPin,
  MapPinned,
  Pause,
  Play,
  RotateCcw,
  Route,
  SkipBack,
  SkipForward,
  X,
} from 'lucide-react';
import { legColor, legId } from '../map/layers';
import type { LegSegment } from '../use-history';
import { cn } from '@/shared/lib/cn';
import { indexAt, SPEEDS } from '../playback';
import type { HistoryData } from '../use-history';
import type { RangeSummary } from '../schemas';

/* -------------------------------------------------------------------------- */
/* The time deck — the bottom dock that owns history & replay.                 */
/*                                                                            */
/* Range mode (nothing loaded): day pickers + quick chips + Load.              */
/* Replay mode: transport controls, the scrubber with stop ticks, day strip,   */
/* summary stats, overlay toggles. The cursor renders through a tiny external  */
/* store so 60fps playback re-renders ONLY the readout row.                    */
/* -------------------------------------------------------------------------- */

export interface CursorStore {
  get: () => number;
  set: (v: number) => void;
  subscribe: (fn: () => void) => () => void;
}

export function createCursorStore(initial = 0): CursorStore {
  let value = initial;
  const subs = new Set<() => void>();
  return {
    get: () => value,
    set: (v) => {
      value = v;
      subs.forEach((fn) => fn());
    },
    subscribe: (fn) => {
      subs.add(fn);
      return () => subs.delete(fn);
    },
  };
}

const timeFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Africa/Cairo',
  hour12: false,
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
});

function fmtSecs(secs: number): string {
  if (secs <= 0) return '0m';
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
}

/** The 60fps half: cursor readout + scrubber. Isolated so playback re-renders
 *  only this subtree. */
const fullFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Africa/Cairo',
  hour12: false,
  weekday: 'short',
  day: 'numeric',
  month: 'short',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
});

/** The leg whose [depart, arrive] holds `ms`, if any. */
export function legAt(legs: LegSegment[], ms: number): LegSegment | null {
  for (const seg of legs) {
    if (ms >= seg.leg.depart.getTime() && ms <= seg.leg.arrive.getTime()) return seg;
  }
  return null;
}

function ScrubRow({
  cursor,
  track,
  stops,
  legs,
  onScrub,
}: {
  cursor: CursorStore;
  track: NonNullable<HistoryData['track']>;
  stops: Array<{ from: Date }>;
  /** Shown as colored time bands + the current-leg line (empty = legs off). */
  legs: LegSegment[];
  onScrub: (ms: number) => void;
}) {
  const { t } = useTranslation();
  const startMs = track.startMs;
  const endMs = track.endMs;
  const value = React.useSyncExternalStore(cursor.subscribe, cursor.get);
  const span = Math.max(1, endMs - startMs);
  const pct = Math.min(100, Math.max(0, ((value - startMs) / span) * 100));

  // The full state line: complete Cairo timestamp + the speed at the cursor.
  const idx = indexAt(track.timesMs, value || startMs);
  const speed = track.speeds[idx] ?? 0;
  const limit = track.limits[idx] ?? 0;
  const speeding = limit > 0 && speed > limit;

  const current = legs.length > 0 ? legAt(legs, value || startMs) : null;
  const currentColor = current ? legColor(current) : null;

  return (
    <div className="space-y-1.5">
    <div className="flex items-center justify-between gap-3 px-0.5">
      <span className="flex min-w-0 items-center gap-2 font-mono text-[11px] font-semibold tabular-nums">
        {fullFmt.format(new Date(value || startMs))}
        {current && currentColor && (
          <span
            className="flex min-w-0 items-center gap-1.5 rounded-full border px-2 py-0.5 text-[10px] font-semibold"
            style={{ borderColor: `rgb(${currentColor.join(' ')} / .5)` }}
          >
            <span
              className="h-1.5 w-1.5 shrink-0 rounded-full"
              style={{ background: `rgb(${currentColor.join(' ')})` }}
            />
            <span className="truncate">
              {current.leg.fromName ?? '—'} → {current.leg.toName ?? '—'}
            </span>
          </span>
        )}
      </span>
      <span
        className={cn(
          'shrink-0 rounded-md px-1.5 py-0.5 font-mono text-[11px] font-bold tabular-nums',
          speeding ? 'bg-destructive/10 text-destructive' : 'bg-muted text-foreground',
        )}
      >
        {Math.round(speed)} {t('tracking.kmh', 'km/h')}
        {limit > 0 && <span className="ms-1 font-normal text-muted-foreground">/ {Math.round(limit)}</span>}
      </span>
    </div>
    <div className="flex items-center gap-3">
      <span className="w-[74px] shrink-0 text-end font-mono text-[11px] font-semibold tabular-nums">
        {timeFmt.format(new Date(value || startMs))}
      </span>
      <div className="relative min-w-0 flex-1">
        {/* leg time-bands under everything — the replay timeline's idea */}
        {legs.length > 0 && (
          <div className="pointer-events-none absolute inset-x-0 top-1/2 h-3 -translate-y-1/2 overflow-hidden rounded-full">
            {legs.map((seg) => {
              const a = Math.max(0, ((seg.leg.depart.getTime() - startMs) / span) * 100);
              const b = Math.min(100, ((seg.leg.arrive.getTime() - startMs) / span) * 100);
              if (b <= 0 || a >= 100 || b <= a) return null;
              const [r, g, bl] = legColor(seg);
              return (
                <span
                  key={legId(seg)}
                  className="absolute top-0 h-3"
                  style={{
                    insetInlineStart: `${a}%`,
                    width: `${b - a}%`,
                    background: `rgb(${r} ${g} ${bl} / 0.35)`,
                  }}
                />
              );
            })}
          </div>
        )}
        {/* stop ticks under the range input */}
        <div className="pointer-events-none absolute inset-x-0 top-1/2 h-2 -translate-y-1/2">
          {stops.map((s, i) => {
            const p = ((s.from.getTime() - startMs) / span) * 100;
            if (p < 0 || p > 100) return null;
            return (
              <span
                key={i}
                className="absolute top-0 h-2 w-[3px] rounded-sm bg-amber-500/80"
                style={{ insetInlineStart: `${p}%` }}
              />
            );
          })}
        </div>
        <input
          type="range"
          min={startMs}
          max={endMs}
          step={1000}
          value={value || startMs}
          onChange={(e) => onScrub(Number(e.target.value))}
          aria-label="scrub"
          className="relative z-10 h-2 w-full cursor-pointer appearance-none rounded-full bg-muted accent-primary"
          style={{
            background: `linear-gradient(to right, hsl(var(--primary)) ${pct}%, hsl(var(--muted)) ${pct}%)`,
          }}
        />
      </div>
      <span className="w-[74px] shrink-0 font-mono text-[10px] text-muted-foreground tabular-nums">
        {timeFmt.format(new Date(endMs))}
      </span>
    </div>
    </div>
  );
}

export function TimeDeck({
  history,
  track,
  lockedStops,
  beyondRange,
  summary,
  cursor,
  playing,
  speed,
  follow,
  onToggleFollow,
  showStops,
  showIgnitions,
  showPins,
  onTogglePins,
  showLegs,
  onToggleLegs,
  activeLegId,
  onActivateLeg,
  activeTripId,
  onActivateTrip,
  legWindowLoading,
  onJumpLeg,
  onScrub,
  onPlayPause,
  onRestart,
  onSpeed,
  onToggleStops,
  onToggleIgnitions,
  onExit,
}: {
  history: HistoryData;
  /** The clock's world — the range track, or the active leg's when locked. */
  track: HistoryData['track'];
  /** The locked leg's own stops (null = not locked). */
  lockedStops: Array<{ from: Date }> | null;
  /** The locked leg reached beyond the loaded range — data was fetched. */
  beyondRange: boolean;
  summary: RangeSummary | null;
  cursor: CursorStore;
  playing: boolean;
  speed: number;
  follow: boolean;
  onToggleFollow: () => void;
  showStops: boolean;
  showIgnitions: boolean;
  showPins: boolean;
  onTogglePins: () => void;
  showLegs: boolean;
  onToggleLegs: () => void;
  activeLegId: string | null;
  onActivateLeg: (id: string) => void;
  activeTripId: number | null;
  onActivateTrip: (tripId: number) => void;
  /** True while an isolated cut leg is still fetching its missing days. */
  legWindowLoading: boolean;
  /** Seek to the previous/next leg's departure. */
  onJumpLeg: (dir: -1 | 1) => void;
  onScrub: (ms: number) => void;
  onPlayPause: () => void;
  onRestart: () => void;
  onSpeed: (s: number) => void;
  onToggleStops: () => void;
  onToggleIgnitions: () => void;
  onExit: () => void;
}) {
  const { t } = useTranslation();
  const locked = lockedStops !== null;

  return (
    <div className="pointer-events-auto w-full rounded-t-2xl border border-b-0 bg-card/95 shadow-2xl backdrop-blur md:mx-auto md:max-w-3xl">
      {/* header strip: day progress + stats + exit */}
      <div className="flex items-center gap-3 border-b px-3 py-1.5">
        {history.totalCount > 1 && (
          <div className="flex min-w-0 flex-1 items-center gap-2">
            <div className="flex min-w-0 flex-1 gap-0.5">
              {history.days.map((d) => (
                <span
                  key={d.day}
                  title={d.day}
                  className={cn(
                    'h-1 min-w-1 flex-1 rounded-sm',
                    d.status === 'loaded' && 'bg-success',
                    d.status === 'pending' && 'animate-pulse bg-muted',
                    d.status === 'error' && 'bg-destructive',
                  )}
                />
              ))}
            </div>
            <span className="shrink-0 font-mono text-[9px] text-muted-foreground tabular-nums">
              {history.loadedCount}/{history.totalCount}
            </span>
          </div>
        )}
        {summary && (
          <div className="flex shrink-0 items-center gap-3 font-mono text-[10px] text-muted-foreground">
            <span className="font-semibold text-foreground tabular-nums">
              {summary.mileageKm.toFixed(1)} {t('tracking.km', 'km')}
            </span>
            <span className="tabular-nums">{fmtSecs(summary.activeSecs)} ▲</span>
            <span className="tabular-nums">{fmtSecs(summary.idleSecs)} ●</span>
            <span className="tabular-nums">
              {summary.stopCount} {t('tracking.stops', 'stops')}
            </span>
          </div>
        )}
        {beyondRange && (
          <span
            className="shrink-0 rounded-full border border-amber-500/50 bg-amber-500/10 px-2 py-0.5 font-mono text-[9px] font-semibold text-amber-600"
            title={t('tracking.beyondRangeHint', 'This leg extends past the loaded range — its missing days were fetched for the locked view.')}
          >
            ‹ {t('tracking.beyondRange', 'beyond range')} ›
          </span>
        )}
        <button
          type="button"
          onClick={onExit}
          aria-label={t('common.exit', 'Exit')}
          className="ms-auto grid h-6 w-6 shrink-0 place-items-center rounded-md text-muted-foreground hover:bg-destructive/15 hover:text-destructive"
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>

      <div className="space-y-2 px-3 py-2.5">
        {track ? (
          <>
            <ScrubRow
              cursor={cursor}
              track={track}
              stops={showStops ? (lockedStops ?? history.stops) : []}
              legs={showLegs && !locked ? history.legs : []}
              onScrub={onScrub}
            />
            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={onRestart}
                aria-label={t('tracking.restart', 'Restart')}
                className="grid h-8 w-8 place-items-center rounded-lg border bg-background hover:bg-muted"
              >
                <RotateCcw className="h-3.5 w-3.5" />
              </button>
              {showLegs && history.legs.length > 0 && (
                <>
                  <button
                    type="button"
                    onClick={() => onJumpLeg(-1)}
                    aria-label={t('tracking.prevLeg', 'Previous leg')}
                    className="grid h-8 w-8 place-items-center rounded-lg border bg-background hover:bg-muted"
                  >
                    <SkipBack className="h-3.5 w-3.5 rtl:rotate-180" />
                  </button>
                  <button
                    type="button"
                    onClick={() => onJumpLeg(1)}
                    aria-label={t('tracking.nextLeg', 'Next leg')}
                    className="grid h-8 w-8 place-items-center rounded-lg border bg-background hover:bg-muted"
                  >
                    <SkipForward className="h-3.5 w-3.5 rtl:rotate-180" />
                  </button>
                </>
              )}
              <button
                type="button"
                onClick={onPlayPause}
                aria-label={playing ? t('tracking.pause', 'Pause') : t('tracking.play', 'Play')}
                className="grid h-8 w-12 place-items-center rounded-lg bg-primary text-primary-foreground shadow hover:bg-primary/90"
              >
                {playing ? <Pause className="h-4 w-4" /> : <Play className="h-4 w-4" />}
              </button>
              <div className="flex items-center gap-1 ps-1">
                {SPEEDS.map((s) => (
                  <button
                    key={s}
                    type="button"
                    aria-pressed={speed === s}
                    onClick={() => onSpeed(s)}
                    className={cn(
                      'rounded-md border px-1.5 py-1 font-mono text-[10px] font-semibold tabular-nums',
                      speed === s
                        ? 'border-primary/50 bg-primary/10 text-primary'
                        : 'bg-background text-muted-foreground hover:bg-muted',
                    )}
                  >
                    {s}×
                  </button>
                ))}
              </div>

              <div className="ms-auto flex items-center gap-1">
                <button
                  type="button"
                  aria-pressed={follow}
                  onClick={onToggleFollow}
                  title={t('tracking.follow', 'Follow the truck')}
                  className={cn(
                    'grid h-8 w-8 place-items-center rounded-lg border',
                    follow
                      ? 'border-primary/50 bg-primary/10 text-primary'
                      : 'bg-background text-muted-foreground hover:bg-muted',
                  )}
                >
                  <LocateFixed className="h-3.5 w-3.5" />
                </button>
                <button
                  type="button"
                  aria-pressed={showStops}
                  onClick={onToggleStops}
                  title={t('tracking.stops', 'Stops')}
                  className={cn(
                    'grid h-8 w-8 place-items-center rounded-lg border',
                    showStops
                      ? 'border-amber-500/50 bg-amber-500/10 text-amber-600'
                      : 'bg-background text-muted-foreground hover:bg-muted',
                  )}
                >
                  <MapPinned className="h-3.5 w-3.5" />
                </button>
                <button
                  type="button"
                  aria-pressed={showIgnitions}
                  onClick={onToggleIgnitions}
                  title={t('tracking.ignitions', 'Ignitions')}
                  className={cn(
                    'grid h-8 w-8 place-items-center rounded-lg border',
                    showIgnitions
                      ? 'border-muted-foreground/40 bg-muted text-foreground'
                      : 'bg-background text-muted-foreground hover:bg-muted',
                  )}
                >
                  <Flame className="h-3.5 w-3.5" />
                </button>
                <button
                  type="button"
                  aria-pressed={showPins}
                  onClick={onTogglePins}
                  title={t('tracking.places', 'Places')}
                  className={cn(
                    'grid h-8 w-8 place-items-center rounded-lg border',
                    showPins
                      ? 'border-primary/50 bg-primary/10 text-primary'
                      : 'bg-background text-muted-foreground hover:bg-muted',
                  )}
                >
                  <MapPin className="h-3.5 w-3.5" />
                </button>
                <button
                  type="button"
                  aria-pressed={showLegs}
                  onClick={onToggleLegs}
                  title={t('tracking.legs', 'Legs')}
                  className={cn(
                    'grid h-8 w-8 place-items-center rounded-lg border',
                    showLegs
                      ? 'border-violet-500/50 bg-violet-500/10 text-violet-600'
                      : 'bg-background text-muted-foreground hover:bg-muted',
                  )}
                >
                  <Route className="h-3.5 w-3.5" />
                </button>
              </div>
            </div>
            {activeLegId && legWindowLoading && (
              <p className="text-center font-mono text-[10px] text-muted-foreground">
                {t('tracking.legLoading', 'Loading the whole leg…')}
              </p>
            )}
            {showLegs && history.legs.length > 0 && (
              <LegRail
                legs={history.legs}
                activeLegId={activeLegId}
                activeTripId={activeTripId}
                onActivateLeg={onActivateLeg}
                onActivateTrip={onActivateTrip}
              />
            )}
          </>
        ) : history.isLoading ? (
          <p className="py-1 text-center text-xs text-muted-foreground">
            {t('tracking.loadingDay', 'Loading the first day…')}
          </p>
        ) : history.isError ? (
          <p className="py-1 text-center text-xs text-destructive">
            {t('tracking.historyFailed', 'History failed to load')}
          </p>
        ) : (
          <p className="py-1 text-center text-xs text-muted-foreground">
            {t('tracking.noPoints', 'No GPS points in this range.')}
          </p>
        )}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* The leg rail — one horizontal strip (touch-scrollable, so it stays mobile  */
/* friendly): a header chip per TRIP, its leg cards revealed on expand. The   */
/* trip chip's play glyph locks the whole trip; a leg card locks that leg.    */
/* -------------------------------------------------------------------------- */

function LegRail({
  legs,
  activeLegId,
  activeTripId,
  onActivateLeg,
  onActivateTrip,
}: {
  legs: LegSegment[];
  activeLegId: string | null;
  activeTripId: number | null;
  onActivateLeg: (id: string) => void;
  onActivateTrip: (tripId: number) => void;
}) {
  const { t } = useTranslation();
  const [expanded, setExpanded] = React.useState<Set<number>>(new Set());

  const trips = React.useMemo(() => {
    const m2 = new Map<number, LegSegment[]>();
    for (const seg of legs) {
      if (!m2.has(seg.leg.parentTripId)) m2.set(seg.leg.parentTripId, []);
      m2.get(seg.leg.parentTripId)!.push(seg);
    }
    return [...m2.entries()];
  }, [legs]);

  const anyLock = activeLegId !== null || activeTripId !== null;

  return (
    <div className="flex items-stretch gap-1.5 overflow-x-auto pb-0.5 pt-0.5 [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
      {trips.map(([tripId, members]) => {
        const [r, g, b] = members[0].color;
        const tripActive = activeTripId === tripId;
        const open = expanded.has(tripId) || tripActive || members.some(
          (m3) => `${m3.leg.parentTripId}:${m3.leg.seq}` === activeLegId,
        );
        const km = members.reduce((s2, m3) => s2 + (m3.leg.actualKm ?? 0), 0);
        const cut = members.some((m3) => m3.cutStart || m3.cutEnd);
        const first = members[0].leg;
        const last = members[members.length - 1].leg;
        return (
          <React.Fragment key={tripId}>
            <div
              className={cn(
                'flex shrink-0 items-center overflow-hidden rounded-lg border transition-opacity',
                tripActive ? 'border-transparent text-white' : 'bg-background',
                anyLock && !tripActive && !open && 'opacity-40',
              )}
              style={tripActive ? { background: `rgb(${r} ${g} ${b})` } : undefined}
            >
              <button
                type="button"
                aria-expanded={open}
                onClick={() =>
                  setExpanded((prev) => {
                    const next = new Set(prev);
                    if (next.has(tripId)) next.delete(tripId);
                    else next.add(tripId);
                    return next;
                  })
                }
                className="flex flex-col items-start px-2 py-1 text-start"
              >
                <span className="flex items-center gap-1.5 font-mono text-[10px] font-bold">
                  <span
                    className="h-1.5 w-1.5 rounded-full"
                    style={{ background: tripActive ? '#fff' : `rgb(${r} ${g} ${b})` }}
                  />
                  {cut && '‹'}#{tripId}
                  <span className={tripActive ? 'text-white/80' : 'text-muted-foreground'}>
                    · {members.length} {t('tracking.legsShort', 'legs')}
                  </span>
                  {cut && '›'}
                </span>
                <span
                  className={cn(
                    'ps-3 font-mono text-[9px] tabular-nums',
                    tripActive ? 'text-white/80' : 'text-muted-foreground',
                  )}
                >
                  {first.fromName ?? '—'} → {last.toName ?? '—'}
                  {km > 0 && ` · ${km.toFixed(0)} km`}
                </span>
              </button>
              <button
                type="button"
                aria-pressed={tripActive}
                onClick={() => onActivateTrip(tripId)}
                title={t('tracking.lockTrip', 'Lock playback to this trip')}
                className={cn(
                  'grid h-full w-7 place-items-center border-s',
                  tripActive
                    ? 'border-white/25 text-white'
                    : 'text-muted-foreground hover:bg-muted',
                )}
              >
                <Play className="h-3 w-3" />
              </button>
            </div>
            {open &&
              members.map((seg) => {
                const id = legId(seg);
                const [lr, lg, lb] = seg.color;
                const active = activeLegId === id;
                return (
                  <button
                    key={id}
                    type="button"
                    aria-pressed={active}
                    onClick={() => onActivateLeg(id)}
                    title={`${seg.leg.fromName ?? '—'} → ${seg.leg.toName ?? '—'}`}
                    className={cn(
                      'flex shrink-0 flex-col items-start gap-0 rounded-lg border px-2 py-1 text-start transition-opacity',
                      active ? 'border-transparent text-white' : 'bg-background hover:bg-muted',
                      anyLock && !active && 'opacity-40 hover:opacity-100',
                    )}
                    style={active ? { background: `rgb(${lr} ${lg} ${lb})` } : undefined}
                  >
                    <span className="flex items-center gap-1.5 font-mono text-[10px] font-bold">
                      <span
                        className="h-1.5 w-1.5 rounded-full"
                        style={{ background: active ? '#fff' : `rgb(${lr} ${lg} ${lb})` }}
                      />
                      {seg.cutStart && '‹'}
                      <span className={active ? '' : 'text-foreground'}>
                        {seg.leg.fromName ?? '—'} → {seg.leg.toName ?? '—'}
                      </span>
                      {seg.cutEnd && '›'}
                    </span>
                    <span
                      className={cn(
                        'ps-3 font-mono text-[9px] tabular-nums',
                        active ? 'text-white/80' : 'text-muted-foreground',
                      )}
                    >
                      {timeFmt.format(seg.leg.depart).slice(0, 5)}–
                      {timeFmt.format(seg.leg.arrive).slice(0, 5)}
                      {seg.leg.actualKm != null && ` · ${seg.leg.actualKm.toFixed(0)} km`}
                    </span>
                  </button>
                );
              })}
          </React.Fragment>
        );
      })}
    </div>
  );
}

import * as React from 'react';
import { setOptions, importLibrary } from '@googlemaps/js-api-loader';
import { GoogleMapsOverlay } from '@deck.gl/google-maps';
import { STATUS_COLOR, statusGroup, type LiveStatus, type Vehicle } from '../schemas';
import { buildStaticLayers, buildTailLayer, type HistoryLayerInput } from './layers';
import { buildMarkerSvg, markerSize } from '@/shared/lib/maps/marker-svg';
import type { SensorEvent, Stop } from '../schemas';
import type { LegSegment } from '../use-history';
import { legId, type PinCluster } from './layers';
import { sampleAt } from '../playback';

/* -------------------------------------------------------------------------- */
/* The map host. One Google vector map + one deck.gl overlay, driven          */
/* imperatively through a ref so replay frames never touch React:             */
/*                                                                            */
/*   setHistory(input)   — rebuild the static GPU layers (data changed)       */
/*   setCursor(ms)       — one uniform update + one DOM transform per frame   */
/*   setLive(vehicles)   — reconcile the 22 plate-chip markers                */
/*   fitTo / flyTo       — camera                                             */
/* -------------------------------------------------------------------------- */

export interface LiveMarkerDatum {
  vehicle: Vehicle;
  live: LiveStatus | null;
  selected: boolean;
  hidden: boolean;
}

export interface TrackingMapHandle {
  setHistory(input: HistoryLayerInput | null): void;
  /** Camera follows the replay marker while playing. */
  setFollow(on: boolean): void;
  /** Basemap: streets or satellite hybrid. */
  setMapType(type: 'roadmap' | 'hybrid'): void;
  setCursor(ms: number | null): void;
  setLive(data: LiveMarkerDatum[]): void;
  fitTo(coords: [number, number][]): void;
  flyTo(lng: number, lat: number, zoom?: number): void;
}

interface Props {
  onSelect: (vehicleId: string) => void;
  /** The user grabbed the map — the page usually turns follow off. */
  onUserPan?: () => void;
  /** A leg segment was tapped on the map. */
  onActivateLeg?: (legId: string) => void;
  onMapReady?: () => void;
  className?: string;
}

const FALLBACK_CENTER = { lat: 30.0444, lng: 31.2357 };

let loaderConfigured = false;
function configureLoader() {
  if (loaderConfigured) return;
  setOptions({ key: (import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string) ?? '', v: 'weekly' });
  loaderConfigured = true;
}

function digits(plate: string): string {
  const d = plate.replace(/\D/g, '');
  return d || plate.trim();
}

/** A live vehicle renders as the ORIGINAL vehicle marker SVG with the plate
 *  digits chip beneath it — the artwork the fleet already knows. */
function chipElement(datum: LiveMarkerDatum): HTMLElement {
  const group = statusGroup(datum.live?.status ?? datum.vehicle.status);
  const color = STATUS_COLOR[group];
  const size = markerSize('vehicle');
  const el = document.createElement('div');
  el.style.cssText = 'display:flex;flex-direction:column;align-items:center;cursor:pointer';
  const img = document.createElement('img');
  img.src = buildMarkerSvg(color, `trk-live-${datum.vehicle.id}`, 'vehicle');
  img.width = size.width;
  img.height = size.height;
  img.style.cssText = datum.selected ? 'filter:drop-shadow(0 0 6px rgba(31,58,95,.9))' : '';
  img.draggable = false;
  const label = document.createElement('span');
  label.textContent = digits(datum.vehicle.plate);
  label.style.cssText =
    'margin-top:1px;padding:0 5px;border-radius:6px;background:rgba(17,19,24,.85);color:#fff;' +
    'font:600 10px ui-monospace,monospace;letter-spacing:.03em;line-height:15px;' +
    (datum.selected ? `box-shadow:0 0 0 1.5px ${color}` : '');
  el.append(img, label);
  return el;
}

/** The replay position marker — the same vehicle artwork in trail blue. */
function replayElement(): HTMLElement {
  const size = markerSize('vehicle');
  const el = document.createElement('div');
  const img = document.createElement('img');
  img.src = buildMarkerSvg('#1d4ed8', 'trk-replay', 'vehicle');
  img.width = size.width;
  img.height = size.height;
  img.draggable = false;
  el.appendChild(img);
  return el;
}

const infoTimeFmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Africa/Cairo',
  hour12: false,
  day: 'numeric',
  month: 'short',
  hour: '2-digit',
  minute: '2-digit',
});

const esc = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/**
 * The one tooltip shell every marker uses: a left-aligned card with the
 * title row, the detail rows, and a footer button that opens the exact
 * coordinate in Google Maps. Direction-aware; text is never selectable.
 */
function tipShell(title: string, rows: string[], lat: number, lng: number): string {
  const mapsUrl = `https://www.google.com/maps?q=${lat.toFixed(6)},${lng.toFixed(6)}`;
  const body = rows.filter(Boolean).join('');
  return (
    `<div dir="auto" style="font:12px system-ui;display:grid;gap:3px;min-width:150px;max-width:250px;` +
    `user-select:none;text-align:start;padding:2px 2px 0">` +
    `<div style="display:flex;align-items:center;justify-content:space-between;gap:10px">` +
    `<div style="font-weight:700;min-width:0">${title}</div>` +
    `<a href="${mapsUrl}" target="_blank" rel="noopener" title="Google Maps" ` +
    `style="flex:none;display:grid;place-items:center;width:24px;height:24px;border-radius:6px;` +
    `border:1px solid #d6d9e0;color:#1f3a5f;text-decoration:none;background:#fff">` +
    `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" ` +
    `stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">` +
    `<path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>` +
    `<polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>` +
    `</a>` +
    `</div>` +
    body +
    `</div>`
  );
}

const row = (html: string) => `<div style="line-height:1.45">${html}</div>`;
const dimRow = (html: string) => `<div style="color:#6b7280;line-height:1.45">${html}</div>`;

function vehicleInfoHtml(datum: LiveMarkerDatum, lat: number, lng: number): string {
  const live = datum.live;
  return tipShell(
    `<span style="font:700 14px ui-monospace,monospace">${esc(datum.vehicle.plate)}</span>`,
    [
      row(esc(live?.statusLabel ?? datum.vehicle.statusLabel)),
      live && live.speed > 0 ? row(`${Math.round(live.speed)} km/h`) : '',
      live?.timestamp || datum.vehicle.lastLocationAt
        ? dimRow(infoTimeFmt.format((live?.timestamp ?? datum.vehicle.lastLocationAt)!))
        : '',
    ],
    lat,
    lng,
  );
}

function stopInfoHtml(stop: Stop): string {
  return tipShell(
    esc(stop.duration),
    [
      stop.address ? row(esc(stop.address)) : '',
      dimRow(`${infoTimeFmt.format(stop.from)} → ${infoTimeFmt.format(stop.to)}`),
    ],
    stop.lat,
    stop.lng,
  );
}

function fmtDwell(secs: number): string {
  const h = Math.floor(secs / 3600);
  const mm = Math.floor((secs % 3600) / 60);
  return h > 0 ? `${h}h ${mm}m` : `${mm}m`;
}

/** One marker can stand for several back-to-back visits — list them all. */
function pinInfoHtml(cluster: PinCluster): string {
  const head = cluster.visits[0];
  return tipShell(
    esc(head.name),
    [
      dimRow(esc(cluster.kind)),
      ...cluster.visits.map((pin) => {
        const bits = [
          pin.parentTripId ? `#${pin.parentTripId}` : '',
          pin.arrive ? `▾ ${infoTimeFmt.format(pin.arrive)}` : '',
          pin.depart ? `▴ ${infoTimeFmt.format(pin.depart)}` : '',
          pin.dwellSecs != null && pin.dwellSecs > 0 ? `<b>${fmtDwell(pin.dwellSecs)}</b>` : '',
        ].filter(Boolean);
        return row(`<span dir="ltr">${bits.join(' · ')}</span>`);
      }),
    ],
    cluster.lat,
    cluster.lng,
  );
}

function legInfoHtml(seg: LegSegment, lat: number, lng: number): string {
  const l = seg.leg;
  return tipShell(
    `${esc(l.fromName ?? '—')} → ${esc(l.toName ?? '—')}`,
    [
      dimRow(`${esc(l.legType)} · #${l.parentTripId}·${l.seq}`),
      row(`<span dir="ltr">${infoTimeFmt.format(l.depart)} → ${infoTimeFmt.format(l.arrive)}</span>`),
      l.actualKm != null ? row(`<b>${l.actualKm.toFixed(1)} km</b>`) : '',
      l.actualSecs != null ? row(fmtDwell(l.actualSecs)) : '',
      seg.cutStart || seg.cutEnd
        ? `<div style="color:#b45309;line-height:1.45">⟷ continues beyond the loaded range</div>`
        : '',
    ],
    lat,
    lng,
  );
}

function sensorInfoHtml(ev: SensorEvent): string {
  return tipShell(esc(ev.typeName), [dimRow(infoTimeFmt.format(ev.timestamp))], ev.lat, ev.lng);
}

function endpointInfoHtml(kind: 'route-start' | 'route-end', lat: number, lng: number): string {
  const label = kind === 'route-start' ? 'Route start' : 'Route end';
  return tipShell(esc(label), [], lat, lng);
}

export const TrackingMap = React.forwardRef<TrackingMapHandle, Props>(
  function TrackingMap({ onSelect, onUserPan, onActivateLeg, onMapReady, className }, ref) {
    const containerRef = React.useRef<HTMLDivElement>(null);
    const mapRef = React.useRef<google.maps.Map | null>(null);
    const overlayRef = React.useRef<GoogleMapsOverlay | null>(null);
    const markersRef = React.useRef<
      Map<string, { marker: google.maps.marker.AdvancedMarkerElement; fingerprint: string }>
    >(new Map());
    const replayMarkerRef = React.useRef<google.maps.marker.AdvancedMarkerElement | null>(null);
    const historyRef = React.useRef<HistoryLayerInput | null>(null);
    const cursorRef = React.useRef<number | null>(null);
    const readyRef = React.useRef(false);
    const pendingLiveRef = React.useRef<LiveMarkerDatum[] | null>(null);
    const infoRef = React.useRef<google.maps.InfoWindow | null>(null);
    const followRef = React.useRef(true);
    const lastPanRef = React.useRef(0);
    const lastPickRef = React.useRef<{ key: string; at: number }>({ key: '', at: 0 });
    const pickAtRef = React.useRef(0);
    const onSelectRef = React.useRef(onSelect);
    const onUserPanRef = React.useRef(onUserPan);
    const onActivateLegRef = React.useRef(onActivateLeg);
    React.useEffect(() => {
      onSelectRef.current = onSelect;
      onUserPanRef.current = onUserPan;
      onActivateLegRef.current = onActivateLeg;
    });

    const staticLayersRef = React.useRef<ReturnType<typeof buildStaticLayers>>([]);

    /** Recompute the static layers (data/toggles/cursor-day changed). */
    const rebuildStatic = React.useCallback(() => {
      const h = historyRef.current;
      staticLayersRef.current = h ? buildStaticLayers(h) : [];
    }, []);

    /** Push static + tail. Per replay frame only the tail layer is new —
     *  the cached statics diff to no-ops inside deck. */
    const pushLayers = React.useCallback(() => {
      const overlay = overlayRef.current;
      if (!overlay) return;
      const h = historyRef.current;
      if (!h) {
        overlay.setProps({ layers: [] });
        return;
      }
      const layers = [...staticLayersRef.current];
      if (h.track && cursorRef.current !== null) {
        layers.push(buildTailLayer(h.track, cursorRef.current));
      }
      overlay.setProps({ layers });
    }, []);

    const applyLive = React.useCallback((data: LiveMarkerDatum[]) => {
      const map = mapRef.current;
      if (!map || !readyRef.current) {
        pendingLiveRef.current = data;
        return;
      }
      const markers = markersRef.current;
      const seen = new Set<string>();
      for (const datum of data) {
        const id = datum.vehicle.id;
        const lat = datum.live?.lat ?? datum.vehicle.lat;
        const lng = datum.live?.lng ?? datum.vehicle.lng;
        if (datum.hidden || lat == null || lng == null || (lat === 0 && lng === 0)) continue;
        seen.add(id);
        const fingerprint = [
          lat.toFixed(5),
          lng.toFixed(5),
          datum.live?.status ?? datum.vehicle.status,
          datum.selected ? 's' : '',
        ].join('|');
        const existing = markers.get(id);
        if (existing) {
          if (existing.fingerprint === fingerprint) continue;
          existing.marker.position = { lat, lng };
          existing.marker.content = chipElement(datum);
          existing.fingerprint = fingerprint;
        } else {
          const marker = new google.maps.marker.AdvancedMarkerElement({
            map,
            position: { lat, lng },
            content: chipElement(datum),
            zIndex: datum.selected ? 20 : 10,
            // Without this the marker neither receives clicks nor shows a
            // pointer cursor — taps fall through to the map beneath it.
            gmpClickable: true,
          });
          marker.addListener('click', () => {
            const now = performance.now();
            const isDouble =
              lastPickRef.current.key === `v:${id}` && now - lastPickRef.current.at < 350;
            lastPickRef.current = { key: `v:${id}`, at: now };
            const pos = marker.position as google.maps.LatLngLiteral | null;
            if (isDouble && pos) {
              infoRef.current?.close();
              map.panTo(pos);
              map.setZoom(Math.max(map.getZoom() ?? 0, 16));
              return;
            }
            onSelectRef.current(id);
            if (infoRef.current && pos) {
              // Guard against the map click that follows — it was closing
              // this tooltip the instant it opened.
              pickAtRef.current = now;
              const latN = typeof pos.lat === 'function' ? (pos.lat as () => number)() : pos.lat;
              const lngN = typeof pos.lng === 'function' ? (pos.lng as () => number)() : pos.lng;
              infoRef.current.setContent(vehicleInfoHtml(datum, latN, lngN));
              infoRef.current.setOptions({ pixelOffset: new google.maps.Size(0, 0) });
              // Anchoring to the marker aligns the window above the artwork.
              infoRef.current.open({ map, anchor: marker });
            }
          });
          markers.set(id, { marker, fingerprint });
        }
      }
      for (const [id, entry] of markers) {
        if (!seen.has(id)) {
          entry.marker.map = null;
          markers.delete(id);
        }
      }
    }, []);

    React.useImperativeHandle(
      ref,
      (): TrackingMapHandle => ({
        setHistory(input) {
          historyRef.current = input;
          if (!input?.track) {
            cursorRef.current = null;
            if (replayMarkerRef.current) replayMarkerRef.current.map = null;
            replayMarkerRef.current = null;
          }
          rebuildStatic();
          pushLayers();
        },
        setFollow(on) {
          followRef.current = on;
        },
        setMapType(type) {
          mapRef.current?.setMapTypeId(type);
        },
        setCursor(ms) {
          cursorRef.current = ms;
          const h = historyRef.current;
          if (!h?.track || ms === null) return;
          // One uniform update on the GPU tail…
          pushLayers();
          // …and one DOM transform on the marker.
          const map = mapRef.current;
          if (!map) return;
          const sample = sampleAt(h.track, ms);
          // Auto-follow: keep the runner centred, panning at most ~3×/s so
          // the camera glides instead of jittering.
          const now = performance.now();
          if (followRef.current && now - lastPanRef.current > 350) {
            lastPanRef.current = now;
            map.panTo({ lat: sample.lat, lng: sample.lng });
          }
          if (!replayMarkerRef.current) {
            replayMarkerRef.current = new google.maps.marker.AdvancedMarkerElement({
              map,
              position: { lat: sample.lat, lng: sample.lng },
              content: replayElement(),
              zIndex: 30,
            });
          } else {
            replayMarkerRef.current.position = { lat: sample.lat, lng: sample.lng };
          }
          const arrow = (replayMarkerRef.current.content as HTMLElement | null)?.querySelector(
            '[data-arrow]',
          ) as HTMLElement | null;
          if (arrow) arrow.style.transform = `rotate(${sample.heading}deg)`;
        },
        setLive: applyLive,
        fitTo(coords) {
          const map = mapRef.current;
          if (!map || coords.length === 0) return;
          const bounds = new google.maps.LatLngBounds();
          for (const [lng, lat] of coords) bounds.extend({ lat, lng });
          map.fitBounds(bounds, 64);
        },
        flyTo(lng, lat, zoom = 15) {
          const map = mapRef.current;
          if (!map) return;
          map.panTo({ lat, lng });
          map.setZoom(zoom);
        },
      }),
      [applyLive, pushLayers, rebuildStatic],
    );

    React.useEffect(() => {
      let cancelled = false;
      configureLoader();
      void Promise.all([importLibrary('maps'), importLibrary('marker')]).then(() => {
        if (cancelled || !containerRef.current) return;
        const map = new google.maps.Map(containerRef.current, {
          center: FALLBACK_CENTER,
          zoom: 8,
          mapId: (import.meta.env.VITE_GOOGLE_MAPS_MAP_ID as string) || 'DEMO_MAP_ID',
          disableDefaultUI: true,
          zoomControl: true,
          gestureHandling: 'greedy',
          clickableIcons: false,
          disableDoubleClickZoom: true,
        });
        const overlay = new GoogleMapsOverlay({
          onClick: (info: {
            object?: unknown;
            layer?: { id: string } | null;
            coordinate?: number[];
          }) => {
            if (!info.object || !info.layer || !info.coordinate) return;
            const [lng, lat] = info.coordinate;
            const key = `${info.layer.id}:${lng.toFixed(6)},${lat.toFixed(6)}`;
            const now = performance.now();
            const isDouble =
              lastPickRef.current.key === key && now - lastPickRef.current.at < 350;
            lastPickRef.current = { key, at: now };
            if (isDouble) {
              infoRef.current?.close();
              map.panTo({ lat, lng });
              map.setZoom(Math.max(map.getZoom() ?? 0, 16));
              return;
            }
            if (info.layer.id === 'legs' || info.layer.id === 'legs-garage') {
              onActivateLegRef.current?.(legId(info.object as LegSegment));
            }
            const html =
              info.layer.id === 'stops'
                ? stopInfoHtml(info.object as Stop)
                : info.layer.id === 'sensors'
                  ? sensorInfoHtml(info.object as SensorEvent)
                  : info.layer.id === 'trip-pins'
                    ? pinInfoHtml(info.object as PinCluster)
                    : info.layer.id === 'endpoints'
                      ? endpointInfoHtml(
                          (info.object as { kind: 'route-start' | 'route-end' }).kind,
                          lat,
                          lng,
                        )
                      : info.layer.id === 'legs' || info.layer.id === 'legs-garage'
                        ? legInfoHtml(info.object as LegSegment, lat, lng)
                        : null;
            if (html && infoRef.current) {
              pickAtRef.current = performance.now();
              infoRef.current.setContent(html);
              infoRef.current.setPosition({ lat, lng });
              // Lift the window clear of the icon artwork beneath it.
              infoRef.current.setOptions({
                pixelOffset: new google.maps.Size(
                  0,
                  info.layer.id === 'trip-pins' || info.layer.id === 'endpoints' ? -30 : -14,
                ),
              });
              infoRef.current.open({ map });
            }
          },
          onHover: (info: { object?: unknown }) => {
            // A pointer over a pickable object reads as clickable.
            mapRef.current?.setOptions({
              draggableCursor: info.object ? 'pointer' : null,
            });
          },
        });
        overlay.setMap(map);
        infoRef.current = new google.maps.InfoWindow({ headerDisabled: true });
        map.addListener('click', () => {
          // The map click that accompanies a deck pick must not close the
          // tooltip the pick just opened.
          if (performance.now() - pickAtRef.current > 250) infoRef.current?.close();
        });
        map.addListener('dragstart', () => onUserPanRef.current?.());
        // Double-press on a picked object flies in (native dblclick zoom is
        // off, and Google swallows the second click, so we pick manually).
        map.addListener('dblclick', (e: google.maps.MapMouseEvent) => {
          const dom = e.domEvent as MouseEvent | undefined;
          const el = containerRef.current;
          if (!dom || !el) return;
          const rect = el.getBoundingClientRect();
          try {
            const picked = overlay.pickObject({
              x: dom.clientX - rect.left,
              y: dom.clientY - rect.top,
              radius: 12,
            }) as { coordinate?: number[] } | null;
            if (picked?.coordinate) {
              infoRef.current?.close();
              const [lng, lat] = picked.coordinate;
              map.panTo({ lat, lng });
              map.setZoom(Math.max(map.getZoom() ?? 0, 16));
            }
          } catch {
            /* picking unavailable — ignore */
          }
        });
        mapRef.current = map;
        overlayRef.current = overlay;
        readyRef.current = true;
        rebuildStatic();
        if (pendingLiveRef.current) {
          applyLive(pendingLiveRef.current);
          pendingLiveRef.current = null;
        }
        pushLayers();
        onMapReady?.();
      });
      return () => {
        cancelled = true;
        infoRef.current?.close();
        infoRef.current = null;
        overlayRef.current?.finalize();
        overlayRef.current = null;
        for (const { marker } of markersRef.current.values()) marker.map = null;
        markersRef.current.clear();
        if (replayMarkerRef.current) replayMarkerRef.current.map = null;
        replayMarkerRef.current = null;
        mapRef.current = null;
        readyRef.current = false;
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return <div ref={containerRef} className={className} />;
  },
);

