import { useRouteError, isRouteErrorResponse, useNavigate } from 'react-router-dom';
import { AlertTriangle, RefreshCw, Home, ChevronLeft } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from '@/shared/ui/card';
import { useTranslation } from 'react-i18next';

export default function RouteErrorPage() {
  const error = useRouteError();
  const navigate = useNavigate();
  const { t } = useTranslation();

  console.error('Route error caught by ErrorBoundary:', error);

  let title = t('errors.unexpected.title');
  let message = t('errors.unexpected.message');
  let isChunkError = false;

  if (isRouteErrorResponse(error)) {
    if (error.status === 404) {
      title = t('errors.404.title');
      message = t('errors.404.message');
    } else {
      message = error.statusText || message;
    }
  } else if (error instanceof Error) {
    message = error.message;
    // Catch the specific "Failed to fetch dynamically imported module" error
    if (
      message.includes('Failed to fetch dynamically imported module') ||
      message.includes('error loading dynamically imported module')
    ) {
      isChunkError = true;
      title = t('errors.chunkLoad.title', 'Application Update');
      message = t(
        'errors.chunkLoad.message',
        'A new version of the application is available. Please refresh the page to continue.'
      );
    }
  }

  const handleRefresh = () => {
    window.location.reload();
  };

  const handleGoBack = () => {
    navigate(-1);
  };

  const handleGoHome = () => {
    navigate('/');
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-muted/30 p-4 md:p-6 lg:p-8">
      <Card className="w-full max-w-md shadow-2xl border-2 border-primary/10">
        <CardHeader className="text-center pt-8">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-destructive/10 text-destructive">
            <AlertTriangle className="h-8 w-8" />
          </div>
          <CardTitle className="text-2xl font-bold tracking-tight">{title}</CardTitle>
        </CardHeader>
        <CardContent className="text-center px-8 pb-8">
          <p className="text-muted-foreground leading-relaxed">
            {message}
          </p>
          {isChunkError && (
            <div className="mt-4 p-3 bg-primary/5 rounded-lg border border-primary/10 text-sm font-medium text-primary">
              {t('errors.chunkLoad.hint', 'This usually happens after a new deployment.')}
            </div>
          )}
        </CardContent>
        <CardFooter className="flex flex-col gap-2 p-6 bg-muted/20">
          {isChunkError ? (
            <Button onClick={handleRefresh} className="w-full gap-2 py-6 text-base font-bold shadow-lg shadow-primary/20" size="lg">
              <RefreshCw className="h-5 w-5" />
              {t('common.refreshNow', 'Refresh Now')}
            </Button>
          ) : (
            <>
              <Button onClick={handleGoBack} variant="default" className="w-full gap-2" size="lg">
                <ChevronLeft className="h-5 w-5" />
                {t('common.goBack')}
              </Button>
              <div className="grid grid-cols-2 gap-2 w-full mt-2">
                <Button onClick={handleRefresh} variant="outline" className="gap-2">
                  <RefreshCw className="h-4 w-4" />
                  {t('common.retry')}
                </Button>
                <Button onClick={handleGoHome} variant="outline" className="gap-2">
                  <Home className="h-4 w-4" />
                  {t('common.home')}
                </Button>
              </div>
            </>
          )}
        </CardFooter>
      </Card>
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from '@/shared/ui/toaster';
import { AlertCircle, Banknote, Download, Loader2, RefreshCw } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Card, CardContent } from '@/shared/ui/card';
import { Skeleton } from '@/shared/ui/skeleton';
import { ConfirmDialog } from '@/shared/ui/confirm-dialog';
import { PageShell } from '@/shared/ui/page-shell';
import { extractErrorMessage } from '@/shared/api/errors';
import {
  useBulkEnrichFeeMappings,
  useDeleteFeeMapping,
  useFeeMappings,
} from '@/entities/fee-mapping/queries';
import {
  calculateAccuracy,
  type EnrichmentResult,
  type FeeMapping,
} from '@/entities/fee-mapping/schemas';
import { FeeMappingsStats } from '@/widgets/fee-mappings/fee-mappings-stats';
import {
  FeeMappingsFilters,
  type FeeMappingsFilterState,
} from '@/widgets/fee-mappings/fee-mappings-filters';
import { FeeMappingsForm } from '@/widgets/fee-mappings/fee-mappings-form';
import { FeeMappingsTable } from '@/widgets/fee-mappings/fee-mappings-table';
import { FeeMappingLocationDialog } from '@/widgets/fee-mappings/fee-mappings-location-dialog';
import { BulkEnrichDialog } from '@/widgets/fee-mappings/fee-mappings-bulk-enrich-dialog';
import { exportFeeMappingsExcel } from '@/widgets/fee-mappings/fee-mappings-excel';

/**
 * Fee mappings admin page.
 *
 * Composes filter bar, stats strip, add/edit form, the data table, and
 * three dialogs (location picker, bulk-enrich results, delete confirm).
 * All server-state lives in the entity layer's queries; this component
 * only owns UI state.
 */
export function FeeMappingsPage() {
  const { t } = useTranslation();

  /* ---- Server data ---- */
  const { data: mappings = [], isLoading, isError, refetch } = useFeeMappings();
  const deleteMutation = useDeleteFeeMapping();
  const bulkEnrich = useBulkEnrichFeeMappings();

  /* ---- UI state ---- */
  const [filters, setFilters] = React.useState<FeeMappingsFilterState>({
    search: '',
    company: '',
    accuracy: 'all',
  });
  const [editing, setEditing] = React.useState<FeeMapping | null>(null);
  const [locationTarget, setLocationTarget] = React.useState<FeeMapping | null>(null);
  const [pendingDelete, setPendingDelete] = React.useState<FeeMapping | null>(null);
  const [enrichResults, setEnrichResults] = React.useState<EnrichmentResult[] | null>(null);

  /* ---- Filtering ---- */
  const filtered = React.useMemo(() => {
    const search = filters.search.trim().toLowerCase();
    return mappings.filter((m) => {
      if (filters.company && m.company !== filters.company) return false;
      if (filters.accuracy !== 'all') {
        const { kind } = calculateAccuracy(m.distance, m.osrmDistanceKm);
        if (kind !== filters.accuracy) return false;
      }
      if (search) {
        const haystack = `${m.company} ${m.terminal} ${m.dropOffPoint}`.toLowerCase();
        if (!haystack.includes(search)) return false;
      }
      return true;
    });
  }, [mappings, filters]);

  /**
   * Build a human-readable summary of the active filters for the Excel
   * meta line. Skipped when no filters are active.
   */
  const filterMeta = React.useMemo(() => {
    const parts: string[] = [];
    if (filters.company) parts.push(`Company: ${filters.company}`);
    if (filters.accuracy !== 'all') {
      parts.push(`Accuracy: ${t(`feeMappings.accuracy.${filters.accuracy}`)}`);
    }
    if (filters.search) parts.push(`Search: "${filters.search}"`);
    return parts.length ? parts.join(' · ') : undefined;
  }, [filters, t]);

  /* ---- Handlers ---- */

  const handleEdit = (m: FeeMapping) => {
    setEditing(m);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async () => {
    if (!pendingDelete) return;
    try {
      await deleteMutation.mutateAsync(pendingDelete.id);
      toast.success(t('feeMappings.delete.success'));
      setPendingDelete(null);
    } catch (err) {
      toast.error(extractErrorMessage(err, t('feeMappings.delete.failed')));
    }
  };

  const handleBulkEnrich = async () => {
    try {
      const results = await bulkEnrich.mutateAsync();
      setEnrichResults(results);
    } catch (err) {
      toast.error(extractErrorMessage(err, t('feeMappings.bulkEnrich.failed')));
    }
  };

  const handleExport = () => {
    if (filtered.length === 0) {
      toast.error(t('feeMappings.export.empty'));
      return;
    }
    void exportFeeMappingsExcel(filtered, { filterMeta });
  };

  /* ---- Render ---- */

  const actions = (
    <>
      <Button
        size="sm"
        variant="outline"
        onClick={() => void handleBulkEnrich()}
        disabled={bulkEnrich.isPending}
        className="gap-1.5"
      >
        {bulkEnrich.isPending ? (
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
        ) : (
          <RefreshCw className="h-3.5 w-3.5" />
        )}
        {t('feeMappings.actions.bulkEnrich')}
      </Button>
      <Button
        size="sm"
        onClick={handleExport}
        disabled={filtered.length === 0}
        className="gap-1.5"
      >
        <Download className="h-3.5 w-3.5" />
        {t('feeMappings.actions.export')}
      </Button>
    </>
  );

  return (
    <PageShell
      title={t('feeMappings.pageTitle')}
      description={t('feeMappings.pageSubtitle')}
      icon={<Banknote className="h-5 w-5" />}
      actions={actions}
    >

      {/* Error banner */}
      {isError && (
        <Card className="border-destructive/30 bg-destructive/5">
          <CardContent className="flex items-start gap-3 p-4">
            <AlertCircle className="mt-0.5 h-4 w-4 shrink-0 text-destructive" />
            <div className="flex-1 text-sm">
              <p className="font-medium">{t('feeMappings.errors.loadFailed')}</p>
              <Button
                variant="link"
                size="sm"
                className="h-auto p-0"
                onClick={() => void refetch()}
              >
                {t('common.retry')}
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Stats */}
      {isLoading ? (
        <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-5">
          {Array.from({ length: 5 }).map((_, i) => (
            <Skeleton key={i} className="h-16 rounded-lg" />
          ))}
        </div>
      ) : (
        <FeeMappingsStats mappings={mappings} />
      )}

      {/* Add/edit form */}
      <FeeMappingsForm
        editing={editing}
        onCancelEdit={() => setEditing(null)}
        onSaved={() => setEditing(null)}
      />

      {/* Filters */}
      <FeeMappingsFilters
        state={filters}
        onChange={setFilters}
        mappings={mappings}
        filteredCount={filtered.length}
      />

      {/* Table */}
      <FeeMappingsTable
        mappings={filtered}
        loading={isLoading}
        onEdit={handleEdit}
        onDelete={(m) => setPendingDelete(m)}
        onSetLocation={(m) => setLocationTarget(m)}
      />

      {/* Location dialog */}
      <FeeMappingLocationDialog
        mapping={locationTarget}
        onOpenChange={(open) => !open && setLocationTarget(null)}
      />

      {/* Bulk enrich results */}
      <BulkEnrichDialog
        results={enrichResults}
        onOpenChange={(open) => !open && setEnrichResults(null)}
      />

      {/* Delete confirm */}
      <ConfirmDialog
        open={pendingDelete !== null}
        onOpenChange={(open) => !open && setPendingDelete(null)}
        variant="destructive"
        title={t('feeMappings.delete.confirmTitle')}
        description={
          pendingDelete
            ? t('feeMappings.delete.confirmDescription', {
                company: pendingDelete.company,
                dropoff: pendingDelete.dropOffPoint,
              })
            : undefined
        }
        confirmLabel={t('common.delete')}
        loading={deleteMutation.isPending}
        onConfirm={() => void handleDelete()}
      />
    </PageShell>
  );
}

export default FeeMappingsPage;

import * as React from 'react';
import { useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useTranslation } from 'react-i18next';
import { ArrowLeft, CheckCircle2, Copy, Lock, Receipt, Save, Split, Trash2 } from 'lucide-react';

import { PageShell } from '@/shared/ui/page-shell';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Textarea } from '@/shared/ui/textarea';
import { Card, CardContent } from '@/shared/ui/card';
import { NativeSelect } from '@/shared/ui/native-select';
import { ConfirmDialog } from '@/shared/ui/confirm-dialog';
import { Skeleton } from '@/shared/ui/skeleton';
import { toast } from '@/shared/ui/toaster';
import { cn } from '@/shared/lib/cn';
import { formatMoney, trimMoney } from '@/shared/lib/money';
import {
  cairoDateInput,
  cairoTimeInput,
  formatCairoDate,
  formatCairoDateTime,
} from '@/shared/lib/cairo';
import { SmartPartyField, type PartyValue } from '@/widgets/fleet-expenses-table/party-picker';
import { SplitEditor } from '@/widgets/fleet-expenses-table/split-editor';
import { useDebounce } from '@/shared/hooks/use-debounce';
import { useVehicles } from '@/entities/transaction/vehicles';
import {
  categoryLabel,
  posts,
  requiresParty,
  useCategories,
  useParties,
  type Category,
  type PartyKind,
} from '@/entities/transaction/categories';
import { useMessage } from '@/entities/raw-message/queries';
import {
  useCreateTransaction,
  useDeleteTransaction,
  useTransaction,
  useUpdateTransaction,
} from '@/entities/transaction/queries';
import {
  COMPANIES,
  PAYMENT_METHODS,
  isSplitChild,
  splitEligible,
  transactionFormSchema,
  type TransactionFormValues,
} from '@/entities/transaction/schemas';

/**
 * Shared create/edit form. `/fleet-expenses/{id}/edit` is the ntfy deep-link
 * target and keeps its URL.
 *
 * Two panels: the editable fields, and — for whatsapp rows or a message being
 * promoted — the verbatim source message. The party field ("to whom") renders
 * only when the selected category's `required_party` says so, and saving a
 * posting category registers the loan server-side in the same PATCH/POST.
 *
 * Amounts are STRINGS: a text input with inputmode="decimal", submitted
 * verbatim. Never prefilled during promotion — guessing money is the one
 * thing this system refuses to do; tap-to-copy on the body replaces retyping.
 */
export default function FleetExpenseFormPage({ mode }: { mode: 'create' | 'edit' }) {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const params = useParams<{ id: string }>();
  const [searchParams] = useSearchParams();

  const id = params.id ? Number(params.id) : undefined;
  const rawMessageIdParam = searchParams.get('raw_message_id');
  const rawMessageId =
    mode === 'create' && rawMessageIdParam ? Number(rawMessageIdParam) || undefined : undefined;

  const existing = useTransaction(mode === 'edit' ? id : undefined);
  // Fetched by id so a refresh of the promotion form survives.
  const message = useMessage(rawMessageId);
  const categories = useCategories();
  const vehicles = useVehicles();
  const parties = useParties();

  const createMutation = useCreateTransaction();
  const updateMutation = useUpdateTransaction();
  const deleteMutation = useDeleteTransaction();

  // Party and vehicle live outside react-hook-form: ids with rules, not text.
  const [party, setParty] = React.useState<PartyValue>({ driver_id: null, employee_id: null });
  const [carId, setCarId] = React.useState<number | null>(null);
  const [partyMissing, setPartyMissing] = React.useState(false);
  const [confirmDelete, setConfirmDelete] = React.useState(false);
  const [splitOpen, setSplitOpen] = React.useState(false);

  const form = useForm<TransactionFormValues>({
    resolver: zodResolver(transactionFormSchema),
    defaultValues: {
      amount: '',
      currency: 'EGP',
      direction: 'out',
      occurred_date: cairoDateInput(new Date()),
      occurred_time: cairoTimeInput(new Date()),
      category: '',
      account: '',
      counterparty: '',
      reference: '',
      description: '',
      payment_method: '',
      company: '',
      paid_by: '',
    },
  });

  /* ── Populate: edit row ── */
  React.useEffect(() => {
    const row = existing.data;
    if (mode !== 'edit' || !row) return;
    form.reset({
      amount: trimMoney(row.amount),
      currency: row.currency ?? 'EGP',
      direction: row.direction === 'in' ? 'in' : 'out',
      occurred_date: cairoDateInput(row.occurred_at),
      occurred_time: cairoTimeInput(row.occurred_at),
      category: row.category ?? '',
      account: row.account ?? '',
      counterparty: row.counterparty ?? '',
      reference: row.reference ?? '',
      description: row.description ?? '',
      payment_method: row.payment_method ?? '',
      company: row.company ?? '',
      paid_by: row.paid_by ?? '',
    });
    setParty({ driver_id: row.driver_id ?? null, employee_id: row.employee_id ?? null });
    setCarId(row.car_id ?? null);
  }, [existing.data, mode, form]);

  /* ── Populate: promotion — date/time from the envelope, direction out,
        currency EGP, all visibly editable. NEVER the amount. ── */
  React.useEffect(() => {
    const msg = message.data;
    if (mode !== 'create' || !msg || form.formState.isDirty) return;
    form.reset({
      ...form.getValues(),
      direction: 'out',
      currency: 'EGP',
      occurred_date: cairoDateInput(msg.wa_timestamp),
      occurred_time: cairoTimeInput(msg.wa_timestamp),
    });
  }, [message.data, mode, form]);

  const row = existing.data;
  const readOnly = mode === 'edit' && row ? !row.editable : false;

  /* ── Split state of this row ──
     A child's money fields are owned by the split: amount, direction and
     date/time are set server-side and any PATCH touching them is a 400, so
     they render disabled with a pointer to the editor. Category, person and
     description stay editable as normal. An unsplit cash-out row instead
     gets a "Split" action next to Delete. */
  const splitChild = mode === 'edit' && !!row && isSplitChild(row);
  const canSplit = mode === 'edit' && !!row && !readOnly && splitEligible(row);
  const moneyLocked = readOnly || splitChild;

  const catKey = form.watch('category');
  const selectedCategory: Category | undefined = React.useMemo(
    () => categories.data?.find((c) => c.key === catKey),
    [categories.data, catKey],
  );
  const needsParty = requiresParty(selectedCategory);
  const willPost = posts(selectedCategory);
  const hasParty = !!party.driver_id || !!party.employee_id;

  // The history suggestion keys off the counterparty text. Debounced so
  // typing in the field doesn't fire a lookup per keystroke, and disabled
  // entirely when the row already names a person — no second-guessing.
  const suggestCounterparty = useDebounce(form.watch('counterparty') ?? '', 300);
  const suggestParty =
    mode === 'create' || !(existing.data?.driver_id || existing.data?.employee_id);

  React.useEffect(() => {
    if (hasParty || !needsParty) setPartyMissing(false);
  }, [hasParty, needsParty]);

  /* ── Save → history.back() when we came from the ledger/messages list
        (query cache + scroll restoration); deep-link entries go to the ledger. ── */
  const cameFrom = (location.state as { from?: string } | null)?.from;
  const finish = React.useCallback(() => {
    if (cameFrom) navigate(-1);
    else navigate('/fleet-expenses');
  }, [cameFrom, navigate]);

  const onSubmit = form.handleSubmit((values) => {
    if (needsParty && !hasParty) {
      setPartyMissing(true);
      return;
    }
    const partyFields = needsParty
      ? { driver_id: party.driver_id, employee_id: party.employee_id }
      : { driver_id: null, employee_id: null };

    if (mode === 'create') {
      createMutation.mutate(
        {
          ...values,
          car_id: carId,
          ...(needsParty
            ? { driver_id: party.driver_id ?? undefined, employee_id: party.employee_id ?? undefined }
            : {}),
          ...(rawMessageId ? { raw_message_id: rawMessageId } : {}),
        },
        { onSuccess: finish },
      );
      return;
    }
    if (!id || !row) return;
    // A split child's money fields belong to the set — the server 400s any
    // PATCH that carries them, so they are stripped rather than echoed back.
    const patchValues: Partial<TransactionFormValues> = { ...values };
    if (splitChild) {
      delete patchValues.amount;
      delete patchValues.direction;
      delete patchValues.occurred_date;
      delete patchValues.occurred_time;
    }
    updateMutation.mutate(
      {
        id,
        // The version we loaded is the If-Match token — a concurrent edit is
        // rejected with 409 rather than silently overwritten.
        version: row.version,
        values: { ...patchValues, car_id: carId, ...partyFields },
      },
      { onSuccess: finish },
    );
  });

  const saving = createMutation.isPending || updateMutation.isPending;

  const partyName = React.useMemo(() => {
    if (!row) return '';
    const list = parties.data ?? [];
    if (row.driver_id) return list.find((p) => p.kind === 'driver' && p.id === row.driver_id)?.name ?? '';
    if (row.employee_id)
      return list.find((p) => p.kind === 'employee' && p.id === row.employee_id)?.name ?? '';
    return row.counterparty ?? '';
  }, [row, parties.data]);

  const copyBody = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      toast.success(t('fleetExpenses.copied'));
    } catch {
      toast.error(t('fleetExpenses.copyFailed'));
    }
  };

  if (mode === 'edit' && existing.isLoading) {
    return (
      <PageShell title={t('fleetExpenses.editExpense')}>
        <div className="space-y-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} className="h-10 w-full" />
          ))}
        </div>
      </PageShell>
    );
  }

  const sourceBody = mode === 'edit' ? row?.raw_body : message.data?.body;
  const sourceStamp = mode === 'edit' ? row?.raw_wa_timestamp : message.data?.wa_timestamp;
  const showSource = mode === 'edit' ? row?.source === 'whatsapp' && !!sourceBody : !!rawMessageId;

  return (
    <PageShell
      title={
        mode === 'create'
          ? t('fleetExpenses.addExpense')
          : t('fleetExpenses.transactionTitle', { id })
      }
      description={t('fleetExpenses.formSubtitle')}
      icon={<Receipt className="h-5 w-5" />}
      actions={
        <Button variant="outline" size="sm" onClick={finish}>
          <ArrowLeft className="h-4 w-4 rtl:rotate-180" />
          {t('common.back')}
        </Button>
      }
    >
      <div className="grid items-start gap-6 lg:grid-cols-3">
        {/* ── Side panel: the verbatim source message + row facts.
              First in the DOM so it pins ABOVE the form on phones. ── */}
        <div className="space-y-4 lg:order-2">
          {showSource && (
            <div className="rounded-xl border border-s-4 border-s-primary bg-muted/40 p-3.5">
              <div className="mb-1.5 flex items-center justify-between gap-2 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                <span>
                  {t('fleetExpenses.sourceMessage')}
                  {mode === 'edit' && row?.raw_message_id ? ` · #${row.raw_message_id}` : ''}
                  {mode === 'create' && rawMessageId ? ` · #${rawMessageId}` : ''}
                </span>
                {sourceStamp && <span>{formatCairoDateTime(sourceStamp, i18n.language)}</span>}
              </div>
              {message.isLoading && mode === 'create' ? (
                <Skeleton className="h-16 w-full" />
              ) : (
                <button
                  type="button"
                  onClick={() => sourceBody && void copyBody(sourceBody)}
                  className="w-full rounded-md text-start outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  title={t('fleetExpenses.tapToCopy')}
                >
                  <p
                    dir="auto"
                    className="whitespace-pre-wrap break-words text-sm leading-relaxed text-muted-foreground [overflow-wrap:anywhere]"
                  >
                    {sourceBody}
                  </p>
                  <span className="mt-2 inline-flex items-center gap-1 text-xs font-medium text-primary">
                    <Copy className="h-3 w-3" />
                    {t('fleetExpenses.tapToCopy')}
                  </span>
                </button>
              )}
              {mode === 'create' && (
                <p className="mt-2 border-t pt-2 text-xs text-muted-foreground">
                  {t('fleetExpenses.promoteAmountHint')}
                </p>
              )}
            </div>
          )}

          {mode === 'edit' && row?.edited_by && (
            <div className="rounded-lg bg-amber-500/10 px-3 py-2 text-xs font-medium text-amber-700 dark:text-amber-400">
              {t('fleetExpenses.editedBy', {
                name: row.edited_by,
                date: row.edited_at ? formatCairoDate(row.edited_at, i18n.language) : '',
              })}
            </div>
          )}

          {/* Fuel events and loans are owned by other pipelines; an edit here
              would be discarded by their next sync. */}
          {readOnly && (
            <div className="flex items-start gap-2 rounded-lg border bg-muted/40 px-3 py-2.5 text-sm text-muted-foreground">
              <Lock className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{t('fleetExpenses.readOnlyExplain')}</span>
            </div>
          )}
        </div>

        {/* ── The form ── */}
        <form onSubmit={onSubmit} className="space-y-4 lg:order-1 lg:col-span-2">
          <Card>
            <CardContent className="grid gap-4 px-4 py-5 sm:grid-cols-2 sm:px-6 sm:py-6">
              {/* A split child's money fields belong to the set as a whole. */}
              {splitChild && (
                <div className="flex flex-wrap items-center gap-2.5 rounded-lg border border-primary/30 bg-primary/5 px-3 py-2.5 text-sm sm:col-span-2">
                  <Split className="h-4 w-4 shrink-0 text-primary" />
                  <div className="min-w-0 flex-1">
                    <p>{t('fleetExpenses.split.childHint')}</p>
                    {row?.parent_amount != null && (
                      <p className="text-xs text-muted-foreground" dir="auto">
                        {t('fleetExpenses.split.chipPartOf', {
                          amount: formatMoney(row.parent_amount),
                        })}
                      </p>
                    )}
                  </div>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="min-h-10 w-full sm:min-h-8 sm:w-auto"
                    onClick={() => setSplitOpen(true)}
                  >
                    {t('fleetExpenses.split.editSplit')}
                  </Button>
                </div>
              )}

              <div className="grid grid-cols-[1fr_5rem] gap-2">
                <Field
                  label={t('fleetExpenses.fields.amount')}
                  error={form.formState.errors.amount}
                >
                  <Input
                    inputMode="decimal"
                    dir="ltr"
                    placeholder="0.00"
                    autoFocus={mode === 'create'}
                    disabled={moneyLocked}
                    {...form.register('amount')}
                  />
                </Field>
                <Field
                  label={t('fleetExpenses.fields.currency')}
                  error={form.formState.errors.currency}
                >
                  <Input dir="ltr" maxLength={3} disabled={readOnly} {...form.register('currency')} />
                </Field>
              </div>

              {/* Direction stays editable — flipping to "out" here is the same
                  reclassification the cash-in pocket offers. Creation defaults
                  to 'out'; promotions force it. */}
              <Field label={t('fleetExpenses.fields.direction')}>
                <div className="flex h-11 overflow-hidden rounded-md border sm:h-9">
                  {(['out', 'in'] as const).map((d) => (
                    <button
                      key={d}
                      type="button"
                      disabled={moneyLocked}
                      onClick={() => form.setValue('direction', d, { shouldDirty: true })}
                      className={cn(
                        'flex-1 text-sm font-semibold transition-colors',
                        form.watch('direction') === d
                          ? 'bg-foreground text-background'
                          : 'bg-card text-muted-foreground hover:bg-accent',
                      )}
                    >
                      {t(`fleetExpenses.direction.${d}`)}
                    </button>
                  ))}
                </div>
              </Field>

              <Field
                label={t('fleetExpenses.fields.date')}
                error={form.formState.errors.occurred_date}
              >
                <Input type="date" disabled={moneyLocked} {...form.register('occurred_date')} />
              </Field>
              <Field label={t('fleetExpenses.fields.time')}>
                <Input type="time" disabled={moneyLocked} {...form.register('occurred_time')} />
              </Field>

              <Field
                label={t('fleetExpenses.fields.expenseType')}
                error={form.formState.errors.category}
              >
                {categories.isLoading ? (
                  <Skeleton className="h-9 w-full" />
                ) : (
                  <NativeSelect
                    value={form.watch('category') ?? ''}
                    disabled={readOnly}
                    onChange={(e) =>
                      form.setValue('category', e.target.value, { shouldDirty: true })
                    }
                  >
                    <option value="">{t('common.none')}</option>
                    {(categories.data ?? []).map((c) => (
                      <option key={c.key} value={c.key}>
                        {categoryLabel(c, i18n.language)}
                      </option>
                    ))}
                  </NativeSelect>
                )}
              </Field>

              {/* Rendered from the category's own requirements: adding a
                  category that needs a person is a database row, not a code
                  change here. */}
              {needsParty && (
                <Field label={t('fleetExpenses.toWhom')}>
                  <SmartPartyField
                    counterparty={suggestCounterparty}
                    suggest={suggestParty}
                    value={party}
                    onChange={setParty}
                    disabled={readOnly}
                    required={(selectedCategory?.required_party ?? 'either') as PartyKind}
                  />
                  {partyMissing && (
                    <p className="text-xs text-destructive">{t('fleetExpenses.partyRequired')}</p>
                  )}
                  {willPost && !row?.loan && (
                    <p className="text-xs text-muted-foreground">
                      {t('fleetExpenses.party.postsNow')}
                    </p>
                  )}
                </Field>
              )}

              {/* The registration chip says what happened, in words. One-way:
                  it links nowhere the user can break. */}
              {mode === 'edit' && row?.loan && (
                <div className="flex items-start gap-2 rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-3 py-2.5 text-sm sm:col-span-2">
                  <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-emerald-500" />
                  <div>
                    <span dir="auto">
                      {t('fleetExpenses.loanChip', {
                        kind: t(`fleetExpenses.loanKind.${row.loan.kind}`, row.loan.kind),
                        name: partyName,
                        status: t(
                          `fleetExpenses.loanStatus.${row.loan.is_paid ? 'paid' : 'unpaid'}`,
                        ),
                      })}
                    </span>
                    <p className="mt-0.5 text-xs text-muted-foreground">
                      {row.loan.is_paid
                        ? t('fleetExpenses.loanSettledNote')
                        : t('fleetExpenses.loanSyncNote')}
                    </p>
                  </div>
                </div>
              )}

              <Field
                label={t('fleetExpenses.fields.counterparty')}
                error={form.formState.errors.counterparty}
              >
                <Input dir="auto" disabled={readOnly} {...form.register('counterparty')} />
              </Field>

              <Field
                label={t('fleetExpenses.fields.reference')}
                error={form.formState.errors.reference}
              >
                <Input dir="ltr" disabled={readOnly} {...form.register('reference')} />
              </Field>

              <Field
                label={t('fleetExpenses.fields.account')}
                error={form.formState.errors.account}
              >
                <Input dir="ltr" disabled={readOnly} {...form.register('account')} />
              </Field>

              <Field label={t('fleetExpenses.fields.paymentMethod')}>
                <NativeSelect
                  value={form.watch('payment_method') ?? ''}
                  disabled={readOnly}
                  onChange={(e) =>
                    form.setValue('payment_method', e.target.value, { shouldDirty: true })
                  }
                >
                  <option value="">{t('common.none')}</option>
                  {PAYMENT_METHODS.map((m) => (
                    <option key={m} value={m}>
                      {m}
                    </option>
                  ))}
                </NativeSelect>
              </Field>

              <Field label={t('fleetExpenses.fields.company')}>
                <NativeSelect
                  value={form.watch('company') ?? ''}
                  disabled={readOnly}
                  onChange={(e) => form.setValue('company', e.target.value, { shouldDirty: true })}
                >
                  <option value="">{t('common.none')}</option>
                  {COMPANIES.map((c) => (
                    <option key={c} value={c}>
                      {c}
                    </option>
                  ))}
                </NativeSelect>
              </Field>

              <Field label={t('fleetExpenses.fields.car')}>
                {vehicles.isLoading ? (
                  <Skeleton className="h-9 w-full" />
                ) : (
                  <NativeSelect
                    value={carId == null ? '' : String(carId)}
                    disabled={readOnly}
                    onChange={(e) => setCarId(e.target.value === '' ? null : Number(e.target.value))}
                  >
                    <option value="">{t('common.none')}</option>
                    {(vehicles.data ?? []).map((v) => (
                      <option key={v.id} value={String(v.id)}>
                        {v.car_no_plate}
                      </option>
                    ))}
                  </NativeSelect>
                )}
              </Field>

              <Field label={t('fleetExpenses.fields.paidBy')} error={form.formState.errors.paid_by}>
                {/* Free text with name suggestions. Picking a driver or an
                    employee here appends their NAME only — deliberately not an
                    id link. Salary settlements are labels, not registrations,
                    and an unregistered name needs no creating to be typed. */}
                <Input
                  dir="auto"
                  disabled={readOnly}
                  list="party-name-suggestions"
                  {...form.register('paid_by')}
                />
                <datalist id="party-name-suggestions">
                  {(parties.data ?? []).map((p) => (
                    <option key={`${p.kind}-${p.id}`} value={p.name} />
                  ))}
                </datalist>
              </Field>

              <div className="sm:col-span-2">
                <Field
                  label={t('fleetExpenses.fields.description')}
                  error={form.formState.errors.description}
                >
                  <Textarea rows={3} dir="auto" disabled={readOnly} {...form.register('description')} />
                </Field>
              </div>
            </CardContent>
          </Card>

          {!readOnly && (
            /* On phones the actions pin to the bottom of the viewport (with
               iOS safe-area padding) so Save never scrolls out of reach; from
               sm up they sit statically under the card as before. */
            <div className="sticky bottom-0 z-10 -mx-4 flex flex-wrap gap-2 border-t bg-background p-4 pb-[max(1rem,env(safe-area-inset-bottom))] sm:static sm:z-auto sm:mx-0 sm:flex-nowrap sm:justify-end sm:border-0 sm:bg-transparent sm:p-0">
              <Button
                type="button"
                variant="outline"
                onClick={finish}
                className="order-1 min-h-11 flex-1 sm:order-2 sm:min-h-9 sm:flex-none"
              >
                {t('common.cancel')}
              </Button>
              <Button
                type="submit"
                disabled={saving}
                className="order-2 min-h-11 flex-1 sm:order-3 sm:min-h-9 sm:flex-none"
              >
                <Save className="h-4 w-4" />
                {saving ? t('common.saving') : t('common.save')}
              </Button>
              {mode === 'edit' && row && !splitChild && (
                <Button
                  type="button"
                  variant="ghost"
                  className={cn(
                    'order-3 min-h-10 w-full text-destructive hover:text-destructive sm:order-1 sm:min-h-9 sm:w-auto',
                    !canSplit && 'sm:me-auto',
                  )}
                  onClick={() => setConfirmDelete(true)}
                  disabled={saving || deleteMutation.isPending}
                >
                  <Trash2 className="h-4 w-4" />
                  {t('common.delete')}
                </Button>
              )}
              {/* Splitting an unsplit cash-out row — sits with Delete because
                  both replace this screen's row with something else. */}
              {canSplit && (
                <Button
                  type="button"
                  variant="ghost"
                  className="order-4 min-h-10 w-full text-muted-foreground sm:order-1 sm:me-auto sm:min-h-9 sm:w-auto"
                  onClick={() => setSplitOpen(true)}
                  disabled={saving || deleteMutation.isPending}
                >
                  <Split className="h-4 w-4" />
                  {t('fleetExpenses.split.action')}
                </Button>
              )}
            </div>
          )}
        </form>
      </div>

      {/* One editor for both entry points: splitting THIS row, or editing the
          set THIS row is a part of. Either way the saved result replaces the
          row this screen was loaded around, so onDone leaves the screen. */}
      {mode === 'edit' && (
        <SplitEditor
          open={splitOpen}
          onOpenChange={setSplitOpen}
          row={row ?? null}
          onDone={finish}
          canEdit={!readOnly}
        />
      )}

      <ConfirmDialog
        open={confirmDelete}
        onOpenChange={setConfirmDelete}
        title={t('fleetExpenses.deleteConfirmTitle')}
        description={t('fleetExpenses.deleteConfirmDescription', {
          amount: row ? `${formatMoney(row.amount)} ${row.currency ?? 'EGP'}` : '',
        })}
        confirmLabel={t('common.delete')}
        variant="destructive"
        onConfirm={() => {
          if (!id || !row) return;
          deleteMutation.mutate(
            { id, version: row.version },
            {
              onSuccess: () => {
                setConfirmDelete(false);
                navigate('/fleet-expenses');
              },
              onError: () => setConfirmDelete(false),
            },
          );
        }}
      />
    </PageShell>
  );
}

/* -------------------------------------------------------------------------- */

function Field({
  label,
  error,
  children,
}: {
  label: string;
  error?: { message?: string };
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-1.5">
      <Label>{label}</Label>
      {children}
      {error?.message && <p className="text-xs text-destructive">{error.message}</p>}
    </div>
  );
}

import * as React from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { ArrowLeft, Inbox, RefreshCw, Search } from 'lucide-react';

import { PageShell } from '@/shared/ui/page-shell';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { EmptyState } from '@/shared/ui/empty-state';
import { Skeleton } from '@/shared/ui/skeleton';
import { cn } from '@/shared/lib/cn';
import { formatCairoDateTime } from '@/shared/lib/cairo';
import { useDebounce } from '@/shared/hooks/use-debounce';
import { usePermissions } from '@/shared/hooks/use-permissions';

import { useMessagesPaged } from '@/entities/raw-message/queries';
import {
  MESSAGE_STATUSES,
  STATUS_TONE,
  type Message,
  type MessageStatus,
} from '@/entities/raw-message/schemas';

/**
 * The Messages screen — every verdict the parser made, searchable.
 *
 * These are verdicts, not work items: nothing demands emptying. `matched`
 * minted a transaction; `suppressed` was excluded on purpose (the PetroApp
 * double-count guard) and the card says why in words; `ignored` matched no
 * template, and a wrongly-ignored bank SMS gets exactly one action — "Record
 * as transaction" — which opens the create form with the message pinned
 * alongside. Terminal and visible; nothing re-queues.
 */
export default function FleetExpensesMessagesPage() {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { canManageExpenses } = usePermissions();
  const [searchParams, setSearchParams] = useSearchParams();

  const [status, setStatus] = React.useState<MessageStatus>(() => {
    const s = searchParams.get('status');
    return (MESSAGE_STATUSES as readonly string[]).includes(s ?? '')
      ? (s as MessageStatus)
      : 'ignored';
  });
  // Off by default: 254 empty-body media rows would drown the list.
  const [includeMedia, setIncludeMedia] = React.useState(
    () => searchParams.get('media') === '1',
  );
  const [search, setSearch] = React.useState(() => searchParams.get('q') ?? '');
  const debouncedSearch = useDebounce(search, 250);

  React.useEffect(() => {
    const next = new URLSearchParams();
    if (status !== 'ignored') next.set('status', status);
    if (includeMedia) next.set('media', '1');
    if (debouncedSearch) next.set('q', debouncedSearch);
    setSearchParams(next, { replace: true });
  }, [status, includeMedia, debouncedSearch, setSearchParams]);

  const query = useMessagesPaged({
    status,
    q: debouncedSearch || undefined,
    include_media: includeMedia ? 'true' : undefined,
  });

  const messages = React.useMemo(
    () => query.data?.pages.flatMap((p) => p.data) ?? [],
    [query.data],
  );

  return (
    <PageShell
      title={t('messages.title')}
      description={t('messages.subtitle')}
      icon={<Inbox className="h-5 w-5" />}
      actions={
        <div className="flex flex-wrap items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => navigate('/fleet-expenses')}>
            <ArrowLeft className="h-4 w-4 rtl:rotate-180" />
            <span className="hidden sm:inline">{t('messages.backToExpenses')}</span>
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => void query.refetch()}
            disabled={query.isFetching}
          >
            <RefreshCw className={cn('h-4 w-4', query.isFetching && 'animate-spin')} />
            <span className="hidden sm:inline">{t('common.refresh')}</span>
          </Button>
        </div>
      }
    >
      {/* ── Chips + search ────────────────────────────────────────────────── */}
      <div className="space-y-3">
        <div className="-mx-4 flex gap-1.5 overflow-x-auto px-4 pb-1 [scrollbar-width:none] md:mx-0 md:px-0">
          {MESSAGE_STATUSES.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => setStatus(s)}
              className={cn(
                'min-h-11 shrink-0 whitespace-nowrap rounded-full border px-3.5 py-1 text-xs font-semibold transition-colors lg:min-h-8 lg:px-3',
                status === s
                  ? 'border-foreground bg-foreground text-background'
                  : 'bg-card text-muted-foreground hover:bg-accent',
              )}
            >
              {t(`messages.chips.${s}`)}
            </button>
          ))}
          <button
            type="button"
            onClick={() => setIncludeMedia((v) => !v)}
            aria-pressed={includeMedia}
            className={cn(
              'min-h-11 shrink-0 whitespace-nowrap rounded-full border border-dashed px-3.5 py-1 text-xs font-semibold transition-colors lg:min-h-8 lg:px-3',
              includeMedia
                ? 'border-foreground bg-foreground text-background'
                : 'bg-card text-muted-foreground hover:bg-accent',
            )}
          >
            {t('messages.chips.media')}
          </button>
        </div>

        <div className="relative max-w-md">
          <Search className="pointer-events-none absolute start-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={t('messages.searchPlaceholder')}
            className="ps-9"
            dir="auto"
          />
        </div>
      </div>

      {/* ── Cards ─────────────────────────────────────────────────────────── */}
      {query.isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} className="h-28 w-full" />
          ))}
        </div>
      ) : messages.length === 0 ? (
        <EmptyState
          icon={<Inbox className="h-8 w-8" />}
          title={t('messages.empty.title')}
          description={t('messages.empty.hint')}
        />
      ) : (
        <>
          <div className="space-y-3">
            {messages.map((message) => (
              <MessageCard
                key={message.id}
                message={message}
                canAct={canManageExpenses}
                language={i18n.language}
              />
            ))}
          </div>

          {query.hasNextPage && (
            <div className="flex justify-center py-1">
              <Button
                variant="outline"
                size="sm"
                onClick={() => void query.fetchNextPage()}
                disabled={query.isFetchingNextPage}
                className="w-full sm:w-auto"
              >
                {query.isFetchingNextPage ? t('common.loading') : t('common.loadMore')}
              </Button>
            </div>
          )}
        </>
      )}
    </PageShell>
  );
}

/* -------------------------------------------------------------------------- */
/* Card                                                                        */
/*                                                                            */
/* A card, not a table row: the payload is a free-text message, often long     */
/* and often Arabic. Verbatim body, dir="auto", pre-wrap, and                  */
/* overflow-wrap:anywhere so a bare-hex reference wraps at 375px instead of    */
/* forcing horizontal scroll.                                                  */
/* -------------------------------------------------------------------------- */

function MessageCard({
  message,
  canAct,
  language,
}: {
  message: Message;
  canAct: boolean;
  language: string;
}) {
  const { t } = useTranslation();
  const navigate = useNavigate();

  const pill = message.template
    ? `${t(`messages.status.${message.status}`, message.status)} · ${message.template}`
    : t(`messages.status.${message.status}`, message.status);

  return (
    <div className="rounded-lg border bg-card p-3 sm:p-4">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
        <span
          className={cn(
            'rounded-full px-2 py-0.5 text-xs font-medium',
            STATUS_TONE[message.status] ?? STATUS_TONE.ignored,
          )}
        >
          {message.transaction_id && message.status === 'ignored'
            ? t('messages.recordedPill')
            : pill}
        </span>
        <span className="text-xs text-muted-foreground">
          {formatCairoDateTime(message.wa_timestamp, language)}
        </span>
      </div>

      <p
        dir="auto"
        className="whitespace-pre-wrap break-words rounded-md bg-muted/50 p-3 text-sm leading-relaxed [overflow-wrap:anywhere]"
      >
        {message.body || (
          <span className="italic text-muted-foreground">{t('messages.emptyBody')}</span>
        )}
      </p>

      {message.is_from_me && (
        <p className="mt-1.5 text-xs text-muted-foreground">{t('messages.fromMe')}</p>
      )}

      {/* One line of consequence per verdict. */}
      {message.status === 'suppressed' && (
        <p className="mt-2 text-xs text-muted-foreground">{t('messages.suppressedWhy')}</p>
      )}

      {message.transaction_id ? (
        <p className="mt-2 text-sm">
          <Link
            to={`/fleet-expenses/${message.transaction_id}/edit`}
            state={{ from: 'messages' }}
            className="font-semibold text-primary hover:underline"
          >
            {message.status === 'matched'
              ? t('messages.toTransaction', { id: message.transaction_id })
              : t('messages.recordedAs', { id: message.transaction_id })}
          </Link>
        </p>
      ) : message.status === 'ignored' && canAct ? (
        <div className="mt-2.5">
          <Button
            variant="secondary"
            className="min-h-11 w-full sm:min-h-9 sm:w-auto"
            onClick={() =>
              navigate(`/fleet-expenses/new?raw_message_id=${message.id}`, {
                state: { from: 'messages' },
              })
            }
          >
            {t('messages.recordAsTransaction')}
          </Button>
        </div>
      ) : null}
    </div>
  );
}

