        />
        <StatCard
          label={t('fleetExpenses.stats.fees')}
          value={
            statsQuery.isLoading
              ? statSkeleton
              : {
                  full: `${formatMoney(stats?.total_fees)} EGP`,
                  compact: formatCompactNumber(Number(stats?.total_fees ?? 0)),
