            setCategory('');
          }}
          className={cn(
            'col-span-2 rounded-xl text-start outline-none transition-shadow focus-visible:ring-2 focus-visible:ring-ring lg:col-span-1',
            uncatOnly && 'ring-2 ring-warning',
          )}
