        >
          <StatCard
            label={t('fleetExpenses.stats.uncategorized')}
            value={t('fleetExpenses.stats.rowsArrow', { count: uncatCount })}
            subvalue={
              uncatOnly
                ? t('fleetExpenses.stats.showingUncategorized')
