          />
        </button>
      </div>

      {/* ── Cash in — needs review. A quiet amber pocket that only exists
            while there is something in it. ─────────────────────────────────── */}
      {pendingIn.count > 0 && (
        <button
          type="button"
          onClick={() => setCashInOpen((v) => !v)}
