            {t('fleetExpenses.allCategories')}
          </FilterChip>
          {(categories.data ?? []).map((c) => (
            <FilterChip
              key={c.key}
              active={category === c.key}
              onClick={() => {
                setCategory(category === c.key ? '' : c.key);
