/* Component                                                                   */
/* -------------------------------------------------------------------------- */

export default function FuelEventsPage() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { canEditFuel } = usePermissions();
  const [searchParams, setSearchParams] = useSearchParams();
  const queryClient = useQueryClient();

  const [search, setSearch] = React.useState(() => searchParams.get('q') ?? '');
  const debouncedSearch = useDebounce(search, 200);

  // Dates come from the GLOBAL scope (the header bar).
  const { range: scopeRange } = useScope();
  const from = scopeRange.from;
  const to = scopeRange.to;

  const [grouping, setGrouping] = React.useState<FuelEventGrouping>(() => {
    const url = searchParams.get('g');
    if (url === 'v') return 'vehicle';
    if (url === 'd') return 'driver';
    if (url === 'a') return 'none';
    return loadDefault(FUEL_STORAGE_KEYS.grouping, 'vehicle' as FuelEventGrouping, isValidGrouping);
  });

  const [activeFilters, setActiveFilters] = React.useState<Set<FuelEventStatusFilter>>(() =>
    parseFilters(searchParams.get('f')),
  );

  const [methodFilter, setMethodFilter] = React.useState<FuelEventMethodFilter>(() =>
    parseMethod(searchParams.get('m')),
  );

  const [sortKey, setSortKey] = React.useState<FuelEventSortKey>(() => {
    const url = searchParams.get('s');
    return (url && isValidSortKey(url)) || 'date';
  });

  const [sortDirection, setSortDirection] = React.useState<SortDirection>(() => {
    const url = searchParams.get('d');
    return (url && isValidDirection(url)) || 'desc';
  });

  const [exporting, setExporting] = React.useState(false);
  const [exportingGroup, setExportingGroup] = React.useState<string | null>(null);

  /* ------------------------------------------------------------------------ */
  /* Sync state → URL                                                         */
  /* ------------------------------------------------------------------------ */

  React.useEffect(() => {
    setSearchParams(
      (prev) => {
        // Start from the CURRENT params so the global scope's keys survive.
        const next = new URLSearchParams(prev);
        const setOrDelete = (k: string, v: string | null) =>
          v ? next.set(k, v) : next.delete(k);
        setOrDelete('q', debouncedSearch || null);
        setOrDelete('g', grouping !== 'vehicle' ? (grouping === 'none' ? 'a' : grouping[0]) : null);
        setOrDelete('f', serializeFilters(activeFilters));
        setOrDelete('m', serializeMethod(methodFilter));
        setOrDelete('s', sortKey !== 'date' ? sortKey : null);
        setOrDelete('d', sortDirection !== 'desc' ? sortDirection : null);
        return next;
      },
      { replace: true },
    );
  }, [debouncedSearch, grouping, activeFilters, methodFilter, sortKey, sortDirection, setSearchParams]);

  /* ------------------------------------------------------------------------ */
  /* Sync state → localStorage (only the sticky bits)                         */
  /* ------------------------------------------------------------------------ */

  React.useEffect(() => {
    window.localStorage.setItem(FUEL_STORAGE_KEYS.grouping, grouping);
  }, [grouping]);


  /* ------------------------------------------------------------------------ */
  /* Data pipeline                                                            */
  /*                                                                          */
  /*   fetched events                                                         */
  /*   → search filter                                                        */
  /*   → pair analysis  (runs on the FULL search-filtered set so pairing      */
  /*                     stays holistic across methods)                       */
  /*   → status filter                                                        */
  /*   → method filter                                                        */
  /*   → sort                                                                 */
  /* ------------------------------------------------------------------------ */

  const {
    data: events = [],
    isLoading,
    isError,
    refetch,
  } = useFuelEvents({ from, to });

  const searched = React.useMemo(() => {
    if (!debouncedSearch.trim()) return events;
    return events.filter(
      (e) =>
        matches(e.car_no_plate, debouncedSearch) || matches(e.driver_name, debouncedSearch),
    );
  }, [events, debouncedSearch]);

  const analysis = React.useMemo(() => analyseEvents(searched), [searched]);

  const afterStatus = React.useMemo(
    () => applyStatusFilter(searched, analysis.map, activeFilters),
    [searched, analysis.map, activeFilters],
  );

  const filtered = React.useMemo(
    () => applyMethodFilter(afterStatus, methodFilter),
    [afterStatus, methodFilter],
  );

  const sorted = React.useMemo(
    () => applySort(filtered, analysis.map, sortKey, sortDirection),
    [filtered, analysis.map, sortKey, sortDirection],
  );

  // Method tab counts — computed from the set after status filter applies
  // (but before method filter) so tab counts reflect what each tab would show.
  const methodCounts = React.useMemo(() => countByMethod(afterStatus), [afterStatus]);

  /* ------------------------------------------------------------------------ */
  /* Stats — computed from the VISIBLE (post-filter) set                      */
  /* ------------------------------------------------------------------------ */

  const stats = React.useMemo(() => {
    const { totals } = analyseEvents(filtered);
    const start = parseISO(from) ?? firstDayOfMonth();
    const end = parseISO(to) ?? new Date();
    const days = daysBetween(start, end);

    return {
      totalEvents: totals.totalEvents,
      totalLiters: totals.totalLiters,
      totalCost: totals.totalCost,
      avgFuelRate: totals.avgRate,
      avgCostPerDay: days > 0 ? totals.totalCost / days : 0,
      avgLitersPerDay: days > 0 ? totals.totalLiters / days : 0,
      avgPerFuelUp: totals.totalEvents > 0 ? totals.totalLiters / totals.totalEvents : 0,
      pairedCount: totals.pairedCount,
      days,
    };
  }, [filtered, from, to]);

  /* ------------------------------------------------------------------------ */
  /* Exports                                                                  */
  /* ------------------------------------------------------------------------ */

  const handleExport = async () => {
    if (sorted.length === 0) return;
    setExporting(true);
    try {
      await exportFuelEvents({ events: sorted, grouping, t });
    } finally {
      setExporting(false);
    }
  };

  const handleExportGroup = async (groupKey: string, groupEvents: FuelEvent[]) => {
    if (groupEvents.length === 0 || grouping === 'none') return;
    setExportingGroup(groupKey);
    try {
      await exportFuelEventsGroup({
        groupKey,
        events: groupEvents,
        grouping: grouping as 'vehicle' | 'driver',
        t,
      });
    } finally {
      setExportingGroup(null);
    }
  };

  const anyFilterActive = activeFilters.size > 0 || methodFilter !== 'all';

  return (
    <PageShell
      title={t('fuelEvents.title')}
      description={t('fuelEvents.subtitle')}
      icon={<Fuel className="h-5 w-5" />}
      actions={
        <>
          <Button
            variant="outline"
            size="sm"
            onClick={handleExport}
            disabled={exporting || sorted.length === 0}
          >
            <Download className="h-4 w-4" />
            <span className="hidden sm:inline">{t('common.export')}</span>
          </Button>
          {canEditFuel && (
            <Button onClick={() => navigate('/fuel-events/new')} size="sm" {...intentProps(() => warmFuelForm(queryClient))}>
              <Plus className="h-4 w-4" />
              <span className="hidden sm:inline">{t('fuelEvents.addEvent')}</span>
            </Button>
          )}
        </>
      }
    >
      {/* Toolbar row 2 — search + grouping */}
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative max-w-sm flex-1">
          <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={t('fuelEvents.searchPlaceholder')}
            className="ps-9"
          />
        </div>

        <div
          className="inline-flex h-9 items-center gap-0.5 rounded-md border bg-muted/40 p-0.5"
          role="tablist"
          aria-label={t('fuelEvents.grouping.label')}
        >
          <GroupingButton
            active={grouping === 'vehicle'}
            onClick={() => setGrouping('vehicle')}
            icon={<CarIcon className="h-3.5 w-3.5" />}
            label={t('fuelEvents.grouping.byVehicle')}
          />
          <GroupingButton
            active={grouping === 'driver'}
            onClick={() => setGrouping('driver')}
            icon={<Users className="h-3.5 w-3.5" />}
            label={t('fuelEvents.grouping.byDriver')}
          />
          <GroupingButton
            active={grouping === 'none'}
            onClick={() => setGrouping('none')}
            icon={<LayoutGrid className="h-3.5 w-3.5" />}
            label={t('fuelEvents.grouping.all')}
          />
        </div>
      </div>

      {/* Toolbar row 3 — method tabs + status filter + sort */}
      <div className="flex flex-wrap items-center gap-2">
        <FuelEventsMethodControl
          value={methodFilter}
          onChange={setMethodFilter}
          counts={methodCounts}
        />
        <FuelEventsFilterPopover active={activeFilters} onChange={setActiveFilters} />
        <FuelEventsSortControl
          sortKey={sortKey}
          direction={sortDirection}
          onSortKeyChange={setSortKey}
          onDirectionToggle={() =>
            setSortDirection((d) => (d === 'desc' ? 'asc' : 'desc'))
          }
        />
        {anyFilterActive && (
          <span className="text-xs text-muted-foreground">
            {t('fuelEvents.filters.showingCount', {
              shown: filtered.length,
              total: searched.length,
            })}
          </span>
        )}
      </div>

      {/* Stats */}
      {!isLoading && filtered.length > 0 && (
<div className="grid grid-cols-2 gap-2.5 md:grid-cols-3 lg:grid-cols-5">
  <StatCard
    label={t('fuelEvents.stats.totalFuel')}
    value={{
      full: `${formatNumber(stats.totalLiters, 1)} L`,
      compact: `${formatCompactNumber(stats.totalLiters, 1)} L`,
    }}
    subvalue={t('fuelEvents.stats.events', { count: stats.totalEvents })}
    icon={Droplet}
    tone="primary"
  />
  <StatCard
    label={t('fuelEvents.stats.avgEfficiency')}
    value={`${formatNumber(stats.avgFuelRate, 1)} ${t('fuelEvents.efficiency.unit')}`}
    subvalue={
      stats.pairedCount > 0
        ? t('fuelEvents.stats.pairedNote', { count: stats.pairedCount })
        : undefined
    }
    icon={Gauge}
    tone="success"
  />
  <StatCard
    label={t('fuelEvents.stats.totalCost')}
    value={{
      full: formatCurrency(stats.totalCost),
      compact: formatCompactCurrency(stats.totalCost),
    }}
    icon={DollarSign}
    tone="primary"
  />
  <StatCard
    label={t('fuelEvents.stats.costPerDay')}
    value={{
      full: formatCurrency(stats.avgCostPerDay),
      compact: formatCompactCurrency(stats.avgCostPerDay),
    }}
    subvalue={t('fuelEvents.stats.dayPeriod', { count: stats.days })}
    icon={TrendingUp}
    tone="warning"
  />
  <StatCard
    label={t('fuelEvents.stats.fuelPerDay')}
    value={{
      full: `${formatNumber(stats.avgLitersPerDay, 2)} L`,
      compact: `${formatCompactNumber(stats.avgLitersPerDay, 2)} L`,
    }}
    subvalue={t('fuelEvents.stats.dayPeriod', { count: stats.days })}
    icon={Droplet}
  />
  <StatCard
    label={t('fuelEvents.stats.perFuelUp')}
    value={`${formatNumber(stats.avgPerFuelUp, 1)} L`}
    icon={Clock}
    className="lg:hidden"
  />
</div>
      )}

      {/* Paired events explainer */}
      {stats.pairedCount > 0 && (
        <div className="flex items-start gap-2 rounded-md border border-primary/20 bg-primary/5 p-2.5 text-xs text-muted-foreground">
          <Link2 className="mt-0.5 h-3.5 w-3.5 shrink-0 text-primary" />
          <span>{t('fuelEvents.efficiency.pairedExplainer')}</span>
        </div>
      )}

      {/* Table / empty state */}
      {isError ? (
        <EmptyState
          lottieSrc="/animations/warning.lottie"
          lottieWidth={100}
          lottieHeight={100}
          title={t('errors.generic')}
          action={
            <Button onClick={() => void refetch()} variant="outline">
              {t('common.retry')}
            </Button>
          }
        />
      ) : !isLoading && searched.length === 0 ? (
        <EmptyState
          lottieSrc="/animations/no_results.json"
          lottieWidth={100}
          lottieHeight={100}
          title={t('fuelEvents.noEvents')}
          description={t('fuelEvents.noEventsDescription')}
          action={
            canEditFuel && (
              <Button onClick={() => navigate('/fuel-events/new')} {...intentProps(() => warmFuelForm(queryClient))}>
                <Plus className="h-4 w-4" />
                {t('fuelEvents.addEvent')}
              </Button>
            )
          }
        />
      ) : (
        <FuelEventsTable
          events={sorted}
          originalEvents={searched}
          grouping={grouping}
          loading={isLoading}
          analysis={analysis.map}
          onExportGroup={handleExportGroup}
          exportingGroup={exportingGroup}
        />
      )}
    </PageShell>
  );
}

function GroupingButton({
  active,
  onClick,
  icon,
  label,
}: {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={active}
      onClick={onClick}
      className={cn(
        'inline-flex h-7 items-center gap-1.5 rounded px-2.5 text-xs font-medium transition-colors',
        active
          ? 'bg-background text-foreground shadow-sm'
          : 'text-muted-foreground hover:text-foreground',
      )}
    >
      {icon}
      <span className="hidden sm:inline">{label}</span>
    </button>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { CheckCircle2, Inbox, MapPin, Warehouse } from 'lucide-react';
import { PageShell } from '@/shared/ui/page-shell';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { Progress } from '@/shared/ui/progress';
import { SearchInput } from '@/shared/ui/search-input';
import { ConfirmDialog } from '@/shared/ui/confirm-dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import { cn } from '@/shared/lib/cn';
import { isValidCoordinate } from '@/shared/lib/coords';
import { useDebounce } from '@/shared/hooks/use-debounce';
import {
  useDeleteDropoff,
  useDropoffs,
  useLocationsInbox,
  usePinSuggestions,
  useTerminals,
} from '@/entities/location/queries';
import type { DropOffPoint } from '@/entities/location/schemas';
import { LocationsNeedsAttention } from '@/widgets/locations-needs-attention';
import { LocationsTerminalsTable } from '@/widgets/locations-terminals-table';
import { LocationsDropoffsTable } from '@/widgets/locations-dropoffs-table';
import { LocationsTerminalDialog } from '@/widgets/locations-terminal-dialog';
import { LocationsDropoffDialog } from '@/widgets/locations-dropoff-dialog';
import { TripsPagination } from '@/widgets/trips-table/trips-pagination';

type LocationsTab = 'inbox' | 'terminals' | 'dropoffs';
type PinFilter = 'all' | 'missing';

const LIMIT_STORAGE_KEY = 'apex:locations:limit';

function storedLimit(): number {
  try {
    const v = parseInt(localStorage.getItem(LIMIT_STORAGE_KEY) ?? '', 10);
    return [10, 25, 50, 100].includes(v) ? v : 25;
  } catch {
    return 25;
  }
}

/**
 * Locations — the single place where canonical terminals and drop-off points
 * are managed. The page's job is one thing: every place ends up with an
 * accurate pin. The header shows coverage and points at the work; the
 * "Needs attention" queue is where the work happens; the two catalog views
 * are for browsing and editing.
 */
export default function LocationsPage() {
  const { t } = useTranslation();

  const [tab, setTab] = React.useState<LocationsTab>('inbox');
  const tabDecided = React.useRef(false);

  /* ---- Shared data for the header + inbox badge ---- */
  const inboxQuery = useLocationsInbox();
  const suggestionsQuery = usePinSuggestions();
  const autoAppliedQuery = usePinSuggestions('auto_applied');
  const terminalsQuery = useTerminals();
  // One-row probe: the envelope's `total` is the full drop-off count.
  const dropoffTotalsQuery = useDropoffs({ page: 1, per_page: 1 });

  const pendingCount = React.useMemo(
    () =>
      (suggestionsQuery.data ?? []).filter(
        (s) =>
          s.status === 'pending' &&
          ((s.current_lat != null && s.current_lng != null && (s.offset_m ?? 0) > 0) ||
            (s.kind === 'terminal' && s.current_lat == null)),
      ).length,
    [suggestionsQuery.data],
  );
  const provisionalCount = React.useMemo(
    () => (autoAppliedQuery.data ?? []).filter((s) => s.status === 'auto_applied').length,
    [autoAppliedQuery.data],
  );
  const unpinnedDropoffs = inboxQuery.data?.total_unpinned ?? 0;
  const attentionCount = unpinnedDropoffs + pendingCount + provisionalCount;

  const terminals = terminalsQuery.data ?? [];
  const terminalsPinned = terminals.filter((x) => isValidCoordinate(x.lat, x.long)).length;
  const dropoffsTotalAll = dropoffTotalsQuery.data?.total ?? 0;
  const dropoffsPinned = Math.max(0, dropoffsTotalAll - unpinnedDropoffs);
  const totalPlaces = terminals.length + dropoffsTotalAll;
  const totalPinned = terminalsPinned + dropoffsPinned;
  const coveragePct = totalPlaces > 0 ? Math.round((totalPinned / totalPlaces) * 100) : 0;

  // Land on the catalog when there is nothing to fix (user choice always wins).
  React.useEffect(() => {
    if (tabDecided.current) return;
    const settled =
      (inboxQuery.isSuccess || inboxQuery.isError) &&
      (suggestionsQuery.isSuccess || suggestionsQuery.isError);
    if (!settled) return;
    tabDecided.current = true;
    if (attentionCount === 0) setTab('dropoffs');
  }, [
    inboxQuery.isSuccess,
    inboxQuery.isError,
    suggestionsQuery.isSuccess,
    suggestionsQuery.isError,
    attentionCount,
  ]);

  const handleTabChange = (value: string) => {
    tabDecided.current = true;
    setTab(value as LocationsTab);
  };

  /* ---- Terminals view ---- */
  const [terminalSearch, setTerminalSearch] = React.useState('');
  const [terminalPinFilter, setTerminalPinFilter] = React.useState<PinFilter>('all');
  const [selectedTerminalId, setSelectedTerminalId] = React.useState<number | null>(null);
  const selectedTerminal =
    selectedTerminalId != null ? terminals.find((x) => x.ID === selectedTerminalId) ?? null : null;

  const visibleTerminals = React.useMemo(() => {
    const q = terminalSearch.trim().toLowerCase();
    return terminals.filter((x) => {
      if (terminalPinFilter === 'missing' && isValidCoordinate(x.lat, x.long)) return false;
      if (q && !x.name.toLowerCase().includes(q)) return false;
      return true;
    });
  }, [terminals, terminalSearch, terminalPinFilter]);

  /* ---- Drop-offs view (server-side search + filter + pagination) ---- */
  const [search, setSearch] = React.useState('');
  const debouncedSearch = useDebounce(search, 300);
  const [pinFilter, setPinFilter] = React.useState<PinFilter>('all');
  const [page, setPage] = React.useState(1);
  const [limit, setLimit] = React.useState(storedLimit);

  React.useEffect(() => {
    setPage(1);
  }, [debouncedSearch, pinFilter, limit]);

  const dropoffsQuery = useDropoffs({
    q: debouncedSearch.trim() || undefined,
    missing: pinFilter === 'missing' || undefined,
    page,
    per_page: limit,
  });
  const dropoffs = dropoffsQuery.data?.items ?? [];
  const dropoffsTotal = dropoffsQuery.data?.total ?? 0;
  const dropoffsPages = Math.max(1, Math.ceil(dropoffsTotal / limit));

  const handleLimitChange = (next: number) => {
    setLimit(next);
    try {
      localStorage.setItem(LIMIT_STORAGE_KEY, String(next));
    } catch {
      /* storage may be unavailable; the in-memory value still applies */
    }
  };

  const [editingDropoffId, setEditingDropoffId] = React.useState<number | null>(null);
  const editingDropoff =
    editingDropoffId != null ? dropoffs.find((d) => d.ID === editingDropoffId) ?? null : null;
  const [pendingDelete, setPendingDelete] = React.useState<DropOffPoint | null>(null);
  const deleteDropoff = useDeleteDropoff();

  const handleDeleteConfirm = async () => {
    if (!pendingDelete) return;
    try {
      await deleteDropoff.mutateAsync(pendingDelete.ID);
    } catch {
      // Toast (incl. the 409 "still referenced" case) handled by the mutation
    } finally {
      setPendingDelete(null);
    }
  };

  const pinPills = (
    value: PinFilter,
    onChange: (v: PinFilter) => void,
    missingCount?: number,
  ) => (
    <div className="flex gap-1.5">
      {(
        [
          { id: 'all', label: t('locations.filter.all', 'All') },
          { id: 'missing', label: t('locations.filter.missingPins', 'Missing pins') },
        ] as Array<{ id: PinFilter; label: string }>
      ).map((p) => (
        <button
          key={p.id}
          type="button"
          onClick={() => onChange(p.id)}
          aria-pressed={value === p.id}
          className={cn(
            'inline-flex h-8 items-center gap-1.5 rounded-full border px-3 text-xs font-medium transition-colors',
            value === p.id
              ? 'border-primary bg-primary text-primary-foreground'
              : 'bg-card text-muted-foreground hover:bg-muted/60',
          )}
        >
          {p.label}
          {p.id === 'missing' && (missingCount ?? 0) > 0 && (
            <span className="tabular-nums opacity-80">{missingCount}</span>
          )}
        </button>
      ))}
    </div>
  );

  return (
    <PageShell
      title={t('locations.title', 'Locations')}
      description={t(
        'locations.description',
        'Manage canonical terminals and drop-off points — pins, radii, company allowlists, and receipt serialization — in one place.',
      )}
    >
      {/* ---- Coverage header: the page's one job, made visible ---- */}
      <div className="mb-4 grid gap-3 sm:grid-cols-3">
        <div
          className={cn(
            'rounded-lg border p-4 sm:col-span-1',
            attentionCount > 0 ? 'border-warning/50 bg-warning/5' : 'border-success/40 bg-success/5',
          )}
        >
          {attentionCount > 0 ? (
            <>
              <div className="text-3xl font-semibold tabular-nums text-warning">
                {attentionCount}
              </div>
              <div className="mt-0.5 text-sm text-muted-foreground">
                {t('locations.header.needAttention', 'locations need attention')}
              </div>
              <Button size="sm" className="mt-3" onClick={() => handleTabChange('inbox')}>
                {t('locations.header.startPinning', 'Start pinning')}
              </Button>
            </>
          ) : (
            <div className="flex h-full flex-col justify-center gap-1">
              <div className="flex items-center gap-2 text-success">
                <CheckCircle2 className="h-5 w-5" />
                <span className="font-medium">
                  {t('locations.header.allPinned', 'Every location is pinned')}
                </span>
              </div>
              <p className="text-xs text-muted-foreground">
                {t('locations.header.allPinnedSub', 'New names appear here automatically.')}
              </p>
            </div>
          )}
        </div>

        <div className="rounded-lg border bg-card p-4">
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <MapPin className="h-4 w-4" />
            {t('locations.header.dropoffs', 'Drop-off points')}
          </div>
          <div className="mt-1 text-2xl font-semibold tabular-nums" dir="ltr">
            {dropoffsPinned}/{dropoffsTotalAll}
          </div>
          <div className="text-xs text-muted-foreground">
            {t('locations.header.pinned', 'pinned')}
          </div>
        </div>

        <div className="rounded-lg border bg-card p-4">
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Warehouse className="h-4 w-4" />
            {t('locations.header.terminals', 'Terminals')}
          </div>
          <div className="mt-1 text-2xl font-semibold tabular-nums" dir="ltr">
            {terminalsPinned}/{terminals.length}
          </div>
          <div className="text-xs text-muted-foreground">
            {t('locations.header.pinned', 'pinned')}
          </div>
        </div>

        <div className="sm:col-span-3">
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>{t('locations.header.coverage', 'Pin coverage')}</span>
            <span className="tabular-nums">{coveragePct}%</span>
          </div>
          <Progress value={coveragePct} className="mt-1 h-1.5" />
        </div>
      </div>

      <Tabs value={tab} onValueChange={handleTabChange}>
        <TabsList>
          <TabsTrigger value="inbox" className="gap-1.5">
            <Inbox className="h-3.5 w-3.5" />
            {t('locations.tabs.inbox', 'Needs Attention')}
            {attentionCount > 0 && (
              <Badge variant="warning" className="px-1.5">
                {attentionCount}
              </Badge>
            )}
          </TabsTrigger>
          <TabsTrigger value="dropoffs">
            {t('locations.tabs.dropoffs', 'Drop-off Points')}
          </TabsTrigger>
          <TabsTrigger value="terminals">{t('locations.tabs.terminals', 'Terminals')}</TabsTrigger>
        </TabsList>

        <TabsContent value="inbox" className="mt-4">
          <LocationsNeedsAttention onBrowseDropoffs={() => handleTabChange('dropoffs')} />
        </TabsContent>

        <TabsContent value="dropoffs" className="mt-4 space-y-3">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
            <SearchInput
              value={search}
              onChange={setSearch}
              placeholder={t('locations.dropoffs.searchPlaceholder', 'Search drop-off points…')}
              className="sm:max-w-sm"
            />
            {pinPills(pinFilter, setPinFilter, unpinnedDropoffs)}
          </div>
          <LocationsDropoffsTable
            dropoffs={dropoffs}
            loading={dropoffsQuery.isLoading}
            onRowClick={(dropoff) => setEditingDropoffId(dropoff.ID)}
            pageSize={limit}
          />
          <TripsPagination
            page={page}
            pages={dropoffsPages}
            total={dropoffsTotal}
            limit={limit}
            onPageChange={setPage}
            onLimitChange={handleLimitChange}
            loading={dropoffsQuery.isFetching}
          />
        </TabsContent>

        <TabsContent value="terminals" className="mt-4 space-y-3">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
            <SearchInput
              value={terminalSearch}
              onChange={setTerminalSearch}
              placeholder={t('locations.terminals.searchPlaceholder', 'Search terminals…')}
              className="sm:max-w-sm"
            />
            {pinPills(
              terminalPinFilter,
              setTerminalPinFilter,
              terminals.length - terminalsPinned,
            )}
          </div>
          <LocationsTerminalsTable
            terminals={visibleTerminals}
            loading={terminalsQuery.isLoading}
            onRowClick={(terminal) => setSelectedTerminalId(terminal.ID)}
          />
        </TabsContent>
      </Tabs>

      {/* Terminal editor */}
      <LocationsTerminalDialog
        terminal={selectedTerminal}
        onOpenChange={(open) => {
          if (!open) setSelectedTerminalId(null);
        }}
      />

      {/* Drop-off editor */}
      <LocationsDropoffDialog
        open={editingDropoff !== null}
        onOpenChange={(open) => {
          if (!open) setEditingDropoffId(null);
        }}
        dropoff={editingDropoff}
        onDelete={(d) => {
          setEditingDropoffId(null);
          setPendingDelete(d);
        }}
      />

      {/* Delete confirmation */}
      <ConfirmDialog
        open={pendingDelete !== null}
        onOpenChange={(open) => {
          if (!open) setPendingDelete(null);
        }}
        title={t('locations.dropoffs.deleteTitle', 'Delete drop-off point?')}
        description={pendingDelete?.name}
        loading={deleteDropoff.isPending}
        onConfirm={handleDeleteConfirm}
      />
    </PageShell>
  );
}

import * as React from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { intentProps, warmOilForm } from '@/shared/lib/prefetch';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Droplets,
  Plus,
  Download,
  CheckCircle2,
  AlertTriangle,
  AlertCircle,
  Truck,
} from 'lucide-react';
import { PageShell } from '@/shared/ui/page-shell';
import { Button } from '@/shared/ui/button';
import { StatCard } from '@/shared/ui/stat-card';
import { EmptyState } from '@/shared/ui/empty-state';
import { ConfirmDialog } from '@/shared/ui/confirm-dialog';
import {
  useOilChanges,
  useDeleteOilChange,
} from '@/entities/oil-change/queries';
import { selectLatestPerCar } from '@/entities/oil-change/api';
import type { OilChangeView } from '@/entities/oil-change/schemas';
import { useDebounce } from '@/shared/hooks/use-debounce';
import { matches } from '@/shared/lib/normalize';
import { formatCurrency } from '@/shared/lib/format';
import { formatCompactCurrency } from '@/shared/lib/format-number';
import { OilChangesTable } from '@/widgets/oil-changes-table/oil-changes-table';
import {
  OilChangesFilters,
  type StatusFilterValue,
} from '@/widgets/oil-changes-table/oil-changes-filters';
import { exportOilChangesFleet } from '@/widgets/oil-changes-table/oil-changes-excel';

/* -------------------------------------------------------------------------- */
/* URL helpers                                                                 */
/* -------------------------------------------------------------------------- */

function isStatusFilter(v: string | null): v is StatusFilterValue {
  return v === 'all' || v === 'good' || v === 'warning' || v === 'critical';
}

export default function OilChangesPage() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [searchParams, setSearchParams] = useSearchParams();

  const [search, setSearch] = React.useState(() => searchParams.get('q') ?? '');
  const debouncedSearch = useDebounce(search, 200);

  const [statusFilter, setStatusFilter] = React.useState<StatusFilterValue>(() => {
    const url = searchParams.get('status');
    return isStatusFilter(url) ? url : 'all';
  });

  const [pendingDelete, setPendingDelete] = React.useState<OilChangeView | null>(null);
  const [exporting, setExporting] = React.useState(false);

  const { data: records = [], isLoading, isError, refetch } = useOilChanges();
  const deleteMutation = useDeleteOilChange();

  /* ------------------------------------------------------------------------ */
  /* Sync state → URL                                                         */
  /* ------------------------------------------------------------------------ */

  React.useEffect(() => {
    const next = new URLSearchParams();
    if (debouncedSearch) next.set('q', debouncedSearch);
    if (statusFilter !== 'all') next.set('status', statusFilter);
    setSearchParams(next, { replace: true });
  }, [debouncedSearch, statusFilter, setSearchParams]);

  /* ------------------------------------------------------------------------ */
  /* Pipeline: fetched → latest-per-car → search → status                     */
  /* ------------------------------------------------------------------------ */

  const latestPerCar = React.useMemo(
    () => selectLatestPerCar(records),
    [records],
  );

  const searched = React.useMemo(() => {
    if (!debouncedSearch.trim()) return latestPerCar;
    return latestPerCar.filter(
      (r) =>
        matches(r.car_no_plate, debouncedSearch) ||
        matches(r.super_visor, debouncedSearch) ||
        matches(r.driver_name, debouncedSearch),
    );
  }, [latestPerCar, debouncedSearch]);

  const filtered = React.useMemo(() => {
    if (statusFilter === 'all') return searched;
    return searched.filter((r) => r.status === statusFilter);
  }, [searched, statusFilter]);

  /* ------------------------------------------------------------------------ */
  /* Counts (derived from the SEARCH result, before status filter applies)    */
  /* This way the status tabs always show how many items would appear if you  */
  /* clicked them.                                                            */
  /* ------------------------------------------------------------------------ */

  const counts = React.useMemo(() => {
    const c = { all: searched.length, good: 0, warning: 0, critical: 0 };
    for (const r of searched) c[r.status]++;
    return c;
  }, [searched]);

  /* ------------------------------------------------------------------------ */
  /* KPI stats — computed from latest-per-car (NOT the filtered set), so the  */
  /* fleet-wide picture stays stable while the table reflects the filter.    */
  /* ------------------------------------------------------------------------ */

  const stats = React.useMemo(() => {
    const totalCost = latestPerCar.reduce((s, r) => s + r.cost, 0);
    const good = latestPerCar.filter((r) => r.status === 'good').length;
    const warning = latestPerCar.filter((r) => r.status === 'warning').length;
    const critical = latestPerCar.filter((r) => r.status === 'critical').length;
    return {
      totalVehicles: latestPerCar.length,
      good,
      warning,
      critical,
      totalCost,
    };
  }, [latestPerCar]);

  /* ------------------------------------------------------------------------ */
  /* Handlers                                                                 */
  /* ------------------------------------------------------------------------ */

  const handleViewHistory = React.useCallback(
    (carNoPlate: string) => {
      // The history page reads the plate from the URL — encode it so plates
      // with spaces or Arabic glyphs survive the round-trip.
      navigate(`/oil-changes/car/${encodeURIComponent(carNoPlate)}`);
    },
    [navigate],
  );

  const handleConfirmDelete = async () => {
    if (!pendingDelete) return;
    await deleteMutation.mutateAsync(pendingDelete.ID);
    setPendingDelete(null);
  };

  const handleExport = async () => {
    if (filtered.length === 0) return;
    setExporting(true);
    try {
      await exportOilChangesFleet({ rows: filtered, t });
    } finally {
      setExporting(false);
    }
  };

  /* ------------------------------------------------------------------------ */
  /* Render                                                                   */
  /* ------------------------------------------------------------------------ */

  const showEmptyState = !isLoading && latestPerCar.length === 0;

  return (
    <PageShell
      title={t('oilChanges.title')}
      description={t('oilChanges.subtitle')}
      icon={<Droplets className="h-5 w-5" />}
      actions={
        <>
          <Button
            variant="outline"
            size="sm"
            onClick={handleExport}
            disabled={exporting || filtered.length === 0}
          >
            <Download className="h-4 w-4" />
            <span className="hidden sm:inline">{t('common.export')}</span>
          </Button>
          <Button onClick={() => navigate('/oil-changes/new')} size="sm" {...intentProps(() => warmOilForm(queryClient))}>
            <Plus className="h-4 w-4" />
            <span className="hidden sm:inline">{t('oilChanges.addNew')}</span>
          </Button>
        </>
      }
    >
      {isError ? (
        <EmptyState
          lottieSrc="/animations/warning.lottie"
          lottieWidth={100}
          lottieHeight={100}
          title={t('errors.generic')}
          action={
            <Button onClick={() => void refetch()} variant="outline">
              {t('common.retry')}
            </Button>
          }
        />
      ) : showEmptyState ? (
        <EmptyState
          lottieSrc="/animations/construction.lottie"
          lottieWidth={120}
          lottieHeight={120}
          title={t('oilChanges.empty.title')}
          description={t('oilChanges.empty.description')}
          action={
            <Button onClick={() => navigate('/oil-changes/new')} {...intentProps(() => warmOilForm(queryClient))}>
              <Plus className="h-4 w-4" />
              {t('oilChanges.addNew')}
            </Button>
          }
        />
      ) : (
        <>
          {/* KPI cards */}
          <div className="grid grid-cols-2 gap-2.5 md:grid-cols-3 lg:grid-cols-5">
            <StatCard
              label={t('oilChanges.stats.totalVehicles')}
              value={String(stats.totalVehicles)}
              icon={Truck}
              tone="primary"
            />
            <StatCard
              label={t('oilChanges.status.good')}
              value={String(stats.good)}
              icon={CheckCircle2}
              tone="success"
            />
            <StatCard
              label={t('oilChanges.status.warning')}
              value={String(stats.warning)}
              icon={AlertTriangle}
              tone="warning"
            />
            <StatCard
              label={t('oilChanges.status.critical')}
              value={String(stats.critical)}
              icon={AlertCircle}
              tone="destructive"
            />
            <StatCard
              label={t('oilChanges.stats.totalCost')}
              value={{
                full: formatCurrency(stats.totalCost),
                compact: formatCompactCurrency(stats.totalCost),
              }}
              icon={Droplets}
              tone="primary"
            />
          </div>

          {/* Filters */}
          <OilChangesFilters
            search={search}
            onSearchChange={setSearch}
            statusFilter={statusFilter}
            onStatusFilterChange={setStatusFilter}
            counts={counts}
          />

          {/* Filter-aware count line */}
          {(debouncedSearch || statusFilter !== 'all') && (
            <p className="text-xs text-muted-foreground">
              {t('oilChanges.filters.showingCount', {
                shown: filtered.length,
                total: latestPerCar.length,
              })}
            </p>
          )}

          {/* Table */}
          <OilChangesTable
            rows={filtered}
            loading={isLoading}
            onViewHistory={handleViewHistory}
            onDelete={(row) => setPendingDelete(row)}
            emptyState={
              <div className="flex flex-col items-center gap-2 py-8 text-sm">
                <span className="text-muted-foreground">
                  {t('oilChanges.empty.noMatches')}
                </span>
                {(debouncedSearch || statusFilter !== 'all') && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      setSearch('');
                      setStatusFilter('all');
                    }}
                  >
                    {t('common.clearFilters')}
                  </Button>
                )}
              </div>
            }
          />
        </>
      )}

      <ConfirmDialog
        open={!!pendingDelete}
        onOpenChange={(open) => {
          if (!open) setPendingDelete(null);
        }}
        title={t('oilChanges.delete.title')}
        description={
          pendingDelete
            ? t('oilChanges.delete.description', { plate: pendingDelete.car_no_plate })
            : ''
        }
        confirmLabel={t('common.delete')}
        loading={deleteMutation.isPending}
        onConfirm={handleConfirmDelete}
      />
    </PageShell>
  );
}

