                        {formatNumber(needsReviewCount)}
                      </span>
                    )}
                  </TabsTrigger>
                ))}
              </TabsList>
            </Tabs>

            <div className="flex flex-1 flex-wrap items-center justify-end gap-2 sm:flex-nowrap">
              <SearchInput
                value={search}
                onChange={setSearch}
                placeholder={t(
                  'tripAudit.filters.searchPlaceholder',
