                  </Button>
                </PopoverTrigger>
                <PopoverContent align="end" className="w-[340px] space-y-4 p-4">
                  {view === 'all' && (
                    <div className="space-y-2">
                      <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
