import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { resolveAnimationPath } from '@/shared/lib/animations';
import { Loader2 } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogTitle,
} from './dialog';
import { Button } from './button';

const LazyDotLottieReact = React.lazy(() =>
  import('@lottiefiles/dotlottie-react').then((module) => ({
    default: module.DotLottieReact,
  }))
);

interface ConfirmDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  confirmLabel?: React.ReactNode;
  cancelLabel?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'success';
  loading?: boolean;
  onConfirm: () => void | Promise<void>;
  lottieSrc?: string;
  /** Render above bottom sheets (needed when confirming from inside one). */
  stacked?: boolean;
}

export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  description,
  confirmLabel,
  cancelLabel,
  variant = 'destructive',
  loading = false,
  onConfirm,
  lottieSrc,
  stacked = false,
}: ConfirmDialogProps) {
  const { t } = useTranslation();

  // Auto-default Lottie animation based on variant
  const activeLottieSrc = lottieSrc ?? (
    variant === 'destructive' ? '/animations/warning.lottie' :
    variant === 'success' ? '/animations/success.lottie' :
    undefined
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent stacked={stacked} className="max-w-[400px] text-center p-6 gap-6">
        <div className="flex flex-col items-center gap-4">
          {activeLottieSrc && (
            <div className="flex h-20 w-20 items-center justify-center shrink-0">
              <React.Suspense fallback={<div className="h-full w-full bg-transparent" />}>
                <LazyDotLottieReact
                  src={resolveAnimationPath(activeLottieSrc)}
                  loop
                  autoplay
                />
              </React.Suspense>
            </div>
          )}

          <div className="space-y-2">
            <DialogTitle className="text-xl font-bold tracking-tight text-center">
              {title}
            </DialogTitle>
            {description && (
              <DialogDescription className="text-sm text-muted-foreground text-center px-2">
                {description}
              </DialogDescription>
            )}
          </div>
        </div>

        <DialogFooter className="flex flex-col-reverse sm:flex-row sm:justify-center gap-2 sm:gap-2">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={loading}
            className="w-full sm:w-auto"
          >
            {cancelLabel ?? t('common.cancel')}
          </Button>
          <Button
            variant={variant === 'success' ? 'default' : variant}
            onClick={() => void onConfirm()}
            disabled={loading}
            className="w-full sm:w-auto min-w-[80px]"
          >
            {loading && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
            {confirmLabel ?? t('common.confirm')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import * as React from 'react';
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type Row,
  type SortingState,
  type ColumnFiltersState,
  type ExpandedState,
  type RowSelectionState,
} from '@tanstack/react-table';
import { ChevronLeft, ChevronRight, ArrowUpDown } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { cn } from '@/shared/lib/cn';
import { Button } from './button';
import { Skeleton } from './skeleton';
import { EmptyState } from './empty-state';

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  loading?: boolean;
  emptyState?: React.ReactNode;
  onRowClick?: (row: TData) => void;
  /**
   * Intent prefetch: fired when the pointer enters, focus lands on, or a
   * finger touches a row — BEFORE any click. Pages pass a warmer that
   * preloads the destination chunk and/or the query the click would mount,
   * so the click lands on work already done. Must be cheap to repeat (chunk
   * imports and prefetchQuery both dedupe). Optional; rows without it behave
   * exactly as before.
   */
  onRowIntent?: (row: TData) => void;
  pageSize?: number;
  className?: string;
  /**
   * Optional footer row, typically used for column totals.
   *
   * Pass a function that receives the table's data and returns either an
   * array of cell values (one per column, must match `columns.length`) or
   * a fully rendered <tr>. When provided, the table renders a sticky
   * highlighted footer below the body.
   */
  footer?: (data: TData[]) => React.ReactNode[] | React.ReactElement;
  /**
   * Optional row-expansion config.
   *
   * Pass `getRowCanExpand` to gate which rows are expandable, and
   * `renderSubComponent` to render the expanded content (typically a
   * sub-table inset with start-side padding for visual hierarchy).
   *
   * When provided, rows render an additional toggle behaviour — clicking
   * the row toggles expansion (instead of firing `onRowClick`, which is
   * disabled when expansion is enabled to avoid conflicting handlers).
   */
  getRowCanExpand?: (row: Row<TData>) => boolean;
  renderSubComponent?: (row: Row<TData>) => React.ReactNode;
  /** Server-side pagination config */
  pagination?: {
    page: number;
    totalPages: number;
    onPageChange: (page: number) => void;
  };
}

/**
 * Generic data table on top of TanStack Table v8.
 *
 * Sortable column headers, client-side filtering, paginated, with optional
 * row-click handler, footer totals slot, and (new) row expansion for
 * drill-down hierarchies.
 *
 * **Row expansion.** When `renderSubComponent` is passed, each row that
 * passes `getRowCanExpand` becomes clickable; clicking toggles the expansion
 * state and renders the sub-component in a full-width row beneath. The
 * sub-component is your responsibility — typically a nested table for the
 * drill-down level. Expansion state is preserved across renders by TanStack
 * Table's internal state machine.
 *
 * Multiple rows can be expanded simultaneously. If you need exclusive (one-
 * at-a-time) expansion, manage the state externally and reset it via
 * controlled props (not currently exposed; add when needed).
 */
export function DataTable<TData, TValue>({
  columns,
  data,
  loading,
  emptyState,
  onRowClick,
  onRowIntent,
  pageSize = 20,
  className,
  footer,
  getRowCanExpand,
  renderSubComponent,
  pagination,
}: DataTableProps<TData, TValue>) {
  const { t } = useTranslation();
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([]);
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({});
  const [expanded, setExpanded] = React.useState<ExpandedState>({});

  const expansionEnabled = !!renderSubComponent;

  const table = useReactTable({
    data,
    columns,
    state: { 
      sorting, 
      columnFilters, 
      rowSelection, 
      expanded,
      ...(pagination ? {
        pagination: {
          pageIndex: pagination.page - 1,
          pageSize: pageSize,
        }
      } : {})
    },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onRowSelectionChange: setRowSelection,
    onExpandedChange: setExpanded,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: pagination ? undefined : getPaginationRowModel(),
    manualPagination: !!pagination,
    pageCount: pagination?.totalPages,
    getExpandedRowModel: expansionEnabled ? getExpandedRowModel() : undefined,
    getRowCanExpand,
    initialState: { 
      pagination: { 
        pageSize,
        pageIndex: pagination ? pagination.page - 1 : 0 
      } 
    },
  });

  // Resolve the footer slot — accept array-of-cells or rendered element forms
  const renderedFooter = React.useMemo(() => {
    if (!footer || loading || data.length === 0) return null;
    const rendered = footer(data);
    if (Array.isArray(rendered)) {
      return (
        <tr className="border-t-2 bg-muted/40 font-semibold">
          {rendered.map((cell, i) => {
            const col = columns[i];
            const align = (col?.meta as { align?: 'start' | 'end' | 'center' } | undefined)?.align;
            return (
              <td
                key={i}
                className={cn(
                  'px-4 py-3 text-sm tabular-nums',
                  align === 'end' && 'text-end',
                  align === 'center' && 'text-center',
                )}
              >
                {cell}
              </td>
            );
          })}
        </tr>
      );
    }
    return rendered;
  }, [footer, data, loading, columns]);

  return (
    <div className={cn('space-y-3', className)}>
      <div className="overflow-hidden rounded-lg border bg-card">
        <div className="relative w-full overflow-auto">
          <table className="w-full caption-bottom text-sm">
            <thead className="border-b bg-muted/50 text-xs uppercase tracking-wider text-muted-foreground">
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id}>
                  {headerGroup.headers.map((header) => (
                    <th
                      key={header.id}
                      className="h-11 px-4 text-start font-medium"
                      style={{ width: header.getSize() !== 150 ? header.getSize() : undefined }}
                    >
                      {header.isPlaceholder ? null : header.column.getCanSort() ? (
                        <button
                          type="button"
                          className="flex items-center gap-1 hover:text-foreground"
                          onClick={header.column.getToggleSortingHandler()}
                        >
                          {flexRender(header.column.columnDef.header, header.getContext())}
                          <ArrowUpDown className="h-3 w-3" />
                        </button>
                      ) : (
                        flexRender(header.column.columnDef.header, header.getContext())
                      )}
                    </th>
                  ))}
                </tr>
              ))}
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <tr key={i} className="border-b last:border-0">
                    {columns.map((_, j) => (
                      <td key={j} className="p-4">
                        <Skeleton className="h-4 w-full" />
                      </td>
                    ))}
                  </tr>
                ))
              ) : table.getRowModel().rows?.length ? (
                table.getRowModel().rows.map((row) => {
                  const canExpand =
                    expansionEnabled && row.getCanExpand && row.getCanExpand();
                  const isExpanded = canExpand && row.getIsExpanded();
                  return (
                    <React.Fragment key={row.id}>
                      <tr
                        data-state={row.getIsSelected() && 'selected'}
                        data-expanded={isExpanded ? 'true' : undefined}
                        className={cn(
                          'border-b transition-colors last:border-0 hover:bg-muted/40 data-[state=selected]:bg-muted',
                          (onRowClick || canExpand) && 'cursor-pointer',
                          isExpanded && 'bg-muted/30',
                        )}
                        onClick={() => {
                          if (canExpand) {
                            row.toggleExpanded();
                          } else {
                            onRowClick?.(row.original);
                          }
                        }}
                        onPointerEnter={onRowIntent ? () => onRowIntent(row.original) : undefined}
                        onFocus={onRowIntent ? () => onRowIntent(row.original) : undefined}
                        onTouchStart={onRowIntent ? () => onRowIntent(row.original) : undefined}
                      >
                        {row.getVisibleCells().map((cell) => (
                          <td key={cell.id} className="px-4 py-3 align-middle">
                            {flexRender(cell.column.columnDef.cell, cell.getContext())}
                          </td>
                        ))}
                      </tr>
                      {isExpanded && renderSubComponent && (
                        <tr key={`${row.id}-expanded`} className="bg-muted/10">
                          <td
                            colSpan={row.getVisibleCells().length}
                            className="p-0"
                          >
                            {renderSubComponent(row)}
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={columns.length} className="p-0">
                    {typeof emptyState === 'string' || !emptyState ? (
                      <EmptyState
                        lottieSrc="/animations/no_results.json"
                        lottieWidth={100}
                        lottieHeight={100}
                        title={emptyState ?? t('common.noResults')}
                        className="border-0 bg-transparent py-12 shadow-none"
                      />
                    ) : (
                      emptyState
                    )}
                  </td>
                </tr>
              )}
            </tbody>
            {renderedFooter && <tfoot>{renderedFooter}</tfoot>}
          </table>
        </div>
      </div>

      {(pagination ? pagination.totalPages > 1 : table.getPageCount() > 1) && (
        <div className="flex items-center justify-between gap-2 text-sm text-muted-foreground">
          <span>
            {pagination ? pagination.page : table.getState().pagination.pageIndex + 1} / {pagination ? pagination.totalPages : table.getPageCount()}
          </span>
          <div className="flex items-center gap-1">
            <Button
              variant="outline"
              size="icon"
              onClick={() => pagination ? pagination.onPageChange(pagination.page - 1) : table.previousPage()}
              disabled={pagination ? pagination.page <= 1 : !table.getCanPreviousPage()}
            >
              <ChevronLeft className="h-4 w-4 rtl:rotate-180" />
            </Button>
            <Button
              variant="outline"
              size="icon"
              onClick={() => pagination ? pagination.onPageChange(pagination.page + 1) : table.nextPage()}
              disabled={pagination ? pagination.page >= pagination.totalPages : !table.getCanNextPage()}
            >
              <ChevronRight className="h-4 w-4 rtl:rotate-180" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Calendar as CalendarIcon } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from './button';
import { Popover, PopoverContent, PopoverTrigger } from './popover';
import { MonthYearSelector } from './month-year-selector';
import { fmtDate, localToday, type LocalParts } from '@/shared/lib/format';

interface Props {
  /** `YYYY-MM-DD` string — matches what zod's `zDateString` expects */
  value?: string;
  onChange: (value: string) => void;
  /** Optional max boundary as YYYY-MM-DD (inclusive) */
  max?: string;
  /** Optional min boundary as YYYY-MM-DD (inclusive) */
  min?: string;
  disabled?: boolean;
  placeholder?: string;
  className?: string;
  id?: string;
}

function partsFromDateString(s?: string): LocalParts | undefined {
  if (!s) return undefined;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return undefined;
  return { y: Number(m[1]), m: Number(m[2]) - 1, d: Number(m[3]) };
}

function toDateString(p: LocalParts): string {
  const mm = String(p.m + 1).padStart(2, '0');
  const dd = String(p.d).padStart(2, '0');
  return `${p.y}-${mm}-${dd}`;
}

const toNum = (p: LocalParts) => p.y * 10000 + p.m * 100 + p.d;

/**
 * Single-date picker, visually consistent with `DateRangePicker`. Uses the
 * same calendar grid, month navigation, and disabled-future-date behaviour.
 *
 * Value is a `YYYY-MM-DD` string so it slots directly into react-hook-form
 * fields validated by `zDateString`. When the popover is closed, the trigger
 * shows the formatted date ("24 Apr 2026") or a placeholder.
 */
export function DatePicker({
  value,
  onChange,
  max,
  min,
  disabled,
  placeholder,
  className,
  id,
}: Props) {
  const { t, i18n } = useTranslation();
  const locale = i18n.language.startsWith('ar') ? 'ar-EG' : 'en-GB';
  const [open, setOpen] = React.useState(false);

  const selected = partsFromDateString(value);
  const today = localToday();

  const [viewMonth, setViewMonth] = React.useState(selected?.m ?? today.m);
  const [viewYear, setViewYear] = React.useState(selected?.y ?? today.y);

  // When opening, reset the viewport to whatever is currently selected
  React.useEffect(() => {
    if (open) {
      const anchor = selected ?? today;
      setViewMonth(anchor.m);
      setViewYear(anchor.y);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const minParts = partsFromDateString(min);
  const maxParts = partsFromDateString(max);
  const minNum = minParts ? toNum(minParts) : null;
  const maxNum = maxParts ? toNum(maxParts) : null;
  const selectedNum = selected ? toNum(selected) : null;
  const todayNum = toNum(today);

  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
  const firstDay = new Date(viewYear, viewMonth, 1).getDay();
  const cells: (number | null)[] = [
    ...Array(firstDay).fill(null),
    ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
  ];

  const weekdayNames = React.useMemo(() => {
    const fmt = new Intl.DateTimeFormat(locale, { weekday: 'short' });
    return Array.from({ length: 7 }, (_, i) => fmt.format(new Date(2024, 0, 7 + i))); // Sun..Sat
  }, [locale]);

  const handleSelect = (day: number) => {
    const p: LocalParts = { y: viewYear, m: viewMonth, d: day };
    onChange(toDateString(p));
    setOpen(false);
  };

  const label = value ? fmtDate(value) : (placeholder ?? t('common.selectDate'));

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          id={id}
          variant="outline"
          role="combobox"
          disabled={disabled}
          className={cn(
            'h-9 w-full justify-between font-normal',
            !value && 'text-muted-foreground',
            className,
          )}
        >
          <span className="truncate">{label}</span>
          <CalendarIcon className="h-4 w-4 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-4" align="start">
        <MonthYearSelector
          month={viewMonth}
          year={viewYear}
          onChange={(m, y) => {
            setViewMonth(m);
            setViewYear(y);
          }}
          minYear={minParts?.y}
          maxYear={maxParts?.y}
        />

        <div className="mb-1 grid grid-cols-7">
          {weekdayNames.map((d) => (
            <div
              key={d}
              className="py-1 text-center text-[10px] font-semibold text-muted-foreground"
            >
              {d}
            </div>
          ))}
        </div>

        <div className="grid grid-cols-7 gap-y-0.5">
          {cells.map((d, i) => {
            if (!d) return <div key={i} />;
            const dn = viewYear * 10000 + viewMonth * 100 + d;
            const isFuture = maxNum !== null ? dn > maxNum : dn > todayNum;
            const isBeforeMin = minNum !== null && dn < minNum;
            const disabledCell = isFuture || isBeforeMin;
            const isToday = dn === todayNum;
            const isSelected = selectedNum !== null && dn === selectedNum;

            return (
              <div key={i} className="flex h-8 items-center justify-center">
                <button
                  type="button"
                  disabled={disabledCell}
                  onClick={() => !disabledCell && handleSelect(d)}
                  className={cn(
                    'flex h-8 w-8 items-center justify-center rounded-full text-xs font-medium transition-colors',
                    disabledCell && 'cursor-not-allowed text-muted-foreground/30',
                    !disabledCell && !isSelected && 'hover:bg-muted',
                    isToday && !isSelected && 'border border-primary text-primary',
                    isSelected && 'bg-primary font-semibold text-primary-foreground shadow-sm',
                  )}
                >
                  {d}
                </button>
              </div>
            );
          })}
        </div>

        <div className="mt-3 flex items-center justify-between border-t pt-3">
          <button
            type="button"
            onClick={() => {
              onChange(toDateString(today));
              setOpen(false);
            }}
            className="text-xs font-medium text-primary hover:underline"
          >
            {t('datePicker.today')}
          </button>
          <Button variant="ghost" size="sm" onClick={() => setOpen(false)}>
            {t('common.cancel')}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Calendar as CalendarIcon } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from './button';
import { Popover, PopoverContent, PopoverTrigger } from './popover';
import { MonthYearSelector } from './month-year-selector';
import {
  fmtDate,
  localDateISO,
  localParts,
  localToday,
  type LocalParts,
} from '@/shared/lib/format';

const toNum = (p?: LocalParts) => (p ? p.y * 10000 + p.m * 100 + p.d : null);

interface Props {
  from?: string | null;
  to?: string | null;
  onChange: (from: string | null, to: string | null) => void;
  /** Optional class name for the outer flex container */
  className?: string;
}

/**
 * A preset is a named range producer. `getRange` returns `[fromISO, toISO]`
 * for that preset given today's local date. This generalisation (vs. the
 * old N-days shape) lets us express boundary-based ranges like "current
 * month" — start of this month → today — alongside count-based ones.
 */
interface Preset {
  key: string;
  getRange: (today: LocalParts) => [string, string];
}

function lastNDaysRange(today: LocalParts, days: number): [string, string] {
  const startMs = new Date(today.y, today.m, today.d).getTime() - days * 86_400_000;
  const d = new Date(startMs);
  return [
    localDateISO(d.getFullYear(), d.getMonth(), d.getDate()),
    localDateISO(today.y, today.m, today.d, true),
  ];
}

function currentMonthRange(today: LocalParts): [string, string] {
  return [
    localDateISO(today.y, today.m, 1),
    localDateISO(today.y, today.m, today.d, true),
  ];
}

const PRESETS: Preset[] = [
  { key: 'today', getRange: (today) => lastNDaysRange(today, 0) },
  { key: 'days7', getRange: (today) => lastNDaysRange(today, 7) },
  { key: 'currentMonth', getRange: (today) => currentMonthRange(today) },
  { key: 'days90', getRange: (today) => lastNDaysRange(today, 90) },
];

export function DateRangePicker({ from, to, onChange, className }: Props) {
  const { t, i18n } = useTranslation();
  const locale = i18n.language.startsWith('ar') ? 'ar-EG' : 'en-GB';
  const [open, setOpen] = React.useState(false);
  const [hovered, setHovered] = React.useState<LocalParts | undefined>();

  const fromParts = from ? localParts(from) : undefined;
  const toParts = to ? localParts(to) : undefined;
  const [selected, setSelected] = React.useState<{ from?: LocalParts; to?: LocalParts }>({
    from: fromParts,
    to: toParts,
  });

  React.useEffect(() => {
    setSelected({
      from: from ? localParts(from) : undefined,
      to: to ? localParts(to) : undefined,
    });
  }, [from, to]);

  const today = localToday();
  const [month, setMonth] = React.useState(today.m);
  const [year, setYear] = React.useState(today.y);

  const applyPreset = (preset: Preset) => {
    const [f, tt] = preset.getRange(localToday());
    onChange(f, tt);
  };

  const isPresetActive = (preset: Preset): boolean => {
    if (!from || !to) return false;
    const [f, tt] = preset.getRange(localToday());
    return from === f && to === tt;
  };

  const handleSelect = (p: LocalParts) => {
    if (!selected.from || (selected.from && selected.to)) {
      setSelected({ from: p, to: undefined });
    } else {
      const f = toNum(selected.from)!;
      const c = toNum(p)!;
      if (c >= f) setSelected({ from: selected.from, to: p });
      else setSelected({ from: p, to: selected.from });
    }
  };

  const handleApply = () => {
    if (selected.from) {
      const f = selected.from;
      const tEnd = selected.to ?? selected.from;
      onChange(localDateISO(f.y, f.m, f.d), localDateISO(tEnd.y, tEnd.m, tEnd.d, true));
    }
    setOpen(false);
  };

  const isAllTime = !from && !to;
  const isCustom = Boolean(from) && !PRESETS.some(isPresetActive) && !isAllTime;

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();
  const cells: (number | null)[] = [
    ...Array(firstDay).fill(null),
    ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
  ];

  const fromNum = toNum(selected.from);
  const toNum_ = toNum(selected.to ?? hovered);
  const todayNum = today.y * 10000 + today.m * 100 + today.d;

  const weekdayNames = React.useMemo(() => {
    const fmt = new Intl.DateTimeFormat(locale, { weekday: 'short' });
    return Array.from({ length: 7 }, (_, i) => fmt.format(new Date(2024, 0, 7 + i)));
  }, [locale]);

  return (
    <div
      className={cn(
        // Wraps rather than scrolls. A horizontal scroller hides options
        // off-screen with nothing to say they are there, which is a poor trade
        // for a control whose whole job is showing you the choices. The chips
        // are small enough on a phone that all of them fit in two lines.
        'flex flex-wrap items-center gap-1.5',
        className,
      )}
    >
      {PRESETS.map((p) => (
        <Button
          key={p.key}
          variant={isPresetActive(p) ? 'default' : 'outline'}
          size="sm"
          onClick={() => applyPreset(p)}
          className="h-7 shrink-0 px-2 text-[11px] sm:h-8 sm:px-3 sm:text-xs"
        >
          <span className="sm:hidden">{t(`datePicker.short.${p.key}`)}</span>
          <span className="hidden sm:inline">{t(`datePicker.${p.key}`)}</span>
        </Button>
      ))}
      <Button
        variant={isAllTime ? 'default' : 'outline'}
        size="sm"
        onClick={() => onChange(null, null)}
        className="h-7 shrink-0 px-2 text-[11px] sm:h-8 sm:px-3 sm:text-xs"
      >
        <span className="sm:hidden">{t('datePicker.short.allTime')}</span>
        <span className="hidden sm:inline">{t('datePicker.allTime')}</span>
      </Button>

      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant={isCustom ? 'default' : 'outline'}
            size="sm"
            className="h-7 shrink-0 gap-1 px-2 text-[11px] sm:h-8 sm:gap-1.5 sm:px-3 sm:text-xs"
          >
            <CalendarIcon className="h-3 w-3" />
            {isCustom ? `${fmtDate(from)} → ${to ? fmtDate(to) : ''}` : t('datePicker.custom')}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-4" align="start">
          <div className="mb-4 flex items-center gap-3 rounded-lg bg-muted p-2.5 text-xs">
            <div className="flex-1 text-center">
              <p className="mb-0.5 text-muted-foreground">{t('common.from')}</p>
              <p className="font-semibold">
                {selected.from
                  ? fmtDate(localDateISO(selected.from.y, selected.from.m, selected.from.d))
                  : '—'}
              </p>
            </div>
            <div className="h-6 w-px bg-border" />
            <div className="flex-1 text-center">
              <p className="mb-0.5 text-muted-foreground">{t('common.to')}</p>
              <p className="font-semibold">
                {selected.to
                  ? fmtDate(localDateISO(selected.to.y, selected.to.m, selected.to.d))
                  : hovered
                    ? fmtDate(localDateISO(hovered.y, hovered.m, hovered.d))
                    : '—'}
              </p>
            </div>
          </div>

          <MonthYearSelector
            month={month}
            year={year}
            onChange={(m, y) => {
              setMonth(m);
              setYear(y);
            }}
          />

          <div className="mb-1 grid grid-cols-7">
            {weekdayNames.map((d) => (
              <div
                key={d}
                className="py-1 text-center text-[10px] font-semibold text-muted-foreground"
              >
                {d}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-y-0.5">
            {cells.map((d, i) => {
              if (!d) return <div key={i} />;
              const dn = year * 10000 + month * 100 + d;
              const isFuture = dn > todayNum;
              const isToday = dn === todayNum;
              const isStart = fromNum !== null && dn === fromNum;
              const isEnd =
                toNum_ !== null && fromNum !== null && dn === toNum_ && toNum_ !== fromNum;
              const lo = fromNum !== null && toNum_ !== null ? Math.min(fromNum, toNum_) : null;
              const hi = fromNum !== null && toNum_ !== null ? Math.max(fromNum, toNum_) : null;
              const inRange = lo !== null && hi !== null && dn > lo && dn < hi;

              return (
                <div
                  key={i}
                  className={cn(
                    'relative flex h-8 items-center justify-center',
                    inRange && 'bg-primary/10',
                    isStart && 'rounded-s-full bg-primary/10',
                    isEnd && 'rounded-e-full bg-primary/10',
                    isStart && !selected.to && !hovered && 'rounded-full',
                  )}
                >
                  <button
                    type="button"
                    disabled={isFuture}
                    onClick={() => !isFuture && handleSelect({ y: year, m: month, d })}
                    onMouseEnter={() => !isFuture && setHovered({ y: year, m: month, d })}
                    onMouseLeave={() => setHovered(undefined)}
                    className={cn(
                      'flex h-8 w-8 items-center justify-center rounded-full text-xs font-medium',
                      isFuture && 'cursor-not-allowed text-muted-foreground/30',
                      !isFuture && !isStart && !isEnd && 'hover:bg-muted',
                      isToday && !isStart && !isEnd && 'border border-primary text-primary',
                      (isStart || isEnd) &&
                        'bg-primary font-semibold text-primary-foreground shadow-sm',
                    )}
                  >
                    {d}
                  </button>
                </div>
              );
            })}
          </div>

          <div className="mt-4 flex items-center justify-between border-t pt-3">
            <p className="text-xs text-muted-foreground">
              {!selected.from
                ? t('datePicker.clickStart')
                : !selected.to
                  ? t('datePicker.clickEnd')
                  : t('datePicker.rangeSelected')}
            </p>
            <div className="flex gap-2">
              <Button variant="ghost" size="sm" onClick={() => setOpen(false)}>
                {t('common.cancel')}
              </Button>
              <Button size="sm" onClick={handleApply} disabled={!selected.from}>
                {t('datePicker.apply')}
              </Button>
            </div>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

