import * as React from 'react';
import { cn } from '@/shared/lib/cn';
import { isGoogleMapsConfigured } from '@/shared/lib/maps/google-provider';
import type { MapProvider, MapViewProps } from '@/shared/lib/maps/types';

declare global {
  interface Window {
    gm_authFailure?: () => void;
  }
}

/* -------------------------------------------------------------------------- */
/* Lazy provider components                                                    */
/*                                                                             */
/* Both providers are lazy-loaded. The Google provider's bundle pulls in       */
/* @googlemaps/js-api-loader; Leaflet's pulls in leaflet + its CSS. Lazy       */
/* loading both means the user pays the cost of exactly one provider — the    */
/* one that ends up rendering — instead of both upfront.                      */
/* -------------------------------------------------------------------------- */

const GoogleMapView = React.lazy(() =>
  import('@/shared/lib/maps/google-provider').then((m) => ({
    default: m.GoogleMapView,
  })),
);

const LeafletMapView = React.lazy(() =>
  import('@/shared/lib/maps/leaflet-provider').then((m) => ({
    default: m.LeafletMapView,
  })),
);

/* -------------------------------------------------------------------------- */
/* Provider selection logic                                                    */
/*                                                                             */
/* Always tries Google first. Falls through to Leaflet when:                   */
/*   1. VITE_GOOGLE_MAPS_API_KEY isn't set in the environment                 */
/*   2. The Google SDK fails to load within `fallbackTimeoutMs` (default 3s)  */
/*   3. The Google SDK throws on import (e.g. blocked by network policy)      */
/*                                                                             */
/* Once the cascade has decided which provider to use for a given page load,  */
/* it sticks with that decision — we don't bounce back to Google after a      */
/* fallback, since the user has already seen the Leaflet UI.                  */
/* -------------------------------------------------------------------------- */

interface MapShellProps extends MapViewProps {}

export function MapView({
  fallbackTimeoutMs = 8000,
  onProviderChange,
  className,
  ...rest
}: MapShellProps) {
  // Decide initial provider synchronously based on env
  const [provider, setProvider] = React.useState<MapProvider>(() => {
    const configured = isGoogleMapsConfigured();
    const apiKey = import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string | undefined;
    console.log('[MapView] Initializing map view.', {
      isGoogleMapsConfigured: configured,
      apiKeyLength: apiKey?.length || 0,
      apiKeyPreview: apiKey ? `${apiKey.substring(0, 8)}...` : 'none',
      fallbackTimeoutMs,
    });
    return configured ? 'google' : 'leaflet';
  });
  const [forcedFallback, setForcedFallback] = React.useState(false);

  // Listen for Google Maps authentication or referer failures globally.
  // This triggers an immediate, seamless fallback to Leaflet if the key is restricted/invalid.
  React.useEffect(() => {
    window.gm_authFailure = () => {
      console.warn('[MapView] Google Maps global auth/referer failure detected — falling back to Leaflet');
      setProvider('leaflet');
      setForcedFallback(true);
    };
    return () => {
      window.gm_authFailure = undefined;
    };
  }, []);

  // Notify consumer of provider choice
  React.useEffect(() => {
    console.log('[MapView] Map provider set to:', provider, { forcedFallback });
    onProviderChange?.(provider);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [provider]);

  /* -------- Timeout-based fallback -------------------------------------- */
  /*
   * If we're trying Google but the SDK doesn't render within the timeout,
   * flip to Leaflet. We can't directly observe "Google SDK loaded" from
   * here (the lazy boundary hides that), so we use a simple wall-clock
   * timer: if the Google component hasn't replaced the suspense fallback
   * within N ms, we assume it's stuck and switch. Once switched, we stay.
   */

  const containerRef = React.useRef<HTMLDivElement>(null);
  React.useEffect(() => {
    if (provider !== 'google' || forcedFallback) return;

    const timer = window.setTimeout(() => {
      // If after the timeout the inner container has no children with
      // dimension > 0, we assume Google failed silently (e.g. invalid key,
      // blocked network) and fall back. The "rendered something" check
      // looks for a Google-injected canvas/img/div with non-zero size.
      // We only accept `.gm-style` (fully loaded map) and exclude
      // `.gm-err-container` (error popup container) so that errors also fallback.
      const node = containerRef.current;
      if (!node) return;
      const rendered = node.querySelector('.gm-style');
      if (!rendered) {
        console.warn(
          '[MapView] Google Maps did not render within',
          fallbackTimeoutMs,
          'ms — falling back to Leaflet',
        );
        setProvider('leaflet');
        setForcedFallback(true);
      }
    }, fallbackTimeoutMs);

    return () => window.clearTimeout(timer);
  }, [provider, fallbackTimeoutMs, forcedFallback]);

  /* -------- Error-boundary-style fallback ------------------------------- */
  /*
   * The lazy import itself can reject — e.g. Google's loader hits a CORS
   * error or the chunk fails to fetch. React.lazy surfaces this as a
   * thrown promise / error which would otherwise crash the tree. A small
   * inline error boundary catches it and triggers fallback.
   */

  return (
    <div ref={containerRef} className={cn('relative h-full w-full', className)}>
      <ProviderErrorBoundary
        onError={(err) => {
          if (provider === 'google') {
            console.error('[MapView] Google provider threw an error — falling back to Leaflet:', err);
            setProvider('leaflet');
            setForcedFallback(true);
          }
        }}
      >
        <React.Suspense fallback={<MapLoadingState />}>
          {provider === 'google' ? (
            <GoogleMapView {...rest} className={className} />
          ) : (
            <LeafletMapView {...rest} className={className} />
          )}
        </React.Suspense>
      </ProviderErrorBoundary>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Loading + error states                                                      */
/* -------------------------------------------------------------------------- */

function MapLoadingState() {
  return (
    <div className="flex h-full w-full items-center justify-center rounded-lg bg-muted/30">
      <div className="flex flex-col items-center gap-2 text-muted-foreground">
        <div className="h-6 w-6 animate-spin rounded-full border-2 border-current border-t-transparent" />
        <span className="text-xs">Loading map…</span>
      </div>
    </div>
  );
}

interface ErrorBoundaryProps {
  children: React.ReactNode;
  onError: (err: unknown) => void;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

class ProviderErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(err: unknown) {
    this.props.onError(err);
  }

  componentDidUpdate(prevProps: ErrorBoundaryProps) {
    // Reset when children identity changes — i.e. provider swap
    if (prevProps.children !== this.props.children && this.state.hasError) {
      this.setState({ hasError: false });
    }
  }

  render() {
    if (this.state.hasError) return <MapLoadingState />;
    return this.props.children;
  }
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from './select';

interface MonthYearSelectorProps {
  month: number; // 0-indexed
  year: number;
  onChange: (month: number, year: number) => void;
  /** Optional lower bound year — defaults to current year - 10 */
  minYear?: number;
  /** Optional upper bound year — defaults to current year */
  maxYear?: number;
}

/**
 * Header bar for both DatePicker and DateRangePicker.
 *
 * Month-by-month navigation via chevrons stays fast for adjacent months.
 * The month and year labels are clickable dropdowns for quick jumps back
 * in time — a two-click path to any month in the past decade.
 *
 * Month names are locale-aware via Intl. Year range clamps to `minYear` /
 * `maxYear` when given, otherwise defaults to the last ten years through
 * the current year (no future years by default — the pickers disable future
 * dates anyway, so exposing future years would create dead options).
 */
export function MonthYearSelector({
  month,
  year,
  onChange,
  minYear,
  maxYear,
}: MonthYearSelectorProps) {
  const { i18n } = useTranslation();
  const locale = i18n.language.startsWith('ar') ? 'ar-EG' : 'en-GB';

  const currentYear = new Date().getFullYear();
  const yMin = minYear ?? currentYear - 10;
  const yMax = maxYear ?? currentYear;

  // Always include the currently-selected year in the range even if it's
  // somehow outside the bounds (edit mode on old data, for example).
  const effectiveMin = Math.min(yMin, year);
  const effectiveMax = Math.max(yMax, year);

  const monthNames = React.useMemo(() => {
    const fmt = new Intl.DateTimeFormat(locale, { month: 'long' });
    return Array.from({ length: 12 }, (_, i) => fmt.format(new Date(2024, i, 1)));
  }, [locale]);

  const years = React.useMemo(() => {
    const list: number[] = [];
    for (let y = effectiveMax; y >= effectiveMin; y--) list.push(y);
    return list;
  }, [effectiveMin, effectiveMax]);

  const goPrev = () => {
    if (month === 0) onChange(11, year - 1);
    else onChange(month - 1, year);
  };
  const goNext = () => {
    if (month === 11) onChange(0, year + 1);
    else onChange(month + 1, year);
  };

  return (
    <div className="mb-3 flex items-center gap-1.5">
      <button
        type="button"
        onClick={goPrev}
        className="rounded p-1 hover:bg-muted"
        aria-label="Previous month"
      >
        <ChevronLeft className="h-3.5 w-3.5 rtl:rotate-180" />
      </button>

      <div className="flex flex-1 items-center justify-center gap-1">
        <Select
          value={String(month)}
          onValueChange={(v) => onChange(Number(v), year)}
        >
          <SelectTrigger className="h-8 w-auto gap-1 border-none bg-transparent px-2 text-sm font-semibold shadow-none focus:ring-1">
            <SelectValue>{monthNames[month]}</SelectValue>
          </SelectTrigger>
          <SelectContent>
            {monthNames.map((name, i) => (
              <SelectItem key={i} value={String(i)}>
                {name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <Select
          value={String(year)}
          onValueChange={(v) => onChange(month, Number(v))}
        >
          <SelectTrigger className="h-8 w-auto gap-1 border-none bg-transparent px-2 text-sm font-semibold shadow-none focus:ring-1">
            <SelectValue>{year}</SelectValue>
          </SelectTrigger>
          <SelectContent>
            {years.map((y) => (
              <SelectItem key={y} value={String(y)}>
                {y}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <button
        type="button"
        onClick={goNext}
        className="rounded p-1 hover:bg-muted"
        aria-label="Next month"
      >
        <ChevronRight className="h-3.5 w-3.5 rtl:rotate-180" />
      </button>
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Check, ChevronDown, X } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from './button';
import { Popover, PopoverContent, PopoverTrigger } from './popover';
import { EmptyState } from './empty-state';

export interface MultiSelectOption<T extends string = string> {
  value: T;
  label: React.ReactNode;
  /** Optional sub-label / hint shown in muted text under the main label. */
  description?: React.ReactNode;
  /** Optional dot color class (e.g. `bg-success`) for a leading status dot. */
  dot?: string;
  /** Disable this option without removing it. */
  disabled?: boolean;
}

interface MultiSelectProps<T extends string = string> {
  options: MultiSelectOption<T>[];
  value: T[];
  onChange: (next: T[]) => void;

  /** Placeholder shown on the trigger when nothing is selected. */
  placeholder?: React.ReactNode;
  /** Heading shown at the top of the popover. */
  heading?: React.ReactNode;
  /** Empty-state message when there are no options. */
  emptyState?: React.ReactNode;

  /** Optional id forwarded to the trigger button (so labels link up). */
  id?: string;
  className?: string;

  /** Match the trigger height to your form inputs. Defaults to `h-10`. */
  triggerHeight?: 'sm' | 'md';

  /** Disable the entire control. */
  disabled?: boolean;

  /** Show the trigger in compact form (no count badge / clear icon). */
  compact?: boolean;

  /** Override the popover alignment — defaults to `start` for form context. */
  align?: 'start' | 'center' | 'end';
}

/**
 * Multi-select popover with checkbox-style toggling.
 *
 * Trigger button shows the selected items as a comma-separated summary (or a
 * placeholder when empty). The body renders each option as a row with a
 * leading dot/checkbox indicator, the label, optional description, and a
 * trailing checkmark when selected. Clicking an option toggles it in place
 * without closing the popover so users can pick multiple values quickly.
 *
 * Design follows the existing `FuelEventsFilterPopover` pattern — same
 * popover-with-toggleable-rows shape, same dot-indicator approach. The
 * difference is this is generic and works with any value type.
 *
 * Use this whenever a form field needs to accept 0..N values from a fixed
 * list. For free-form tag entry use a different control.
 */
export function MultiSelect<T extends string = string>({
  options,
  value,
  onChange,
  placeholder,
  heading,
  emptyState,
  id,
  className,
  triggerHeight = 'md',
  disabled,
  compact,
  align = 'start',
}: MultiSelectProps<T>) {
  const { t } = useTranslation();
  const [open, setOpen] = React.useState(false);

  const selected = React.useMemo(() => new Set(value), [value]);
  const count = selected.size;

  const toggle = (v: T) => {
    const next = new Set(selected);
    if (next.has(v)) next.delete(v);
    else next.add(v);
    // Preserve the original option order when emitting the new array
    onChange(options.filter((o) => next.has(o.value)).map((o) => o.value));
  };

  const clear = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    onChange([]);
  };

  // Compose a readable summary of selected options for the trigger button.
  // For 1–2 items show the labels; for more, show "N selected".
  const summaryNode = React.useMemo(() => {
    if (count === 0) {
      return (
        <span className="truncate text-muted-foreground">
          {placeholder ?? t('common.select')}
        </span>
      );
    }
    if (count <= 2) {
      const labels = options
        .filter((o) => selected.has(o.value))
        .map((o) => o.label);
      return (
        <span className="truncate">
          {labels.map((l, i) => (
            <React.Fragment key={i}>
              {i > 0 && <span className="text-muted-foreground">, </span>}
              {l}
            </React.Fragment>
          ))}
        </span>
      );
    }
    return (
      <span className="truncate">
        {t('common.selectedCount', { count })}
      </span>
    );
  }, [count, options, selected, placeholder, t]);

  const triggerHClass = triggerHeight === 'sm' ? 'h-9' : 'h-10';

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          id={id}
          variant="outline"
          disabled={disabled}
          className={cn(
            'w-full justify-between gap-2 px-3 font-normal',
            triggerHClass,
            // Match the visual weight of <SelectTrigger>: when nothing's
            // selected the placeholder is muted; when something is, full
            // foreground.
            count === 0 && 'text-muted-foreground',
            className,
          )}
        >
          <span className="flex min-w-0 flex-1 items-center gap-2">
            {summaryNode}
            {!compact && count > 0 && (
              <span className="inline-flex h-4 min-w-4 shrink-0 items-center justify-center rounded-full bg-primary px-1 text-[10px] font-semibold text-primary-foreground">
                {count}
              </span>
            )}
          </span>
          <span className="flex shrink-0 items-center gap-1">
            {!compact && count > 0 && (
              <span
                role="button"
                tabIndex={0}
                aria-label={t('common.clear')}
                onClick={clear}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    clear();
                  }
                }}
                className="inline-flex h-4 w-4 items-center justify-center rounded-sm text-muted-foreground hover:bg-muted hover:text-foreground"
              >
                <X className="h-3 w-3" />
              </span>
            )}
            <ChevronDown className="h-4 w-4 shrink-0 text-muted-foreground" />
          </span>
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align={align}
        className="w-[--radix-popover-trigger-width] min-w-[12rem] p-2"
      >
        {(heading || count > 0) && (
          <div className="flex items-center justify-between px-2 py-1.5">
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
              {heading ?? t('common.options')}
            </p>
            {count > 0 && (
              <button
                type="button"
                onClick={() => clear()}
                className="inline-flex items-center gap-0.5 text-[11px] text-muted-foreground hover:text-foreground"
              >
                <X className="h-3 w-3" />
                {t('common.clear')}
              </button>
            )}
          </div>
        )}
        {options.length === 0 ? (
          <div className="p-0">
            <EmptyState
              lottieSrc="/animations/no_results.json"
              lottieWidth={70}
              lottieHeight={70}
              title={emptyState ?? t('common.noOptions')}
              className="border-0 bg-transparent py-4 shadow-none"
            />
          </div>
        ) : (
          <ul className="space-y-0.5">
            {options.map((opt) => {
              const isSelected = selected.has(opt.value);
              return (
                <li key={opt.value}>
                  <button
                    type="button"
                    onClick={() => !opt.disabled && toggle(opt.value)}
                    disabled={opt.disabled}
                    className={cn(
                      'flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm transition-colors',
                      isSelected
                        ? 'bg-accent text-accent-foreground'
                        : 'hover:bg-accent/60',
                      opt.disabled && 'cursor-not-allowed opacity-40 hover:bg-transparent',
                    )}
                  >
                    {opt.dot ? (
                      <span className={cn('h-2 w-2 shrink-0 rounded-full', opt.dot)} />
                    ) : (
                      // Checkbox affordance for options without a dot
                      <span
                        className={cn(
                          'flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded border',
                          isSelected
                            ? 'border-primary bg-primary text-primary-foreground'
                            : 'border-input',
                        )}
                      >
                        {isSelected && <Check className="h-3 w-3" />}
                      </span>
                    )}
                    <span className="flex min-w-0 flex-1 flex-col text-start">
                      <span className="truncate">{opt.label}</span>
                      {opt.description && (
                        <span className="truncate text-[11px] text-muted-foreground">
                          {opt.description}
                        </span>
                      )}
                    </span>
                    {opt.dot && isSelected && (
                      <Check className="h-3.5 w-3.5 shrink-0 text-primary" />
                    )}
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </PopoverContent>
    </Popover>
  );
}

