                      placeholder={t('drivers.fields.namePlaceholder')}
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="mobile_number"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>
                    {t('drivers.fields.phone')}{' '}
                    <span className="text-xs text-muted-foreground">({t('common.optional')})</span>
                  </FormLabel>
                  <FormControl>
                    <Input
                      type="tel"
