                <FormItem>
                  <FormLabel>
                    {t('drivers.fields.idExpiry')}{' '}
                    <span className="text-xs text-muted-foreground">({t('common.optional')})</span>
                  </FormLabel>
                  <FormControl>
                    <DatePicker
                      value={field.value}
                      onChange={field.onChange}
                      max="2099-12-31"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
