            <FormField
              control={form.control}
              name="safety_license_expiration_date"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('drivers.fields.safetyExpiry')}</FormLabel>
                  <FormControl>
                    <DatePicker
                      value={field.value}
                      onChange={field.onChange}
                      max="2099-12-31"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
