/* -------------------------------------------------------------------------- */
/* Day grouping                                                                */
/*                                                                            */
/* Rows arrive ordered occurred_at DESC from the API, so grouping is a single  */
/* sequential pass — a day split across two fetched pages still lands in one   */
/* group. Day TOTALS never come from these rows: they are looked up in         */
/* statistics.by_date, which the server computed over the whole filtered set   */
/* in exact decimal. No client float sums, ever.                               */
/* -------------------------------------------------------------------------- */

interface DayGroup {
  key: string;
  rows: Transaction[];
}

function groupByCairoDay(rows: Transaction[]): DayGroup[] {
  const groups: DayGroup[] = [];
  let current: DayGroup | null = null;
  for (const row of rows) {
    const key = cairoDayKey(row.occurred_at);
    if (!current || current.key !== key) {
      current = { key, rows: [] };
      groups.push(current);
    }
    current.rows.push(row);
  }
  return groups;
}

/* -------------------------------------------------------------------------- */
/* Inline category flow                                                        */
/* -------------------------------------------------------------------------- */

type CategoryFlow =
  | { row: Transaction; step: 'category' }
  | { row: Transaction; step: 'party'; category: Category };

/* -------------------------------------------------------------------------- */
/* Widget                                                                      */
/* -------------------------------------------------------------------------- */

interface LedgerListProps {
  rows: Transaction[];
  /** statistics.by_date, keyed by Cairo day — the only source of day totals. */
  dayTotals: Map<string, ByDate>;
  canEdit: boolean;
}

/**
 * The day-grouped transaction list with STICKY day headers.
 *
 * Stickiness silently no-ops under the wrong ancestors, so the structure is
 * deliberate: the app's scroll root is the layout's `<main>` (the app bar sits
 * OUTSIDE it, so the correct offset is `top-0`), and nothing between these
 * headers and `<main>` — this widget, PageShell, or the page — may have
 * non-visible overflow. That is why there is no rounded `overflow-hidden`
 * card around the list and no `overflow-x-auto` around the desktop table;
 * the table uses `table-fixed` + truncation for width containment instead.
 */
export function LedgerList({ rows, dayTotals, canEdit }: LedgerListProps) {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const categories = useCategories();
  const update = useUpdateTransaction();

  const [flow, setFlow] = React.useState<CategoryFlow | null>(null);
  const [party, setParty] = React.useState<PartyValue>({ driver_id: null, employee_id: null });
  /** The row the split editor was opened for — a child OR an unsplit row. */
  const [splitRow, setSplitRow] = React.useState<Transaction | null>(null);
  const [splitOpen, setSplitOpen] = React.useState(false);

  const groups = React.useMemo(() => groupByCairoDay(rows), [rows]);
  const catByKey = React.useMemo(
    () => new Map((categories.data ?? []).map((c) => [c.key, c])),
    [categories.data],
  );

  // Loaded siblings per parent, in list order — lets a chip say "2 of 3" when
  // the set happens to be on this page, and just "part of X" when it isn't.
  const splitSiblings = React.useMemo(() => {
    const map = new Map<number, number[]>();
    for (const row of rows) {
      if (row.parent_id == null) continue;
      const ids = map.get(row.parent_id) ?? [];
      ids.push(row.id);
      map.set(row.parent_id, ids);
    }
    return map;
  }, [rows]);

  const openSplit = (row: Transaction) => {
    setSplitRow(row);
    setSplitOpen(true);
  };

  const queryClient = useQueryClient();

  // Intent: the edit page mounts the transaction by id. Warming it on
  // hover/focus of a row means the edit form opens pre-filled from cache
  // instead of on a spinner. The chunk warms alongside it.
  const warmEdit = (row: Transaction) => {
    if (!canEdit || !row.editable) return;
    warmLedgerForm(queryClient, 'fleet-expense-edit');
    prefetchTransaction(queryClient, row.id);
  };

  const openEdit = (row: Transaction) => {
    if (!canEdit || !row.editable) return;
    navigate(`/fleet-expenses/${row.id}/edit`, { state: { from: 'ledger' } });
  };

  /** A category was picked for a row (from the select or the sheet). */
  const pickCategory = (row: Transaction, key: string) => {
    const cat = catByKey.get(key);
    if (!cat) return;
    if (requiresParty(cat) || posts(cat)) {
      // Two-step: the category needs a person. One PATCH at the end.
      setParty({ driver_id: null, employee_id: null });
      setFlow({ row, step: 'party', category: cat });
      return;
    }
    update.mutate(
      { id: row.id, version: row.version, values: { category: key } },
      { onSuccess: () => setFlow(null) },
    );
  };

  const saveWithParty = () => {
    if (flow?.step !== 'party') return;
    if (!party.driver_id && !party.employee_id) return;
    update.mutate(
      {
        id: flow.row.id,
        version: flow.row.version,
        values: {
          category: flow.category.key,
          driver_id: party.driver_id,
          employee_id: party.employee_id,
        },
      },
      { onSuccess: () => setFlow(null) },
    );
  };

  return (
    <div>
      {groups.map((group, index) => {
        const total = dayTotals.get(group.key);
        return (
          // Keyed with the index too: the API orders rows occurred_at DESC so
          // a day never repeats, but a duplicate React key would silently
          // drop rows if that ordering ever hiccuped.
          <section key={`${group.key}-${index}`}>
            {/* Sticky day header — top-0 because the app bar is outside the
                scroll root. bg required: content scrolls beneath it. */}
            <div className="sticky top-0 z-10 flex items-center justify-between gap-3 border-y bg-background px-3 py-1.5 text-xs font-semibold text-muted-foreground">
              <span>{formatCairoDay(group.key, i18n.language)}</span>
              {total && (
                <span className="tabular-nums" dir="ltr">
                  − {formatMoney(total.out)}
                </span>
              )}
            </div>

            {/* Phones ≤ lg: cards. */}
            <ul className="lg:hidden">
              {group.rows.map((row) => (
                <li key={`${row.source}-${row.id}`} {...intentProps(() => warmEdit(row))}>
                  <TxnCard
                    row={row}
                    canEdit={canEdit}
                    catByKey={catByKey}
                    onOpen={() => openEdit(row)}
                    onAddCategory={() => setFlow({ row, step: 'category' })}
                    splitSiblings={splitSiblings}
                    onOpenSplit={() => openSplit(row)}
                  />
                </li>
              ))}
            </ul>

            {/* Desktop: a table per day. table-fixed with shared widths keeps
                columns aligned across day groups without an overflow wrapper. */}
            <table className="hidden w-full table-fixed text-sm lg:table">
              {/* Delegated intent: rows are <tr>s rendered by TxnRow, so the
                  warm listens once here and resolves the row from the id the
                  <tr> stamps. */}
              <tbody
                onPointerOver={(e) => {
                  const tr = (e.target as HTMLElement).closest('tr[data-txn-id]');
                  const id = tr?.getAttribute('data-txn-id');
                  const row = id ? group.rows.find((r) => String(r.id) === id) : undefined;
                  if (row) warmEdit(row);
                }}
              >
                {group.rows.map((row) => (
                  <TxnRow
                    key={`${row.source}-${row.id}`}
                    row={row}
                    canEdit={canEdit}
                    catByKey={catByKey}
                    categories={categories.data ?? []}
                    saving={update.isPending}
                    onOpen={() => openEdit(row)}
                    onPickCategory={(key) => pickCategory(row, key)}
                    splitSiblings={splitSiblings}
                    onOpenSplit={() => openSplit(row)}
                  />
                ))}
              </tbody>
            </table>
          </section>
        );
      })}

      {/* Bottom sheet: category step (mobile) and "to whom?" step (both). */}
      <Sheet open={!!flow} onOpenChange={(open) => !open && setFlow(null)}>
        <SheetContent
          side="bottom"
          className="mx-auto max-h-[80dvh] max-w-lg overflow-y-auto rounded-t-2xl p-4 pb-[max(1.5rem,env(safe-area-inset-bottom))]"
        >
          {flow?.step === 'category' && (
            <div className="space-y-3">
              <SheetHeading
                title={t('fleetExpenses.chooseCategory')}
                subtitle={flow.row.counterparty || flow.row.description || ''}
              />
              <div className="grid grid-cols-2 gap-2">
                {(categories.data ?? []).map((c) => (
                  <button
                    key={c.key}
                    type="button"
                    disabled={update.isPending}
                    onClick={() => pickCategory(flow.row, c.key)}
                    className="min-h-11 rounded-lg border px-3 py-2 text-start text-sm font-medium hover:bg-accent disabled:opacity-50"
                  >
                    {categoryLabel(c, i18n.language)}
                  </button>
                ))}
              </div>
            </div>
          )}

          {flow?.step === 'party' && (
            <div className="space-y-4">
              <SheetHeading
                title={t('fleetExpenses.toWhom')}
                subtitle={`${categoryLabel(flow.category, i18n.language)} · ${formatMoney(flow.row.amount)}`}
              />
              {/* History-aware: an exact counterparty match pre-selects the
                  person as a visible card; "Someone else" restores the picker.
                  Advancing becomes: pick category → see person → save. */}
              <SmartPartyField
                counterparty={flow.row.counterparty}
                value={party}
                onChange={setParty}
                required={(flow.category.required_party || 'either') as PartyKind}
              />
              {posts(flow.category) && (
                <p className="text-xs text-muted-foreground">
                  {t('fleetExpenses.party.postsNow')}
                </p>
              )}
              <div className="flex gap-2">
                <Button
                  variant="outline"
                  className="min-h-11 flex-1 sm:min-h-9"
                  onClick={() => setFlow(null)}
                  disabled={update.isPending}
                >
                  {t('common.cancel')}
                </Button>
                <Button
                  className="min-h-11 flex-1 sm:min-h-9"
                  onClick={saveWithParty}
                  disabled={update.isPending || (!party.driver_id && !party.employee_id)}
                >
                  {update.isPending ? t('common.saving') : t('common.save')}
                </Button>
              </div>
            </div>
          )}
        </SheetContent>
      </Sheet>

      {/* Split editor — new splits and existing sets both land here. The row
          is kept through the close animation on purpose. */}
      <SplitEditor
        open={splitOpen}
        onOpenChange={setSplitOpen}
        row={splitRow}
        canEdit={canEdit}
      />
    </div>
  );
}

function SheetHeading({ title, subtitle }: { title: string; subtitle?: string }) {
  return (
    <div className="space-y-0.5">
      <h3 className="text-base font-semibold">{title}</h3>
      {subtitle ? (
        <p className="truncate text-xs text-muted-foreground" dir="auto">
          {subtitle}
        </p>
      ) : null}
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Shared bits                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * The effective amount, signed by direction. Received money is the rare case
 * so it gets the colour; spending stays quiet ink. When the bank bundled the
 * 0.1% IPN fee, the derived split shows on hover.
 */
function Amount({ row, className }: { row: Transaction; className?: string }) {
  const { t } = useTranslation();
  const isIn = row.direction === 'in';
  const text = `${isIn ? '+' : '−'} ${formatMoney(row.amount)}${
    row.currency && row.currency !== 'EGP' ? ` ${row.currency}` : ''
  }`;

  const span = (
    <span
      dir="ltr"
      className={cn(
        'whitespace-nowrap font-semibold tabular-nums',
        isIn && 'text-emerald-600 dark:text-emerald-400',
        row.fee != null && 'cursor-help border-b border-dotted border-muted-foreground/50',
        className,
      )}
    >
      {text}
    </span>
  );

  if (row.fee == null) return span;
  return (
    <Tooltip>
      <TooltipTrigger asChild>{span}</TooltipTrigger>
      <TooltipContent>
        <div className="space-y-0.5 text-xs" dir="ltr">
          <div>
            {t('fleetExpenses.principal')}: {formatMoney(row.principal)}
          </div>
          <div>
            {t('fleetExpenses.fields.fee')}: {formatMoney(row.fee)}
          </div>
        </div>
      </TooltipContent>
    </Tooltip>
  );
}

/** Category chip for categorized rows. */
function CategoryChip({
  row,
  catByKey,
}: {
  row: Transaction;
  catByKey: Map<string, Category>;
}) {
  const { i18n } = useTranslation();
  if (!row.category) return null;
  const cat = catByKey.get(row.category);
  return (
    <span className="rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground">
      {cat ? categoryLabel(cat, i18n.language) : row.category}
    </span>
  );
}

function RowFlags({ row }: { row: Transaction }) {
  const { t, i18n } = useTranslation();
  return (
    <>
      {row.source === 'fuel_event' && <Fuel className="h-3.5 w-3.5 shrink-0 text-amber-500" />}
      {row.source === 'loan' && <HandCoins className="h-3.5 w-3.5 shrink-0 text-sky-500" />}
      {!row.editable && (
        <Tooltip>
          <TooltipTrigger asChild>
            <Lock className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
          </TooltipTrigger>
          <TooltipContent>{t('fleetExpenses.readOnlySource')}</TooltipContent>
        </Tooltip>
      )}
      {row.edited_by && (
        <Tooltip>
          <TooltipTrigger asChild>
            <PenLine className="h-3 w-3 shrink-0 text-amber-600 dark:text-amber-400" />
          </TooltipTrigger>
          <TooltipContent>
            {t('fleetExpenses.editedBy', {
              name: row.edited_by,
              date: row.edited_at ? formatCairoDate(row.edited_at, i18n.language) : '',
            })}
          </TooltipContent>
        </Tooltip>
      )}
    </>
  );
}

/* -------------------------------------------------------------------------- */
/* Mobile card                                                                 */
/*                                                                            */
/* Amount owns the right edge; references wrap (`overflow-wrap: anywhere`) so  */
/* a bare-hex token cannot force horizontal scroll at 375px; Arabic renders    */
/* dir="auto". No fixed columns.                                               */
/* -------------------------------------------------------------------------- */

function TxnCard({
  row,
  canEdit,
  catByKey,
  onOpen,
  onAddCategory,
  splitSiblings,
  onOpenSplit,
}: {
  row: Transaction;
  canEdit: boolean;
  catByKey: Map<string, Category>;
  onOpen: () => void;
  onAddCategory: () => void;
  splitSiblings: Map<number, number[]>;
  onOpenSplit: () => void;
}) {
  const { t, i18n } = useTranslation();
  const tappable = canEdit && row.editable;

  return (
    <div
      role={tappable ? 'button' : undefined}
      tabIndex={tappable ? 0 : undefined}
      onClick={tappable ? onOpen : undefined}
      onKeyDown={
        tappable
          ? (e) => {
              if (e.key === 'Enter' || e.key === ' ') onOpen();
            }
          : undefined
      }
      className={cn(
        'grid grid-cols-[minmax(0,1fr)_auto] gap-x-3 gap-y-1 border-b bg-card px-3 py-3',
        tappable && 'cursor-pointer active:bg-muted/40',
      )}
    >
      <p className="min-w-0 text-sm font-medium [overflow-wrap:anywhere]" dir="auto">
        {row.counterparty || row.description || '—'}
      </p>
      <Amount row={row} className="text-sm" />

      <div className="col-span-2 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground">
        {row.reference && (
          <span className="font-mono text-[11px] [overflow-wrap:anywhere]">{row.reference}</span>
        )}
        {row.account && <span className="tabular-nums">****{row.account}</span>}
        <span className="tabular-nums">{formatCairoTime(row.occurred_at, i18n.language)}</span>
        <RowFlags row={row} />
        {row.category ? (
          <CategoryChip row={row} catByKey={catByKey} />
        ) : canEdit && row.editable ? (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onAddCategory();
            }}
            className="min-h-9 rounded-full border border-dashed border-primary/50 px-3 py-0.5 text-xs font-semibold text-primary lg:min-h-8 lg:px-2.5"
          >
            + {t('fleetExpenses.addCategory')}
          </button>
        ) : null}
        {isSplitChild(row) && (
          <SplitChip
            row={row}
            siblings={row.parent_id != null ? splitSiblings.get(row.parent_id) : undefined}
            onOpen={onOpenSplit}
            className="min-h-9 lg:min-h-6"
          />
        )}
        {canEdit && splitEligible(row) && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onOpenSplit();
            }}
            className="inline-flex min-h-9 items-center gap-1 rounded-full border border-dashed px-3 py-0.5 text-xs font-semibold text-muted-foreground hover:text-foreground lg:min-h-8 lg:px-2.5"
          >
            <Split className="h-3 w-3 shrink-0" />
            {t('fleetExpenses.split.action')}
          </button>
        )}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Desktop row                                                                 */
/* -------------------------------------------------------------------------- */

function TxnRow({
  row,
  canEdit,
  catByKey,
  categories,
  saving,
  onOpen,
  onPickCategory,
  splitSiblings,
  onOpenSplit,
}: {
  row: Transaction;
  canEdit: boolean;
  catByKey: Map<string, Category>;
  categories: Category[];
  saving: boolean;
  onOpen: () => void;
  onPickCategory: (key: string) => void;
  splitSiblings: Map<number, number[]>;
  onOpenSplit: () => void;
}) {
  const { t, i18n } = useTranslation();
  const tappable = canEdit && row.editable;

  return (
    <tr
      data-txn-id={row.id}
      onClick={tappable ? onOpen : undefined}
      className={cn('border-b bg-card', tappable && 'cursor-pointer hover:bg-muted/40')}
    >
      <td className="w-16 whitespace-nowrap px-3 py-2.5 text-xs tabular-nums text-muted-foreground">
        {formatCairoTime(row.occurred_at, i18n.language)}
      </td>
      <td className="px-3 py-2.5">
        <div className="flex min-w-0 items-center gap-2">
          <span className="min-w-0 truncate font-medium" dir="auto">
            {row.counterparty || row.description || '—'}
          </span>
          {isSplitChild(row) && (
            <SplitChip
              row={row}
              siblings={row.parent_id != null ? splitSiblings.get(row.parent_id) : undefined}
              onOpen={onOpenSplit}
              className="shrink-0"
            />
          )}
        </div>
        {row.counterparty && row.description && (
          <div className="truncate text-xs text-muted-foreground" dir="auto">
            {row.description}
          </div>
        )}
      </td>
      <td className="w-44 px-3 py-2.5">
        {row.category ? (
          <CategoryChip row={row} catByKey={catByKey} />
        ) : canEdit && row.editable ? (
          /* Native select, on purpose — see NativeSelect. Click must not
             bubble into the row navigation. */
          <span onClick={(e) => e.stopPropagation()}>
            <NativeSelect
              className="w-36"
              value=""
              disabled={saving}
              aria-label={t('fleetExpenses.addCategory')}
              onChange={(e) => {
                if (e.target.value) onPickCategory(e.target.value);
              }}
            >
              <option value="">+ {t('fleetExpenses.addCategory')}</option>
              {categories.map((c) => (
                <option key={c.key} value={c.key}>
                  {categoryLabel(c, i18n.language)}
                </option>
              ))}
            </NativeSelect>
          </span>
        ) : (
          <span className="text-xs text-muted-foreground">—</span>
        )}
      </td>
      <td className="w-44 truncate px-3 py-2.5 font-mono text-xs text-muted-foreground">
        {row.reference || ''}
      </td>
      <td className="w-24 whitespace-nowrap px-3 py-2.5 text-xs tabular-nums text-muted-foreground">
        {row.account ? `****${row.account}` : ''}
      </td>
      <td className="w-24 px-3 py-2.5">
        <div className="flex items-center gap-1.5">
          <RowFlags row={row} />
          {canEdit && splitEligible(row) && (
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onOpenSplit();
                  }}
                  aria-label={t('fleetExpenses.split.action')}
                  className="flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground opacity-60 hover:bg-accent hover:text-foreground hover:opacity-100"
                >
                  <Split className="h-3.5 w-3.5" />
                </button>
              </TooltipTrigger>
              <TooltipContent>{t('fleetExpenses.split.action')}</TooltipContent>
            </Tooltip>
          )}
        </div>
      </td>
      <td className="w-36 px-3 py-2.5 text-end">
        <Amount row={row} className="text-sm" />
      </td>
    </tr>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Check, CheckCircle2, ChevronsUpDown, UserPlus, User, Truck } from 'lucide-react';

import { Button } from '@/shared/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/shared/ui/command';
import { Skeleton } from '@/shared/ui/skeleton';
import { cn } from '@/shared/lib/cn';
import {
  findExistingParty,
  useCreateEmployee,
  useParties,
  usePartySuggestion,
  type Party,
  type PartyKind,
} from '@/entities/transaction/categories';

export interface PartyValue {
  driver_id: number | null;
  employee_id: number | null;
}

/**
 * Picks the person a transaction is about, and can create a new employee inline.
 *
 * Stores an **id**, never a name. `public.loans.method` in this database shows
 * what free text becomes: one person recorded as 'Shady', 'shady', 'شادى',
 * 'Shady (تاني)' and 'Shady (x2)', in a column that also collected payment
 * methods, reasons, dates and whole sentences. None of that can be reported on.
 *
 * Creating is allowed; creating a duplicate is not. A typed name that matches an
 * existing person case- and whitespace-insensitively selects them instead of
 * offering to create a second row.
 */
export function PartyPicker({
  value,
  onChange,
  required,
  disabled,
}: {
  value: PartyValue;
  onChange: (v: PartyValue) => void;
  /** From the category: which kinds of person are acceptable. */
  required: PartyKind;
  disabled?: boolean;
}) {
  const { t } = useTranslation();
  const [open, setOpen] = React.useState(false);
  const [search, setSearch] = React.useState('');

  const parties = useParties();
  const createEmployee = useCreateEmployee();

  const all = React.useMemo(() => parties.data ?? [], [parties.data]);

  // Only offer people the category actually accepts — an advance restricted to
  // drivers must not let an office employee be selected.
  const selectable = React.useMemo(() => {
    if (required === 'driver') return all.filter((p) => p.kind === 'driver');
    if (required === 'employee') return all.filter((p) => p.kind === 'employee');
    return all;
  }, [all, required]);

  const selected: Party | undefined = React.useMemo(() => {
    if (value.driver_id) return all.find((p) => p.kind === 'driver' && p.id === value.driver_id);
    if (value.employee_id)
      return all.find((p) => p.kind === 'employee' && p.id === value.employee_id);
    return undefined;
  }, [all, value]);

  const select = (p: Party) => {
    onChange(
      p.kind === 'driver'
        ? { driver_id: p.id, employee_id: null }
        : { driver_id: null, employee_id: p.id },
    );
    setOpen(false);
    setSearch('');
  };

  const existingMatch = findExistingParty(all, search);
  // Creating is only offered for employees: drivers are onboarded properly
  // elsewhere, with licences and documents this picker knows nothing about.
  const canCreate =
    required !== 'driver' &&
    search.trim().length > 1 &&
    !existingMatch &&
    !createEmployee.isPending;

  const create = () => {
    createEmployee.mutate(search.trim(), {
      onSuccess: (created) => {
        const id = created?.ID ?? created?.id;
        if (typeof id === 'number') {
          onChange({ driver_id: null, employee_id: id });
          setOpen(false);
          setSearch('');
        }
      },
    });
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          disabled={disabled}
          // Full width so it is comfortably tappable on a phone.
          className="w-full justify-between font-normal"
        >
          <span className={cn('truncate', !selected && 'text-muted-foreground')}>
            {selected ? selected.name : t('fleetExpenses.party.placeholder')}
          </span>
          <ChevronsUpDown className="ms-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>

      {/* z-bumped above the Sheet overlay (z-[9999]) so the picker works when
          it renders inside the inline-category bottom sheet as well as on the
          plain edit form. */}
      <PopoverContent className="z-[10060] w-[--radix-popover-trigger-width] p-0" align="start">
        <Command shouldFilter>
          <CommandInput
            placeholder={t('fleetExpenses.party.search')}
            value={search}
            onValueChange={setSearch}
          />
          <CommandList>
            <CommandEmpty>
              <span className="block px-3 py-2 text-sm text-muted-foreground">
                {t('fleetExpenses.party.noMatch')}
              </span>
            </CommandEmpty>

            {selectable.some((p) => p.kind === 'driver') && (
              <CommandGroup heading={t('fleetExpenses.party.drivers')}>
                {selectable
                  .filter((p) => p.kind === 'driver')
                  .map((p) => (
                    <PartyRow
                      key={`d-${p.id}`}
                      party={p}
                      selected={value.driver_id === p.id}
                      onSelect={select}
                    />
                  ))}
              </CommandGroup>
            )}

            {selectable.some((p) => p.kind === 'employee') && (
              <CommandGroup heading={t('fleetExpenses.party.employees')}>
                {selectable
                  .filter((p) => p.kind === 'employee')
                  .map((p) => (
                    <PartyRow
                      key={`e-${p.id}`}
                      party={p}
                      selected={value.employee_id === p.id}
                      onSelect={select}
                    />
                  ))}
              </CommandGroup>
            )}
          </CommandList>

          {/* Persistent create action, OUTSIDE the filtered list: a new
              employee's name often partially matches existing people (half the
              staff share a first name), so waiting for zero matches would hide
              the button exactly when it's needed. It only disappears when the
              typed name matches someone exactly — that's the duplicate guard. */}
          {canCreate && (
            <button
              type="button"
              onClick={create}
              className="flex w-full items-center gap-2 border-t px-3 py-2 text-start text-sm hover:bg-accent"
            >
              <UserPlus className="h-4 w-4 shrink-0 text-muted-foreground" />
              <span className="truncate" dir="auto">
                {t('fleetExpenses.party.create', { name: search.trim() })}
              </span>
            </button>
          )}
        </Command>
      </PopoverContent>
    </Popover>
  );
}

/* -------------------------------------------------------------------------- */
/* SmartPartyField — the "to whom?" field with an exact-match history hint     */
/* -------------------------------------------------------------------------- */

/**
 * When the transaction's counterparty text was attributed to the same person
 * before, /parties/suggest returns them and this renders a PRE-SELECTED
 * suggestion card instead of the empty picker: the primary flow is just
 * confirming (saving uses the suggested ids), and "Someone else" swaps in the
 * normal PartyPicker (which keeps its create-employee footer).
 *
 * The suggestion never saves silently: the card is on screen the whole time
 * and saving still takes the form's explicit save tap. A suggestion whose kind
 * the category refuses (e.g. an employee for a drivers-only advance) is
 * treated as no suggestion at all.
 */
export function SmartPartyField({
  counterparty,
  value,
  onChange,
  required,
  disabled,
  suggest = true,
}: {
  /** The transaction's counterparty text — the lookup key. */
  counterparty?: string | null;
  value: PartyValue;
  onChange: (v: PartyValue) => void;
  required: PartyKind;
  disabled?: boolean;
  /** Pass false when the row already names a person — no second-guessing. */
  suggest?: boolean;
}) {
  const { t } = useTranslation();
  const [manual, setManual] = React.useState(false);

  const trimmed = (counterparty ?? '').trim();
  const active = suggest && !manual && !disabled && trimmed.length > 0;
  const suggestionQuery = usePartySuggestion(active ? trimmed : '');

  const raw = suggestionQuery.data ?? null;
  const suggestion =
    raw && (required === 'either' || required === 'none' || raw.kind === required)
      ? raw
      : null;

  // Pre-select the suggested ids the moment the card shows. Visible, not
  // silent: the card names the person, and saving is still the user's tap.
  const valueEmpty = !value.driver_id && !value.employee_id;
  React.useEffect(() => {
    if (!active || !suggestion || !valueEmpty) return;
    onChange({
      driver_id: suggestion.driver_id ?? null,
      employee_id: suggestion.employee_id ?? null,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, suggestion?.driver_id, suggestion?.employee_id]);

  if (active && suggestionQuery.isLoading) {
    return <Skeleton className="h-[74px] w-full rounded-lg" />;
  }

  if (active && suggestion) {
    const Icon = suggestion.kind === 'driver' ? Truck : User;
    return (
      <div className="rounded-lg border bg-muted/30 p-3">
        <div className="flex items-center gap-3">
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary">
            <Icon className="h-5 w-5" />
          </span>
          <span className="min-w-0 flex-1">
            <span className="block truncate text-sm font-semibold" dir="auto">
              {suggestion.name}
            </span>
            <span className="block text-xs text-muted-foreground">
              {t('fleetExpenses.party.matchedTimes', { count: suggestion.times })}
            </span>
          </span>
          <CheckCircle2 className="h-5 w-5 shrink-0 text-emerald-500" />
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="mt-2.5 min-h-10 w-full sm:min-h-8 sm:w-auto"
          onClick={() => {
            setManual(true);
            onChange({ driver_id: null, employee_id: null });
          }}
        >
          {t('fleetExpenses.party.someoneElse')}
        </Button>
      </div>
    );
  }

  return (
    <PartyPicker value={value} onChange={onChange} required={required} disabled={disabled} />
  );
}

function PartyRow({
  party,
  selected,
  onSelect,
}: {
  party: Party;
  selected: boolean;
  onSelect: (p: Party) => void;
}) {
  const Icon = party.kind === 'driver' ? Truck : User;
  return (
    <CommandItem value={`${party.name} ${party.kind}`} onSelect={() => onSelect(party)}>
      <Icon className="me-2 h-4 w-4 shrink-0 text-muted-foreground" />
      <span className="truncate" dir="auto">
        {party.name}
      </span>
      {selected && <Check className="ms-auto h-4 w-4 shrink-0" />}
    </CommandItem>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Plus, Split, X } from 'lucide-react';

import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { NativeSelect } from '@/shared/ui/native-select';
import { Sheet, SheetContent } from '@/shared/ui/sheet';
import { ConfirmDialog } from '@/shared/ui/confirm-dialog';
import { Skeleton } from '@/shared/ui/skeleton';
import { cn } from '@/shared/lib/cn';
import { addMoneyStrings, formatMoney, trimMoney } from '@/shared/lib/money';
import {
  categoryLabel,
  requiresParty,
  useCategories,
  type PartyKind,
} from '@/entities/transaction/categories';
import {
  useSaveSplit,
  useTransactionSplit,
  useUnsplit,
} from '@/entities/transaction/queries';
import {
  isSplitChild,
  type SplitPartInput,
  type Transaction,
} from '@/entities/transaction/schemas';
import { SmartPartyField, type PartyValue } from './party-picker';

/* -------------------------------------------------------------------------- */
/* Split editor                                                                */
/*                                                                            */
/* ONE sheet for every entry point: splitting an unsplit cash-out row (from    */
/* its edit screen or the ledger row action) and editing an existing set       */
/* (from a child's chip or edit screen). Which mode applies is read off the    */
/* row itself: a split child loads the whole set via GET .../split; anything   */
/* else IS the parent-to-be.                                                   */
/*                                                                            */
/* The source amount is a fixed header; parts are amount + category (+ the     */
/* SmartPartyField when the category needs a person); a live remainder line    */
/* does EXACT decimal math through addMoneyStrings — never a float — and the   */
/* save button stays disabled until the remainder is exactly zero, because     */
/* the server rejects any other sum with a 400 anyway.                         */
/*                                                                            */
/* Saving POSTs a new split or PUTs a replacement part set, always with the    */
/* PARENT's version as If-Match. Unsplit dissolves the set behind a confirm.   */
/* -------------------------------------------------------------------------- */

/** Same shape the transaction form accepts: NUMERIC(18,4)'s decimal strings. */
const AMOUNT_RE = /^\d+(\.\d{1,4})?$/;

/** "0", "0.00", "0.0000" — an exactly-allocated remainder. */
function isZeroMoney(value: string): boolean {
  return /^0(\.0*)?$/.test(value);
}

interface PartDraft {
  /** Local list key — stable across removes, never sent to the server. */
  key: number;
  amount: string;
  category: string;
  party: PartyValue;
  /** History suggestion off for loaded parts that already name a person. */
  suggest: boolean;
  /** Not surfaced here, but carried so replacing the set doesn't wipe them. */
  description?: string;
  paid_by?: string;
  car_id?: number;
}

interface SplitEditorProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** An unsplit cash-out row (new split) OR any split child (edit the set). */
  row: Transaction | null;
  /**
   * Called after a successful save/unsplit, after the sheet closes. The edit
   * screens pass their leave-navigation: a saved split replaces the row set,
   * so the screen underneath is stale either way.
   */
  onDone?: () => void;
  canEdit: boolean;
}

export function SplitEditor({ open, onOpenChange, row, onDone, canEdit }: SplitEditorProps) {
  const { t, i18n } = useTranslation();
  const categories = useCategories();
  const save = useSaveSplit();
  const unsplit = useUnsplit();

  const editing = !!row && isSplitChild(row);
  const splitQuery = useTransactionSplit(open && editing ? row.id : undefined);
  const set = editing ? splitQuery.data : undefined;

  /** The row whose amount is being divided — and whose version is If-Match. */
  const parent = editing ? set?.parent : row;

  const [drafts, setDrafts] = React.useState<PartDraft[]>([]);
  const [confirmUnsplit, setConfirmUnsplit] = React.useState(false);
  // Hydrate once per open; a background refetch must not clobber typing.
  const dirtyRef = React.useRef(false);
  const keyRef = React.useRef(0);

  const nextKey = () => ++keyRef.current;
  const emptyDraft = (): PartDraft => ({
    key: nextKey(),
    amount: '',
    category: '',
    party: { driver_id: null, employee_id: null },
    suggest: true,
  });

  React.useEffect(() => {
    if (!open) {
      dirtyRef.current = false;
      return;
    }
    if (dirtyRef.current || !row) return;
    if (editing) {
      if (!set) return;
      setDrafts(
        set.parts.map((p) => ({
          key: nextKey(),
          amount: trimMoney(p.amount),
          category: p.category ?? '',
          party: { driver_id: p.driver_id ?? null, employee_id: p.employee_id ?? null },
          suggest: !p.driver_id && !p.employee_id,
          description: p.description ?? undefined,
          paid_by: p.paid_by ?? undefined,
          car_id: p.car_id ?? undefined,
        })),
      );
    } else {
      setDrafts([emptyDraft(), emptyDraft()]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, editing, row?.id, set]);

  const catByKey = React.useMemo(
    () => new Map((categories.data ?? []).map((c) => [c.key, c])),
    [categories.data],
  );

  const patchDraft = (key: number, patch: Partial<PartDraft>) => {
    dirtyRef.current = true;
    setDrafts((all) => all.map((d) => (d.key === key ? { ...d, ...patch } : d)));
  };
  const addDraft = () => {
    dirtyRef.current = true;
    setDrafts((all) => [...all, emptyDraft()]);
  };
  const removeDraft = (key: number) => {
    dirtyRef.current = true;
    setDrafts((all) => (all.length > 2 ? all.filter((d) => d.key !== key) : all));
  };

  /* ── The live remainder — exact decimal-string arithmetic ── */
  const remainder = React.useMemo(
    () =>
      addMoneyStrings([
        parent?.amount ?? '0',
        ...drafts.map((d) => (d.amount.trim() ? `-${d.amount.trim()}` : '0')),
      ]),
    [parent?.amount, drafts],
  );
  const allocatedAll = isZeroMoney(remainder);
  const overAllocated = remainder.startsWith('-');

  const amountsValid = drafts.every(
    (d) => AMOUNT_RE.test(d.amount.trim()) && /[1-9]/.test(d.amount),
  );
  const partiesOk = drafts.every((d) => {
    const cat = catByKey.get(d.category);
    return !requiresParty(cat) || !!d.party.driver_id || !!d.party.employee_id;
  });

  const busy = save.isPending || unsplit.isPending;
  const canSave =
    canEdit && !!parent && drafts.length >= 2 && amountsValid && allocatedAll && partiesOk && !busy;

  const finish = () => {
    onOpenChange(false);
    onDone?.();
  };

  const submit = () => {
    if (!parent || !canSave) return;
    const parts: SplitPartInput[] = drafts.map((d) => {
      const cat = catByKey.get(d.category);
      const part: SplitPartInput = { amount: d.amount.trim() };
      if (d.category) part.category = d.category;
      if (requiresParty(cat)) {
        if (d.party.driver_id) part.driver_id = d.party.driver_id;
        if (d.party.employee_id) part.employee_id = d.party.employee_id;
      }
      if (d.description) part.description = d.description;
      if (d.paid_by) part.paid_by = d.paid_by;
      if (d.car_id != null) part.car_id = d.car_id;
      return part;
    });
    save.mutate(
      { id: parent.id, version: parent.version, parts, replace: editing },
      { onSuccess: finish },
    );
  };

  const currency = parent?.currency ?? 'EGP';
  const loadFailed = editing && splitQuery.isError;

  return (
    <>
      <Sheet open={open} onOpenChange={(o) => !busy && onOpenChange(o)}>
        <SheetContent
          side="bottom"
          className="mx-auto flex max-h-[90dvh] w-full max-w-lg flex-col rounded-t-2xl p-0"
        >
          {/* ── Fixed header: the amount being divided ── */}
          <div className="shrink-0 border-b px-4 py-3 pe-12">
            <h3 className="flex items-center gap-2 text-base font-semibold">
              <Split className="h-4 w-4 shrink-0 text-primary" />
              <span dir="auto">
                {parent
                  ? t('fleetExpenses.split.title', {
                      amount: `${formatMoney(parent.amount)} ${currency}`,
                    })
                  : t('fleetExpenses.split.action')}
              </span>
            </h3>
            {parent?.counterparty && (
              <p className="mt-0.5 truncate text-xs text-muted-foreground" dir="auto">
                {parent.counterparty}
              </p>
            )}
          </div>

          {/* ── Parts ── */}
          <div className="min-h-0 flex-1 space-y-3 overflow-y-auto px-4 py-3">
            {editing && splitQuery.isLoading ? (
              <>
                {Array.from({ length: 2 }).map((_, i) => (
                  <Skeleton key={i} className="h-28 w-full rounded-lg" />
                ))}
              </>
            ) : loadFailed ? (
              <p className="rounded-lg border border-destructive/40 bg-destructive/5 px-3 py-2.5 text-sm text-destructive">
                {t('fleetExpenses.split.loadFailed')}
              </p>
            ) : (
              <>
                <ul className="space-y-3">
                  {drafts.map((draft, index) => {
                    const cat = catByKey.get(draft.category);
                    const needsParty = requiresParty(cat);
                    const partyMissing =
                      needsParty && !draft.party.driver_id && !draft.party.employee_id;
                    return (
                      <li key={draft.key} className="space-y-2 rounded-lg border bg-card p-3">
                        <div className="flex min-h-6 items-center justify-between gap-2">
                          <span className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                            {t('fleetExpenses.split.part', { n: index + 1 })}
                          </span>
                          {drafts.length > 2 && (
                            <button
                              type="button"
                              onClick={() => removeDraft(draft.key)}
                              disabled={busy}
                              aria-label={t('fleetExpenses.split.removePart')}
                              className="flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground"
                            >
                              <X className="h-4 w-4" />
                            </button>
                          )}
                        </div>

                        <div className="grid grid-cols-1 gap-2 min-[420px]:grid-cols-2">
                          <div className="space-y-1">
                            <Label className="text-xs">{t('fleetExpenses.fields.amount')}</Label>
                            <Input
                              inputMode="decimal"
                              dir="ltr"
                              placeholder="0.00"
                              value={draft.amount}
                              disabled={busy}
                              onChange={(e) => patchDraft(draft.key, { amount: e.target.value })}
                              className="tabular-nums"
                            />
                          </div>
                          <div className="space-y-1">
                            <Label className="text-xs">
                              {t('fleetExpenses.fields.expenseType')}
                            </Label>
                            <NativeSelect
                              value={draft.category}
                              disabled={busy}
                              onChange={(e) => patchDraft(draft.key, { category: e.target.value })}
                            >
                              <option value="">{t('common.none')}</option>
                              {(categories.data ?? []).map((c) => (
                                <option key={c.key} value={c.key}>
                                  {categoryLabel(c, i18n.language)}
                                </option>
                              ))}
                            </NativeSelect>
                          </div>
                        </div>

                        {needsParty && (
                          <div className="space-y-1">
                            <Label className="text-xs">{t('fleetExpenses.toWhom')}</Label>
                            <SmartPartyField
                              counterparty={parent?.counterparty}
                              suggest={draft.suggest}
                              value={draft.party}
                              onChange={(party) => patchDraft(draft.key, { party })}
                              disabled={busy}
                              required={(cat?.required_party ?? 'either') as PartyKind}
                            />
                            {partyMissing && (
                              <p className="text-xs text-amber-600 dark:text-amber-400">
                                {t('fleetExpenses.partyRequired')}
                              </p>
                            )}
                          </div>
                        )}
                      </li>
                    );
                  })}
                </ul>

                <Button
                  type="button"
                  variant="outline"
                  className="min-h-11 w-full border-dashed sm:min-h-9"
                  onClick={addDraft}
                  disabled={busy}
                >
                  <Plus className="h-4 w-4" />
                  {t('fleetExpenses.split.addPart')}
                </Button>
              </>
            )}
          </div>

          {/* ── Fixed footer: live remainder + actions ── */}
          <div className="shrink-0 space-y-2.5 border-t px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
            {parent && !loadFailed && (
              <p
                dir="auto"
                aria-live="polite"
                className={cn(
                  'text-sm font-medium tabular-nums',
                  overAllocated
                    ? 'text-destructive'
                    : allocatedAll
                      ? 'text-emerald-600 dark:text-emerald-400'
                      : 'text-amber-600 dark:text-amber-400',
                )}
              >
                {overAllocated
                  ? t('fleetExpenses.split.overAllocated', {
                      amount: formatMoney(remainder.slice(1)),
                    })
                  : allocatedAll
                    ? t('fleetExpenses.split.fullyAllocated')
                    : t('fleetExpenses.split.remaining', {
                        remaining: formatMoney(remainder),
                        total: formatMoney(parent.amount),
                      })}
              </p>
            )}

            <div className="flex flex-wrap gap-2">
              {editing && canEdit && !loadFailed && (
                <Button
                  type="button"
                  variant="ghost"
                  className="order-3 min-h-10 w-full text-destructive hover:text-destructive sm:order-1 sm:me-auto sm:min-h-9 sm:w-auto"
                  onClick={() => setConfirmUnsplit(true)}
                  disabled={busy || !set}
                >
                  {t('fleetExpenses.split.unsplit')}
                </Button>
              )}
              <Button
                type="button"
                variant="outline"
                className="order-1 min-h-11 flex-1 sm:order-2 sm:min-h-9 sm:flex-none"
                onClick={() => onOpenChange(false)}
                disabled={busy}
              >
                {t('common.cancel')}
              </Button>
              <Button
                type="button"
                className="order-2 min-h-11 flex-1 sm:order-3 sm:min-h-9 sm:flex-none"
                onClick={submit}
                disabled={!canSave}
              >
                {save.isPending ? t('common.saving') : t('fleetExpenses.split.save')}
              </Button>
            </div>
          </div>
        </SheetContent>
      </Sheet>

      <ConfirmDialog
        open={confirmUnsplit}
        onOpenChange={setConfirmUnsplit}
        stacked
        title={t('fleetExpenses.split.unsplitConfirmTitle')}
        description={t('fleetExpenses.split.unsplitConfirmDescription', {
          amount: parent ? `${formatMoney(parent.amount)} ${currency}` : '',
        })}
        confirmLabel={t('fleetExpenses.split.unsplit')}
        variant="destructive"
        loading={unsplit.isPending}
        onConfirm={() => {
          if (!set) return;
          unsplit.mutate(
            { id: set.parent.id, version: set.parent.version },
            {
              onSuccess: () => {
                setConfirmUnsplit(false);
                finish();
              },
              onError: () => setConfirmUnsplit(false),
            },
          );
        }}
      />
    </>
  );
}

/* -------------------------------------------------------------------------- */
/* SplitChip — the compact "part of 20,000.00" marker on child rows            */
/* -------------------------------------------------------------------------- */

export function SplitChip({
  row,
  siblings,
  onOpen,
  className,
}: {
  row: Transaction;
  /** Ids of loaded rows sharing this parent, in list order (for "n of m"). */
  siblings?: number[];
  onOpen: () => void;
  className?: string;
}) {
  const { t } = useTranslation();
  if (row.parent_amount == null) return null;

  const amount = formatMoney(row.parent_amount);
  const index = siblings ? siblings.indexOf(row.id) : -1;
  const label =
    siblings && siblings.length > 1 && index >= 0
      ? t('fleetExpenses.split.chipNOfM', { n: index + 1, m: siblings.length, amount })
      : t('fleetExpenses.split.chipPartOf', { amount });

  return (
    <button
      type="button"
      onClick={(e) => {
        e.stopPropagation();
        onOpen();
      }}
      className={cn(
        'inline-flex min-h-6 items-center gap-1 rounded-full bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary hover:bg-primary/15',
        className,
      )}
    >
      <Split className="h-3 w-3 shrink-0" />
      <span className="tabular-nums" dir="auto">
        {label}
      </span>
    </button>
  );
}

