      (initial?.price_per_liter as number) ?? (parseFloat(DEFAULT_PRICE_PER_LITER) as number),
    odometer_before: (initial?.odometer_before as number) ?? (undefined as unknown as number),
    odometer_after: (initial?.odometer_after as number) ?? (undefined as unknown as number),
  };
}

export function FuelEventForm({
  mode,
  initialValues,
  submitting,
  onSubmit,
  onCancel,
  submitLabel,
  showResetChanges = false,
}: FuelEventFormProps) {
  const { t } = useTranslation();
  const { data: cars = [], isLoading: carsLoading } = useCars();
  const { data: drivers = [], isLoading: driversLoading } = useDrivers();

  const form = useForm<FuelEventFormValues>({
    resolver: zodResolver(fuelEventFormSchema),
    defaultValues: getDefaults(initialValues),
    mode: 'onTouched',
  });

  const [driverAutoAssigned, setDriverAutoAssigned] = React.useState(false);

  React.useEffect(() => {
    if (initialValues) {
      const defaults = getDefaults(initialValues);
      // Fallback for legacy backend records that don't return driver_id yet
      if (defaults.driver_id == null && defaults.driver_name && drivers.length > 0) {
        const match = drivers.find(d => d.name === defaults.driver_name);
        if (match) defaults.driver_id = match.ID;
      }
      form.reset(defaults);
      setDriverAutoAssigned(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialValues?.car_id, initialValues?.driver_name, initialValues?.date, drivers.length]);

  const carOptions = React.useMemo(
    () => cars.map((c) => ({ value: c.ID, label: c.car_no_plate })),
    [cars],
  );

  const driverOptions = React.useMemo(
    () =>
      drivers.map((d) => ({
        value: d.ID,
        label: d.name,
        description: d.mobile_number || undefined,
      })),
    [drivers],
  );

  // Auto-fill driver on car change. Runs in BOTH create and edit modes —
  // when a user deliberately switches the car in an existing event, they
  // almost always want the new car's assigned driver too. The ref check
  // prevents the initial load (where `watchedCarId === previousCarIdRef`)
  // from firing.
  //
  // Odometer pre-fill, however, stays gated to create mode. Overwriting
  // a historical event's odometer-before with the newest live reading
  // would corrupt the record.
  const watchedCarId = form.watch('car_id');
  // If we have a driver_name in initial values, we skip the first auto-assignment
  // to avoid overwriting existing data. If not (e.g. new from carId param), we allow it.
  const previousCarIdRef = React.useRef<number | undefined>(
    initialValues?.driver_name ? initialValues?.car_id : undefined,
  );

  React.useEffect(() => {
    if (!watchedCarId || watchedCarId === previousCarIdRef.current) return;
    previousCarIdRef.current = watchedCarId;

    const selectedCar: CarEntity | undefined = cars.find((c) => c.ID === watchedCarId);
    if (!selectedCar) return;

    const assignedDriver: Driver | undefined =
      selectedCar.driver_id && selectedCar.driver_id !== 0
        ? drivers.find((d) => d.ID === selectedCar.driver_id)
        : undefined;

    if (assignedDriver) {
      form.setValue('driver_id', assignedDriver.ID);
      form.setValue('driver_name', assignedDriver.name, { shouldValidate: true });
      setDriverAutoAssigned(true);
    } else {
      form.setValue('driver_id', null);
      form.setValue('driver_name', '');
      setDriverAutoAssigned(false);
    }

    // Odometer prefill only on create — never overwrite historical data
    if (mode === 'create' && selectedCar.last_fuel_odometer != null) {
      form.setValue('odometer_before', selectedCar.last_fuel_odometer, {
        shouldValidate: true,
      });
    }
  }, [watchedCarId, cars, drivers, form, mode]);

  // Live calculations
  const liters = form.watch('liters');
  const pricePerLiter = form.watch('price_per_liter');
  const odometerBefore = form.watch('odometer_before');
  const odometerAfter = form.watch('odometer_after');

  const calc = React.useMemo(() => {
    const distance = calculateDistance(odometerBefore ?? 0, odometerAfter ?? 0);
    const fuelRate = calculateFuelRate(liters ?? 0, odometerBefore ?? 0, odometerAfter ?? 0);
    const totalPrice = calculateTotalPrice(liters ?? 0, pricePerLiter ?? 0);
    return { distance, fuelRate, totalPrice };
  }, [liters, pricePerLiter, odometerBefore, odometerAfter]);

  const efficiency = evaluateEfficiency(calc.fuelRate);

  const loading = carsLoading || driversLoading;

  if (loading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-40 w-full" />
        <Skeleton className="h-56 w-full" />
        <Skeleton className="h-40 w-full" />
      </div>
    );
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        {/* Vehicle & Driver */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-base">
              <Car className="h-4 w-4 text-muted-foreground" />
              {t('fuelEvents.fields.car')} &amp; {t('fuelEvents.fields.driver')}
            </CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <FormField
              control={form.control}
              name="car_id"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('fuelEvents.fields.carPlate')}</FormLabel>
                  <FormControl>
                    <SearchableSelect
                      options={carOptions}
                      value={field.value}
                      onChange={(v) => field.onChange(v as number)}
                      placeholder={t('fuelEvents.fields.selectCar')}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="driver_id"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('fuelEvents.fields.driver')}</FormLabel>
                  <FormControl>
                    <SearchableSelect
                      options={driverOptions}
                      value={field.value}
                      onChange={(v) => {
                        field.onChange(v);
                        const d = drivers.find((drv) => drv.ID === Number(v));
                        if (d) {
                          form.setValue('driver_name', d.name);
                        } else {
                          form.setValue('driver_name', '');
                        }
                        setDriverAutoAssigned(false);
                      }}
                      placeholder={t('fuelEvents.fields.selectDriver')}
                      className={cn(driverAutoAssigned && 'border-primary/40')}
                    />
                  </FormControl>
                  {driverAutoAssigned && !form.formState.errors.driver_name && (
                    <div className="absolute bottom-0 left-0 right-0 flex items-center gap-1.5 text-xs text-primary">
                      <Sparkles className="h-3 w-3 shrink-0" />
                      <span className="truncate">{t('fuelEvents.fields.driverAutoAssigned')}</span>
                      <button
                        type="button"
                        onClick={() => {
                          form.setValue('driver_id', null);
                          form.setValue('driver_name', '', { shouldValidate: true });
                          setDriverAutoAssigned(false);
                        }}
                        className="ms-auto inline-flex shrink-0 items-center gap-0.5 rounded px-1 py-0.5 text-muted-foreground hover:bg-muted hover:text-foreground"
                      >
                        <X className="h-3 w-3" />
                        <span>{t('common.clear')}</span>
                      </button>
                    </div>
                  )}
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Fuel details */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-base">
              <Droplet className="h-4 w-4 text-muted-foreground" />
              {t('fuelEvents.title')}
            </CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <FormField
              control={form.control}
              name="date"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('fuelEvents.fields.date')}</FormLabel>
                  <FormControl>
                    <DatePicker
                      value={field.value}
                      onChange={field.onChange}
                      max={today()}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="liters"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('fuelEvents.fields.liters')}</FormLabel>
                  <FormControl>
                    <Input
                      type="number"
                      step="0.01"
                      inputMode="decimal"
                      placeholder="0.00"
                      {...field}
                      value={field.value ?? ''}
                      onChange={(e) =>
                        field.onChange(e.target.value === '' ? undefined : e.target.value)
                      }
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="price_per_liter"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('fuelEvents.fields.pricePerLiter')}</FormLabel>
                  <FormControl>
                    <Input
                      type="number"
                      step="0.01"
                      inputMode="decimal"
                      placeholder="0.00"
                      {...field}
                      value={field.value ?? ''}
                      onChange={(e) =>
                        field.onChange(e.target.value === '' ? undefined : e.target.value)
                      }
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/*
              Total price mirrors the structure of sibling FormFields exactly
              (plain FormLabel, FormControl, FormMessage). The readonly div
              swaps in for <Input /> inside FormControl.
            */}
            <FormItem>
              <FormLabel>{t('fuelEvents.fields.totalPrice')}</FormLabel>
              <FormControl>
                <div className="flex h-10 w-full items-center rounded-md border border-input bg-muted/30 px-3 text-sm font-semibold shadow-sm">
                  {formatCurrency(calc.totalPrice)}
                </div>
              </FormControl>
              <FormMessage />
            </FormItem>
          </CardContent>
        </Card>

        {/* Odometer + efficiency */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-base">
              <Gauge className="h-4 w-4 text-muted-foreground" />
              {t('fuelEvents.fields.odometerBefore')} / {t('fuelEvents.fields.odometerAfter')}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <FormField
                control={form.control}
                name="odometer_before"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('fuelEvents.fields.odometerBefore')}</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        inputMode="numeric"
                        placeholder="0"
                        {...field}
                        value={field.value ?? ''}
                        onChange={(e) =>
                          field.onChange(e.target.value === '' ? undefined : e.target.value)
                        }
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="odometer_after"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('fuelEvents.fields.odometerAfter')}</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        inputMode="numeric"
                        placeholder="0"
                        {...field}
                        value={field.value ?? ''}
                        onChange={(e) =>
                          field.onChange(e.target.value === '' ? undefined : e.target.value)
                        }
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              <div className="rounded-lg border bg-card p-3">
                <p className="text-xs text-muted-foreground">{t('fuelEvents.fields.distance')}</p>
                <p className="text-xl font-semibold">{formatNumber(calc.distance, 0)} km</p>
              </div>
              <div className={cn('rounded-lg border p-3', efficiency.bgClassName)}>
                <p className="text-xs text-muted-foreground">{t('fuelEvents.fields.fuelRate')}</p>
                <div className="flex items-center justify-between">
                  <p className={cn('text-xl font-semibold', efficiency.className)}>
                    {formatNumber(calc.fuelRate, 1)} {t('fuelEvents.efficiency.unit')}
                  </p>
                  <div className="flex items-center gap-1">
                    <span>{efficiency.icon}</span>
                    <span className={cn('text-xs font-medium', efficiency.className)}>
                      {t(efficiency.labelKey)}
                    </span>
                  </div>
                </div>
                {!efficiency.isValid && calc.fuelRate > 0 && (
                  <p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground">
                    <Info className="h-3 w-3" />
                    {t('fuelEvents.efficiency.excludedReason', {
                      min: FUEL_EFFICIENCY.MIN_VALID,
                      max: FUEL_EFFICIENCY.MAX_VALID,
                    })}
                  </p>
                )}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Actions */}
        <div className="sticky bottom-0 -mx-4 flex flex-col gap-2 border-t bg-background/90 p-4 backdrop-blur supports-[backdrop-filter]:bg-background/70 md:-mx-6 md:flex-row md:justify-end md:gap-3 md:px-6">
          {showResetChanges && form.formState.isDirty && (
            <Button
              type="button"
              variant="outline"
              onClick={() => form.reset()}
              disabled={submitting}
              className="md:me-auto"
            >
              <RotateCcw className="h-4 w-4" />
              {t('common.reset')}
            </Button>
          )}
          {onCancel && (
            <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>
              {t('common.cancel')}
            </Button>
          )}
          <Button
            type="submit"
            disabled={submitting || (mode === 'edit' && !form.formState.isDirty)}
          >
            {submitting ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Save className="h-4 w-4" />
            )}
            {submitLabel ?? t('common.save')}
          </Button>
        </div>
      </form>
    </Form>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import {
  Filter,
  ArrowDownWideNarrow,
  ArrowUpNarrowWide,
  Check,
  X,
  Zap,
  Pencil,
} from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from '@/shared/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import type { FuelEvent, FuelMethod } from '@/entities/fuel-event/schemas';
import { normaliseMethod } from '@/entities/fuel-event/schemas';
import type { EfficiencyMap } from '@/shared/lib/fuel';

/* -------------------------------------------------------------------------- */
/* Types                                                                       */
/* -------------------------------------------------------------------------- */

export type FuelEventStatusFilter = 'good' | 'average' | 'poor' | 'excluded' | 'paired';

export type FuelEventMethodFilter = 'all' | FuelMethod;

export type FuelEventSortKey = 'date' | 'rate' | 'cost' | 'liters';
export type SortDirection = 'asc' | 'desc';

export const ALL_FILTERS: FuelEventStatusFilter[] = [
  'good',
  'average',
  'poor',
  'paired',
  'excluded',
];

const FILTER_META: Record<FuelEventStatusFilter, { labelKey: string; dot: string }> = {
  good: { labelKey: 'fuelEvents.efficiency.good', dot: 'bg-success' },
  average: { labelKey: 'fuelEvents.efficiency.average', dot: 'bg-warning' },
  poor: { labelKey: 'fuelEvents.efficiency.poor', dot: 'bg-destructive' },
  paired: { labelKey: 'fuelEvents.efficiency.paired', dot: 'bg-primary' },
  excluded: { labelKey: 'fuelEvents.efficiency.excluded', dot: 'bg-muted-foreground' },
};

const SORT_OPTIONS: { key: FuelEventSortKey; labelKey: string }[] = [
  { key: 'date', labelKey: 'fuelEvents.sort.date' },
  { key: 'rate', labelKey: 'fuelEvents.sort.rate' },
  { key: 'cost', labelKey: 'fuelEvents.sort.cost' },
  { key: 'liters', labelKey: 'fuelEvents.sort.liters' },
];

/* -------------------------------------------------------------------------- */
/* Status filter popover                                                       */
/* -------------------------------------------------------------------------- */

interface FilterPopoverProps {
  active: Set<FuelEventStatusFilter>;
  onChange: (next: Set<FuelEventStatusFilter>) => void;
}

export function FuelEventsFilterPopover({ active, onChange }: FilterPopoverProps) {
  const { t } = useTranslation();
  const [open, setOpen] = React.useState(false);

  const toggle = (key: FuelEventStatusFilter) => {
    const next = new Set(active);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    onChange(next);
  };

  const clear = () => onChange(new Set());
  const count = active.size;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant={count > 0 ? 'default' : 'outline'} size="sm" className="h-9 gap-1.5">
          <Filter className="h-3.5 w-3.5" />
          <span className="hidden sm:inline">{t('common.filter')}</span>
          {count > 0 && (
            <span className="inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-primary-foreground px-1 text-[10px] font-semibold text-primary">
              {count}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-60 p-2">
        <div className="flex items-center justify-between px-2 py-1.5">
          <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            {t('fuelEvents.filters.byStatus')}
          </p>
          {count > 0 && (
            <button
              type="button"
              onClick={clear}
              className="inline-flex items-center gap-0.5 text-[11px] text-muted-foreground hover:text-foreground"
            >
              <X className="h-3 w-3" />
              {t('fuelEvents.filters.clearFilter')}
            </button>
          )}
        </div>
        <ul className="space-y-0.5">
          {ALL_FILTERS.map((key) => {
            const meta = FILTER_META[key];
            const selected = active.has(key);
            return (
              <li key={key}>
                <button
                  type="button"
                  onClick={() => toggle(key)}
                  className={cn(
                    'flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm transition-colors',
                    selected ? 'bg-accent text-accent-foreground' : 'hover:bg-accent/60',
                  )}
                >
                  <span className={cn('h-2 w-2 rounded-full', meta.dot)} />
                  <span className="flex-1 text-start">{t(meta.labelKey)}</span>
                  {selected && <Check className="h-3.5 w-3.5 text-primary" />}
                </button>
              </li>
            );
          })}
        </ul>
      </PopoverContent>
    </Popover>
  );
}

/* -------------------------------------------------------------------------- */
/* Method filter — segmented control (all / PetroApp / Manual)                */
/* -------------------------------------------------------------------------- */

interface MethodControlProps {
  value: FuelEventMethodFilter;
  onChange: (next: FuelEventMethodFilter) => void;
  /**
   * Counts used to grey out methods with zero events in the current set.
   * Prevents dead ends — if the user filters to PetroApp but no PetroApp
   * events exist in the current date/search scope, the button is disabled.
   */
  counts?: { all: number; PetroApp: number; Manual: number };
}

export function FuelEventsMethodControl({ value, onChange, counts }: MethodControlProps) {
  const { t } = useTranslation();

  return (
    <div
      className="inline-flex h-9 items-center gap-0.5 rounded-md border bg-muted/40 p-0.5"
      role="tablist"
      aria-label={t('fuelEvents.method.label')}
    >
      <MethodButton
        active={value === 'all'}
        disabled={false}
        onClick={() => onChange('all')}
        label={t('fuelEvents.method.all')}
        count={counts?.all}
      />
      <MethodButton
        active={value === 'PetroApp'}
        disabled={counts?.PetroApp === 0}
        onClick={() => onChange('PetroApp')}
        icon={<Zap className="h-3 w-3" />}
        label={t('fuelEvents.method.petroApp')}
        count={counts?.PetroApp}
      />
      <MethodButton
        active={value === 'Manual'}
        disabled={counts?.Manual === 0}
        onClick={() => onChange('Manual')}
        icon={<Pencil className="h-3 w-3" />}
        label={t('fuelEvents.method.manual')}
        count={counts?.Manual}
      />
    </div>
  );
}

function MethodButton({
  active,
  disabled,
  onClick,
  icon,
  label,
  count,
}: {
  active: boolean;
  disabled: boolean;
  onClick: () => void;
  icon?: React.ReactNode;
  label: string;
  count?: number;
}) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={active}
      disabled={disabled}
      onClick={onClick}
      className={cn(
        'inline-flex h-7 items-center gap-1.5 rounded px-2.5 text-xs font-medium transition-colors',
        active
          ? 'bg-background text-foreground shadow-sm'
          : 'text-muted-foreground hover:text-foreground',
        disabled && 'cursor-not-allowed opacity-40 hover:text-muted-foreground',
      )}
    >
      {icon}
      <span>{label}</span>
      {typeof count === 'number' && (
        <span
          className={cn(
            'hidden rounded-full px-1 text-[10px] font-semibold tabular-nums sm:inline-block',
            active ? 'bg-muted text-foreground' : 'bg-background text-muted-foreground',
          )}
        >
          {count}
        </span>
      )}
    </button>
  );
}

/* -------------------------------------------------------------------------- */
/* Sort control — dropdown + direction toggle                                 */
/* -------------------------------------------------------------------------- */

interface SortControlProps {
  sortKey: FuelEventSortKey;
  direction: SortDirection;
  onSortKeyChange: (key: FuelEventSortKey) => void;
  onDirectionToggle: () => void;
}

export function FuelEventsSortControl({
  sortKey,
  direction,
  onSortKeyChange,
  onDirectionToggle,
}: SortControlProps) {
  const { t } = useTranslation();
  const DirectionIcon = direction === 'desc' ? ArrowDownWideNarrow : ArrowUpNarrowWide;

  return (
    <div className="inline-flex h-9 items-center">
      <Select value={sortKey} onValueChange={(v) => onSortKeyChange(v as FuelEventSortKey)}>
        <SelectTrigger className="h-9 w-[130px] gap-1 rounded-e-none border-e-0 text-xs">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {SORT_OPTIONS.map((opt) => (
            <SelectItem key={opt.key} value={opt.key}>
              {t(opt.labelKey)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Button
        variant="outline"
        size="icon"
        onClick={onDirectionToggle}
        className="h-9 w-9 rounded-s-none"
        aria-label={
          direction === 'desc'
            ? t('fuelEvents.sort.directionDesc')
            : t('fuelEvents.sort.directionAsc')
        }
      >
        <DirectionIcon className="h-3.5 w-3.5" />
      </Button>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Helpers — apply to analysed events                                          */
/* -------------------------------------------------------------------------- */

export function applyStatusFilter(
  events: FuelEvent[],
  map: EfficiencyMap,
  active: Set<FuelEventStatusFilter>,
): FuelEvent[] {
  if (active.size === 0) return events;
  return events.filter((e) => {
    const a = map.get(e.ID);
    return !!a && active.has(a.status as FuelEventStatusFilter);
  });
}

/**
 * Filter by method. Runs AFTER pair analysis so pairing stays holistic
 * across methods — a Manual undershoot can pair with a PetroApp overshoot
 * for the same vehicle and both get flagged as paired regardless of which
 * method filter is active afterwards.
 */
export function applyMethodFilter(
  events: FuelEvent[],
  method: FuelEventMethodFilter,
): FuelEvent[] {
  if (method === 'all') return events;
  return events.filter((e) => normaliseMethod(e.method) === method);
}

/** Count events per method in a set — powers the badge counts on the tabs. */
export function countByMethod(events: FuelEvent[]): {
  all: number;
  PetroApp: number;
  Manual: number;
} {
  let petroApp = 0;
  let manual = 0;
  for (const e of events) {
    if (normaliseMethod(e.method) === 'PetroApp') petroApp++;
    else manual++;
  }
  return { all: events.length, PetroApp: petroApp, Manual: manual };
}

/**
 * Parse a 12-hour time string like "3:07 PM" into minutes since midnight.
 * Returns null for empty strings, malformed input, or any non-parseable value
 * — callers should fall through to a different tiebreaker when null.
 */
function parseTimeToMinutes(time: string | null | undefined): number | null {
  if (!time) return null;
  const m = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(time.trim());
  if (!m) return null;
  let hours = Number(m[1]);
  const minutes = Number(m[2]);
  const meridiem = m[3].toUpperCase();
  if (hours < 1 || hours > 12 || minutes < 0 || minutes > 59) return null;
  // 12 AM = 00:xx, 12 PM = 12:xx, otherwise add 12 for PM
  if (hours === 12) hours = 0;
  if (meridiem === 'PM') hours += 12;
  return hours * 60 + minutes;
}

/**
 * Sort events by the chosen key and direction.
 *
 * Ties are broken with a deterministic chain: date → time → odometer_before
 * → ID. This gives same-day events a sensible order by fueling time when
 * available, falls back to odometer_before (which monotonically increases
 * per vehicle), and lastly to ID (which guarantees stable ordering for
 * events with no better distinguisher). Tiebreakers follow the user's chosen
 * direction — sorting newest-first also breaks ties newest-first.
 *
 * `rate` uses the pair-aware effective rate so paired events sort by their
 * combined rate rather than the raw out-of-band one. Date primary sort is
 * string-comparable since we use ISO date strings.
 */
export function applySort(
  events: FuelEvent[],
  map: EfficiencyMap,
  key: FuelEventSortKey,
  direction: SortDirection,
): FuelEvent[] {
  const mult = direction === 'asc' ? 1 : -1;
  const sorted = [...events];

  sorted.sort((a, b) => {
    // Primary — whichever column the user picked
    let av: number | string;
    let bv: number | string;
    switch (key) {
      case 'rate':
        av = map.get(a.ID)?.effectiveRate ?? a.fuel_rate;
        bv = map.get(b.ID)?.effectiveRate ?? b.fuel_rate;
        break;
      case 'cost':
        av = a.price;
        bv = b.price;
        break;
      case 'liters':
        av = a.liters;
        bv = b.liters;
        break;
      case 'date':
      default:
        av = a.date;
        bv = b.date;
        break;
    }
    if (av < bv) return -1 * mult;
    if (av > bv) return 1 * mult;

    // Tiebreak 1 — date (skipped when date was the primary sort)
    if (key !== 'date') {
      if (a.date < b.date) return -1 * mult;
      if (a.date > b.date) return 1 * mult;
    }

    // Tiebreak 2 — time of day, if both events have parseable times
    const at = parseTimeToMinutes(a.time);
    const bt = parseTimeToMinutes(b.time);
    if (at !== null && bt !== null && at !== bt) {
      return (at - bt) * mult;
    }

    // Tiebreak 3 — odometer_before, monotonic per vehicle
    if (a.odometer_before !== b.odometer_before) {
      return (a.odometer_before - b.odometer_before) * mult;
    }

    // Tiebreak 4 — ID as the final stable fallback
    return (a.ID - b.ID) * mult;
  });

  return sorted;
}

