import { Label } from '@/shared/ui/label';
import { isValidCoordinate } from '@/shared/lib/coords';
import {
  DROPOFF_DEFAULT_RADIUS_M,
  type DropOffPoint,
  type UpdateDropoffPayload,
} from '@/entities/location/schemas';
import { useUpdateDropoff } from '@/entities/location/queries';
import { LocationsMapPicker } from '../locations-map-picker';
import { PinSourceBadge } from '../locations-dropoffs-table/pin-source-badge';

interface LocationsDropoffDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** The drop-off point being edited. */
  dropoff: DropOffPoint | null;
  /** Pre-placed pin, e.g. a GPS-suggested position from the inbox. */
  initialPin?: { lat: number; lng: number } | null;
  /** `pin_source` sent on save. Defaults to `"manual"`. */
  pinSourceOnSave?: string;
  /** Extra context line under the title (e.g. "GPS suggests…"). */
  note?: React.ReactNode;
  /** Runs after a successful save (e.g. ack the GPS suggestion). */
  onSaved?: () => void | Promise<void>;
  /** Renders a delete button when provided. */
  onDelete?: (dropoff: DropOffPoint) => void;
}

/**
 * Drop-off point pin editor. Same map interaction as the terminal dialog
 * (click to place, drag to adjust, manual coord entry) with a 300 m default
 * radius visualization. In the inbox "Review" flow the suggested GPS
 * position arrives via `initialPin` and saves with
 * `pin_source: "gps_suggested"`.
 *
 * Creation is gone on purpose — drop-off points now come into existence
 * implicitly when a fee mapping references a new name.
 */
export function LocationsDropoffDialog({
  open,
  onOpenChange,
  dropoff,
  initialPin,
  pinSourceOnSave = 'manual',
  note,
  onSaved,
  onDelete,
}: LocationsDropoffDialogProps) {
  const { t } = useTranslation();

  const updateDropoff = useUpdateDropoff();

  const [lat, setLat] = React.useState('');
  const [lng, setLng] = React.useState('');
  const [radius, setRadius] = React.useState('');

  React.useEffect(() => {
    if (!open) return;
    if (initialPin && isValidCoordinate(initialPin.lat, initialPin.lng)) {
      setLat(initialPin.lat.toFixed(6));
      setLng(initialPin.lng.toFixed(6));
    } else if (dropoff && isValidCoordinate(dropoff.lat, dropoff.long)) {
      setLat(String(dropoff.lat));
      setLng(String(dropoff.long));
    } else {
      setLat('');
      setLng('');
    }
    setRadius(dropoff?.radius_m != null ? String(dropoff.radius_m) : '');
  }, [open, dropoff, initialPin]);

  const numericLat = Number(lat);
  const numericLng = Number(lng);
  const coordValid =
    lat.trim() !== '' && lng.trim() !== '' && isValidCoordinate(numericLat, numericLng);

  const radiusOverride = radius.trim() === '' ? null : Number(radius);
  const radiusValid =
    radiusOverride === null || (Number.isFinite(radiusOverride) && radiusOverride > 0);
  const effectiveRadius = radiusOverride ?? DROPOFF_DEFAULT_RADIUS_M;

  const canSave = coordValid && radiusValid;
  const saving = updateDropoff.isPending;

  const handlePositionChange = React.useCallback((newLat: number, newLng: number) => {
    setLat(newLat.toFixed(6));
    setLng(newLng.toFixed(6));
  }, []);

  const handleSave = async () => {
    if (!canSave || !dropoff) return;
    try {
      const payload: UpdateDropoffPayload = {
        lat: Number(numericLat.toFixed(6)),
        long: Number(numericLng.toFixed(6)),
        pin_source: pinSourceOnSave,
      };
      if (radiusOverride !== null) {
        payload.radius_m = radiusOverride;
      } else if (dropoff.radius_m != null) {
        payload.clear_radius = true;
      }
      await updateDropoff.mutateAsync({ id: dropoff.ID, payload });
      await onSaved?.();
      onOpenChange(false);
    } catch {
      // Toast handled by the mutations
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[90vh] max-w-2xl flex-col gap-0 overflow-hidden p-0">
        <DialogHeader className="shrink-0 border-b px-6 py-4">
          <DialogTitle className="flex items-center gap-2">
            <MapPin className="h-4 w-4 text-primary" />
            {t('locations.dialog.editDropoff', 'Edit Drop-off Point')}
          </DialogTitle>
          <DialogDescription className="flex items-center gap-2 truncate" dir="auto">
            <span dir="auto" className="truncate">{dropoff?.name}</span>
            <PinSourceBadge pinSource={dropoff?.pin_source} />
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-1 flex-col gap-4 overflow-y-auto px-6 py-4">
          {note && (
            <div className="flex items-start gap-2 rounded-md border border-primary/30 bg-primary/5 p-2.5 text-sm">
              <Sparkles className="mt-0.5 h-4 w-4 shrink-0 text-primary" />
              <div className="min-w-0">{note}</div>
            </div>
          )}

          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
            <div className="space-y-1">
              <Label htmlFor="dropoff-lat" className="text-xs">
                {t('locations.fields.lat', 'Latitude')}
              </Label>
              <Input
                id="dropoff-lat"
                type="number"
                step="0.000001"
                value={lat}
                onChange={(e) => setLat(e.target.value)}
                placeholder="30.044420"
                className="font-mono"
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor="dropoff-lng" className="text-xs">
                {t('locations.fields.lng', 'Longitude')}
              </Label>
              <Input
                id="dropoff-lng"
                type="number"
                step="0.000001"
                value={lng}
                onChange={(e) => setLng(e.target.value)}
                placeholder="31.235712"
                className="font-mono"
              />
            </div>
            <div className="col-span-2 space-y-1 sm:col-span-1">
              <Label htmlFor="dropoff-radius" className="text-xs">
                {t('locations.fields.radius', 'Radius (m)')}
              </Label>
              <Input
                id="dropoff-radius"
                type="number"
                step="1"
                min="1"
                value={radius}
                onChange={(e) => setRadius(e.target.value)}
                placeholder={t('locations.fields.radiusDefaultPlaceholder', {
                  m: DROPOFF_DEFAULT_RADIUS_M,
                  defaultValue: 'Default ({{m}} m)',
                })}
                className="font-mono"
              />
            </div>
          </div>

          <p className="text-xs text-muted-foreground">
            {t(
              'locations.dialog.mapHelper',
              'Click the map or drag the marker to set the pin. Leave the radius empty to use the default.',
            )}
          </p>

          <LocationsMapPicker
            lat={coordValid ? numericLat : null}
            lng={coordValid ? numericLng : null}
            radiusM={effectiveRadius}
            radiusIsDefault={radiusOverride === null}
            onPositionChange={handlePositionChange}
            primaryTitle={dropoff?.name}
            className="h-[320px]"
          />
        </div>

        <DialogFooter className="shrink-0 gap-2 border-t px-6 py-3 sm:justify-between">
          <div>
            {dropoff && onDelete && (
              <Button
                variant="ghost"
                className="gap-1.5 text-destructive hover:bg-destructive/10 hover:text-destructive"
                onClick={() => onDelete(dropoff)}
              >
                <Trash2 className="h-4 w-4" />
                {t('common.delete', 'Delete')}
              </Button>
            )}
          </div>
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              {t('common.cancel', 'Cancel')}
            </Button>
            <Button onClick={() => void handleSave()} disabled={!canSave || saving}>
              {saving ? (
                <Loader2 className="me-1.5 h-4 w-4 animate-spin" />
              ) : (
                <Save className="me-1.5 h-4 w-4" />
              )}
              {t('common.save', 'Save')}
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useTranslation } from 'react-i18next';
import type { DropOffPoint } from '@/entities/location/schemas';
import { DataTable } from '@/shared/ui/data-table';
import { useDropoffColumns } from './columns';

interface LocationsDropoffsTableProps {
  dropoffs: DropOffPoint[];
  loading?: boolean;
  onRowClick: (dropoff: DropOffPoint) => void;
  /** Server-side pagination — the list endpoint is paginated now. */
  pagination?: {
    page: number;
    totalPages: number;
    onPageChange: (page: number) => void;
  };
  pageSize?: number;
}

export function LocationsDropoffsTable({
  dropoffs,
  loading,
  onRowClick,
  pagination,
  pageSize = 50,
}: LocationsDropoffsTableProps) {
  const { t } = useTranslation();
  const columns = useDropoffColumns();

  return (
    <DataTable
      columns={columns}
      data={dropoffs}
      loading={loading}
      onRowClick={onRowClick}
      pageSize={pageSize}
      pagination={pagination}
      emptyState={t('locations.dropoffs.empty', 'No drop-off points found')}
    />
  );
}

import * as React from 'react';
import { MapView } from '@/shared/ui/map-view';
import type { MapCircle, MapMarker } from '@/shared/lib/maps/types';
import { DEFAULT_MAP_CENTER, isValidCoordinate } from '@/shared/lib/coords';
import { cn } from '@/shared/lib/cn';

export interface SecondaryPin {
  lat: number;
  lng: number;
  color?: string;
  title?: string;
}

interface LocationsMapPickerProps {
  lat: number | null;
  lng: number | null;
  /** Radius circle drawn around the primary pin. Omit/null for no circle. */
  radiusM?: number | null;
  /** Faint circle styling when the radius shown is the fallback default. */
  radiusIsDefault?: boolean;
  /** When set, map clicks and marker drags reposition the primary pin. */
  onPositionChange?: (lat: number, lng: number) => void;
  /** Extra pin (e.g. a GPS-suggested position) rendered alongside. */
  secondary?: SecondaryPin | null;
  primaryColor?: string;
  primaryTitle?: string;
  className?: string;
}

/**
 * Generalized location picker — the zones map picker pattern, reworked for
 * nullable pins (many drop-off points have none yet), a default-radius
 * visualization, and an optional second read-only pin for comparing a
 * stored position against a GPS-suggested one.
 */
export function LocationsMapPicker({
  lat,
  lng,
  radiusM,
  radiusIsDefault = false,
  onPositionChange,
  secondary,
  primaryColor = '#2563eb',
  primaryTitle,
  className,
}: LocationsMapPickerProps) {
  const hasPosition = isValidCoordinate(lat, lng);
  const editable = !!onPositionChange;

  const handleMapClick = React.useCallback(
    (newLat: number, newLng: number) => {
      onPositionChange?.(newLat, newLng);
    },
    [onPositionChange],
  );

  const handleMarkerDragEnd = React.useCallback(
    (id: string, newLat: number, newLng: number) => {
      if (id === 'primary-pin') {
        onPositionChange?.(newLat, newLng);
      }
    },
    [onPositionChange],
  );

  const markers: MapMarker[] = React.useMemo(() => {
    const list: MapMarker[] = [];
    if (hasPosition) {
      list.push({
        id: 'primary-pin',
        lat: lat as number,
        lng: lng as number,
        color: primaryColor,
        title: primaryTitle,
        draggable: editable,
        affectsBounds: true,
      });
    }
    if (secondary && isValidCoordinate(secondary.lat, secondary.lng)) {
      list.push({
        id: 'secondary-pin',
        lat: secondary.lat,
        lng: secondary.lng,
        color: secondary.color ?? '#16a34a',
        title: secondary.title,
        affectsBounds: true,
      });
    }
    return list;
  }, [hasPosition, lat, lng, primaryColor, primaryTitle, editable, secondary]);

  const circles: MapCircle[] = React.useMemo(() => {
    if (!hasPosition || radiusM == null || radiusM <= 0) return [];
    return [
      {
        id: 'primary-radius',
        lat: lat as number,
        lng: lng as number,
        radius_m: radiusM,
        color: primaryColor,
        fillOpacity: radiusIsDefault ? 0.08 : 0.2,
      },
    ];
  }, [hasPosition, lat, lng, radiusM, radiusIsDefault, primaryColor]);

  const centerFallback = React.useMemo<[number, number]>(() => {
    if (hasPosition) return [lat as number, lng as number];
    if (secondary && isValidCoordinate(secondary.lat, secondary.lng)) {
      return [secondary.lat, secondary.lng];
    }
    return DEFAULT_MAP_CENTER;
  }, [hasPosition, lat, lng, secondary]);

  return (
    <div className={cn('h-[360px] w-full overflow-hidden rounded-lg border', className)}>
      <MapView
        markers={markers}
        circles={circles}
        onMapClick={editable ? handleMapClick : undefined}
        onMarkerDragEnd={editable ? handleMarkerDragEnd : undefined}
        centerFallback={centerFallback}
        liveUpdates={true}
      />
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import {
  AlertTriangle,
  ArrowRightLeft,
  CheckCircle2,
  ChevronDown,
  HelpCircle,
  Loader2,
  MapPin,
  MapPinOff,
  Pencil,
  Sparkles,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Skeleton } from '@/shared/ui/skeleton';
import { EmptyState } from '@/shared/ui/empty-state';
import { NativeSelect } from '@/shared/ui/native-select';
import { cn } from '@/shared/lib/cn';
import { normalize } from '@/shared/lib/normalize';
import { locationApi } from '@/entities/location/api';
import {
  useAckSuggestion,
  useLocationsInbox,
  usePinSuggestions,
  useTerminals,
  useUpdateDropoff,
  useUpdateTerminal,
} from '@/entities/location/queries';
import type { DropOffPoint, PinSuggestion, Terminal } from '@/entities/location/schemas';
import { LocationsDropoffDialog } from '../locations-dropoff-dialog';
import { LocationsTerminalDialog } from '../locations-terminal-dialog';
import { LocationsMapPicker } from '../locations-map-picker';
import { TripsPagination } from '../trips-table/trips-pagination';

const STORED_PIN_COLOR = '#2563eb';
const SUGGESTED_PIN_COLOR = '#16a34a';

/** Case/diacritic-insensitive name matching (Arabic-aware). */
function sameName(a: string, b: string): boolean {
  return normalize(a) === normalize(b);
}

/* -------------------------------------------------------------------------- */
/* Queue model                                                                 */
/*                                                                             */
/* Every inbox source flattens into ONE work item type so the whole page is a  */
/* single prioritized, filterable list — not four stacked sections. Priority   */
/* mirrors impact: a wrong pin corrupts audits (worst), a one-click fix is     */
/* cheap value, provisional confirmations are housekeeping, and manual pinning */
/* comes last because it needs the most human effort.                          */
/* -------------------------------------------------------------------------- */

type QueueItem =
  | { type: 'mismatch'; key: string; name: string; kind: 'terminal' | 'dropoff'; s: PinSuggestion }
  | {
      type: 'unpinned';
      key: string;
      name: string;
      kind: 'terminal' | 'dropoff';
      dropoff: DropOffPoint | null;
      s: PinSuggestion | null;
    }
  | { type: 'provisional'; key: string; name: string; kind: 'terminal' | 'dropoff'; s: PinSuggestion };

type IssueFilter = 'all' | 'mismatch' | 'unpinned' | 'provisional';
type KindFilter = 'all' | 'terminal' | 'dropoff';

const PRIORITY: Record<QueueItem['type'], number> = { mismatch: 0, unpinned: 1, provisional: 2 };

function itemEvidence(item: QueueItem): number {
  if (item.type === 'unpinned') return item.s?.stop_count ?? 0;
  return item.s.stop_count;
}

/**
 * "Needs Attention" — the Locations work queue.
 *
 * One flat, prioritized list. Each row: what the place is, one sentence on
 * why it is here, and ONE primary action. Expanding a row (single-open
 * accordion) reveals the map evidence — maps render only for the open row,
 * which keeps a 60-item queue fast.
 */
export function LocationsNeedsAttention({ onBrowseDropoffs }: { onBrowseDropoffs?: () => void }) {
  const { t } = useTranslation();

  const inboxQuery = useLocationsInbox();
  const suggestionsQuery = usePinSuggestions();
  const autoAppliedQuery = usePinSuggestions('auto_applied');
  const { data: terminals = [] } = useTerminals();

  const updateDropoff = useUpdateDropoff();
  const updateTerminal = useUpdateTerminal();
  const ackSuggestion = useAckSuggestion();

  const inbox = inboxQuery.data;
  const suggestionsUnavailable = suggestionsQuery.isError;

  const pending = React.useMemo(
    () => (suggestionsQuery.data ?? []).filter((s) => s.status === 'pending'),
    [suggestionsQuery.data],
  );
  const provisional = React.useMemo(
    () => (autoAppliedQuery.data ?? []).filter((s) => s.status === 'auto_applied'),
    [autoAppliedQuery.data],
  );

  const findTerminalByName = React.useCallback(
    (name: string): Terminal | null => terminals.find((x) => sameName(x.name, name)) ?? null,
    [terminals],
  );

  /* ---- Build the unified queue ---- */
  const items = React.useMemo<QueueItem[]>(() => {
    const out: QueueItem[] = [];

    for (const s of pending) {
      const hasStored = s.current_lat != null && s.current_lng != null && (s.offset_m ?? 0) > 0;
      if (hasStored) {
        out.push({ type: 'mismatch', key: `m-${s.id}`, name: s.name, kind: s.kind, s });
      } else if (s.kind === 'terminal') {
        out.push({ type: 'unpinned', key: `t-${s.id}`, name: s.name, kind: 'terminal', dropoff: null, s });
      }
    }

    const newDropoffPins = pending.filter((s) => s.kind === 'dropoff' && s.current_lat == null);
    for (const d of inbox?.unpinned_dropoffs ?? []) {
      const s = newDropoffPins.find((x) => sameName(x.name, d.name)) ?? null;
      out.push({ type: 'unpinned', key: `d-${d.ID}`, name: d.name, kind: 'dropoff', dropoff: d, s });
    }

    for (const s of provisional) {
      out.push({ type: 'provisional', key: `p-${s.id}`, name: s.name, kind: s.kind, s });
    }

    // Impact order, then strongest GPS evidence first, then name.
    out.sort((a, b) => {
      if (PRIORITY[a.type] !== PRIORITY[b.type]) return PRIORITY[a.type] - PRIORITY[b.type];
      const ev = itemEvidence(b) - itemEvidence(a);
      if (ev !== 0) return ev;
      return a.name.localeCompare(b.name);
    });
    return out;
  }, [pending, provisional, inbox]);

  /* ---- Filters ---- */
  const [issue, setIssue] = React.useState<IssueFilter>('all');
  const [kind, setKind] = React.useState<KindFilter>('all');
  const [page, setPage] = React.useState(1);
  const [limit, setLimit] = React.useState(25);

  const counts = React.useMemo(
    () => ({
      all: items.length,
      mismatch: items.filter((i) => i.type === 'mismatch').length,
      unpinned: items.filter((i) => i.type === 'unpinned').length,
      provisional: items.filter((i) => i.type === 'provisional').length,
    }),
    [items],
  );

  const filtered = React.useMemo(
    () =>
      items.filter(
        (i) => (issue === 'all' || i.type === issue) && (kind === 'all' || i.kind === kind),
      ),
    [items, issue, kind],
  );

  React.useEffect(() => {
    setPage(1);
    setExpandedKey(null);
  }, [issue, kind, limit]);

  /* ---- Single-open accordion ---- */
  const [expandedKey, setExpandedKey] = React.useState<string | null>(null);

  /* ---- Actions (same semantics as before the redesign) ---- */
  const [busyKey, setBusyKey] = React.useState<string | null>(null);

  const [reviewTarget, setReviewTarget] = React.useState<{
    dropoff: DropOffPoint;
    suggestion: PinSuggestion | null;
    pinSource: string;
  } | null>(null);
  const [terminalTarget, setTerminalTarget] = React.useState<{
    terminal: Terminal;
    suggestion: PinSuggestion;
  } | null>(null);

  const notFoundToast = () =>
    toast.error(
      t(
        'locations.inbox.noMatch',
        'No matching record found for this name — the pin cannot be moved automatically.',
      ),
    );

  const findDropoffByName = React.useCallback(async (name: string): Promise<DropOffPoint | null> => {
    try {
      const page = await locationApi.listDropoffs({ q: name, per_page: 10 });
      return page.items.find((d) => sameName(d.name, name)) ?? null;
    } catch {
      return null;
    }
  }, []);

  const applySuggestedPin = async (item: QueueItem, s: PinSuggestion, pinSource: string) => {
    setBusyKey(item.key);
    try {
      if (s.kind === 'dropoff') {
        const dropoff =
          (item.type === 'unpinned' ? item.dropoff : null) ?? (await findDropoffByName(s.name));
        if (!dropoff) {
          notFoundToast();
          return;
        }
        await updateDropoff.mutateAsync({
          id: dropoff.ID,
          payload: { lat: s.suggested_lat, long: s.suggested_lng, pin_source: pinSource },
        });
      } else {
        const terminal = findTerminalByName(s.name);
        if (!terminal) {
          notFoundToast();
          return;
        }
        await updateTerminal.mutateAsync({
          id: terminal.ID,
          payload: { lat: s.suggested_lat, long: s.suggested_lng, pin_source: pinSource },
        });
      }
      await ackSuggestion.mutateAsync({ id: s.id, status: 'accepted' });
    } catch {
      // Toasts handled by the mutations
    } finally {
      setBusyKey(null);
    }
  };

  const dismissSuggestion = async (item: QueueItem, s: PinSuggestion) => {
    setBusyKey(item.key);
    try {
      await ackSuggestion.mutateAsync({ id: s.id, status: 'dismissed' });
    } catch {
      // Toast handled by the mutation
    } finally {
      setBusyKey(null);
    }
  };

  const adjustPin = async (item: QueueItem, s: PinSuggestion) => {
    setBusyKey(item.key);
    try {
      if (s.kind === 'dropoff') {
        const dropoff =
          (item.type === 'unpinned' ? item.dropoff : null) ?? (await findDropoffByName(s.name));
        if (!dropoff) {
          notFoundToast();
          return;
        }
        setReviewTarget({ dropoff, suggestion: s, pinSource: 'manual' });
      } else {
        const terminal = findTerminalByName(s.name);
        if (!terminal) {
          notFoundToast();
          return;
        }
        setTerminalTarget({ terminal, suggestion: s });
      }
    } finally {
      setBusyKey(null);
    }
  };

  /* ---- Loading / empty ---- */
  if (inboxQuery.isLoading) {
    return (
      <div className="space-y-2">
        <Skeleton className="h-12 w-full" />
        <Skeleton className="h-12 w-full" />
        <Skeleton className="h-12 w-full" />
      </div>
    );
  }

  const totalUnpinned = inbox?.total_unpinned ?? inbox?.unpinned_dropoffs.length ?? 0;
  const cappedNote = totalUnpinned > (inbox?.unpinned_dropoffs.length ?? 0);

  if (items.length === 0) {
    return (
      <EmptyState
        icon={<CheckCircle2 className="h-6 w-6" />}
        title={t('locations.inbox.allClear', 'All caught up')}
        description={t('locations.inbox.allClearDesc', 'No locations need attention right now.')}
        action={
          onBrowseDropoffs ? (
            <Button variant="outline" size="sm" onClick={onBrowseDropoffs}>
              {t('locations.inbox.browseDropoffs', 'Browse drop-off points')}
            </Button>
          ) : undefined
        }
      />
    );
  }

  const issuePills: Array<{ id: IssueFilter; label: string; count: number }> = [
    { id: 'all', label: t('locations.inbox.filter.all', 'All'), count: counts.all },
    { id: 'mismatch', label: t('locations.inbox.filter.mismatch', 'Wrong pin'), count: counts.mismatch },
    { id: 'unpinned', label: t('locations.inbox.filter.unpinned', 'Missing pin'), count: counts.unpinned },
    {
      id: 'provisional',
      label: t('locations.inbox.filter.provisional', 'Provisional'),
      count: counts.provisional,
    },
  ];

  return (
    <div className="space-y-4">
      {suggestionsUnavailable && (
        <div className="flex items-start gap-2 rounded-md border border-warning/40 bg-warning/5 p-3 text-sm text-muted-foreground">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-warning" />
          {t(
            'locations.inbox.suggestionsUnavailable',
            'GPS suggestions are unavailable right now — showing database items only.',
          )}
        </div>
      )}

      {/* Toolbar: issue pills + kind select */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex flex-wrap gap-1.5">
          {issuePills
            .filter((p) => p.id === 'all' || p.count > 0)
            .map((p) => (
              <button
                key={p.id}
                type="button"
                onClick={() => setIssue(p.id)}
                aria-pressed={issue === p.id}
                className={cn(
                  'inline-flex h-8 items-center gap-1.5 rounded-full border px-3 text-xs font-medium transition-colors',
                  issue === p.id
                    ? 'border-primary bg-primary text-primary-foreground'
                    : 'bg-card text-muted-foreground hover:bg-muted/60',
                )}
              >
                {p.label}
                <span className="tabular-nums opacity-80">{p.count}</span>
              </button>
            ))}
        </div>
        <NativeSelect
          value={kind}
          onChange={(e) => setKind(e.target.value as KindFilter)}
          className="ms-auto h-8 w-auto text-xs"
          aria-label={t('locations.inbox.filter.kind', 'Location type')}
        >
          <option value="all">{t('locations.inbox.filter.allKinds', 'All types')}</option>
          <option value="terminal">{t('locations.kind.terminal', 'Terminal')}</option>
          <option value="dropoff">{t('locations.kind.dropoff', 'Drop-off')}</option>
        </NativeSelect>
      </div>

      {cappedNote && (
        <p className="text-xs text-muted-foreground">
          {t('locations.inbox.unpinnedCapped', {
            shown: inbox?.unpinned_dropoffs.length ?? 0,
            total: totalUnpinned,
            defaultValue: 'Showing the first {{shown}} of {{total}} unpinned drop-off points.',
          })}
        </p>
      )}

      {/* The queue */}
      <div className="divide-y overflow-hidden rounded-lg border bg-card">
        {filtered.slice((page - 1) * limit, page * limit).map((item) => (
          <QueueRow
            key={item.key}
            item={item}
            expanded={expandedKey === item.key}
            busy={busyKey === item.key}
            terminalMissing={item.kind === 'terminal' && !findTerminalByName(item.name)}
            onToggle={() => setExpandedKey((k) => (k === item.key ? null : item.key))}
            onApply={(s, source) => void applySuggestedPin(item, s, source)}
            onDismiss={(s) => void dismissSuggestion(item, s)}
            onAdjust={(s) => void adjustPin(item, s)}
            onSetPinManually={() => {
              if (item.type === 'unpinned' && item.dropoff) {
                setReviewTarget({ dropoff: item.dropoff, suggestion: null, pinSource: 'manual' });
              }
            }}
          />
        ))}
        {filtered.length === 0 && (
          <p className="p-6 text-center text-sm text-muted-foreground">
            {t('locations.inbox.noneForFilter', 'Nothing matches this filter.')}
          </p>
        )}
      </div>

      <TripsPagination
        page={page}
        pages={Math.max(1, Math.ceil(filtered.length / limit))}
        total={filtered.length}
        limit={limit}
        onPageChange={(p) => {
          setPage(p);
          setExpandedKey(null);
        }}
        onLimitChange={setLimit}
      />

      {/* Drop-off pin editor */}
      <LocationsDropoffDialog
        open={reviewTarget !== null}
        onOpenChange={(open) => {
          if (!open) setReviewTarget(null);
        }}
        dropoff={reviewTarget?.dropoff ?? null}
        initialPin={
          reviewTarget?.suggestion
            ? { lat: reviewTarget.suggestion.suggested_lat, lng: reviewTarget.suggestion.suggested_lng }
            : null
        }
        pinSourceOnSave={reviewTarget?.pinSource ?? 'manual'}
        note={
          reviewTarget?.suggestion
            ? t('locations.inbox.gpsSuggests', {
                stops: reviewTarget.suggestion.stop_count,
                defaultValue: 'GPS suggests a pin from {{stops}} stops',
              })
            : undefined
        }
        onSaved={async () => {
          if (reviewTarget?.suggestion) {
            await ackSuggestion.mutateAsync({ id: reviewTarget.suggestion.id, status: 'accepted' });
          }
        }}
      />

      {/* Terminal pin editor */}
      <LocationsTerminalDialog
        terminal={terminalTarget?.terminal ?? null}
        onOpenChange={(open) => {
          if (!open) setTerminalTarget(null);
        }}
        onSaved={async () => {
          if (terminalTarget) {
            await ackSuggestion.mutateAsync({ id: terminalTarget.suggestion.id, status: 'accepted' });
          }
        }}
      />
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* One queue row                                                               */
/* -------------------------------------------------------------------------- */

function QueueRow({
  item,
  expanded,
  busy,
  terminalMissing,
  onToggle,
  onApply,
  onDismiss,
  onAdjust,
  onSetPinManually,
}: {
  item: QueueItem;
  expanded: boolean;
  busy: boolean;
  terminalMissing: boolean;
  onToggle: () => void;
  onApply: (s: PinSuggestion, pinSource: string) => void;
  onDismiss: (s: PinSuggestion) => void;
  onAdjust: (s: PinSuggestion) => void;
  onSetPinManually: () => void;
}) {
  const { t } = useTranslation();

  const s = item.type === 'unpinned' ? item.s : item.s;
  const hasEvidence = s != null;

  const icon =
    item.type === 'mismatch' ? (
      <ArrowRightLeft className="h-4 w-4 text-warning" />
    ) : item.type === 'provisional' ? (
      <Sparkles className="h-4 w-4 text-success" />
    ) : (
      <MapPinOff className="h-4 w-4 text-muted-foreground" />
    );

  const why =
    item.type === 'mismatch'
      ? t('locations.inbox.mismatchText', {
          distance: Math.round(item.s.offset_m ?? 0),
          stops: item.s.stop_count,
          defaultValue: 'GPS cluster is {{distance}} m from the stored pin ({{stops}} stops)',
        })
      : item.type === 'provisional'
        ? t('locations.inbox.provisionalText', {
            stops: item.s.stop_count,
            defaultValue: 'Pin applied automatically from {{stops}} GPS stops',
          })
        : s
          ? t('locations.inbox.gpsSuggests', {
              stops: s.stop_count,
              defaultValue: 'GPS suggests a pin from {{stops}} stops',
            })
          : t('locations.inbox.noPinNoData', 'No pin yet — set it on the map');

  /* The ONE primary action per row type. */
  const primary = (() => {
    if (item.type === 'mismatch') {
      return (
        <Button
          size="sm"
          className="gap-1.5"
          disabled={busy || (item.kind === 'terminal' && terminalMissing)}
          onClick={(e) => {
            e.stopPropagation();
            onApply(item.s, 'gps_suggested');
          }}
        >
          {busy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <MapPin className="h-3.5 w-3.5" />}
          {t('locations.inbox.movePin', 'Move pin')}
        </Button>
      );
    }
    if (item.type === 'provisional') {
      return (
        <Button
          size="sm"
          className="gap-1.5"
          disabled={busy}
          onClick={(e) => {
            e.stopPropagation();
            onApply(item.s, 'manual');
          }}
        >
          {busy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <CheckCircle2 className="h-3.5 w-3.5" />}
          {t('locations.inbox.confirmPin', 'Confirm')}
        </Button>
      );
    }
    if (s) {
      return (
        <Button
          size="sm"
          className="gap-1.5"
          disabled={busy || (item.kind === 'terminal' && terminalMissing)}
          onClick={(e) => {
            e.stopPropagation();
            onApply(s, 'gps_suggested');
          }}
        >
          {busy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5" />}
          {t('locations.inbox.applyPin', 'Apply pin')}
        </Button>
      );
    }
    return (
      <Button
        size="sm"
        variant="outline"
        disabled={item.kind === 'terminal'}
        onClick={(e) => {
          e.stopPropagation();
          onSetPinManually();
        }}
      >
        {t('locations.inbox.setPin', 'Set pin')}
      </Button>
    );
  })();

  return (
    <div className={cn('transition-colors', expanded && 'bg-muted/30')}>
      {/* Row line */}
      <div
        role="button"
        tabIndex={0}
        onClick={onToggle}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onToggle();
          }
        }}
        className="flex cursor-pointer items-center gap-3 px-3 py-2.5 hover:bg-muted/40"
      >
        <span className="shrink-0">{icon}</span>
        <div className="min-w-0 flex-1">
          <div className="flex min-w-0 items-baseline gap-2">
            <span className="min-w-0 truncate text-sm font-medium" dir="auto">
              {item.name}
            </span>
            <Badge variant="outline" className="shrink-0 text-[10px]">
              {item.kind === 'terminal'
                ? t('locations.kind.terminal', 'Terminal')
                : t('locations.kind.dropoff', 'Drop-off')}
            </Badge>
          </div>
          <p className="truncate text-xs text-muted-foreground" dir="auto">
            {why}
          </p>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {primary}
          {hasEvidence && (
            <ChevronDown
              className={cn(
                'h-4 w-4 text-muted-foreground transition-transform',
                expanded && 'rotate-180',
              )}
            />
          )}
        </div>
      </div>

      {/* Expanded evidence — the ONLY row that renders a map */}
      {expanded && s && (
        <div className="space-y-3 border-t px-3 py-3">
          <LocationsMapPicker
            lat={item.type === 'mismatch' ? (item.s.current_lat ?? null) : item.type === 'provisional' ? s.suggested_lat : null}
            lng={item.type === 'mismatch' ? (item.s.current_lng ?? null) : item.type === 'provisional' ? s.suggested_lng : null}
            primaryColor={item.type === 'provisional' ? SUGGESTED_PIN_COLOR : STORED_PIN_COLOR}
            primaryTitle={
              item.type === 'provisional'
                ? item.name
                : t('locations.inbox.currentPin', 'Stored pin')
            }
            secondary={
              item.type !== 'provisional'
                ? {
                    lat: s.suggested_lat,
                    lng: s.suggested_lng,
                    color: SUGGESTED_PIN_COLOR,
                    title: t('locations.inbox.suggestedPin', 'GPS suggestion'),
                  }
                : undefined
            }
            className="h-[240px]"
          />
          {item.type === 'mismatch' && (
            <div className="flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
              <span className="flex items-center gap-1.5">
                <span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: STORED_PIN_COLOR }} />
                {t('locations.inbox.currentPin', 'Stored pin')}
              </span>
              <span className="flex items-center gap-1.5">
                <span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: SUGGESTED_PIN_COLOR }} />
                {t('locations.inbox.suggestedPin', 'GPS suggestion')}
              </span>
            </div>
          )}
          {item.kind === 'terminal' && terminalMissing && (
            <p className="flex items-center gap-1.5 text-xs text-warning">
              <HelpCircle className="h-3.5 w-3.5" />
              {t(
                'locations.inbox.noMatch',
                'No matching record found for this name — the pin cannot be moved automatically.',
              )}
            </p>
          )}
          <div className="flex flex-wrap gap-2">
            {(item.type === 'provisional' || item.type === 'unpinned') && (
              <Button
                size="sm"
                variant="outline"
                className="gap-1.5"
                disabled={busy}
                onClick={() => onAdjust(s)}
              >
                <Pencil className="h-3.5 w-3.5" />
                {t('locations.inbox.adjustPin', 'Adjust')}
              </Button>
            )}
            {item.type === 'mismatch' && (
              <Button size="sm" variant="outline" disabled={busy} onClick={() => onDismiss(item.s)}>
                {t('locations.inbox.keepCurrent', 'Keep current')}
              </Button>
            )}
            {item.type !== 'mismatch' && s.status === 'pending' && (
              <Button size="sm" variant="ghost" disabled={busy} onClick={() => onDismiss(s)}>
                {t('locations.inbox.dismiss', 'Dismiss')}
              </Button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Loader2, MapPin, Pencil, Plus, Regex, Save, Trash2, X } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Badge } from '@/shared/ui/badge';
import { Switch } from '@/shared/ui/switch';
import { isValidCoordinate } from '@/shared/lib/coords';
import {
  TERMINAL_DEFAULT_RADIUS_M,
  type ReceiptPattern,
  type Terminal,
  type UpdateTerminalPayload,
} from '@/entities/location/schemas';
import {
  useDeleteReceiptPattern,
  useReceiptPatterns,
  useUpdateTerminal,
  useUpsertReceiptPattern,
} from '@/entities/location/queries';
import { LocationsMapPicker } from '../locations-map-picker';
import { PinSourceBadge } from '../locations-dropoffs-table/pin-source-badge';

interface LocationsTerminalDialogProps {
  terminal: Terminal | null;
  onOpenChange: (open: boolean) => void;
  /** Runs after a successful save (e.g. ack a GPS suggestion). */
  onSaved?: () => void | Promise<void>;
}

/**
 * Terminal editor — draggable pin + radius circle (500 m default shown when
 * no override is stored), radius override input, address, allowed-company
 * chips, and a receipt-serialization pattern editor. Patterns persist
 * immediately through their own upsert/delete endpoints; the rest saves on
 * submit via `PUT /api/locations/terminals/:id`.
 */
export function LocationsTerminalDialog({
  terminal,
  onOpenChange,
  onSaved,
}: LocationsTerminalDialogProps) {
  const { t } = useTranslation();
  const open = terminal !== null;

  const updateTerminal = useUpdateTerminal();

  const [address, setAddress] = React.useState('');
  const [lat, setLat] = React.useState('');
  const [lng, setLng] = React.useState('');
  const [radius, setRadius] = React.useState('');

  // Re-hydrate only when the target terminal changes (not on every cache
  // refresh — pattern mutations refetch the list and we must not clobber
  // in-progress edits).
  const hydratedId = React.useRef<number | null>(null);
  React.useEffect(() => {
    if (!terminal) {
      hydratedId.current = null;
      return;
    }
    if (hydratedId.current === terminal.ID) return;
    hydratedId.current = terminal.ID;
    setAddress(terminal.address ?? '');
    setLat(terminal.lat != null ? String(terminal.lat) : '');
    setLng(terminal.long != null ? String(terminal.long) : '');
    setRadius(terminal.radius_m != null ? String(terminal.radius_m) : '');
  }, [terminal]);

  const numericLat = Number(lat);
  const numericLng = Number(lng);
  const coordValid = lat.trim() !== '' && lng.trim() !== '' && isValidCoordinate(numericLat, numericLng);

  const radiusOverride = radius.trim() === '' ? null : Number(radius);
  const radiusValid = radiusOverride === null || (Number.isFinite(radiusOverride) && radiusOverride > 0);
  const effectiveRadius = radiusOverride ?? TERMINAL_DEFAULT_RADIUS_M;

  const handlePositionChange = React.useCallback((newLat: number, newLng: number) => {
    setLat(newLat.toFixed(6));
    setLng(newLng.toFixed(6));
  }, []);

  const handleSave = async () => {
    if (!terminal || !radiusValid) return;
    const payload: UpdateTerminalPayload = {};

    const trimmedAddress = address.trim();
    if (trimmedAddress !== (terminal.address ?? '').trim()) {
      payload.address = trimmedAddress;
    }
    if (coordValid) {
      payload.lat = Number(numericLat.toFixed(6));
      payload.long = Number(numericLng.toFixed(6));
      // A hand-placed (or hand-confirmed) move counts as a manual pin; an
      // untouched position keeps its stored pin_source.
      const moved =
        terminal.lat == null ||
        terminal.long == null ||
        Math.abs(terminal.lat - payload.lat) > 1e-6 ||
        Math.abs(terminal.long - payload.long) > 1e-6;
      if (moved) payload.pin_source = 'manual';
    }
    if (radiusOverride !== null) {
      payload.radius_m = radiusOverride;
    } else if (terminal.radius_m != null) {
      payload.clear_radius = true;
    }

    try {
      await updateTerminal.mutateAsync({ id: terminal.ID, payload });
      await onSaved?.();
      onOpenChange(false);
    } catch {
      // Toast handled by the mutation
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[90vh] max-w-2xl flex-col gap-0 overflow-hidden p-0">
        <DialogHeader className="shrink-0 border-b px-6 py-4">
          <DialogTitle className="flex items-center gap-2">
            <MapPin className="h-4 w-4 text-primary" />
            {t('locations.dialog.editTerminal', 'Edit Terminal')}
          </DialogTitle>
          <DialogDescription className="flex items-center gap-2 truncate" dir="auto">
            <span dir="auto" className="truncate">{terminal?.name ?? ''}</span>
            <PinSourceBadge pinSource={terminal?.pin_source} />
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-1 flex-col gap-4 overflow-y-auto px-6 py-4">
          {/* Allowed companies (read-only — extend via the trip form's
              create/allow flow or the backend) */}
          {(terminal?.allowed_companies?.length ?? 0) > 0 && (
            <div className="space-y-1.5">
              <Label className="text-xs">
                {t('locations.fields.allowedCompanies', 'Allowed companies')}
              </Label>
              <div className="flex flex-wrap gap-1.5">
                {terminal?.allowed_companies.map((company) => (
                  <Badge key={company} variant="secondary" dir="auto">
                    {company}
                  </Badge>
                ))}
              </div>
            </div>
          )}

          {/* Address */}
          <div className="space-y-1">
            <Label htmlFor="terminal-address" className="text-xs">
              {t('locations.fields.address', 'Address')}
            </Label>
            <Input
              id="terminal-address"
              dir="auto"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              placeholder={t('locations.fields.addressPlaceholder', 'Optional address')}
            />
          </div>

          {/* Coordinates + radius */}
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
            <div className="space-y-1">
              <Label htmlFor="terminal-lat" className="text-xs">
                {t('locations.fields.lat', 'Latitude')}
              </Label>
              <Input
                id="terminal-lat"
                type="number"
                step="0.000001"
                value={lat}
                onChange={(e) => setLat(e.target.value)}
                placeholder="30.044420"
                className="font-mono"
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor="terminal-lng" className="text-xs">
                {t('locations.fields.lng', 'Longitude')}
              </Label>
              <Input
                id="terminal-lng"
                type="number"
                step="0.000001"
                value={lng}
                onChange={(e) => setLng(e.target.value)}
                placeholder="31.235712"
                className="font-mono"
              />
            </div>
            <div className="col-span-2 space-y-1 sm:col-span-1">
              <Label htmlFor="terminal-radius" className="text-xs">
                {t('locations.fields.radius', 'Radius (m)')}
              </Label>
              <Input
                id="terminal-radius"
                type="number"
                step="1"
                min="1"
                value={radius}
                onChange={(e) => setRadius(e.target.value)}
                placeholder={t('locations.fields.radiusDefaultPlaceholder', {
                  m: TERMINAL_DEFAULT_RADIUS_M,
                  defaultValue: 'Default ({{m}} m)',
                })}
                className="font-mono"
              />
            </div>
          </div>

          <p className="text-xs text-muted-foreground">
            {t(
              'locations.dialog.mapHelper',
              'Click the map or drag the marker to set the pin. Leave the radius empty to use the default.',
            )}
          </p>

          <LocationsMapPicker
            lat={coordValid ? numericLat : null}
            lng={coordValid ? numericLng : null}
            radiusM={effectiveRadius}
            radiusIsDefault={radiusOverride === null}
            onPositionChange={handlePositionChange}
            primaryTitle={terminal?.name}
            className="h-[320px]"
          />

          {/* Receipt serialization patterns */}
          {terminal && <ReceiptPatternsSection terminalId={terminal.ID} />}
        </div>

        <DialogFooter className="shrink-0 gap-2 border-t px-6 py-3">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {t('common.cancel', 'Cancel')}
          </Button>
          <Button
            onClick={() => void handleSave()}
            disabled={!radiusValid || updateTerminal.isPending}
          >
            {updateTerminal.isPending ? (
              <Loader2 className="me-1.5 h-4 w-4 animate-spin" />
            ) : (
              <Save className="me-1.5 h-4 w-4" />
            )}
            {t('common.save', 'Save')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/* -------------------------------------------------------------------------- */
/* Receipt patterns editor                                                     */
/*                                                                             */
/* One pattern per (terminal, company); empty company = "all companies".       */
/* Saves through the PUT upsert immediately (independent of the dialog's       */
/* main Save button). The regex must compile client-side before saving.        */
/* -------------------------------------------------------------------------- */

interface PatternFormState {
  /** Empty string = applies to all companies. */
  company: string;
  pattern: string;
  description: string;
  active: boolean;
  /** Company key of the row being edited, null when adding a new pattern. */
  editingCompany: string | null;
}

const emptyPatternForm: PatternFormState = {
  company: '',
  pattern: '',
  description: '',
  active: true,
  editingCompany: null,
};

function ReceiptPatternsSection({ terminalId }: { terminalId: number }) {
  const { t } = useTranslation();
  const patternsQuery = useReceiptPatterns(terminalId);
  const upsertPattern = useUpsertReceiptPattern();
  const deletePattern = useDeleteReceiptPattern();

  const [form, setForm] = React.useState<PatternFormState>(emptyPatternForm);
  const [showForm, setShowForm] = React.useState(false);
  const [deleteBusyCompany, setDeleteBusyCompany] = React.useState<string | null>(null);

  // Reset when switching terminals
  React.useEffect(() => {
    setForm(emptyPatternForm);
    setShowForm(false);
  }, [terminalId]);

  const patterns = patternsQuery.data ?? [];

  const regexError = React.useMemo(() => {
    if (!form.pattern.trim()) return false;
    try {
      void new RegExp(form.pattern);
      return false;
    } catch {
      return true;
    }
  }, [form.pattern]);

  const canSave = !!form.pattern.trim() && !regexError && !upsertPattern.isPending;

  const startEdit = (pattern: ReceiptPattern) => {
    setForm({
      company: pattern.company ?? '',
      pattern: pattern.pattern,
      description: pattern.description,
      active: pattern.active,
      editingCompany: pattern.company ?? '',
    });
    setShowForm(true);
  };

  const handleSavePattern = async () => {
    if (!canSave) return;
    try {
      await upsertPattern.mutateAsync({
        terminalId,
        payload: {
          company: form.company.trim(),
          pattern: form.pattern.trim(),
          description: form.description.trim(),
          active: form.active,
        },
      });
      setForm(emptyPatternForm);
      setShowForm(false);
    } catch {
      // Toast handled by the mutation
    }
  };

  const handleDelete = async (pattern: ReceiptPattern) => {
    const companyKey = pattern.company ?? '';
    setDeleteBusyCompany(companyKey);
    try {
      await deletePattern.mutateAsync({ terminalId, company: companyKey });
      if (form.editingCompany === companyKey) {
        setForm(emptyPatternForm);
        setShowForm(false);
      }
    } catch {
      // Toast handled by the mutation
    } finally {
      setDeleteBusyCompany(null);
    }
  };

  return (
    <div className="space-y-2 rounded-lg border bg-muted/20 p-3">
      <div className="flex items-center justify-between gap-2">
        <Label className="flex items-center gap-1.5 text-xs">
          <Regex className="h-3.5 w-3.5 text-primary" />
          {t('locations.receiptPatterns.title', 'Receipt serialization')}
        </Label>
        {!showForm && (
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-7 gap-1.5 text-xs"
            onClick={() => {
              setForm(emptyPatternForm);
              setShowForm(true);
            }}
          >
            <Plus className="h-3 w-3" />
            {t('locations.receiptPatterns.add', 'Add pattern')}
          </Button>
        )}
      </div>
      <p className="text-xs text-muted-foreground">
        {t(
          'locations.receiptPatterns.helper',
          'Regex patterns receipt numbers must match at this terminal — per company, or one for all companies.',
        )}
      </p>

      {/* Existing patterns */}
      {patternsQuery.isLoading ? (
        <div className="flex items-center gap-2 py-2 text-xs text-muted-foreground">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          {t('common.loading', 'Loading…')}
        </div>
      ) : patterns.length === 0 ? (
        <p className="py-1 text-xs text-muted-foreground">
          {t('locations.receiptPatterns.empty', 'No receipt patterns yet.')}
        </p>
      ) : (
        <div className="divide-y overflow-hidden rounded-md border bg-card">
          {patterns.map((pattern) => {
            const companyKey = pattern.company ?? '';
            const busy = deleteBusyCompany === companyKey && deletePattern.isPending;
            return (
              <div
                key={companyKey || '__all__'}
                className="flex flex-col gap-1.5 p-2.5 text-xs sm:flex-row sm:items-center sm:justify-between"
              >
                <div className="min-w-0 space-y-0.5">
                  <div className="flex flex-wrap items-center gap-1.5">
                    <Badge variant={pattern.company ? 'secondary' : 'outline'} dir="auto">
                      {pattern.company ??
                        t('locations.receiptPatterns.allCompanies', 'All companies')}
                    </Badge>
                    {!pattern.active && (
                      <Badge variant="warning">
                        {t('locations.receiptPatterns.inactive', 'Inactive')}
                      </Badge>
                    )}
                    <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-[11px]">
                      {pattern.pattern}
                    </code>
                  </div>
                  {pattern.description && (
                    <p className="truncate text-muted-foreground" dir="auto">
                      {pattern.description}
                    </p>
                  )}
                </div>
                <div className="flex shrink-0 items-center gap-0.5">
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7"
                    onClick={() => startEdit(pattern)}
                    aria-label={t('common.edit', 'Edit')}
                  >
                    <Pencil className="h-3.5 w-3.5" />
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7 text-destructive hover:bg-destructive/10 hover:text-destructive"
                    onClick={() => void handleDelete(pattern)}
                    disabled={busy}
                    aria-label={t('common.delete', 'Delete')}
                  >
                    {busy ? (
                      <Loader2 className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Trash2 className="h-3.5 w-3.5" />
                    )}
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Add / edit form */}
      {showForm && (
        <div className="space-y-2 rounded-md border bg-card p-3">
          <div className="grid gap-2 sm:grid-cols-2">
            <div className="space-y-1">
              <Label htmlFor="rp-company" className="text-xs">
                {t('locations.receiptPatterns.company', 'Company')}
              </Label>
              <Input
                id="rp-company"
                dir="auto"
                value={form.company}
                // The upsert is keyed on (terminal, company) — changing the
                // company while editing would create a second row, so lock it.
                disabled={form.editingCompany !== null}
                onChange={(e) => setForm((prev) => ({ ...prev, company: e.target.value }))}
                placeholder={t(
                  'locations.receiptPatterns.companyPlaceholder',
                  'Leave empty for all companies',
                )}
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor="rp-pattern" className="text-xs">
                {t('locations.receiptPatterns.pattern', 'Pattern (regex)')}
              </Label>
              <Input
                id="rp-pattern"
                value={form.pattern}
                onChange={(e) => setForm((prev) => ({ ...prev, pattern: e.target.value }))}
                placeholder="^WT-\d{5}$"
                className="font-mono"
                aria-invalid={regexError || undefined}
              />
              {regexError && (
                <p className="text-[11px] font-medium text-destructive">
                  {t(
                    'locations.receiptPatterns.invalidRegex',
                    'This pattern is not a valid regular expression.',
                  )}
                </p>
              )}
            </div>
          </div>
          <div className="space-y-1">
            <Label htmlFor="rp-description" className="text-xs">
              {t('locations.receiptPatterns.description', 'Description')}
            </Label>
            <Input
              id="rp-description"
              dir="auto"
              value={form.description}
              onChange={(e) => setForm((prev) => ({ ...prev, description: e.target.value }))}
              placeholder={t(
                'locations.receiptPatterns.descriptionPlaceholder',
                'e.g. WT- followed by 5 digits',
              )}
            />
          </div>
          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <Switch
                id="rp-active"
                checked={form.active}
                onCheckedChange={(checked) =>
                  setForm((prev) => ({ ...prev, active: checked }))
                }
              />
              <Label htmlFor="rp-active" className="cursor-pointer text-xs">
                {t('locations.receiptPatterns.active', 'Active')}
              </Label>
            </div>
            <div className="flex items-center gap-2">
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="h-7 gap-1 text-xs"
                onClick={() => {
                  setForm(emptyPatternForm);
                  setShowForm(false);
                }}
              >
                <X className="h-3 w-3" />
                {t('common.cancel', 'Cancel')}
              </Button>
              <Button
                type="button"
                size="sm"
                className="h-7 gap-1 text-xs"
                disabled={!canSave}
                onClick={() => void handleSavePattern()}
              >
                {upsertPattern.isPending ? (
                  <Loader2 className="h-3 w-3 animate-spin" />
                ) : (
                  <Save className="h-3 w-3" />
                )}
                {t('locations.receiptPatterns.save', 'Save pattern')}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

