import * as React from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useTranslation } from 'react-i18next';
import {
  Car,
  Wrench,
  Loader2,
  Save,
  RotateCcw,
  Sparkles,
  X,
  History,
} from 'lucide-react';
import {
  oilChangeFormSchema,
  type OilChangeFormValues,
} from '@/entities/oil-change/schemas';
import { useCars } from '@/entities/car/queries';
import { useDrivers } from '@/entities/driver/queries';
import type { Car as CarEntity } from '@/entities/car/schemas';
import type { Driver } from '@/entities/driver/schemas';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { SearchableSelect } from '@/shared/ui/searchable-select';
import { DatePicker } from '@/shared/ui/date-picker';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Skeleton } from '@/shared/ui/skeleton';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/shared/ui/form';
import { cn } from '@/shared/lib/cn';
import { today } from '@/shared/lib/format';
import { OilChangeStatusPreview } from './oil-change-status-preview';

export interface OilChangeFormInitialValues {
  car_id?: number;
  date?: string;
  driver_id?: number | null;
  driver_name?: string;
  supervisor?: string;
  odometer_at_change?: number | string;
  current_odometer?: number | string;
  mileage?: number | string;
  cost?: number | string;
}

interface OilChangeFormProps {
  mode: 'create' | 'edit';
  initialValues?: OilChangeFormInitialValues;
  submitting: boolean;
  onSubmit: (values: OilChangeFormValues) => void | Promise<void>;
  onCancel?: () => void;
  submitLabel?: React.ReactNode;
  showResetChanges?: boolean;
}

function getDefaults(initial?: OilChangeFormInitialValues): OilChangeFormValues {
  return {
    car_id: (initial?.car_id as number) ?? (undefined as unknown as number),
    date: initial?.date ?? today(),
    driver_id: initial?.driver_id ?? null,
    driver_name: initial?.driver_name ?? '',
    supervisor: initial?.supervisor ?? '',
    odometer_at_change:
      (initial?.odometer_at_change as number) ?? (undefined as unknown as number),
    current_odometer:
      initial?.current_odometer != null
        ? (initial.current_odometer as number)
        : undefined,
    mileage: (initial?.mileage as number) ?? (undefined as unknown as number),
    cost: (initial?.cost as number) ?? (undefined as unknown as number),
  };
}

/**
 * Shared create + edit form for oil-change records.
 *
 * Re-structured to match the fuel-event-form architecture. Fields are grouped
 * into logical cards with consistent grid layouts and standard controlled-input
 * patterns.
 */
export function OilChangeForm({
  mode,
  initialValues,
  submitting,
  onSubmit,
  onCancel,
  submitLabel,
  showResetChanges = false,
}: OilChangeFormProps) {
  const { t } = useTranslation();
  const { data: cars = [], isLoading: carsLoading } = useCars();
  const { data: drivers = [], isLoading: driversLoading } = useDrivers();

  const form = useForm<OilChangeFormValues>({
    resolver: zodResolver(oilChangeFormSchema),
    defaultValues: getDefaults(initialValues),
    mode: 'onTouched',
  });

  const [driverAutoAssigned, setDriverAutoAssigned] = React.useState(false);

  React.useEffect(() => {
    if (initialValues) {
      const defaults = getDefaults(initialValues);
      if (defaults.driver_id == null && defaults.driver_name && drivers.length > 0) {
        const match = drivers.find(d => d.name === defaults.driver_name);
        if (match) defaults.driver_id = match.ID;
      }
      form.reset(defaults);
      setDriverAutoAssigned(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    initialValues?.car_id,
    initialValues?.driver_name,
    initialValues?.date,
    initialValues?.supervisor,
    drivers.length
  ]);

  const carOptions = React.useMemo(
    () => cars.map((c) => ({ value: c.ID, label: c.car_no_plate })),
    [cars],
  );
  const driverOptions = React.useMemo(
    () =>
      drivers.map((d) => ({
        value: d.ID,
        label: d.name,
        description: d.mobile_number || undefined,
      })),
    [drivers],
  );

  // Auto-fill driver on car change. Same architecture as fuel-event-form.
  const watchedCarId = form.watch('car_id');
  const previousCarIdRef = React.useRef<number | undefined>(initialValues?.car_id);

  React.useEffect(() => {
    if (!watchedCarId || watchedCarId === previousCarIdRef.current) return;
    previousCarIdRef.current = watchedCarId;

    const selectedCar: CarEntity | undefined = cars.find((c) => c.ID === watchedCarId);
    if (!selectedCar) return;

    const assignedDriver: Driver | undefined =
      selectedCar.driver_id && selectedCar.driver_id !== 0
        ? drivers.find((d) => d.ID === selectedCar.driver_id)
        : undefined;

    if (assignedDriver) {
      form.setValue('driver_id', assignedDriver.ID);
      form.setValue('driver_name', assignedDriver.name, { shouldValidate: true });
      setDriverAutoAssigned(true);
    } else {
      form.setValue('driver_id', null);
      form.setValue('driver_name', '');
      setDriverAutoAssigned(false);
    }
  }, [watchedCarId, cars, drivers, form]);

  // Watched values for the live status preview
  const mileage = form.watch('mileage');
  const odometerAtChange = form.watch('odometer_at_change');
  const currentOdometer = form.watch('current_odometer');

  const loading = carsLoading || driversLoading;
  if (loading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-40 w-full" />
        <Skeleton className="h-40 w-full" />
        <Skeleton className="h-56 w-full" />
      </div>
    );
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        {/* Vehicle & Personnel */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-base">
              <Car className="h-4 w-4 text-muted-foreground" />
              {t('oilChanges.form.sections.vehicle')} &amp; {t('oilChanges.form.sections.personnel')}
            </CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <FormField
              control={form.control}
              name="car_id"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('oilChanges.fields.carPlate')}</FormLabel>
                  <FormControl>
                    <SearchableSelect
                      options={carOptions}
                      value={field.value}
                      onChange={(v) => field.onChange(v as number)}
                      placeholder={t('oilChanges.fields.selectCar')}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="driver_id"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('oilChanges.fields.driver')}</FormLabel>
                  <FormControl>
                    <SearchableSelect
                      options={driverOptions}
                      value={field.value}
                      onChange={(v) => {
                        field.onChange(v);
                        const d = drivers.find((drv) => drv.ID === Number(v));
                        if (d) {
                          form.setValue('driver_name', d.name);
                        } else {
                          form.setValue('driver_name', '');
                        }
                        setDriverAutoAssigned(false);
                      }}
                      placeholder={t('oilChanges.fields.selectDriver')}
                      className={cn(driverAutoAssigned && 'border-primary/40')}
                    />
                  </FormControl>
                  {driverAutoAssigned && !form.formState.errors.driver_name && (
                    <div className="absolute bottom-0 left-0 right-0 flex items-center gap-1.5 text-xs text-primary">
                      <Sparkles className="h-3 w-3 shrink-0" />
                      <span className="truncate">
                        {t('oilChanges.fields.driverAutoAssigned')}
                      </span>
                      <button
                        type="button"
                        onClick={() => {
                          form.setValue('driver_id', null);
                          form.setValue('driver_name', '', { shouldValidate: true });
                          setDriverAutoAssigned(false);
                        }}
                        className="ms-auto inline-flex shrink-0 items-center gap-0.5 rounded px-1 py-0.5 text-muted-foreground hover:bg-muted hover:text-foreground"
                      >
                        <X className="h-3 w-3" />
                        <span>{t('common.clear')}</span>
                      </button>
                    </div>
                  )}
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Maintenance Info */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-base">
              <History className="h-4 w-4 text-muted-foreground" />
              {t('oilChanges.title')}
            </CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <FormField
              control={form.control}
              name="date"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('oilChanges.fields.date')}</FormLabel>
                  <FormControl>
                    <DatePicker
                      value={field.value}
                      onChange={field.onChange}
                      max={today()}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="supervisor"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('oilChanges.fields.supervisor')}</FormLabel>
                  <FormControl>
                    <Input
                      type="text"
                      placeholder={t('oilChanges.fields.supervisorPlaceholder')}
                      {...field}
                      value={field.value ?? ''}
                      onChange={(e) => field.onChange(e.target.value)}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Maintenance Details */}
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-base">
              <Wrench className="h-4 w-4 text-muted-foreground" />
              {t('oilChanges.form.sections.maintenance')}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <FormField
                control={form.control}
                name="odometer_at_change"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('oilChanges.fields.odometerAtChange')}</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        inputMode="numeric"
                        placeholder="0"
                        {...field}
                        value={field.value ?? ''}
                        onChange={(e) =>
                          field.onChange(
                            e.target.value === '' ? undefined : e.target.value,
                          )
                        }
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {mode === 'edit' ? (
                <FormField
                  control={form.control}
                  name="current_odometer"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>{t('oilChanges.fields.currentOdometer')}</FormLabel>
                      <FormControl>
                        <Input
                          type="number"
                          inputMode="numeric"
                          placeholder="0"
                          {...field}
                          value={field.value ?? ''}
                          onChange={(e) =>
                            field.onChange(
                              e.target.value === '' ? undefined : e.target.value,
                            )
                          }
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              ) : (
                /* Empty space in grid for create mode to keep layout balanced */
                <div className="hidden sm:block" />
              )}

              <FormField
                control={form.control}
                name="mileage"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('oilChanges.fields.mileage')}</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        inputMode="numeric"
                        placeholder="0"
                        {...field}
                        value={field.value ?? ''}
                        onChange={(e) =>
                          field.onChange(
                            e.target.value === '' ? undefined : e.target.value,
                          )
                        }
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="cost"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('oilChanges.fields.cost')}</FormLabel>
                    <FormControl>
                      <div className="relative">
                        <Input
                          type="number"
                          step="0.01"
                          inputMode="decimal"
                          placeholder="0.00"
                          className="pe-12"
                          {...field}
                          value={field.value ?? ''}
                          onChange={(e) =>
                            field.onChange(
                              e.target.value === '' ? undefined : e.target.value,
                            )
                          }
                        />
                        <span className="pointer-events-none absolute end-3 top-1/2 -translate-y-1/2 text-[10px] font-bold text-muted-foreground">
                          EGP
                        </span>
                      </div>
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <div className="pt-2">
              <OilChangeStatusPreview
                mileage={Number(mileage) || 0}
                odometerAtChange={Number(odometerAtChange) || 0}
                currentOdometer={
                  currentOdometer != null ? Number(currentOdometer) : undefined
                }
              />
            </div>
          </CardContent>
        </Card>

        {/* Actions */}
        <div className="sticky bottom-0 -mx-4 flex flex-col gap-2 border-t bg-background/90 p-4 backdrop-blur supports-[backdrop-filter]:bg-background/70 md:-mx-6 md:flex-row md:justify-end md:gap-3 md:px-6">
          {showResetChanges && form.formState.isDirty && (
            <Button
              type="button"
              variant="outline"
              onClick={() => form.reset()}
              disabled={submitting}
              className="md:me-auto"
            >
              <RotateCcw className="h-4 w-4" />
              {t('common.reset')}
            </Button>
          )}
          {onCancel && (
            <Button type="button" variant="outline" onClick={onCancel} disabled={submitting}>
              {t('common.cancel')}
            </Button>
          )}
          <Button
            type="submit"
            disabled={submitting || (mode === 'edit' && !form.formState.isDirty)}
          >
            {submitting ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Save className="h-4 w-4" />
            )}
            {submitLabel ?? t('common.save')}
          </Button>
        </div>
      </form>
    </Form>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Search, CheckCircle2, AlertTriangle, AlertCircle, LayoutGrid } from 'lucide-react';
import { Input } from '@/shared/ui/input';
import { cn } from '@/shared/lib/cn';
import type { OilChangeStatus } from '@/entities/oil-change/schemas';

export type StatusFilterValue = 'all' | OilChangeStatus;

interface OilChangesFiltersProps {
  search: string;
  onSearchChange: (value: string) => void;
  statusFilter: StatusFilterValue;
  onStatusFilterChange: (value: StatusFilterValue) => void;
  /** Counts shown as small badges on each tab */
  counts: { all: number; good: number; warning: number; critical: number };
}

/**
 * Search bar plus segmented status control. The control mirrors the
 * `MethodControl` pattern from the fuel-events page so both modules feel
 * the same when toggling filters.
 */
export function OilChangesFilters({
  search,
  onSearchChange,
  statusFilter,
  onStatusFilterChange,
  counts,
}: OilChangesFiltersProps) {
  const { t } = useTranslation();

  return (
    <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
      <div className="relative max-w-sm flex-1">
        <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
          placeholder={t('oilChanges.searchPlaceholder')}
          className="ps-9"
        />
      </div>

      <div
        className="inline-flex h-9 items-center gap-0.5 rounded-md border bg-muted/40 p-0.5"
        role="tablist"
        aria-label={t('oilChanges.filters.byStatus')}
      >
        <FilterTab
          active={statusFilter === 'all'}
          onClick={() => onStatusFilterChange('all')}
          icon={<LayoutGrid className="h-3.5 w-3.5" />}
          label={t('oilChanges.filters.all')}
          count={counts.all}
        />
        <FilterTab
          active={statusFilter === 'good'}
          onClick={() => onStatusFilterChange('good')}
          icon={<CheckCircle2 className="h-3.5 w-3.5 text-success" />}
          label={t('oilChanges.status.good')}
          count={counts.good}
          disabled={counts.good === 0}
        />
        <FilterTab
          active={statusFilter === 'warning'}
          onClick={() => onStatusFilterChange('warning')}
          icon={<AlertTriangle className="h-3.5 w-3.5 text-warning" />}
          label={t('oilChanges.status.warning')}
          count={counts.warning}
          disabled={counts.warning === 0}
        />
        <FilterTab
          active={statusFilter === 'critical'}
          onClick={() => onStatusFilterChange('critical')}
          icon={<AlertCircle className="h-3.5 w-3.5 text-destructive" />}
          label={t('oilChanges.status.critical')}
          count={counts.critical}
          disabled={counts.critical === 0}
        />
      </div>
    </div>
  );
}

function FilterTab({
  active,
  disabled,
  onClick,
  icon,
  label,
  count,
}: {
  active: boolean;
  disabled?: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
  count: number;
}) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={active}
      disabled={disabled}
      onClick={onClick}
      className={cn(
        'inline-flex h-7 items-center gap-1.5 rounded px-2.5 text-xs font-medium transition-colors',
        active
          ? 'bg-background text-foreground shadow-sm'
          : 'text-muted-foreground hover:text-foreground',
        disabled && 'cursor-not-allowed opacity-40 hover:text-muted-foreground',
      )}
    >
      {icon}
      <span className="hidden sm:inline">{label}</span>
      <span
        className={cn(
          'rounded-full px-1 text-[10px] font-semibold tabular-nums',
          active ? 'bg-muted text-foreground' : 'bg-background text-muted-foreground',
        )}
      >
        {count}
      </span>
    </button>
  );
}

import * as React from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { intentProps, preloadChunk, warmOilForm } from '@/shared/lib/prefetch';
import { prefetchOilChange } from '@/entities/oil-change/queries';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Calendar,
  Car as CarIcon,
  Edit,
  History,
  Trash2,
  Clock,
} from 'lucide-react';
import type { ColumnDef } from '@tanstack/react-table';
import { DataTable } from '@/shared/ui/data-table';
import { Button } from '@/shared/ui/button';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/shared/ui/tooltip';
import { cn } from '@/shared/lib/cn';
import { format, formatDateTime, formatCurrency } from '@/shared/lib/format';
import { formatNumber } from '@/shared/lib/format-number';
import type { OilChangeView } from '@/entities/oil-change/schemas';
import { OilChangeStatusBadge } from './oil-change-status-badge';

interface OilChangesTableProps {
  rows: OilChangeView[];
  loading?: boolean;
  /** Called when the user clicks the "View history" action on a row */
  onViewHistory?: (carNoPlate: string) => void;
  /** Called when the user clicks the delete action on a row */
  onDelete?: (row: OilChangeView) => void;
  /**
   * Empty-state node rendered inside the table when there are no rows.
   * The page passes an action-rich placeholder here.
   */
  emptyState?: React.ReactNode;
}

/**
 * Fleet status board — one row per vehicle showing the latest oil-change
 * record. Sorting is handled by the underlying `DataTable`; the footer
 * row sums every numeric column the data has.
 *
 * Row click navigates to the per-car history view; per-row buttons
 * (edit / delete) live in a sticky end-aligned actions cell so they don't
 * compete with the click target.
 */
export function OilChangesTable({
  rows,
  loading,
  onViewHistory,
  onDelete,
  emptyState,
}: OilChangesTableProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const navigate = useNavigate();

  const columns = React.useMemo<ColumnDef<OilChangeView>[]>(
    () => [
      {
        accessorKey: 'car_no_plate',
        header: t('oilChanges.fields.carPlate'),
        cell: ({ row }) => (
          <div className="flex items-center gap-2 font-medium">
            <CarIcon className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            {row.original.car_no_plate}
          </div>
        ),
      },
      {
        accessorKey: 'date',
        header: t('oilChanges.fields.date'),
        cell: ({ row }) => (
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Calendar className="h-3.5 w-3.5 shrink-0" />
            {format(row.original.date, 'dd MMM yyyy')}
          </div>
        ),
      },
      {
        accessorKey: 'super_visor',
        header: t('oilChanges.fields.supervisor'),
        cell: ({ row }) => (
          <span className="text-sm">{row.original.super_visor || '—'}</span>
        ),
      },
      {
        accessorKey: 'driver_name',
        header: t('oilChanges.fields.driver'),
        cell: ({ row }) => (
          <span className="text-sm">{row.original.driver_name || '—'}</span>
        ),
      },
      {
        accessorKey: 'current_odometer',
        header: t('oilChanges.fields.currentOdometer'),
        cell: ({ row }) => (
          <span className="font-mono text-sm tabular-nums">
            {formatNumber(row.original.current_odometer, 0)} km
          </span>
        ),
        meta: { align: 'end' },
      },
      {
        accessorKey: 'kmRemaining',
        header: t('oilChanges.fields.kmRemaining'),
        cell: ({ row }) => (
          <OilChangeStatusBadge
            kmRemaining={row.original.kmRemaining}
            showValue
          />
        ),
      },
      {
        accessorKey: 'cost',
        header: t('oilChanges.fields.cost'),
        cell: ({ row }) => (
          <span className="font-semibold tabular-nums">
            {formatCurrency(row.original.cost)}
          </span>
        ),
        meta: { align: 'end' },
      },
      {
        accessorKey: 'lastUpdated',
        header: t('oilChanges.fields.lastUpdated'),
        cell: ({ row }) =>
          row.original.lastUpdated ? (
            <div className="flex items-center gap-2 text-xs text-muted-foreground">
              <Clock className="h-3 w-3 shrink-0" />
              {formatDateTime(row.original.lastUpdated)}
            </div>
          ) : (
            <span className="text-xs text-muted-foreground">—</span>
          ),
      },
      {
        id: 'actions',
        header: () => <span className="sr-only">{t('common.actions')}</span>,
        enableSorting: false,
        cell: ({ row }) => (
          <div
            className="flex items-center justify-end gap-1"
            // Stop bubbling so the row's onRowClick doesn't fire when you
            // hit one of the action buttons.
            onClick={(e) => e.stopPropagation()}
          >
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8"
                  onClick={() => onViewHistory?.(row.original.car_no_plate)}
                  aria-label={t('oilChanges.actions.viewHistory')}
                >
                  <History className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{t('oilChanges.actions.viewHistory')}</TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8"
                  onClick={() => navigate(`/oil-changes/${row.original.ID}/edit`)}
                  {...intentProps(() => {
                    warmOilForm(queryClient, 'oil-change-edit');
                    prefetchOilChange(queryClient, row.original.ID);
                  })}
                  aria-label={t('common.edit')}
                >
                  <Edit className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{t('common.edit')}</TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className={cn('h-8 w-8 text-destructive hover:text-destructive')}
                  onClick={() => onDelete?.(row.original)}
                  aria-label={t('common.delete')}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{t('common.delete')}</TooltipContent>
            </Tooltip>
          </div>
        ),
        meta: { align: 'end' },
      },
    ],
    [t, navigate, onDelete, onViewHistory],
  );

  return (
    <DataTable
      columns={columns}
      data={rows}
      loading={loading}
      emptyState={emptyState}
      onRowClick={(row) => onViewHistory?.(row.car_no_plate)}
      onRowIntent={() => preloadChunk('oil-change-history')}
      footer={(data) => {
        // Footer cells must align 1:1 with the columns array above. The
        // tally line skips columns that don't reduce sensibly (text,
        // status badges, action buttons).
        const totalCost = data.reduce((s, r) => s + r.cost, 0);
        const avgKmRemaining =
          data.length > 0
            ? data.reduce((s, r) => s + r.kmRemaining, 0) / data.length
            : 0;
        return [
          // car_no_plate
          <span className="text-xs uppercase tracking-wider text-muted-foreground">
            {t('oilChanges.fields.totals')}
          </span>,
          // date
          '',
          // supervisor
          '',
          // driver
          '',
          // current_odometer
          '',
          // kmRemaining (avg)
          <span className="text-xs text-muted-foreground">
            {t('oilChanges.fields.avgRemaining')}:{' '}
            <span className="font-semibold text-foreground">
              {formatNumber(avgKmRemaining, 0)} km
            </span>
          </span>,
          // cost (sum)
          <span className="font-semibold tabular-nums">
            {formatCurrency(totalCost)}
          </span>,
          // lastUpdated
          '',
          // actions
          '',
        ];
      }}
    />
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Building2, SlidersHorizontal } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from '@/shared/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { useCompanies } from '@/entities/mapping/queries';
import { SCOPE_PRESETS, useScope, useScopeCompany, type ScopePreset } from '@/shared/scope';
import { ScopeDatePicker, type PeriodPreset } from './scope-date-picker';

/* -------------------------------------------------------------------------- */
/* The global scope bar — Madar's layout exactly, with COMPANIES where Madar   */
/* has branches: [company select] [period picker]. Desktop renders it inline   */
/* in the header; mobile collapses to one filters button with the same         */
/* controls stacked in a popover.                                              */
/* -------------------------------------------------------------------------- */

const ALL_COMPANIES = '__all__';

const presetFallback: Record<ScopePreset | 'custom', string> = {
  today: 'Today',
  yesterday: 'Yesterday',
  '7d': 'Last 7 days',
  '30d': 'Last 30 days',
  mtd: 'Month to date',
  custom: 'Custom',
};

function ScopeControls({ className }: { className?: string }) {
  const { t } = useTranslation();
  const { scope, range, setPreset, setCustom } = useScope();
  const { company, setCompany } = useScopeCompany();

  const companies = useCompanies();
  const companyNames = companies.data?.data ?? [];

  // Self-heal a stale company: one carried in a shared link but since renamed
  // or removed would silently filter everything to zero.
  React.useEffect(() => {
    if (!companies.isSuccess || companyNames.length === 0) return;
    if (company && !companyNames.includes(company)) setCompany(null);
  }, [companies.isSuccess, company, companyNames, setCompany]);

  const presetOptions: PeriodPreset[] = React.useMemo(
    () =>
      SCOPE_PRESETS.map((p) => ({
        value: p,
        label: t(`scope.preset.${p}`, presetFallback[p]),
      })),
    [t],
  );

  return (
    <div className={className}>
      <Select
        value={company ?? ALL_COMPANIES}
        onValueChange={(v) => setCompany(v === ALL_COMPANIES ? null : v)}
      >
        <SelectTrigger className="h-8 w-auto min-w-32 gap-2" data-slot="select-trigger">
          <Building2 className="h-4 w-4 text-muted-foreground" />
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value={ALL_COMPANIES}>
            {t('scope.allCompanies', 'All companies')}
          </SelectItem>
          {companyNames.map((c) => (
            <SelectItem key={c} value={c}>
              {c}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <ScopeDatePicker
        preset={scope.preset}
        from={range.from}
        to={range.to}
        presets={presetOptions}
        onSelectPreset={(key) => setPreset(key as ScopePreset)}
        onApplyCustom={(f, to) => setCustom(f, to)}
      />
    </div>
  );
}

/** Inline scope controls for the desktop header. */
export function ScopeBar() {
  return <ScopeControls className="hidden items-center gap-2 lg:flex" />;
}

/** Compact popover with the same controls — for the mobile header. */
export function ScopeBarMobile({ className }: { className?: string }) {
  const { t } = useTranslation();
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="icon"
          className={cn('h-8 w-8 lg:hidden', className)}
          aria-label={t('common.filters', 'Filters')}
        >
          <SlidersHorizontal className="h-4 w-4" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-60">
        <ScopeControls className="flex flex-col gap-2 [&_[data-slot=select-trigger]]:w-full" />
      </PopoverContent>
    </Popover>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Calendar as CalendarIcon } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from '@/shared/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { CAIRO_TZ } from '@/shared/lib/cairo';
import {
  CairoRangeCalendar,
  cairoTodayParts,
  dayIso,
  partsOfDay,
  toNum,
  tzDate,
  type DayParts,
} from '@/shared/ui/cairo-range-calendar';

/* -------------------------------------------------------------------------- */
/* Madar's period picker, ported verbatim: quick preset pills + a Cairo-aware  */
/* two-tap range calendar (live hover preview, future-date guard, explicit     */
/* Apply) in ONE popover — no Select→Popover handoff, so choosing "custom"     */
/* never bounces the popover closed.                                           */
/* -------------------------------------------------------------------------- */

export interface PeriodPreset {
  value: string;
  label: string;
}

interface Props {
  /** Active preset key, or 'custom' when a hand-picked range is in effect. */
  preset: string;
  from?: string | null;
  to?: string | null;
  presets: PeriodPreset[];
  onSelectPreset: (key: string) => void;
  /** Day-bounded Cairo YYYY-MM-DD strings. */
  onApplyCustom: (from: string, to: string) => void;
  align?: 'start' | 'center' | 'end';
  triggerClassName?: string;
}

export function ScopeDatePicker({
  preset,
  from,
  to,
  presets,
  onSelectPreset,
  onApplyCustom,
  align = 'end',
  triggerClassName,
}: Props) {
  const { t, i18n } = useTranslation();
  const locale = i18n.language.startsWith('ar') ? 'ar-EG' : 'en-GB';
  const [open, setOpen] = React.useState(false);

  const [hovered, setHovered] = React.useState<DayParts | undefined>();
  const [selected, setSelected] = React.useState<{ from?: DayParts; to?: DayParts }>({});

  const today = cairoTodayParts();
  const [month, setMonth] = React.useState(today.m);
  const [year, setYear] = React.useState(today.y);

  const fmtDay = React.useCallback(
    (p: DayParts) =>
      new Intl.DateTimeFormat(locale, {
        day: 'numeric',
        month: 'short',
        timeZone: CAIRO_TZ,
      }).format(tzDate(p.y, p.m, p.d)),
    [locale],
  );

  // Seed the working selection + visible month from props whenever opened.
  React.useEffect(() => {
    if (!open) return;
    const f = from ? partsOfDay(from) : undefined;
    const tp = to ? partsOfDay(to) : undefined;
    setSelected({ from: f, to: tp });
    setHovered(undefined);
    const anchor = f ?? today;
    setMonth(anchor.m);
    setYear(anchor.y);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const pickPreset = (key: string) => {
    onSelectPreset(key);
    setOpen(false);
  };

  const handleSelect = (p: DayParts) => {
    if (!selected.from || (selected.from && selected.to)) {
      setSelected({ from: p, to: undefined });
    } else {
      const f = toNum(selected.from)!;
      const c = toNum(p)!;
      if (c >= f) setSelected({ from: selected.from, to: p });
      else setSelected({ from: p, to: selected.from });
    }
  };

  const handleApply = () => {
    if (!selected.from) return;
    const f = selected.from;
    const end = selected.to ?? selected.from;
    onApplyCustom(dayIso(f), dayIso(end));
    setOpen(false);
  };

  const activeLabel =
    preset !== 'custom'
      ? (presets.find((p) => p.value === preset)?.label ?? t('scope.preset.custom', 'Custom'))
      : from && to
        ? `${fmtDay(partsOfDay(from))} → ${fmtDay(partsOfDay(to))}`
        : t('scope.preset.custom', 'Custom');

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm" className={cn('h-8 gap-2', triggerClassName)}>
          <CalendarIcon className="h-4 w-4 text-muted-foreground" />
          <span className="truncate">{activeLabel}</span>
        </Button>
      </PopoverTrigger>
      <PopoverContent align={align} className="w-auto max-w-[min(20rem,calc(100vw-2rem))]">
        {/* Quick presets */}
        <div className="mb-3 flex flex-wrap gap-1.5">
          {presets.map((p) => (
            <Button
              key={p.value}
              variant={preset === p.value ? 'default' : 'outline'}
              size="sm"
              className="h-7 text-xs"
              onClick={() => pickPreset(p.value)}
            >
              {p.label}
            </Button>
          ))}
        </div>

        <div className="mb-3 border-t" />

        {/* From / To summary */}
        <div className="mb-3 flex items-center gap-3 rounded-lg bg-muted p-2.5 text-xs">
          <div className="flex-1 text-center">
            <p className="mb-0.5 text-muted-foreground">{t('common.from', 'From')}</p>
            <p className="font-semibold">{selected.from ? fmtDay(selected.from) : '—'}</p>
          </div>
          <div className="h-6 w-px bg-border" />
          <div className="flex-1 text-center">
            <p className="mb-0.5 text-muted-foreground">{t('common.to', 'To')}</p>
            <p className="font-semibold">
              {selected.to ? fmtDay(selected.to) : hovered ? fmtDay(hovered) : '—'}
            </p>
          </div>
        </div>

        <CairoRangeCalendar
          selected={selected}
          onSelect={handleSelect}
          hovered={hovered}
          onHover={setHovered}
          month={month}
          year={year}
          onMonthChange={(m2, y2) => {
            setMonth(m2);
            setYear(y2);
          }}
        />

        <div className="mt-3 flex justify-end gap-2 border-t pt-3">
          <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => setOpen(false)}>
            {t('common.cancel', 'Cancel')}
          </Button>
          <Button
            size="sm"
            className="h-7 text-xs"
            disabled={!selected.from}
            onClick={handleApply}
          >
            {t('common.apply', 'Apply')}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

