  Sparkles,
  Search,
  CheckCircle2,
  AlertCircle,
  Info,
  TrendingUp,
} from 'lucide-react';
import { useLocation } from 'react-router-dom';
import type { ServiceInvoice } from '@/entities/service-invoice/schemas';
