interface SidebarProps {
  collapsed: boolean;
  onToggleCollapse: () => void;
  onNavigate?: () => void;
  className?: string;
}

export function Sidebar({ collapsed, onToggleCollapse, onNavigate, className }: SidebarProps) {
  // Intent prefetch (the Madar pattern): hovering or focusing a nav link warms
  // the destination's code chunk — and, where the mount-time query key is
  // exactly known, its data too — so the click lands on a page that is already
  // downloaded. Deduped, so repeat hovers are free.
  const queryClient = useQueryClient();
  const { t } = useTranslation();
  const { pathname } = useLocation();
  const { atLeast } = usePermissions();

  const visibleSections = React.useMemo(
    () =>
      NAV_SECTIONS.map((section) => ({
        ...section,
        items: section.items.filter(
          (item) => !item.minPermission || atLeast(item.minPermission as 1 | 2 | 3 | 4),
        ),
      })).filter((section) => section.items.length > 0),
    [atLeast],
  );

  return (
    <aside
      data-collapsed={collapsed}
      className={cn(
        'group/sidebar flex h-full shrink-0 flex-col border-e bg-card transition-[width] duration-200 ease-out print:hidden',
        collapsed ? 'w-[72px]' : 'w-64',
        className,
      )}
    >
      {/* Brand */}
      <div
        className={cn(
          'flex h-16 shrink-0 items-center gap-2 border-b transition-all duration-200 ease-out',
          collapsed ? 'justify-center px-2' : 'px-4 gap-3',
        )}
      >
        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-primary text-primary-foreground transition-all duration-200">
          <Truck className="h-4 w-4" />
        </div>
        <div
          className={cn(
            'min-w-0 flex-grow transition-all duration-200 ease-out overflow-hidden origin-left',
            collapsed ? 'max-w-0 opacity-0 pointer-events-none invisible' : 'max-w-40 opacity-100 ml-2'
          )}
        >
          <p className="truncate text-sm font-semibold leading-tight">{t('common.appName')}</p>
          <p className="truncate text-xs text-muted-foreground">{t('common.tagline')}</p>
        </div>
      </div>

      {/* Nav */}
      <ScrollArea className="flex-1">
        <nav className="flex flex-col gap-4 p-3">
          {visibleSections.map((section) => (
            <div key={section.titleKey} className="space-y-1">
              <h3 className={cn(
                "px-2 pt-2 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground transition-all duration-200 ease-out overflow-hidden origin-left",
                collapsed ? "max-h-0 opacity-0 my-0 py-0" : "max-h-8 opacity-100",
              )}>
                {t(section.titleKey)}
              </h3>
              <div className={cn(
                "mx-2 transition-all duration-200 ease-out",
                collapsed && section !== visibleSections[0] ? "my-2 border-t opacity-100" : "my-0 border-t-0 h-0 opacity-0 pointer-events-none"
              )} />
              <ul className="space-y-0.5">
                {section.items.map((item) => {
                  const active = pathname === item.to || pathname.startsWith(item.to + '/');
                  const Icon = item.icon;
                  return (
                    <li key={item.to}>
                      <NavLink
                        // Carry the global date scope across navigation, so
                        // the page you land on reads the range you were in.
                        to={{ pathname: item.to, search: keepScopeSearch(item.to) }}
                        onClick={onNavigate}
                        onPointerEnter={() => prefetchRoute(item.to, queryClient)}
                        onFocus={() => prefetchRoute(item.to, queryClient)}
                        onTouchStart={() => prefetchRoute(item.to, queryClient)}
                        className={cn(
                          'flex items-center rounded-md text-sm font-medium transition-all duration-200 ease-out',
                          active
                            ? 'bg-primary/10 text-primary'
                            : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground',
                          collapsed ? 'h-9 w-9 mx-auto justify-center px-0 gap-0' : 'h-9 px-3 gap-3 w-full',
                        )}
                        title={collapsed ? t(item.labelKey) : undefined}
                      >
                        <Icon className="h-4 w-4 shrink-0 transition-transform duration-200" />
                        <span className={cn(
                          'truncate transition-all duration-200 ease-out origin-left',
                          collapsed ? 'max-w-0 opacity-0 pointer-events-none invisible' : 'max-w-40 opacity-100',
                        )}>
                          {t(item.labelKey)}
                        </span>
                      </NavLink>
                    </li>
                  );
                })}
              </ul>
            </div>
          ))}
        </nav>
      </ScrollArea>

      {/* Footer — always locked to the bottom because the aside has bounded height */}
      <div className="shrink-0 border-t p-2">
        <div className="space-y-2">
          {/* User Menu */}
          <UserMenu collapsed={collapsed} />

          {/* Controls (ThemeToggle, LanguageToggle, and Collapse/Expand Button) */}
          <div className={cn(
            "flex items-center transition-all duration-200 ease-out",
            collapsed ? "flex-col gap-2 pt-1" : "justify-between px-1"
          )}>
            <div className={cn("flex gap-1", collapsed ? "flex-col" : "items-center")}>
              <ThemeToggle />
              <LanguageToggle />
            </div>
            {/* Below md this was `hidden`, and SheetContent is rendered with
                hideCloseButton — so on a phone the drawer had no close control
                at all. It is shown at every width now; in the drawer the same
                handler closes it, which is what the chevron means there. */}
            <Button
              variant="ghost"
              size="icon"
              onClick={onToggleCollapse}
              className="h-8 w-8 shrink-0 transition-transform duration-200"
              aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            >
              <ChevronLeft
                className={cn(
                  'h-4 w-4 transition-transform duration-200',
                  collapsed ? 'rotate-180 rtl:rotate-0' : 'rtl:rotate-180',
                )}
              />
            </Button>
          </div>
        </div>
      </div>
    </aside>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { AlertTriangle } from 'lucide-react';
import { toast } from '@/shared/ui/toaster';
import { SearchableSelect } from '@/shared/ui/searchable-select';
import { ConfirmDialog } from '@/shared/ui/confirm-dialog';
import { normalize } from '@/shared/lib/normalize';
import { useResolveTerminal, useTerminals } from '@/entities/location/queries';
import type { Terminal } from '@/entities/location/schemas';
import type { SelectOption } from '@/shared/types';

interface TerminalSelectProps {
  id?: string;
  /** Options are the terminals allowed for this company. */
  company: string;
  /** Selected terminal id — the canonical value the caller stores. */
  terminalId: number | null;
  /**
   * Legacy free-text terminal name (from existing records / URL params).
   * When `terminalId` is unset, a case/diacritic-insensitive match against
   * the company's terminals auto-selects; an unmatched name shows a hint
   * prompting the user to pick or create.
   */
  terminalName?: string;
  onSelect: (terminal: Terminal) => void;
  disabled?: boolean;
  placeholder?: string;
  /** Extra hint shown under the field when the legacy name is unresolved. */
  className?: string;
}

/**
 * Company-filtered terminal combobox backed by `GET /api/terminals?company=X`.
 *
 * Terminals are picked-by-id entities now (free-text + aliases are gone). If
 * the typed text matches no option, a create affordance offers
 * `POST /api/terminals` — resolve-or-create-or-extend — behind a confirmation
 * dialog, then selects the resulting terminal.
 */
export function TerminalSelect({
  id,
  company,
  terminalId,
  terminalName,
  onSelect,
  disabled,
  placeholder,
  className,
}: TerminalSelectProps) {
  const { t } = useTranslation();
  const trimmedCompany = company.trim();

  const { data: terminals = [], isSuccess } = useTerminals(trimmedCompany, {
    enabled: !!trimmedCompany,
  });

  const resolveTerminal = useResolveTerminal();
  const [pendingName, setPendingName] = React.useState<string | null>(null);

  const options = React.useMemo<SelectOption<number>[]>(
    () =>
      terminals.map((terminal) => ({
        value: terminal.ID,
        label: terminal.name,
        description: terminal.address ?? undefined,
      })),
    [terminals],
  );

  /* ---- Resolve legacy free-text names to ids once options arrive -------- */

  const legacyName = terminalName?.trim() ?? '';
  React.useEffect(() => {
    if (terminalId != null || !legacyName || !isSuccess) return;
    const match = terminals.find((term) => normalize(term.name) === normalize(legacyName));
    if (match) onSelect(match);
    // `onSelect` is intentionally omitted — parents pass inline closures and
    // the effect must not re-fire on every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [terminalId, legacyName, isSuccess, terminals]);

  const unresolved = terminalId == null && !!legacyName && isSuccess;

  /* ---- Create / extend flow --------------------------------------------- */

  const handleConfirmCreate = async () => {
    if (!pendingName || !trimmedCompany) return;
    try {
      const result = await resolveTerminal.mutateAsync({
        name: pendingName,
        company: trimmedCompany,
      });
      toast.success(
        result.created
          ? t('terminalSelect.toastCreated', 'Terminal created')
          : t('terminalSelect.toastExtended', {
              name: result.terminal.name,
              company: trimmedCompany,
              defaultValue: "Terminal '{{name}}' allowed for {{company}}",
            }),
      );
      setPendingName(null);
      onSelect(result.terminal);
    } catch {
      // Error toast handled by the mutation
    }
  };

  return (
    <div className={className}>
      <SearchableSelect<number>
        id={id}
        options={options}
        value={terminalId}
        onChange={(v) => {
          const terminal = terminals.find((term) => term.ID === Number(v));
          if (terminal) onSelect(terminal);
        }}
        disabled={disabled || !trimmedCompany}
        placeholder={placeholder}
        onCreate={(text) => setPendingName(text)}
        createLabel={(text) =>
          t('terminalSelect.createOption', {
            name: text,
            defaultValue: "Create terminal '{{name}}'",
          })
        }
      />
      {unresolved && (
        <p className="mt-1 flex items-start gap-1.5 text-[11px] font-medium text-warning">
          <AlertTriangle className="mt-0.5 h-3 w-3 shrink-0" />
          <span dir="auto">
            {t('terminalSelect.unresolved', {
              name: legacyName,
              company: trimmedCompany,
              defaultValue:
                "'{{name}}' is not in {{company}}'s allowed terminals — pick one or create it.",
            })}
          </span>
        </p>
      )}

      <ConfirmDialog
        open={pendingName !== null}
        onOpenChange={(open) => {
          if (!open) setPendingName(null);
        }}
        variant="default"
        lottieSrc="/animations/warning.lottie"
        title={t('terminalSelect.confirmTitle', 'Create terminal?')}
        description={t('terminalSelect.confirmBody', {
          name: pendingName ?? '',
          company: trimmedCompany,
          defaultValue:
            "This will create a new terminal '{{name}}' — or allow an existing one with this name — for {{company}}.",
        })}
        confirmLabel={t('terminalSelect.confirmAction', 'Create terminal')}
        loading={resolveTerminal.isPending}
        onConfirm={handleConfirmCreate}
      />
    </div>
  );
}

