              ? [detail.company, detail.terminal_name].filter(Boolean).join(' · ') ||
                t('tripAudit.detail.description', 'Actual route vs OSRM optimal and raised flags.')
              : t('tripAudit.detail.description', 'Actual route vs OSRM optimal and raised flags.')}
