import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Badge } from '@/shared/ui/badge';
import { formatNumber } from '@/shared/lib/format';
import { KNOWN_UNMATCHED_REASONS } from '@/entities/trip-audit/schemas';

/* -------------------------------------------------------------------------- */
/* Small display helpers shared by the trip-audit queue and detail dialog.     */
/* -------------------------------------------------------------------------- */

/** Translate a proxy unmatched_reason code; unknown codes are echoed as-is. */
export function useUnmatchedReasonLabel() {
  const { t } = useTranslation();
  return React.useCallback(
    (reason: string): string => {
      if ((KNOWN_UNMATCHED_REASONS as readonly string[]).includes(reason)) {
        return t(`tripAudit.unmatchedReason.${reason}`, reason);
      }
      return reason;
    },
    [t],
  );
}

/** "12.3" km with one decimal, or an em dash for null. */
export function formatKm(km: number | null | undefined): string {
  if (km == null || !Number.isFinite(km)) return '—';
  return formatNumber(km, 1);
}

/** "1h 23m" / "45m" / "30s" from seconds, or an em dash for null. */
export function formatDurationSecs(secs: number | null | undefined): string {
  if (secs == null || !Number.isFinite(secs) || secs < 0) return '—';
  const total = Math.round(secs);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  if (h > 0) return `${h}h ${m}m`;
  if (m > 0) return `${m}m`;
  return `${total}s`;
}

/**
 * Ratio badge — actual vs OSRM optimal. Green up to 1.2x, amber up to
 * 1.5x, red beyond. Forced LTR so "1.35×" doesn't flip in RTL.
 */
export function RatioBadge({ ratio }: { ratio: number | null | undefined }) {
  if (ratio == null || !Number.isFinite(ratio)) {
    return <span className="text-muted-foreground">—</span>;
  }
  const variant = ratio <= 1.2 ? 'success' : ratio <= 1.5 ? 'warning' : 'destructive';
  return (
    <Badge variant={variant} className="tabular-nums" dir="ltr">
      {ratio.toFixed(2)}×
    </Badge>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { CheckCircle2, ChevronRight, Package } from 'lucide-react';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { Skeleton } from '@/shared/ui/skeleton';
import { EmptyState } from '@/shared/ui/empty-state';
import { cn } from '@/shared/lib/cn';
import { formatCairoDay } from '@/shared/lib/cairo';
import { formatNumber } from '@/shared/lib/format';
import type { TripMatch } from '@/entities/trip-audit/schemas';
import { useUnmatchedReasonLabel } from '@/widgets/trip-audit-matches-table';

/* -------------------------------------------------------------------------- */
/* Row severity                                                                */
/*                                                                             */
/* The server reports `critical_count` (exact per-flag severities): any        */
/* critical flag — or an unmatched trip — reads as critical; any other flag,   */
/* missed deliveries, or a ratio above 1.2 reads as warning.                   */
/* -------------------------------------------------------------------------- */

export type QueueSeverity = 'critical' | 'warning' | 'ok';

export function severityOf(m: TripMatch): QueueSeverity {
  if (m.status === 'unmatched' || m.critical_count > 0) return 'critical';
  const ratio = m.distance_ratio;
  const missedDeliveries = m.deliveries_expected > 0 && m.deliveries_visited < m.deliveries_expected;
  if (m.flag_count > 0 || missedDeliveries || (ratio != null && ratio > 1.2)) return 'warning';
  return 'ok';
}

/* -------------------------------------------------------------------------- */
/* Verdict sentence                                                            */
/* -------------------------------------------------------------------------- */

function km(v: number): string {
  return formatNumber(v, v < 100 ? 1 : 0);
}

function verdictText(
  match: TripMatch,
  t: ReturnType<typeof useTranslation>['t'],
  reasonLabel: (code: string) => string,
): string {
  if (match.status === 'unmatched') {
    return t('tripAudit.queue.unmatched', {
      reason: match.unmatched_reason
        ? reasonLabel(match.unmatched_reason)
        : t('tripAudit.queue.unknownReason', 'unknown reason'),
      defaultValue: 'Not audited — {{reason}}',
    });
  }

  const actual = match.actual_km;
  const osrm = match.osrm_km;

  if (actual == null || osrm == null || !Number.isFinite(actual) || !Number.isFinite(osrm)) {
    return t('tripAudit.queue.noComparison', 'No distance comparison available');
  }

  const excess = actual - osrm;
  if (excess > 0.5) {
    return t('tripAudit.queue.drove', {
      actual: km(actual),
      osrm: km(osrm),
      excess: km(excess),
      defaultValue: 'Drove {{actual}} km vs {{osrm}} km optimal — +{{excess}} km excess',
    });
  }
  return t('tripAudit.queue.droveOnTarget', {
    actual: km(actual),
    osrm: km(osrm),
    defaultValue: 'Drove {{actual}} km vs {{osrm}} km optimal — on target',
  });
}

/* -------------------------------------------------------------------------- */
/* Row                                                                         */
/*                                                                             */
/* Deliberately quiet: exactly three visual weights.                           */
/*   1. Primary line — day · terminal · plate (· driver on sm+).               */
/*   2. Verdict line — one muted sentence (plus deliveries when short).        */
/*   3. Right rail — a severity chip (critical/warning only) and ONE action:   */
/*      "Review", which opens the detail view. Reviewed rows fade out and      */
/*      swap the button for a subtle check.                                    */
/* -------------------------------------------------------------------------- */

function QueueRow({ match, onOpen }: { match: TripMatch; onOpen: (m: TripMatch) => void }) {
  const { t, i18n } = useTranslation();
  const reasonLabel = useUnmatchedReasonLabel();
  const severity = severityOf(match);
  const reviewed = Boolean(match.reviewed_at);
  const missedDeliveries =
    match.deliveries_expected > 0 && match.deliveries_visited < match.deliveries_expected;
  const place = match.terminal_name || match.company || '—';

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => onOpen(match)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onOpen(match);
        }
      }}
      className={cn(
        'group flex cursor-pointer items-center gap-3 px-4 py-3.5 transition-colors hover:bg-muted/40',
        reviewed && 'opacity-55 hover:opacity-90',
      )}
    >
      <div className="min-w-0 flex-1 space-y-1">
        {/* Primary line */}
        <div className="flex min-w-0 items-baseline gap-x-2.5">
          <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
            {formatCairoDay(match.day_local, i18n.language)}
          </span>
          <span className="min-w-0 truncate text-sm font-medium" dir="auto" title={place}>
            {place}
          </span>
          {match.car_no_plate && (
            <span className="shrink-0 text-xs text-muted-foreground" dir="ltr">
              {match.car_no_plate}
            </span>
          )}
          {match.driver_name && (
            <span
              className="hidden max-w-[160px] truncate text-xs text-muted-foreground sm:inline"
              dir="auto"
            >
              {match.driver_name}
            </span>
          )}
        </div>
        {/* Verdict line */}
        <p className="flex min-w-0 flex-wrap items-center gap-x-2 text-xs text-muted-foreground">
          <span className="min-w-0 truncate" dir="auto">
            {verdictText(match, t, reasonLabel)}
          </span>
          {match.deliveries_expected > 0 && (
            <span
              className={cn(
                'inline-flex shrink-0 items-center gap-1 tabular-nums',
                missedDeliveries && 'font-medium text-warning',
              )}
            >
              <Package className="h-3 w-3" />
              <span dir="ltr">
                {match.deliveries_visited}/{match.deliveries_expected}
              </span>
              {t('tripAudit.queue.deliveries', 'deliveries')}
            </span>
          )}
        </p>
      </div>

      {/* Right rail — severity + the single action */}
      <div className="flex shrink-0 items-center gap-2.5">
        {reviewed ? (
          <span
            className="hidden items-center gap-1 text-xs text-success sm:flex"
            title={match.review_note ?? undefined}
          >
            <CheckCircle2 className="h-3.5 w-3.5" />
            {t('tripAudit.queue.reviewedOn', {
              when: formatCairoDay(match.reviewed_at as string, i18n.language),
              defaultValue: 'Reviewed {{when}}',
            })}
          </span>
        ) : (
          severity !== 'ok' && (
            <Badge
              variant={severity === 'critical' ? 'destructive' : 'warning'}
              className="hidden sm:inline-flex"
            >
              {t(`tripAudit.severity.${severity}`, severity)}
            </Badge>
          )
        )}
        <Button
          type="button"
          size="sm"
          variant={reviewed ? 'ghost' : 'outline'}
          className="h-8 gap-1 text-xs"
          tabIndex={-1}
          onClick={(e) => {
            e.stopPropagation();
            onOpen(match);
          }}
        >
          {reviewed
            ? t('tripAudit.queue.view', 'View')
            : t('tripAudit.queue.review', 'Review')}
          <ChevronRight className="h-3.5 w-3.5 rtl:rotate-180" />
        </Button>
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Queue list                                                                  */
/* -------------------------------------------------------------------------- */

interface TripAuditQueueProps {
  matches: TripMatch[];
  loading?: boolean;
  onOpen: (match: TripMatch) => void;
  /** Rendered when the list is empty — lets the page vary the empty state per view. */
  empty?: React.ReactNode;
}

/**
 * The review queue. Every row answers one question — "does this trip need
 * attention?" — with one primary line, one verdict sentence and one action.
 * All numeric detail lives in the detail dialog behind "Review".
 */
export function TripAuditQueue({ matches, loading, onOpen, empty }: TripAuditQueueProps) {
  const { t } = useTranslation();

  if (loading && matches.length === 0) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 6 }).map((_, i) => (
          <Skeleton key={i} className="h-[60px] w-full" />
        ))}
      </div>
    );
  }

  if (matches.length === 0) {
    return (
      <>
        {empty ?? (
          <EmptyState
            title={t('tripAudit.table.empty', 'No audited trips in this range')}
            description={t(
              'tripAudit.table.emptyDesc',
              'Adjust the date range or run a scan to audit recent trips.',
            )}
          />
        )}
      </>
    );
  }

  return (
    <div
      className={cn(
        'divide-y divide-border/60 overflow-hidden rounded-lg border bg-card',
        loading && 'opacity-60',
      )}
    >
      {matches.map((match) => (
        <QueueRow key={match.id} match={match} onOpen={onOpen} />
      ))}
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import {
  Check,
  ChevronLeft,
  ChevronRight,
  Loader2,
  MapPin,
  Search,
  UserMinus,
} from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { EmptyState } from '@/shared/ui/empty-state';
import { useDropOffs } from '@/entities/mapping/queries';
import type { MappingDetail } from '@/entities/mapping/schemas';
import { normalize } from '@/shared/lib/normalize';
import { formatNumber, formatCurrency } from '@/shared/lib/format';
import { cn } from '@/shared/lib/cn';

const PAGE_SIZE = 15;
const UNREGISTERED_VALUE = '__unregistered__';

interface DropOffPickerModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  company: string;
  terminal: string;
  /** Currently selected drop-off (string), used to highlight the active option */
  value: string;
  /** Callback fired with both the chosen name and its mapping details (for fee/distance) */
  onSelect: (dropOff: string, mapping?: MappingDetail) => void;
}

/**
 * Drop-off picker — a paginated, searchable modal with fee/distance shown
 * inline next to each option so the user can compare costs before clicking.
 *
 * The search uses the project-wide `normalize` for Arabic-aware matching
 * (handles diacritics, alif variants, ya/alef-maksura, etc).
 *
 * Includes an "Unregistered" sentinel option that lets the user save trips
 * for drop-offs that don't yet have a mapping row — driver still gets paid,
 * route just shows up as غير مسجل until ops adds the mapping.
 */
export function DropOffPickerModal({
  open,
  onOpenChange,
  company,
  terminal,
  value,
  onSelect,
}: DropOffPickerModalProps) {
  const { t } = useTranslation();
  const { data, isLoading } = useDropOffs(company, terminal, {
    enabled: open && !!company && !!terminal,
  });
  const [search, setSearch] = React.useState('');
  const [page, setPage] = React.useState(1);

  // Reset on open / parent change
  React.useEffect(() => {
    if (!open) return;
    setSearch('');
    setPage(1);
  }, [open, company, terminal]);

  const dropOffs = data?.data ?? [];
  const mappings = data?.mappings ?? {};

  // Filter (Arabic-aware), then paginate
  const filtered = React.useMemo(() => {
    if (!search.trim()) return dropOffs;
    const needle = normalize(search);
    return dropOffs.filter((d) => normalize(d).includes(needle));
  }, [dropOffs, search]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);
  const pageItems = filtered.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  const handlePick = (dropOff: string, mapping?: MappingDetail) => {
    onSelect(dropOff, mapping);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xl">
        <DialogHeader>
          <DialogTitle>{t('trips.form.dropOffPicker.title')}</DialogTitle>
          <DialogDescription>
            {company && terminal
              ? t('trips.form.dropOffPicker.descriptionWithRoute', {
                  company,
                  terminal,
                })
              : t('trips.form.dropOffPicker.description')}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-3">
          {/* Search */}
          <div className="relative">
            <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setPage(1);
              }}
              placeholder={t('trips.form.dropOffPicker.searchPlaceholder')}
              className="ps-9"
              autoFocus
            />
          </div>

          {/* Always-available unregistered option */}
          <button
            type="button"
            onClick={() => handlePick(UNREGISTERED_VALUE)}
            className={cn(
              'flex w-full items-center gap-2.5 rounded-md border border-dashed bg-muted/30 px-3 py-2.5 text-start transition-colors hover:bg-muted/60',
              value === UNREGISTERED_VALUE && 'border-solid border-primary bg-primary/5',
            )}
          >
            <UserMinus className="h-4 w-4 text-muted-foreground" />
            <div className="flex-1">
              <div className="text-sm font-medium">
                {t('trips.form.dropOffPicker.unregistered')}
              </div>
              <div className="text-xs text-muted-foreground">
                {t('trips.form.dropOffPicker.unregisteredHint')}
              </div>
            </div>
            {value === UNREGISTERED_VALUE && (
              <Check className="h-4 w-4 text-primary" />
            )}
          </button>

          {/* Results */}
          <ScrollArea className="h-[340px] rounded-md border">
            {isLoading ? (
              <div className="flex h-full items-center justify-center py-12">
                <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              </div>
            ) : pageItems.length === 0 ? (
              <div className="flex h-full items-center justify-center">
                <EmptyState
                  lottieSrc="/animations/no_results.json"
                  lottieWidth={80}
                  lottieHeight={80}
                  title={search
                    ? t('trips.form.dropOffPicker.noMatches')
                    : t('trips.form.dropOffPicker.empty')}
                  className="border-0 bg-transparent py-4 shadow-none"
                />
              </div>
            ) : (
              <ul className="divide-y">
                {pageItems.map((dropOff) => {
                  const mapping = mappings[dropOff];
                  const fee = Number(mapping?.fee ?? 0);
                  const distance = Number(mapping?.distance ?? 0);
                  const isSelected = dropOff === value;

                  return (
                    <li key={dropOff}>
                      <button
                        type="button"
                        onClick={() => handlePick(dropOff, mapping)}
                        className={cn(
                          'flex w-full items-center gap-3 px-3 py-2.5 text-start transition-colors',
                          'hover:bg-muted/60',
                          isSelected && 'bg-primary/5',
                        )}
                      >
                        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-muted text-muted-foreground">
                          <MapPin className="h-4 w-4" />
                        </div>
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2">
                            <span className="truncate text-sm font-medium">
                              {dropOff}
                            </span>
                          </div>
                          {mapping && (
                            <div className="flex items-center gap-3 text-xs text-muted-foreground">
                              {distance > 0 && (
                                <span className="tabular-nums">
                                  {formatNumber(distance, 1)} km
                                </span>
                              )}
                              {fee > 0 && (
                                <span className="tabular-nums text-success">
                                  {formatCurrency(fee)}
                                </span>
                              )}
                              {mapping.route_name && (
                                <span className="truncate">
                                  {mapping.route_name}
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                        {isSelected && (
                          <Check className="h-4 w-4 shrink-0 text-primary" />
                        )}
                      </button>
                    </li>
                  );
                })}
              </ul>
            )}
          </ScrollArea>

          {/* Pagination */}
          {filtered.length > PAGE_SIZE && (
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <span className="tabular-nums">
                {t('trips.form.dropOffPicker.resultsCount', {
                  shown: pageItems.length,
                  total: filtered.length,
                })}
              </span>
              <div className="flex items-center gap-1">
                <Button
                  size="icon"
                  variant="ghost"
                  className="h-7 w-7"
                  disabled={currentPage === 1}
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                >
                  <ChevronLeft className="h-3.5 w-3.5 rtl:rotate-180" />
                </Button>
                <span className="px-2 tabular-nums">
                  {currentPage} / {totalPages}
                </span>
                <Button
                  size="icon"
                  variant="ghost"
                  className="h-7 w-7"
                  disabled={currentPage === totalPages}
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                >
                  <ChevronRight className="h-3.5 w-3.5 rtl:rotate-180" />
                </Button>
              </div>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {t('common.cancel')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

