/* -------------------------------------------------------------------------- */
/* Popup HTML builder                                                         */
/* -------------------------------------------------------------------------- */

interface PopupHtmlOptions {
  color: string;
  bg: string;
  label: string;
  value: string;
}

function buildPopupHtml({ color, bg, label, value }: PopupHtmlOptions): string {
  return `
    <div style="padding:18px 14px 12px;min-width:160px;font-family:inherit;text-align:center">
      <div style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:${bg};margin:0 auto 8px">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
          <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/>
          <circle cx="12" cy="9" r="2.5"/>
        </svg>
      </div>
      <p style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#71717a;margin:0 0 3px;font-weight:500">${escapeHtml(label)}</p>
      <p style="font-size:13px;font-weight:600;margin:0;line-height:1.3">${escapeHtml(value)}</p>
    </div>`;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { ChevronLeft, ChevronRight, X } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { Button } from '@/shared/ui/button';
import { EmptyState } from '@/shared/ui/empty-state';
import { Skeleton } from '@/shared/ui/skeleton';
import { useParentContainers } from '@/entities/trip/queries';
import { type ReceiptImage } from '@/entities/trip/schemas';
import { receiptBatchApi } from '@/entities/receipt-batch/api';
import { cn } from '@/shared/lib/cn';

interface TripReceiptBatchDialogProps {
  parentId: number | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

/**
 * Image gallery for a parent trip's receipt batch.
 *
 * The driver app uploads scanned receipt images that get attached to a parent
 * trip. This dialog lets office staff browse them: thumbnails grid + a
 * lightbox-style enlarged view. Click a thumbnail → enlarged. Arrow keys
 * navigate. Click outside / X / Escape closes the lightbox.
 *
 * The image URL is built from `VITE_API_BASE_URL` + the image's `path` via
 * `receiptBatchApi.imageUrl`. Adjust the env var if your project uses a
 * different one.
 */
export function TripReceiptBatchDialog({
  parentId,
  open,
  onOpenChange,
}: TripReceiptBatchDialogProps) {
  const { t } = useTranslation();
  const { data, isLoading } = useParentContainers(open ? parentId : null);
  const [enlargedIndex, setEnlargedIndex] = React.useState<number | null>(null);

  const images = data?.parent_trip?.receipt_batch?.receipts ?? [];

  // Reset enlarged index when dialog opens / parent changes
  React.useEffect(() => {
    if (!open) setEnlargedIndex(null);
  }, [open, parentId]);

  // Keyboard nav for the lightbox
  React.useEffect(() => {
    if (enlargedIndex == null) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setEnlargedIndex(null);
      } else if (e.key === 'ArrowRight') {
        setEnlargedIndex((i) =>
          i != null ? (i + 1) % images.length : 0,
        );
      } else if (e.key === 'ArrowLeft') {
        setEnlargedIndex((i) =>
          i != null ? (i - 1 + images.length) % images.length : 0,
        );
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [enlargedIndex, images.length]);

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>{t('trips.receiptBatch.dialogTitle')}</DialogTitle>
            <DialogDescription>
              {t('trips.receiptBatch.dialogDescription', {
                count: images.length,
              })}
            </DialogDescription>
          </DialogHeader>

          {isLoading ? (
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4">
              {Array.from({ length: 6 }).map((_, i) => (
                <Skeleton key={i} className="aspect-square w-full" />
              ))}
            </div>
          ) : images.length === 0 ? (
            <div className="flex flex-col items-center justify-center gap-2 py-4 text-center">
              <EmptyState
                lottieSrc="/animations/receipt.lottie"
                lottieWidth={140}
                lottieHeight={140}
                title={t('trips.receiptBatch.noImages')}
                className="border-0 bg-transparent py-4 shadow-none"
              />
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4">
              {images.map((image: ReceiptImage, idx: number) => (
                <button
                  key={image.ID ?? idx}
                  type="button"
                  onClick={() => setEnlargedIndex(idx)}
                  className="group relative aspect-square overflow-hidden rounded-md border bg-muted/30 transition-all hover:ring-2 hover:ring-primary"
                >
                  <img
                    src={receiptBatchApi.imageUrl(image.image_path)}
                    alt={t('trips.receiptBatch.imageAlt', { n: idx + 1 })}
                    loading="lazy"
                    className="h-full w-full object-cover transition-transform group-hover:scale-105"
                  />
                  <span className="absolute bottom-1 end-1 rounded bg-card/90 px-1.5 py-0.5 text-[10px] font-medium tabular-nums">
                    {idx + 1} / {images.length}
                  </span>
                </button>
              ))}
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Lightbox */}
      {enlargedIndex != null && images[enlargedIndex] && (
        <div
          className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 p-4"
          onClick={() => setEnlargedIndex(null)}
        >
          <button
            type="button"
            onClick={() => setEnlargedIndex(null)}
            className="absolute end-4 top-4 inline-flex h-9 w-9 items-center justify-center rounded-full bg-card/20 text-white backdrop-blur-sm transition-colors hover:bg-card/30"
            aria-label={t('common.close')}
          >
            <X className="h-5 w-5" />
          </button>
          {images.length > 1 && (
            <>
              <Button
                size="icon"
                variant="ghost"
                onClick={(e) => {
                  e.stopPropagation();
                  setEnlargedIndex(
                    (enlargedIndex - 1 + images.length) % images.length,
                  );
                }}
                className={cn(
                  'absolute start-4 h-12 w-12 rounded-full bg-card/20 text-white backdrop-blur-sm hover:bg-card/30',
                )}
                aria-label={t('trips.pagination.previousPage')}
              >
                <ChevronLeft className="h-6 w-6 rtl:rotate-180" />
              </Button>
              <Button
                size="icon"
                variant="ghost"
                onClick={(e) => {
                  e.stopPropagation();
                  setEnlargedIndex((enlargedIndex + 1) % images.length);
                }}
                className="absolute end-4 h-12 w-12 rounded-full bg-card/20 text-white backdrop-blur-sm hover:bg-card/30"
                aria-label={t('trips.pagination.nextPage')}
              >
                <ChevronRight className="h-6 w-6 rtl:rotate-180" />
              </Button>
            </>
          )}
          <div
            className="relative max-h-[90vh] max-w-[90vw]"
            onClick={(e) => e.stopPropagation()}
          >
            <img
              src={receiptBatchApi.imageUrl(images[enlargedIndex].image_path)}
              alt={t('trips.receiptBatch.imageAlt', { n: enlargedIndex + 1 })}
              className="max-h-[90vh] max-w-[90vw] object-contain"
            />
            <div className="absolute bottom-2 start-1/2 -translate-x-1/2 rounded-full bg-card/80 px-3 py-1 text-xs font-medium tabular-nums backdrop-blur-sm">
              {enlargedIndex + 1} / {images.length}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from '@/shared/ui/toaster';
import { EmptyState } from '@/shared/ui/empty-state';
import {
  Archive,
  Building2,
  CheckCircle2,
  Loader2,
  Plus,
  Stamp,
  Trash2,
} from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Textarea } from '@/shared/ui/textarea';
import { Checkbox } from '@/shared/ui/checkbox';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { Skeleton } from '@/shared/ui/skeleton';
import {
  useTripReceipts,
  useCreateReceiptStep,
  useUpdateReceiptStep,
  useDeleteReceiptStep,
} from '@/entities/receipt/queries';
import type { ReceiptStep, ReceiptStepLocation } from '@/entities/receipt/schemas';
import { extractErrorMessage } from '@/shared/api/errors';
import { format, formatDateTime } from '@/shared/lib/format';
import { cn } from '@/shared/lib/cn';

interface TripReceiptDialogProps {
  tripId: number | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

/**
 * Full-featured receipt-step manager.
 *
 * Top: trip identity (date / vehicle / route / receipt no) so the user knows
 * what trip they're managing without bouncing back to the table.
 *
 * Middle: timeline of existing steps. Each step has:
 *   - Stamp toggle (checkbox button)
 *   - Delete button
 *   - "Received by" inline-editable
 *   - Notes inline-editable
 *
 * Bottom: form to add a new step. The location dropdown only shows locations
 * that haven't been added yet — Garage and Office are one-of-each per trip in
 * the original module's mental model.
 */
export function TripReceiptDialog({
  tripId,
  open,
  onOpenChange,
}: TripReceiptDialogProps) {
  const { t } = useTranslation();
  const { data, isLoading } = useTripReceipts(open ? tripId : null);
  const createMutation = useCreateReceiptStep();
  const updateMutation = useUpdateReceiptStep(tripId ?? undefined);
  const deleteMutation = useDeleteReceiptStep(tripId ?? undefined);

  const trip = data?.trip;
  const steps = data?.steps ?? [];

  const usedLocations = new Set(steps.map((s) => s.location));
  const availableLocations: ReceiptStepLocation[] = (
    ['Garage', 'Office'] as ReceiptStepLocation[]
  ).filter((l) => !usedLocations.has(l));

  // -- Add-step form state ----------------------------------------------------
  const [newLocation, setNewLocation] = React.useState<ReceiptStepLocation>('Garage');
  const [newReceivedBy, setNewReceivedBy] = React.useState('');
  const [newStamped, setNewStamped] = React.useState(false);
  const [newNotes, setNewNotes] = React.useState('');

  // Reset the form whenever the dialog opens or available locations change
  React.useEffect(() => {
    if (!open) return;
    setNewLocation(availableLocations[0] ?? 'Garage');
    setNewReceivedBy('');
    setNewStamped(false);
    setNewNotes('');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, availableLocations.join(',')]);

  const handleAdd = async () => {
    if (!tripId || !newReceivedBy.trim()) return;
    try {
      await createMutation.mutateAsync({
        trip_id: tripId,
        location: newLocation,
        received_by: newReceivedBy.trim(),
        stamped: newStamped,
        notes: newNotes.trim(),
      });
      toast.success(t('trips.receipt.addedSuccessfully'));
      setNewReceivedBy('');
      setNewNotes('');
      setNewStamped(false);
    } catch (err) {
      toast.error(extractErrorMessage(err, t('trips.receipt.addFailed')));
    }
  };

  const handleToggleStamp = async (step: ReceiptStep) => {
    try {
      await updateMutation.mutateAsync({
        stepId: step.ID,
        input: { stamped: !step.stamped },
      });
      toast.success(t('trips.receipt.updatedSuccessfully'));
    } catch (err) {
      toast.error(extractErrorMessage(err, t('trips.receipt.updateFailed')));
    }
  };

  const handleDelete = async (stepId: number) => {
    try {
      await deleteMutation.mutateAsync(stepId);
      toast.success(t('trips.receipt.deletedSuccessfully'));
    } catch (err) {
      toast.error(extractErrorMessage(err, t('trips.receipt.deleteFailed')));
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex flex-col max-h-[90dvh] overflow-hidden md:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{t('trips.receipt.dialogTitle')}</DialogTitle>
          <DialogDescription>
            {t('trips.receipt.dialogDescription')}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto pr-1 min-h-0 space-y-4 max-h-[55vh] md:max-h-[65vh]">
          {/* Trip context */}
          {isLoading ? (
            <div className="space-y-2 rounded-md border bg-muted/30 p-3">
              <Skeleton className="h-3 w-32" />
              <Skeleton className="h-3 w-48" />
              <Skeleton className="h-3 w-40" />
            </div>
          ) : trip ? (
            <div className="grid grid-cols-2 gap-x-4 gap-y-1 rounded-md border bg-muted/30 p-3 text-xs">
              <Field label={t('trips.fields.receiptNo')} value={`#${trip.receipt_no || '—'}`} />
              <Field label={t('trips.fields.date')} value={format(trip.date, 'PPP')} />
              <Field label={t('trips.fields.vehicle')} value={trip.car_no_plate} />
              <Field label={t('trips.fields.driver')} value={trip.driver_name} />
              <Field
                label={t('trips.fields.terminal')}
                value={trip.terminal}
                className="col-span-2"
              />
              <Field
                label={t('trips.fields.dropOffPoint')}
                value={trip.drop_off_point}
                className="col-span-2"
              />
            </div>
          ) : null}

          {/* Timeline */}
          <section>
            <h4 className="mb-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
              {t('trips.expanded.receiptTimeline')}
            </h4>
            {isLoading ? (
              <div className="space-y-2">
                <Skeleton className="h-16 w-full" />
                <Skeleton className="h-16 w-full" />
              </div>
            ) : steps.length === 0 ? (
              <EmptyState
                lottieSrc="/animations/receipt.lottie"
                lottieWidth={100}
                lottieHeight={100}
                title={t('trips.expanded.noReceiptSteps')}
                className="py-8 bg-transparent border-dashed"
              />
            ) : (
              <ol className="space-y-2">
                {[...steps]
                  .sort(
                    (a, b) =>
                      new Date(a.received_at).getTime() -
                      new Date(b.received_at).getTime(),
                  )
                  .map((step) => (
                    <ReceiptStepRow
                      key={step.ID}
                      step={step}
                      onToggleStamp={() => handleToggleStamp(step)}
                      onDelete={() => handleDelete(step.ID)}
                      busy={
                        (updateMutation.isPending &&
                          updateMutation.variables?.stepId === step.ID) ||
                        (deleteMutation.isPending &&
                          deleteMutation.variables === step.ID)
                      }
                    />
                  ))}
              </ol>
            )}
          </section>

          {/* Add new step */}
          {availableLocations.length > 0 && trip && (
            <section className="rounded-md border bg-card p-3">
              <h4 className="mb-3 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                <Plus className="h-3 w-3" />
                {t('trips.receipt.addStep')}
              </h4>
              <div className="grid gap-3 sm:grid-cols-2">
                <div>
                  <Label htmlFor="step-location" className="text-xs">
                    {t('trips.receipt.location')}
                  </Label>
                  <Select
                    value={newLocation}
                    onValueChange={(v) =>
                      setNewLocation(v as ReceiptStepLocation)
                    }
                  >
                    <SelectTrigger id="step-location" className="mt-1">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {availableLocations.map((loc) => (
                        <SelectItem key={loc} value={loc}>
                          <span className="inline-flex items-center gap-1.5">
                            {loc === 'Garage' ? (
                              <Archive className="h-3.5 w-3.5" />
                            ) : (
                              <Building2 className="h-3.5 w-3.5" />
                            )}
                            {t(`trips.receiptLocation.${loc}`)}
                          </span>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label htmlFor="step-received-by" className="text-xs">
                    {t('trips.receipt.receivedBy')}
                    <span className="text-destructive">*</span>
                  </Label>
                  <Input
                    id="step-received-by"
                    value={newReceivedBy}
                    onChange={(e) => setNewReceivedBy(e.target.value)}
                    placeholder={t('trips.receipt.receivedByPlaceholder')}
                    className="mt-1"
                  />
                </div>
                <div className="sm:col-span-2">
                  <Label htmlFor="step-notes" className="text-xs">
                    {t('trips.receipt.notes')}
                  </Label>
                  <Textarea
                    id="step-notes"
                    value={newNotes}
                    onChange={(e) => setNewNotes(e.target.value)}
                    placeholder={t('trips.receipt.notesPlaceholder')}
                    rows={2}
                    className="mt-1 resize-none"
                  />
                </div>
                <div className="flex items-center gap-2 sm:col-span-2">
                  <Checkbox
                    id="step-stamped"
                    checked={newStamped}
                    onCheckedChange={(v) => setNewStamped(v === true)}
                  />
                  <Label
                    htmlFor="step-stamped"
                    className="flex cursor-pointer items-center gap-1 text-xs"
                  >
                    <Stamp className="h-3 w-3" />
                    {t('trips.receipt.markStamped')}
                  </Label>
                </div>
              </div>
              <div className="mt-3 flex justify-end">
                <Button
                  size="sm"
                  onClick={() => void handleAdd()}
                  disabled={!newReceivedBy.trim() || createMutation.isPending}
                >
                  {createMutation.isPending && (
                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  )}
                  {t('trips.receipt.addStep')}
                </Button>
              </div>
            </section>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            {t('common.close')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/* -------------------------------------------------------------------------- */
/* Step row                                                                    */
/* -------------------------------------------------------------------------- */

interface ReceiptStepRowProps {
  step: ReceiptStep;
  onToggleStamp: () => void;
  onDelete: () => void;
  busy: boolean;
}

function ReceiptStepRow({
  step,
  onToggleStamp,
  onDelete,
  busy,
}: ReceiptStepRowProps) {
  const { t } = useTranslation();
  const Icon = step.location === 'Garage' ? Archive : Building2;

  return (
    <li className="flex items-start gap-3 rounded-md border bg-card p-3">
      <div
        className={cn(
          'flex h-8 w-8 shrink-0 items-center justify-center rounded-full',
          step.stamped
            ? 'bg-success/15 text-success'
            : 'bg-primary/15 text-primary',
        )}
      >
        <Icon className="h-4 w-4" />
      </div>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-sm font-medium">
            {t(`trips.receiptLocation.${step.location}`)}
          </span>
          {step.stamped && (
            <span className="inline-flex items-center gap-0.5 rounded bg-success/15 px-1.5 py-0.5 text-[10px] font-medium text-success">
              <Stamp className="h-2.5 w-2.5" />
              {t('trips.receipt.stamped')}
            </span>
          )}
        </div>
        <p className="text-xs text-muted-foreground">
          <span className="text-foreground">{step.received_by}</span> ·{' '}
          {formatDateTime(step.received_at)}
        </p>
        {step.notes && (
          <p className="mt-1 rounded bg-muted/40 px-2 py-1 text-xs italic text-muted-foreground">
            {step.notes}
          </p>
        )}
      </div>
      <div className="flex shrink-0 flex-col gap-1">
        <Button
          variant="ghost"
          size="icon"
          className={cn(
            'h-7 w-7',
            step.stamped
              ? 'text-success hover:bg-success/10'
              : 'text-muted-foreground hover:text-foreground',
          )}
          onClick={onToggleStamp}
          disabled={busy}
          aria-label={
            step.stamped ? t('trips.receipt.unstamp') : t('trips.receipt.stamp')
          }
          title={
            step.stamped ? t('trips.receipt.unstamp') : t('trips.receipt.stamp')
          }
        >
          {busy ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : step.stamped ? (
            <CheckCircle2 className="h-3.5 w-3.5" />
          ) : (
            <Stamp className="h-3.5 w-3.5" />
          )}
        </Button>
        <Button
          variant="ghost"
          size="icon"
          className="h-7 w-7 text-destructive hover:bg-destructive/10 hover:text-destructive"
          onClick={onDelete}
          disabled={busy}
          aria-label={t('common.delete')}
        >
          <Trash2 className="h-3.5 w-3.5" />
        </Button>
      </div>
    </li>
  );
}

function Field({
  label,
  value,
  className,
}: {
  label: string;
  value: string;
  className?: string;
}) {
  return (
    <div className={cn('flex flex-col gap-0.5', className)}>
      <span className="text-[10px] uppercase tracking-wider text-muted-foreground">
        {label}
      </span>
      <span className="truncate font-medium">{value}</span>
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import {
  Crosshair,
  FastForward,
  Gauge,
  Moon,
  Pause,
  Play,
