/* -------------------------------------------------------------------------- */
/* Formatting                                                                  */
/* -------------------------------------------------------------------------- */

/** "1h 24m" / "4m 12s" — dwell badges and the skipped-dwell chip. */
export function formatDurationShort(ms: number): string {
  const secs = Math.round(ms / 1000);
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  if (h > 0) return `${h}h ${m}m`;
  if (m > 0) return s > 0 ? `${m}m ${s}s` : `${m}m`;
  return `${s}s`;
}

/** "2:41:07" — trip-local elapsed clock. */
export function formatElapsed(ms: number): string {
  const secs = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

/* -------------------------------------------------------------------------- */
/* Props — the page feeds this from a 4Hz-throttled frame snapshot.           */
/* -------------------------------------------------------------------------- */

export interface ReplayHudState {
  elapsedMs: number;
  clockMs: number;
  kmDriven: number;
  kmOptimal: number;
  speedKmh: number;
  speeding: boolean;
  legFrom: string | null;
  legTo: string | null;
  night: boolean;
  skippedDwellMs: number;
  /** Non-null while a compressed dwell pulse is playing. */
  dwellDurationMs: number | null;
  ghostUnavailable: boolean;
  mode: ReplayMode;
  playing: boolean;
  speedX: number;
}

export interface TripReplayHudProps {
  state: ReplayHudState;
  skipStops: boolean;
  followCam: boolean;
  onTogglePlay: () => void;
  onRestart: () => void;
  onSpeedChange: (x: number) => void;
  onSkipStopsChange: (on: boolean) => void;
  onFollowCamChange: (on: boolean) => void;
  className?: string;
}

/* -------------------------------------------------------------------------- */
/* Component — floating glass card, consistent with the app's card styling.   */
/* -------------------------------------------------------------------------- */

function HudToggle({
  active,
  onClick,
  icon,
  label,
}: {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-pressed={active}
      onClick={onClick}
      className={cn(
        'relative flex cursor-pointer items-center gap-1 rounded-full border px-2 py-1 text-[10px] font-semibold transition-colors',
        'after:absolute after:inset-x-0 after:-inset-y-2 after:content-[""]', // ~40px hit
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
        active
          ? 'border-primary/50 bg-primary/10 text-foreground'
          : 'border-border bg-card/60 text-muted-foreground hover:text-foreground',
      )}
    >
      {icon}
      {label}
    </button>
  );
}

export function TripReplayHud({
  state,
  skipStops,
  followCam,
  onTogglePlay,
  onRestart,
  onSpeedChange,
  onSkipStopsChange,
  onFollowCamChange,
  className,
}: TripReplayHudProps) {
  const { t, i18n } = useTranslation();

  return (
    // pointer-events-auto: the page's overlay wrapper is pointer-events-none,
    // so the card must re-enable input for itself. The stop-propagation guards
    // make sure no gesture that starts on the HUD ever reaches the map.
    <div
      className={cn(
        'pointer-events-auto w-64 rounded-xl border bg-card/85 p-3 shadow-xl backdrop-blur-md',
        className,
      )}
      onPointerDown={(e) => e.stopPropagation()}
      onMouseDown={(e) => e.stopPropagation()}
      onTouchStart={(e) => e.stopPropagation()}
      onWheel={(e) => e.stopPropagation()}
    >
      {/* Clock row */}
      <div className="flex items-center justify-between gap-2">
        <div className="font-mono text-lg font-black tabular-nums" dir="ltr">
          {formatElapsed(state.elapsedMs)}
        </div>
        <div className="flex items-center gap-1.5 text-xs font-semibold tabular-nums text-muted-foreground">
          {state.night && (
            <Moon
              className="h-3.5 w-3.5 text-primary"
              aria-label={t('tripReplay.hud.night', 'Night window')}
            />
          )}
          <span dir="ltr">{formatCairoTime(new Date(state.clockMs), i18n.language)}</span>
        </div>
      </div>

      {/* Numbers */}
      <div className="mt-2 grid grid-cols-2 gap-2 text-[11px]">
        <div>
          <div className="text-[9px] font-bold uppercase tracking-wider text-muted-foreground/70">
            {t('tripReplay.hud.kmDriven', 'Driven')}
          </div>
          <div className="font-semibold tabular-nums" dir="ltr">
            {state.kmDriven.toFixed(1)}{' '}
            <span className="font-normal text-muted-foreground">
              / {state.kmOptimal.toFixed(1)} {t('tripReplay.hud.kmOptimal', 'km optimal')}
            </span>
          </div>
        </div>
        <div>
          <div className="text-[9px] font-bold uppercase tracking-wider text-muted-foreground/70">
            {t('tripReplay.hud.speed', 'Speed')}
          </div>
          <div
            className={cn(
              'flex items-center gap-1 font-semibold tabular-nums',
              state.speeding && 'text-destructive',
            )}
            dir="ltr"
          >
            <Gauge className="h-3 w-3" />
            {Math.round(state.speedKmh)} {t('tripReplay.hud.kmh', 'km/h')}
          </div>
        </div>
      </div>

      {/* Current leg */}
      <div className="mt-1.5 truncate text-[11px] text-muted-foreground" dir="auto">
        {state.legFrom || state.legTo
          ? t('tripReplay.hud.leg', '{{from}} → {{to}}', {
              from: state.legFrom || '—',
              to: state.legTo || '—',
            })
          : t('tripReplay.hud.betweenLegs', 'At a stop between legs')}
      </div>

      {/* Dwell badge / skipped chip / ghost note */}
      {state.dwellDurationMs != null && (
        <div className="mt-1.5 inline-flex items-center gap-1.5 rounded-full bg-amber-500/15 px-2 py-0.5 text-[10px] font-bold text-amber-600 dark:text-amber-400">
          <span className="inline-block h-1.5 w-1.5 animate-ping rounded-full bg-amber-500" />
          {t('tripReplay.hud.stoppedFor', 'stopped {{duration}}', {
            duration: formatDurationShort(state.dwellDurationMs),
          })}
        </div>
      )}
      {state.skippedDwellMs > 0 && (
        <div className="mt-1.5 text-[10px] font-medium text-muted-foreground">
          {t('tripReplay.hud.skippedTotal', '{{duration}} of stops skipped', {
            duration: formatDurationShort(state.skippedDwellMs),
          })}
        </div>
      )}
      {state.mode === 'race' && state.ghostUnavailable && (
        <div className="mt-1.5 text-[10px] font-medium text-warning">
          {t('tripReplay.hud.noGhost', 'No optimal route for this leg — ghost hidden')}
        </div>
      )}

      {/* Transport controls */}
      <div className="mt-2.5 flex items-center justify-between gap-2 border-t pt-2">
        <div className="flex items-center gap-1">
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="relative h-7 w-7 text-muted-foreground after:absolute after:-inset-1.5 after:content-[''] hover:text-foreground"
            onClick={onRestart}
            title={t('tripReplay.hud.restart', 'Restart')}
            aria-label={t('tripReplay.hud.restart', 'Restart')}
          >
            <RotateCcw className="h-3.5 w-3.5" />
          </Button>
          <Button
            type="button"
            size="icon"
            className="relative h-8 w-8 rounded-full shadow-lg shadow-primary/30 after:absolute after:-inset-1 after:content-['']"
            onClick={onTogglePlay}
            title={
              state.playing
                ? t('tripReplay.hud.pause', 'Pause (Space)')
                : t('tripReplay.hud.play', 'Play (Space)')
            }
            aria-label={
              state.playing
                ? t('tripReplay.hud.pause', 'Pause (Space)')
                : t('tripReplay.hud.play', 'Play (Space)')
            }
          >
            {state.playing ? (
              <Pause className="h-3.5 w-3.5" />
            ) : (
              <Play className="ms-0.5 h-3.5 w-3.5" />
            )}
          </Button>
        </div>

        {/* Speed selector */}
        <div className="flex rounded-lg border bg-muted/40 p-0.5" role="group" dir="ltr">
          {PLAYBACK_SPEEDS.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => onSpeedChange(s)}
              aria-pressed={state.speedX === s}
              aria-label={t('tripReplay.hud.speedAria', 'Playback speed {{x}}×', { x: s })}
              className={cn(
                'relative cursor-pointer rounded px-1.5 py-1 text-[10px] font-black tabular-nums transition-colors',
                // Segmented control: extend the hit area vertically to ~40px;
                // horizontally each button owns its own slice.
                'after:absolute after:inset-x-0 after:-inset-y-2 after:content-[""]',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                state.speedX === s
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:bg-muted hover:text-foreground',
              )}
            >
              {s}×
            </button>
          ))}
        </div>
      </div>

      {/* Toggles */}
      <div className="mt-2 flex flex-wrap items-center gap-1.5">
        <HudToggle
          active={skipStops}
          onClick={() => onSkipStopsChange(!skipStops)}
          icon={<FastForward className="h-3 w-3" />}
          label={t('tripReplay.hud.skipStops', 'Skip stops')}
        />
        <HudToggle
          active={followCam}
          onClick={() => onFollowCamChange(!followCam)}
          icon={<Crosshair className="h-3 w-3" />}
          label={t('tripReplay.hud.followCam', 'Follow')}
        />
      </div>
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { ChevronLeft, ChevronRight, Moon, Play } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { formatCairoTime } from '@/shared/lib/cairo';
import { legColor, type ReplayModel } from '@/pages/trip-replay/replay-model';

/* -------------------------------------------------------------------------- */
/* TripReplayLegRail — collapsible left rail, one card per leg.                */
/* Active leg follows playback (page passes activeIndex from the 4Hz frame).  */
/* -------------------------------------------------------------------------- */

export interface TripReplayLegRailProps {
  model: ReplayModel;
  /** Index into model.timedLegs, or -1. */
  activeIndex: number;
  disabled?: boolean;
  /** Card click: camera fits the leg + playhead to its start. */
  onLegClick: (index: number) => void;
  /** Mini play button: loop just that leg. */
  onLoopLeg: (index: number) => void;
  className?: string;
}

export function TripReplayLegRail({
  model,
  activeIndex,
  disabled = false,
  onLegClick,
  onLoopLeg,
  className,
}: TripReplayLegRailProps) {
  const { t, i18n } = useTranslation();
  const [collapsed, setCollapsed] = React.useState(false);
  const activeRef = React.useRef<HTMLLIElement>(null);

  // Keep the active card in view as playback advances between legs.
  React.useEffect(() => {
    activeRef.current?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }, [activeIndex]);

  if (collapsed) {
    return (
      <div
        className={cn('pointer-events-auto', className)}
        onPointerDown={(e) => e.stopPropagation()}
        onMouseDown={(e) => e.stopPropagation()}
        onTouchStart={(e) => e.stopPropagation()}
      >
        <Button
          type="button"
          variant="secondary"
          size="icon"
          className="h-10 w-10 rounded-full bg-card/85 shadow-lg backdrop-blur-md"
          onClick={() => setCollapsed(false)}
          title={t('tripReplay.legRail.expand', 'Show legs')}
          aria-label={t('tripReplay.legRail.expand', 'Show legs')}
        >
          <ChevronRight className="h-4 w-4 rtl:rotate-180" />
        </Button>
      </div>
    );
  }

  return (
    // Gestures (drag/scroll/wheel) that start on the rail must never reach
    // the map behind it.
    <div
      className={cn(
        'pointer-events-auto flex max-h-full w-72 flex-col overflow-hidden rounded-xl border bg-card/85 shadow-xl backdrop-blur-md',
        className,
      )}
      onPointerDown={(e) => e.stopPropagation()}
      onMouseDown={(e) => e.stopPropagation()}
      onTouchStart={(e) => e.stopPropagation()}
      onWheel={(e) => e.stopPropagation()}
    >
      <div className="flex items-center justify-between border-b px-3 py-2">
        <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
          {t('tripReplay.legRail.title', 'Legs')}
        </span>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="relative h-6 w-6 text-muted-foreground after:absolute after:-inset-2 after:content-['']"
          onClick={() => setCollapsed(true)}
          title={t('tripReplay.legRail.collapse', 'Hide legs')}
          aria-label={t('tripReplay.legRail.collapse', 'Hide legs')}
        >
          <ChevronLeft className="h-4 w-4 rtl:rotate-180" />
        </Button>
      </div>

      <ul className="flex-1 space-y-1.5 overflow-y-auto overscroll-contain p-2">
        {model.timedLegs.map((leg, i) => {
          const active = i === activeIndex;
          const excessKm =
            leg.actualKm != null && leg.osrmKm != null
              ? leg.actualKm - leg.osrmKm
              : null;
          return (
            <li key={leg.id} ref={active ? activeRef : undefined}>
              <div
                role="button"
                tabIndex={disabled ? -1 : 0}
                onClick={() => !disabled && onLegClick(i)}
                onKeyDown={(e) => {
                  if (!disabled && (e.key === 'Enter' || e.key === ' ')) {
                    e.preventDefault();
                    onLegClick(i);
                  }
                }}
                className={cn(
                  'w-full cursor-pointer rounded-lg border p-2 text-start transition-colors',
                  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                  active
                    ? 'border-primary/60 bg-primary/10'
                    : 'hover:bg-muted/60',
                  disabled && 'pointer-events-none opacity-50',
                )}
              >
                <div className="flex items-center gap-1.5">
                  <span
                    className="inline-block h-2 w-2 shrink-0 rounded-full"
                    style={{ backgroundColor: legColor(leg.legType) }}
                  />
                  <span className="min-w-0 flex-1 truncate text-xs font-semibold" dir="auto">
                    {leg.fromName || '—'} → {leg.toName || '—'}
                  </span>
                  {leg.night && (
                    <Moon
                      className="h-3 w-3 shrink-0 text-primary"
                      aria-label={t('tripReplay.legRail.night', 'Night window')}
                    />
                  )}
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="relative h-6 w-6 shrink-0 text-muted-foreground after:absolute after:-inset-1.5 after:content-[''] hover:text-foreground"
                    onClick={(e) => {
                      e.stopPropagation();
                      onLoopLeg(i);
                    }}
                    title={t('tripReplay.legRail.loop', 'Loop this leg')}
                    aria-label={t('tripReplay.legRail.loop', 'Loop this leg')}
                  >
                    <Play className="h-3 w-3" />
                  </Button>
                </div>

                <div
                  className="mt-1 text-[10px] tabular-nums text-muted-foreground"
                  dir="ltr"
                >
                  {formatCairoTime(new Date(leg.departMs!), i18n.language)} →{' '}
                  {formatCairoTime(new Date(leg.arriveMs!), i18n.language)}
                </div>

                <div className="mt-1 flex flex-wrap items-center gap-x-2 gap-y-0.5 text-[10px] tabular-nums text-muted-foreground">
                  <span dir="ltr">
                    {leg.actualKm != null ? leg.actualKm.toFixed(1) : '—'} /{' '}
                    {leg.osrmKm != null ? leg.osrmKm.toFixed(1) : '—'}{' '}
                    {t('tripReplay.legRail.km', 'km')}
                  </span>
                  {excessKm != null && excessKm > 0.05 && (
                    <Badge variant="warning" className="px-1 py-0 text-[9px]" dir="ltr">
                      +{excessKm.toFixed(1)} {t('tripReplay.legRail.km', 'km')}
                    </Badge>
                  )}
                  {leg.offRoutePct != null && (
                    <span dir="ltr">
                      {t('tripReplay.legRail.offRoute', '{{pct}}% off-route', {
                        pct: leg.offRoutePct.toFixed(0),
                      })}
                    </span>
                  )}
                </div>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { importLibrary } from '@googlemaps/js-api-loader';
import { getSharedMap, releaseSharedMap } from '@/shared/lib/maps/map-pool';
import { buildMarkerSvg, markerSize } from '@/shared/lib/maps/marker-svg';
import type { MarkerKind } from '@/shared/lib/maps/types';
import {
  FOLLOW_THROTTLE_MS,
  GHOST_MARKER_OPACITY,
  PULSE_DURATION_MS,
  PULSE_MAX_RADIUS_M,
  type DynMarkerId,
  type ReplayMapAdapter,
  type ReplayScene,
} from './types';

/* -------------------------------------------------------------------------- */
/* Map styles — same palette as the shared google provider (not exported      */
/* there, duplicated here so the replay map matches the rest of the app).     */
/* -------------------------------------------------------------------------- */

const darkMapStyle: google.maps.MapTypeStyle[] = [
