/* -------------------------------------------------------------------------- */
/* Adapter                                                                     */
/* -------------------------------------------------------------------------- */

interface DynEntry {
  marker: google.maps.Marker;
  color: string;
  kind: MarkerKind;
  opacity: number;
  visible: boolean;
}

export async function createGoogleReplayAdapter(
  container: HTMLElement,
  centerFallback: [number, number],
): Promise<ReplayMapAdapter> {
  await Promise.all([importLibrary('maps'), importLibrary('marker')]);

  const isDark = () => document.documentElement.classList.contains('dark');
  const handle = await getSharedMap(container, {
    center: { lat: centerFallback[0], lng: centerFallback[1] },
    zoom: 11,
    mapTypeId: google.maps.MapTypeId.ROADMAP,
    styles: isDark() ? darkMapStyle : lightMapStyle,
    mapTypeControl: false,
    streetViewControl: false,
    fullscreenControl: false,
    zoomControlOptions: { position: google.maps.ControlPosition.RIGHT_CENTER },
    gestureHandling: 'greedy',
    keyboardShortcuts: false, // the replay owns the keyboard
  });
  const map = handle.map;

  const themeObserver = new MutationObserver(() => {
    if (map.getMapTypeId() !== google.maps.MapTypeId.ROADMAP) return;
    map.setOptions({ styles: isDark() ? darkMapStyle : lightMapStyle });
  });
  themeObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class'],
  });

  const staticOverlays: Array<google.maps.Polyline | google.maps.Marker> = [];
  const dyn = new Map<DynMarkerId, DynEntry>();
  const pinListeners: google.maps.MapsEventListener[] = [];
  let pinClickHandler: ((pinId: string) => void) | null = null;
  let lastPan = 0;
  const pulseRafIds = new Set<number>();

  function icon(kind: MarkerKind, color: string, id: string): google.maps.Icon {
    const sz = markerSize(kind);
    return {
      url: buildMarkerSvg(color, `replay-${id}`, kind),
      anchor: new google.maps.Point(sz.anchorX, sz.anchorY),
    };
  }

  function ensureDyn(id: DynMarkerId): DynEntry {
    let entry = dyn.get(id);
    if (!entry) {
      const kind: MarkerKind = 'vehicle';
      const color = id === 'truck' ? '#2563eb' : '#16a34a';
      const opacity = id === 'truck' ? 1 : GHOST_MARKER_OPACITY;
      const marker = new google.maps.Marker({
        map: null,
        icon: icon(kind, color, id),
        opacity,
        zIndex: id === 'truck' ? 1000 : 900,
        clickable: false,
        optimized: true,
      });
      entry = { marker, color, kind, opacity, visible: false };
      dyn.set(id, entry);
    }
    return entry;
  }

  return {
    setMapType(type: 'roadmap' | 'hybrid') {
      map.setMapTypeId(
        type === 'hybrid' ? google.maps.MapTypeId.HYBRID : google.maps.MapTypeId.ROADMAP,
      );
      if (type === 'roadmap') {
        map.setOptions({ styles: isDark() ? darkMapStyle : lightMapStyle });
      }
    },
    setScene(scene: ReplayScene) {
      staticOverlays.forEach((o) => o.setMap(null));
      staticOverlays.length = 0;
      pinListeners.forEach((l) => google.maps.event.removeListener(l));
      pinListeners.length = 0;

      for (const p of scene.polylines) {
        if (p.path.length < 2) continue;
        staticOverlays.push(
          new google.maps.Polyline({
            path: p.path.map(([lat, lng]) => ({ lat, lng })),
            map,
            strokeColor: p.color,
            strokeOpacity: p.dashed ? 0 : p.opacity,
            strokeWeight: p.weight,
            ...(p.dashed && {
              icons: [
                {
                  icon: {
                    path: 'M 0,-1 0,1',
                    strokeOpacity: p.opacity,
                    scale: p.weight / 1.6,
                  },
                  offset: '0',
                  repeat: '14px',
                },
              ],
            }),
          }),
        );
      }
      for (const pin of scene.pins) {
        const marker = new google.maps.Marker({
          position: { lat: pin.lat, lng: pin.lng },
          map,
          title: pin.title,
          icon: icon(pin.kind, pin.color, pin.id),
        });
        pinListeners.push(
          marker.addListener('click', () => pinClickHandler?.(pin.id)),
        );
        staticOverlays.push(marker);
      }
      if (scene.bounds.length > 0) {
        const bounds = new google.maps.LatLngBounds();
        scene.bounds.forEach(([lat, lng]) => bounds.extend({ lat, lng }));
        map.fitBounds(bounds, { top: 80, bottom: 80, left: 60, right: 60 });
      }
    },

    moveMarker(id, lat, lng) {
      const entry = ensureDyn(id);
      entry.marker.setPosition({ lat, lng });
      if (!entry.visible) {
        entry.visible = true;
        entry.marker.setMap(map);
      }
    },

    setMarkerColor(id, color) {
      const entry = ensureDyn(id);
      if (entry.color === color) return;
      entry.color = color;
      entry.marker.setIcon(icon(entry.kind, color, id));
    },

    setMarkerVisible(id, visible) {
      const entry = ensureDyn(id);
      if (entry.visible === visible) return;
      entry.visible = visible;
      entry.marker.setMap(visible ? map : null);
    },

    follow(lat, lng) {
      const now = performance.now();
      if (now - lastPan < FOLLOW_THROTTLE_MS) return;
      lastPan = now;
      // panTo animates small deltas natively — the eased follow-cam.
      map.panTo({ lat, lng });
    },

    fitPoints(points) {
      if (points.length === 0) return;
      const bounds = new google.maps.LatLngBounds();
      points.forEach(([lat, lng]) => bounds.extend({ lat, lng }));
      map.fitBounds(bounds, { top: 80, bottom: 80, left: 60, right: 60 });
    },

    pulse(lat, lng, color = '#f59e0b') {
      const circle = new google.maps.Circle({
        map,
        center: { lat, lng },
        radius: 1,
        strokeColor: color,
        strokeOpacity: 0.9,
        strokeWeight: 2,
        fillColor: color,
        fillOpacity: 0.35,
        clickable: false,
      });
      const start = performance.now();
      const step = (now: number) => {
        const t = Math.min(1, (now - start) / PULSE_DURATION_MS);
        circle.setRadius(Math.max(1, t * PULSE_MAX_RADIUS_M));
        circle.setOptions({
          fillOpacity: 0.35 * (1 - t),
          strokeOpacity: 0.9 * (1 - t),
        });
        if (t < 1) {
          const id = requestAnimationFrame(step);
          pulseRafIds.add(id);
        } else {
          circle.setMap(null);
        }
      };
      const id = requestAnimationFrame(step);
      pulseRafIds.add(id);
    },

    onPinClick(handler) {
      pinClickHandler = handler;
    },

    destroy() {
      pulseRafIds.forEach((id) => cancelAnimationFrame(id));
      pulseRafIds.clear();
      themeObserver.disconnect();
      pinListeners.forEach((l) => google.maps.event.removeListener(l));
      pinListeners.length = 0;
      staticOverlays.forEach((o) => o.setMap(null));
      staticOverlays.length = 0;
      dyn.forEach((e) => e.marker.setMap(null));
      dyn.clear();
      releaseSharedMap(map);
    },
  };
}

import { buildMarkerSvg, markerSize } from '@/shared/lib/maps/marker-svg';
import type { MarkerKind } from '@/shared/lib/maps/types';
import {
  FOLLOW_THROTTLE_MS,
  GHOST_MARKER_OPACITY,
  PULSE_DURATION_MS,
  PULSE_MAX_RADIUS_M,
  type DynMarkerId,
  type ReplayMapAdapter,
  type ReplayScene,
} from './types';

type LeafletNamespace = typeof import('leaflet');
type LeafletMarker = import('leaflet').Marker;
type LeafletLayer = import('leaflet').Layer;

const TILE_LIGHT =
  'https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png';
const TILE_DARK = 'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png';
const TILE_ATTR =
  '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>';

interface DynEntry {
  marker: LeafletMarker;
  color: string;
  kind: MarkerKind;
  visible: boolean;
}

/**
 * Leaflet fallback adapter — same contract as the Google one, degrading
 * gracefully: `follow` uses a short animated pan, pulses are animated
 * circles, dashed lines use `dashArray`.
 */
export async function createLeafletReplayAdapter(
  container: HTMLElement,
  centerFallback: [number, number],
): Promise<ReplayMapAdapter> {
  const L: LeafletNamespace = await import('leaflet').then((m) => m.default ?? m);

  const isDark = () => document.documentElement.classList.contains('dark');
  const map = L.map(container, {
    center: centerFallback,
    zoom: 11,
    zoomControl: false,
    scrollWheelZoom: true,
    attributionControl: true,
    keyboard: false, // the replay owns the keyboard
  });
  L.control.zoom({ position: 'bottomleft' }).addTo(map);

  let tile = L.tileLayer(isDark() ? TILE_DARK : TILE_LIGHT, {
    attribution: TILE_ATTR,
    maxZoom: 19,
  }).addTo(map);

  const themeObserver = new MutationObserver(() => {
    map.removeLayer(tile);
    tile = L.tileLayer(isDark() ? TILE_DARK : TILE_LIGHT, {
      attribution: TILE_ATTR,
      maxZoom: 19,
    }).addTo(map);
  });
  themeObserver.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['class'],
  });

  const SAT_TILE =
    'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';
  let mapType: 'roadmap' | 'hybrid' = 'roadmap';
  const applyTile = () => {
    map.removeLayer(tile);
    tile = L.tileLayer(mapType === 'hybrid' ? SAT_TILE : isDark() ? TILE_DARK : TILE_LIGHT, {
      attribution: TILE_ATTR,
      maxZoom: 19,
    }).addTo(map);
  };

  const staticLayers: LeafletLayer[] = [];
  const dyn = new Map<DynMarkerId, DynEntry>();
  let pinClickHandler: ((pinId: string) => void) | null = null;
  let lastPan = 0;
  const pulseRafIds = new Set<number>();

  function divIcon(kind: MarkerKind, color: string, id: string) {
    const size = markerSize(kind);
    return L.divIcon({
      html: `<img src="${buildMarkerSvg(color, `replay-${id}`, kind)}" width="${size.width}" height="${size.height}" alt="" />`,
      className: 'custom-marker',
      iconSize: [size.width, size.height],
      iconAnchor: [size.anchorX, size.anchorY],
    });
  }

  function ensureDyn(id: DynMarkerId): DynEntry {
    let entry = dyn.get(id);
    if (!entry) {
      const kind: MarkerKind = 'vehicle';
      const color = id === 'truck' ? '#2563eb' : '#16a34a';
      const marker = L.marker(centerFallback, {
        icon: divIcon(kind, color, id),
        opacity: id === 'truck' ? 1 : GHOST_MARKER_OPACITY,
        zIndexOffset: id === 'truck' ? 1000 : 900,
        interactive: false,
      });
      entry = { marker, color, kind, visible: false };
      dyn.set(id, entry);
    }
    return entry;
  }

  return {
    setMapType(type: 'roadmap' | 'hybrid') {
      mapType = type;
      applyTile();
    },
    setScene(scene: ReplayScene) {
      staticLayers.forEach((l) => map.removeLayer(l));
      staticLayers.length = 0;

      for (const p of scene.polylines) {
        if (p.path.length < 2) continue;
        staticLayers.push(
          L.polyline(p.path, {
            color: p.color,
            opacity: p.opacity,
            weight: p.weight,
            dashArray: p.dashed ? '6 10' : undefined,
          }).addTo(map),
        );
      }
      for (const pin of scene.pins) {
        const marker = L.marker([pin.lat, pin.lng], {
          icon: divIcon(pin.kind, pin.color, pin.id),
          title: pin.title,
          zIndexOffset: 600,
        }).addTo(map);
        marker.on('click', () => pinClickHandler?.(pin.id));
        staticLayers.push(marker);
      }
      if (scene.bounds.length > 1) {
        map.fitBounds(L.latLngBounds(scene.bounds), { padding: [60, 60] });
      } else if (scene.bounds.length === 1) {
        map.setView(scene.bounds[0], 14);
      }
    },

    moveMarker(id, lat, lng) {
      const entry = ensureDyn(id);
      entry.marker.setLatLng([lat, lng]);
      if (!entry.visible) {
        entry.visible = true;
        entry.marker.addTo(map);
      }
    },

    setMarkerColor(id, color) {
      const entry = ensureDyn(id);
      if (entry.color === color) return;
      entry.color = color;
      entry.marker.setIcon(divIcon(entry.kind, color, id));
    },

    setMarkerVisible(id, visible) {
      const entry = ensureDyn(id);
      if (entry.visible === visible) return;
      entry.visible = visible;
      if (visible) entry.marker.addTo(map);
      else entry.marker.remove();
    },

    follow(lat, lng) {
      const now = performance.now();
      if (now - lastPan < FOLLOW_THROTTLE_MS) return;
      lastPan = now;
      map.panTo([lat, lng], { animate: true, duration: 0.25 });
    },

    fitPoints(points) {
      if (points.length === 0) return;
      if (points.length === 1) map.setView(points[0], 15);
      else map.fitBounds(L.latLngBounds(points), { padding: [60, 60] });
    },

    pulse(lat, lng, color = '#f59e0b') {
      const circle = L.circle([lat, lng], {
        radius: 1,
        color,
        opacity: 0.9,
        weight: 2,
        fillColor: color,
        fillOpacity: 0.35,
        interactive: false,
      }).addTo(map);
      const start = performance.now();
      const step = (now: number) => {
        const t = Math.min(1, (now - start) / PULSE_DURATION_MS);
        circle.setRadius(Math.max(1, t * PULSE_MAX_RADIUS_M));
        circle.setStyle({ fillOpacity: 0.35 * (1 - t), opacity: 0.9 * (1 - t) });
        if (t < 1) {
          const id = requestAnimationFrame(step);
          pulseRafIds.add(id);
        } else {
          circle.remove();
        }
      };
      const id = requestAnimationFrame(step);
      pulseRafIds.add(id);
    },

    onPinClick(handler) {
      pinClickHandler = handler;
    },

    destroy() {
      pulseRafIds.forEach((id) => cancelAnimationFrame(id));
      pulseRafIds.clear();
      themeObserver.disconnect();
      staticLayers.forEach((l) => map.removeLayer(l));
      staticLayers.length = 0;
      dyn.forEach((e) => e.marker.remove());
      dyn.clear();
      map.remove();
    },
  };
}

import * as React from 'react';
import { cn } from '@/shared/lib/cn';
import { DEFAULT_MAP_CENTER } from '@/shared/lib/coords';
import { isGoogleMapsConfigured } from '@/shared/lib/maps/google-provider';
import type { DynMarkerId, ReplayMapAdapter, ReplayScene } from './types';

/* -------------------------------------------------------------------------- */
/* TripReplayMap                                                               */
/*                                                                             */
/* React wrapper around the imperative adapters. React renders the container  */
/* exactly once; everything that moves goes through the ref handle so the     */
/* rAF loop never touches React state. Provider cascade mirrors MapView:      */
/* Google when configured (8s budget), otherwise/on failure Leaflet.          */
/* -------------------------------------------------------------------------- */

const GOOGLE_INIT_TIMEOUT_MS = 8_000;

export interface TripReplayMapHandle {
  moveMarker(id: DynMarkerId, lat: number, lng: number): void;
  setMarkerColor(id: DynMarkerId, color: string): void;
  setMarkerVisible(id: DynMarkerId, visible: boolean): void;
  follow(lat: number, lng: number): void;
  fitPoints(points: Array<[number, number]>): void;
  pulse(lat: number, lng: number, color?: string): void;
  setMapType(type: 'roadmap' | 'hybrid'): void;
}

export interface TripReplayMapProps {
  scene: ReplayScene | null;
  onPinClick?: (pinId: string) => void;
  onReady?: () => void;
  className?: string;
}

export const TripReplayMap = React.forwardRef<TripReplayMapHandle, TripReplayMapProps>(
  function TripReplayMap({ scene, onPinClick, onReady, className }, ref) {
    const containerRef = React.useRef<HTMLDivElement>(null);
    const adapterRef = React.useRef<ReplayMapAdapter | null>(null);
    const [ready, setReady] = React.useState(false);

    const onPinClickRef = React.useRef(onPinClick);
    const onReadyRef = React.useRef(onReady);
    React.useEffect(() => {
      onPinClickRef.current = onPinClick;
      adapterRef.current?.onPinClick(onPinClick ?? null);
    }, [onPinClick]);
    React.useEffect(() => {
      onReadyRef.current = onReady;
    }, [onReady]);

    /* ---- Init once ---------------------------------------------------- */

    React.useEffect(() => {
      const container = containerRef.current;
      if (!container) return;
      let cancelled = false;
      let adapter: ReplayMapAdapter | null = null;

      const init = async () => {
        if (isGoogleMapsConfigured()) {
          try {
            const { createGoogleReplayAdapter } = await import('./google-adapter');
            adapter = await Promise.race([
              createGoogleReplayAdapter(container, DEFAULT_MAP_CENTER),
              new Promise<never>((_, reject) =>
                window.setTimeout(
                  () => reject(new Error('google init timeout')),
                  GOOGLE_INIT_TIMEOUT_MS,
                ),
              ),
            ]);
          } catch (err) {
            console.warn('[TripReplayMap] Google init failed — using Leaflet', err);
            adapter = null;
          }
        }
        if (!adapter) {
          const { createLeafletReplayAdapter } = await import('./leaflet-adapter');
          adapter = await createLeafletReplayAdapter(container, DEFAULT_MAP_CENTER);
        }
        if (cancelled) {
          adapter.destroy();
          return;
        }
        adapterRef.current = adapter;
        adapter.onPinClick(onPinClickRef.current ?? null);
        setReady(true);
        onReadyRef.current?.();
      };

      void init().catch((err) => console.error('[TripReplayMap] init failed', err));

      return () => {
        cancelled = true;
        adapterRef.current?.destroy();
        adapterRef.current = null;
        setReady(false);
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    /* ---- Static scene (built once per scene identity) ------------------ */

    React.useEffect(() => {
      if (!ready || !scene) return;
      adapterRef.current?.setScene(scene);
    }, [ready, scene]);

    /* ---- Imperative handle -------------------------------------------- */

    React.useImperativeHandle(
      ref,
      (): TripReplayMapHandle => ({
        moveMarker: (id, lat, lng) => adapterRef.current?.moveMarker(id, lat, lng),
        setMarkerColor: (id, color) => adapterRef.current?.setMarkerColor(id, color),
        setMarkerVisible: (id, visible) =>
          adapterRef.current?.setMarkerVisible(id, visible),
        follow: (lat, lng) => adapterRef.current?.follow(lat, lng),
        fitPoints: (points) => adapterRef.current?.fitPoints(points),
        pulse: (lat, lng, color) => adapterRef.current?.pulse(lat, lng, color),
        setMapType: (type) => adapterRef.current?.setMapType(type),
      }),
      [],
    );

    return (
      <div className={cn('relative h-full w-full', className)}>
        <div ref={containerRef} className="h-full w-full" />
        {!ready && (
          <div className="absolute inset-0 flex items-center justify-center bg-muted/30">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-current border-t-transparent text-muted-foreground" />
          </div>
        )}
      </div>
    );
  },
);

import type { MarkerKind } from '@/shared/lib/maps/types';

/* -------------------------------------------------------------------------- */
/* Static scene + imperative adapter contract                                  */
/*                                                                             */
/* The replay animates at frame rate, so the moving markers are driven        */
/* IMPERATIVELY through this adapter — no React state per frame. Static       */
/* layers (leg polylines, OSRM dashes, event pins) are built exactly once     */
/* per scene. Both providers (Google, Leaflet) implement the same interface;  */
/* the widget picks one and the page never knows which.                       */
/* -------------------------------------------------------------------------- */

export interface ReplayScenePolyline {
  id: string;
  path: Array<[number, number]>;
  color: string;
  weight: number;
  opacity: number;
  dashed?: boolean;
}

export interface ReplayScenePin {
  id: string;
  lat: number;
  lng: number;
  color: string;
  kind: MarkerKind;
  title?: string;
}

export interface ReplayScene {
  polylines: ReplayScenePolyline[];
  pins: ReplayScenePin[];
  /** Every coordinate that participates in the initial fit. */
  bounds: Array<[number, number]>;
}

export type DynMarkerId = 'truck' | 'ghost';

export interface ReplayMapAdapter {
  setScene(scene: ReplayScene): void;
  /** Move (and show) a dynamic marker. Cheap — called every frame. */
  moveMarker(id: DynMarkerId, lat: number, lng: number): void;
  /** Swap marker color (e.g. speeding). Icon is rebuilt only on change. */
  setMarkerColor(id: DynMarkerId, color: string): void;
  setMarkerVisible(id: DynMarkerId, visible: boolean): void;
  /** Eased follow-cam pan. Internally throttled; safe to call every frame. */
  follow(lat: number, lng: number): void;
  fitPoints(points: Array<[number, number]>): void;
  /** Expanding-ring pulse animation at a location (dwell/event emphasis). */
  pulse(lat: number, lng: number, color?: string): void;
  onPinClick(handler: ((pinId: string) => void) | null): void;
  /** Basemap: streets or satellite hybrid. */
  setMapType(type: 'roadmap' | 'hybrid'): void;
  destroy(): void;
}

export const TRUCK_MARKER_OPACITY = 1;
export const GHOST_MARKER_OPACITY = 0.55;
export const FOLLOW_THROTTLE_MS = 180;
export const PULSE_DURATION_MS = 1_400;
export const PULSE_MAX_RADIUS_M = 90;

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Moon } from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { formatCairoTime } from '@/shared/lib/cairo';
import {
  legColor,
  type ReplayEventPin,
  type ReplayModel,
} from '@/pages/trip-replay/replay-model';

/* -------------------------------------------------------------------------- */
/* TripReplayTimeline — the spine of the replay.                               */
/*                                                                             */
/* A horizontal band over [startMs, endMs]: leg segments colored by leg_type, */
/* striped dwell gaps, night shading (20:00–07:00 Cairo), event pins, and a   */
/* playhead that is moved IMPERATIVELY through the ref (no React state per    */
/* frame). Hover scrubs a ghost playhead + tooltip via direct DOM writes.     */
/*                                                                             */
/* RTL note: the band keeps `dir="ltr"` even under the Arabic locale — it is  */
/* a time axis, and time axes read left→right in this product regardless of   */
/* text direction. Labels inside stay locale-formatted.                       */
/* -------------------------------------------------------------------------- */

export interface TripReplayTimelineHandle {
  setPlayhead(ms: number): void;
}

export interface TimelinePreview {
  timeLabel: string;
  speedLabel: string;
  kmLabel: string;
}

export interface TripReplayTimelineProps {
  model: ReplayModel;
  disabled?: boolean;
  /** Click anywhere on the band — lock the playhead there. */
  onScrub: (ms: number) => void;
  /** Hover position (null = pointer left). The page ghost-follows on the map. */
  onHover: (ms: number | null) => void;
  /** Click a leg chip — fit camera to the leg + jump to its start. */
  onLegClick: (index: number) => void;
  onPinClick: (pin: ReplayEventPin) => void;
  /** Tooltip content for a hover instant (local time / speed / km so far). */
  getPreview: (ms: number) => TimelinePreview;
  className?: string;
}

const PIN_KIND_CLASS: Record<ReplayEventPin['kind'], string> = {
  delivery: 'bg-sky-500',
  stop: 'bg-amber-500',
  flag: 'bg-red-500',
};

export const TripReplayTimeline = React.forwardRef<
  TripReplayTimelineHandle,
  TripReplayTimelineProps
>(function TripReplayTimeline(
  { model, disabled = false, onScrub, onHover, onLegClick, onPinClick, getPreview, className },
  ref,
) {
  const { t, i18n } = useTranslation();
  const bandRef = React.useRef<HTMLDivElement>(null);
  const playheadRef = React.useRef<HTMLDivElement>(null);
  const ghostRef = React.useRef<HTMLDivElement>(null);
  const tooltipRef = React.useRef<HTMLDivElement>(null);
  const draggingRef = React.useRef(false);
  const [dragging, setDragging] = React.useState(false);

  const pctOf = React.useCallback(
    (ms: number) =>
      Math.min(100, Math.max(0, ((ms - model.startMs) / model.spanMs) * 100)),
    [model.startMs, model.spanMs],
  );

  React.useImperativeHandle(
    ref,
    (): TripReplayTimelineHandle => ({
      setPlayhead(ms: number) {
        const node = playheadRef.current;
        if (node) node.style.left = `${pctOf(ms)}%`;
        // Keep the slider's value in sync for AT without React re-renders.
        bandRef.current?.setAttribute('aria-valuenow', String(Math.round(ms)));
      },
    }),
    [pctOf],
  );

  /* ---- Pointer → time -------------------------------------------------- */

  const msAtClientX = React.useCallback(
    (clientX: number): number => {
      const band = bandRef.current;
      if (!band) return model.startMs;
      const rect = band.getBoundingClientRect();
      const frac = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
      return model.startMs + frac * model.spanMs;
    },
    [model.startMs, model.spanMs],
  );

  /** Direct DOM writes — pointermove fires at frame rate. */
  const showPreviewAt = (ms: number) => {
    const pct = pctOf(ms);
    if (ghostRef.current) {
      ghostRef.current.style.left = `${pct}%`;
      ghostRef.current.style.opacity = '1';
    }
    const tip = tooltipRef.current;
    if (tip) {
      const p = getPreview(ms);
      tip.textContent = `${p.timeLabel} · ${p.speedLabel} · ${p.kmLabel}`;
      tip.style.opacity = '1';
      tip.style.left = `${pct}%`;
    }
  };

  const hidePreview = () => {
    if (ghostRef.current) ghostRef.current.style.opacity = '0';
    if (tooltipRef.current) tooltipRef.current.style.opacity = '0';
  };

  /* Drag = scrub (playhead locks to the pointer, map never pans).            */
  /* Hover (mouse only, no button) = ghost preview that never fights the      */
  /* locked playhead — the page restores the locked frame on leave.           */

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    // Never let the gesture reach anything behind/around the band.
    e.stopPropagation();
    if (disabled || (e.pointerType === 'mouse' && e.button !== 0)) return;
    e.preventDefault(); // no text selection / native touch pan
    draggingRef.current = true;
    setDragging(true);
    // Keep receiving moves even when the pointer leaves the band mid-drag.
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {
      /* capture unsupported — drag still works while inside the band */
    }
    const ms = msAtClientX(e.clientX);
    showPreviewAt(ms);
    onScrub(ms);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (disabled) return;
    const ms = msAtClientX(e.clientX);
    if (draggingRef.current) {
      showPreviewAt(ms);
      onScrub(ms); // live scrub — lock the playhead as we drag
      return;
    }
    if (e.pointerType !== 'mouse') return; // no hover concept on touch/pen
    showPreviewAt(ms);
    onHover(ms);
  };

  const endDrag = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!draggingRef.current) return;
    draggingRef.current = false;
    setDragging(false);
    try {
      e.currentTarget.releasePointerCapture(e.pointerId);
    } catch {
      /* already released */
    }
    // Touch has no hover — clear the preview once the finger lifts.
    if (e.pointerType !== 'mouse') hidePreview();
  };

  const handlePointerLeave = (e: React.PointerEvent<HTMLDivElement>) => {
    if (draggingRef.current) return; // captured drag continues off-element
    hidePreview();
    if (e.pointerType === 'mouse') onHover(null);
  };

  /* ---- Static geometry (percent positions) ----------------------------- */

  const segments = React.useMemo(() => {
    const legs = model.timedLegs.map((leg) => ({
      key: `leg-${leg.id}`,
      index: leg.index,
      timedIndex: model.timedLegs.indexOf(leg),
      left: pctOf(leg.departMs!),
      width: Math.max(0.4, pctOf(leg.arriveMs!) - pctOf(leg.departMs!)),
      color: legColor(leg.legType),
      night: leg.night,
      label: `${leg.fromName} → ${leg.toName}`,
      seq: leg.seq,
    }));
    // Dwell blocks between consecutive timed legs.
    const dwellGaps: Array<{ key: string; left: number; width: number }> = [];
    for (let i = 0; i < model.timedLegs.length - 1; i++) {
      const a = model.timedLegs[i];
      const b = model.timedLegs[i + 1];
      if (b.departMs! > a.arriveMs!) {
        const left = pctOf(a.arriveMs!);
        const width = pctOf(b.departMs!) - left;
        if (width > 0.15) dwellGaps.push({ key: `gap-${a.id}`, left, width });
      }
    }
    return { legs, dwellGaps };
  }, [model, pctOf]);

  const nightBlocks = React.useMemo(
    () =>
      model.nightIntervals.map(([s, e], i) => ({
        key: `night-${i}`,
        left: pctOf(s),
        width: Math.max(0.2, pctOf(e) - pctOf(s)),
      })),
    [model.nightIntervals, pctOf],
  );

  return (
    // NOTE: dir="ltr" is intentional — the time axis stays LTR in RTL locales.
    // The band is a control surface: gestures that start here must never
    // reach the map or any ancestor drag handler.
    <div
      dir="ltr"
      className={cn('select-none px-4 pb-2 pt-5', className)}
      onPointerDown={(e) => e.stopPropagation()}
      onMouseDown={(e) => e.stopPropagation()}
      onTouchStart={(e) => e.stopPropagation()}
      onWheel={(e) => e.stopPropagation()}
    >
      <div className="relative">
        {/* Tooltip */}
        <div
          ref={tooltipRef}
          className="pointer-events-none absolute -top-6 z-30 -translate-x-1/2 whitespace-nowrap rounded-md border bg-card/95 px-2 py-0.5 text-[10px] font-medium tabular-nums text-foreground shadow-lg backdrop-blur transition-opacity"
          style={{ opacity: 0, left: '0%' }}
        />

        {/* Band */}
        <div
          ref={bandRef}
          role="slider"
          aria-label={t('tripReplay.timeline.label', 'Trip timeline')}
          aria-valuemin={model.startMs}
          aria-valuemax={model.endMs}
          aria-valuenow={model.startMs}
          aria-disabled={disabled || undefined}
          tabIndex={-1}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          onPointerLeave={handlePointerLeave}
          className={cn(
            // touch-none: the browser must never hijack the drag for scrolling.
            'relative h-9 touch-none overflow-hidden rounded-lg border bg-muted/50',
            disabled
              ? 'cursor-not-allowed opacity-40'
              : dragging
                ? 'cursor-grabbing'
                : 'cursor-grab',
          )}
        >
          {/* Dwell gaps — striped, dimmed */}
          {segments.dwellGaps.map((gap) => (
            <div
              key={gap.key}
              className="absolute inset-y-0 opacity-60"
              style={{
                left: `${gap.left}%`,
                width: `${gap.width}%`,
                backgroundImage:
                  'repeating-linear-gradient(45deg, transparent, transparent 3px, hsl(var(--muted-foreground) / 0.35) 3px, hsl(var(--muted-foreground) / 0.35) 5px)',
              }}
            />
          ))}

          {/* Leg segments */}
          {segments.legs.map((seg) => (
            <div
              key={seg.key}
              title={seg.label}
              className="absolute inset-y-1 rounded-sm opacity-80"
              style={{
                left: `${seg.left}%`,
                width: `${seg.width}%`,
                backgroundColor: seg.color,
              }}
            />
          ))}

          {/* Night shading (20:00–07:00 Cairo) */}
          {nightBlocks.map((n) => (
            <div
              key={n.key}
              className="absolute inset-y-0 bg-slate-950/35 dark:bg-black/45"
              style={{ left: `${n.left}%`, width: `${n.width}%` }}
              title={t('tripReplay.timeline.night', 'Night permit window (20:00–07:00)')}
            />
          ))}

          {/* Ghost playhead (hover) */}
          <div
            ref={ghostRef}
            className="pointer-events-none absolute inset-y-0 z-10 w-px bg-foreground/50 transition-opacity"
            style={{ opacity: 0, left: '0%' }}
          />

          {/* Playhead — moved imperatively */}
          <div
            ref={playheadRef}
            className="pointer-events-none absolute inset-y-0 z-20 w-0.5 -translate-x-1/2 bg-primary"
            style={{ left: '0%' }}
          >
            <div className="absolute -top-0.5 left-1/2 h-2 w-2 -translate-x-1/2 rounded-full bg-primary shadow" />
          </div>
        </div>

        {/* Event pins — 12px dot inside a larger invisible hit area */}
        <div className="relative mt-1 h-4">
          {model.pins.map((pin) => (
            <button
              key={pin.id}
              type="button"
              disabled={disabled}
              onClick={() => onPinClick(pin)}
              title={pin.label}
              aria-label={pin.label}
              className={cn(
                'group absolute -top-1.5 z-10 flex h-6 w-6 -translate-x-1/2 cursor-pointer items-center justify-center rounded-full',
                'after:absolute after:-inset-2 after:content-[""]', // ~40px hit
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                disabled && 'pointer-events-none opacity-40',
              )}
              style={{ left: `${pctOf(pin.ms)}%` }}
            >
              <span
                className={cn(
                  'h-3 w-3 rounded-full border border-background shadow transition-transform group-hover:scale-125',
                  PIN_KIND_CLASS[pin.kind],
                )}
              />
            </button>
          ))}
        </div>

        {/* Leg chips + start/end labels */}
        <div className="mt-1 flex items-center justify-between gap-2">
          <span className="text-[10px] font-medium tabular-nums text-muted-foreground">
            {formatCairoTime(new Date(model.startMs), i18n.language)}
          </span>
          <div className="flex flex-wrap items-center justify-center gap-1">
            {segments.legs.map((seg) => (
              <button
                key={`chip-${seg.key}`}
                type="button"
                disabled={disabled}
                onClick={() => onLegClick(seg.timedIndex)}
                title={seg.label}
                aria-label={seg.label}
                className={cn(
                  'relative flex cursor-pointer items-center gap-1 rounded-full border px-1.5 py-0.5 text-[10px] font-semibold tabular-nums transition-colors hover:bg-muted',
                  'after:absolute after:inset-x-0 after:-inset-y-2 after:content-[""]', // taller hit
                  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
                  disabled && 'pointer-events-none opacity-40',
                )}
              >
                <span
                  className="inline-block h-1.5 w-1.5 rounded-full"
                  style={{ backgroundColor: seg.color }}
                />
                {seg.seq}
                {seg.night && <Moon className="h-2.5 w-2.5 text-primary" />}
              </button>
            ))}
          </div>
          <span className="text-[10px] font-medium tabular-nums text-muted-foreground">
            {formatCairoTime(new Date(model.endMs), i18n.language)}
          </span>
        </div>
      </div>
    </div>
  );
});

