import { useTranslation } from 'react-i18next';
import type { TFunction } from 'i18next';

import type { Trip } from '@/entities/trip/schemas';
import { formatCurrency, formatNumber } from '@/shared/lib/format';
import { cn } from '@/shared/lib/cn';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { Truncate } from '@/shared/ui/truncate';

/* -------------------------------------------------------------------------- */
/* What a trip earned, and what it was charged on                              */
/*                                                                            */
/* One module because the table and the mobile list must never disagree about  */
/* a figure. Both render this; neither owns it.                                */
/* -------------------------------------------------------------------------- */

/** Companies billed on distance rather than volume. */
const DISTANCE_BILLED = new Set(['TAQA', 'Petromin']);

/**
 * Sum a revenue field across containers, preserving "not permitted".
 *
 * Undefined when no container carries the field — which is what a caller below
 * permission 4 receives, and must not become a confident zero.
 */
export function sumRevenue(
  trips: Trip[],
  key: 'revenue' | 'allocated_rental' | 'allocated_vat' | 'allocated_total',
): number | undefined {
  let total: number | undefined;
  for (const trip of trips) {
    const value = trip[key];
    if (value == null) continue;
    total = (total ?? 0) + value;
  }
  return total;
}

/**
 * What one container was charged on.
 *
 * `fee` means a different thing per company, which is why this cannot be a
 * single format string: a rate per 1,000 L for Petrol Arrows, a BAND NUMBER
 * from 1 to 15 for Watanya, and nothing at all for TAQA and Petromin, which
 * bill on distance. The rates themselves are deliberately not restated here —
 * they live in the backend's revenue module, and duplicating them on the
 * client is exactly how Go and Rust came to bill TAQA differently.
 */
export interface ChargeLine {
  key: string;
  /** e.g. "39,000 L · band 1", or "211 km" for the distance-billed companies. */
  label: string;
  /** Summed base revenue for the containers on this rate. */
  revenue?: number;
  /** How many containers collapsed into this line. */
  count: number;
}

/**
 * Containers on the SAME rate collapse into one line with volumes summed.
 *
 * A trip dropping 13,000 L and 26,000 L at the same band was charged on
 * 39,000 L at that band. Listing that as two identical-rate lines describes the
 * paperwork rather than the charge, and makes a three-drop trip look like three
 * different prices.
 */
export function chargeLines(containers: Trip[], t: TFunction): ChargeLine[] {
  const groups = new Map<
    string,
    { company: string; fee: number; litres: number; km: number; revenue?: number; count: number }
  >();

  for (const c of containers) {
    const fee = c.fee ?? 0;
    const key = `${c.company}|${fee}`;
    const g = groups.get(key) ?? { company: c.company, fee, litres: 0, km: 0, count: 0 };
    g.litres += c.tank_capacity || 0;
    g.km += c.mileage || c.distance || 0;
    g.count += 1;
    if (c.revenue != null) g.revenue = (g.revenue ?? 0) + c.revenue;
    groups.set(key, g);
  }

  return [...groups.entries()].map(([key, g]) => ({
    key,
    label: DISTANCE_BILLED.has(g.company)
      ? `${formatNumber(g.km, 0)} km`
      : g.company === 'Watanya'
        ? t('trips.revenue.atBand', { volume: formatNumber(g.litres, 0), band: g.fee })
        : t('trips.revenue.atRate', {
            volume: formatNumber(g.litres, 0),
            rate: formatNumber(g.fee, 2),
          }),
    revenue: g.revenue,
    count: g.count,
  }));
}

function Line({
  label,
  value,
  strong,
}: {
  label: React.ReactNode;
  value: string;
  strong?: boolean;
}) {
  return (
    <div className="flex items-baseline justify-between gap-4">
      <dt className={cn('min-w-0', strong ? 'font-medium' : 'text-muted-foreground')}>{label}</dt>
      <dd
        className={cn(
          'shrink-0 font-mono tabular-nums',
          strong ? 'font-semibold text-money' : 'text-foreground/90',
        )}
      >
        {value}
      </dd>
    </div>
  );
}

/**
 * The parts behind a revenue figure, with a fee line per container.
 *
 * A multi-drop trip carries different volumes to different routes and each
 * route has its own fee mapping — the real shape in production is one truck
 * dropping 13,000 L and 26,000 L at one place and 13,000 L at another. A single
 * "Fee" row cannot describe that, so every container states its own basis.
 */
/**
 * One container's revenue, pressable, with its own breakdown.
 *
 * A container earns its own money: its own base from its own volume or
 * distance, its own share of the car's rental, its own VAT. Showing the parent
 * a breakdown while its containers show bare figures made the children look
 * like a summary of the parent rather than the things being summarised.
 */
export function ContainerRevenue({ container }: { container: Trip }) {
  const { t } = useTranslation();
  if (container.allocated_total == null) {
    return <span className="text-muted-foreground">—</span>;
  }
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          onClick={(e) => e.stopPropagation()}
          aria-label={t('trips.revenue.breakdownLabel')}
          className="rounded font-mono text-[12.5px] font-semibold tabular-nums text-money
                     underline decoration-dotted underline-offset-4 hover:bg-money/10
                     focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {formatCurrency(container.allocated_total)}
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="end"
        className="w-72"
        onClick={(e) => e.stopPropagation()}
      >
        <RevenueBreakdown containers={[container]} />
      </PopoverContent>
    </Popover>
  );
}

export function RevenueBreakdown({ containers }: { containers: Trip[] }) {
  const { t } = useTranslation();

  const base = sumRevenue(containers, 'revenue') ?? 0;
  const rental = sumRevenue(containers, 'allocated_rental') ?? 0;
  const vat = sumRevenue(containers, 'allocated_vat') ?? 0;
  const total = sumRevenue(containers, 'allocated_total') ?? 0;

  // With no rental and no VAT the base IS the total, and printing both is the
  // same number twice. Petrol Arrows is always in that state, so this is the
  // common case rather than an edge one.
  const hasParts = rental !== 0 || vat !== 0;
  const lines = chargeLines(containers, t);

  return (
    <div className="text-start text-[12.5px]">
      <dl className="space-y-1">
        {hasParts && (
          <>
            <Line label={t('trips.revenue.base')} value={formatCurrency(base)} />
            {rental !== 0 && (
              <Line label={t('trips.revenue.rentalShare')} value={formatCurrency(rental)} />
            )}
            {vat !== 0 && <Line label={t('trips.revenue.vat')} value={formatCurrency(vat)} />}
          </>
        )}
        <div className={cn(hasParts && 'border-t pt-1')}>
          <Line label={t('trips.revenue.total')} value={formatCurrency(total)} strong />
        </div>
      </dl>

      <dl className="mt-2 space-y-1 border-t pt-2">
        <dt className="text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
          {t('trips.revenue.chargedOn')}
        </dt>
        {lines.map((line) => (
          <Line
            key={line.key}
            label={
              <span className="flex min-w-0 items-baseline gap-1.5">
                {line.count > 1 && (
                  <span className="shrink-0 rounded border px-1 font-mono text-[10px]">
                    ×{line.count}
                  </span>
                )}
                <Truncate dir="auto">{line.label}</Truncate>
              </span>
            }
            value={line.revenue != null ? formatCurrency(line.revenue) : '—'}
          />
        ))}
      </dl>

      {rental !== 0 && (
        <p className="mt-2 text-[11px] leading-relaxed text-muted-foreground">
          {t('trips.revenue.shareHint')}
        </p>
      )}
    </div>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import {
  ChevronRight,
  Edit3,
  ImageIcon,
  Layers,
  Map,
  Trash2,
  Truck,
  User,
} from 'lucide-react';

import type { Trip } from '@/entities/trip/schemas';
import { Card } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Skeleton } from '@/shared/ui/skeleton';
import { EmptyState } from '@/shared/ui/empty-state';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { format, formatCurrency, formatNumber } from '@/shared/lib/format';
import { cn } from '@/shared/lib/cn';
import { useQueryClient } from '@tanstack/react-query';
import { intentProps, warmTripForm } from '@/shared/lib/prefetch';
import { prefetchParentContainers, prefetchTripDetails } from '@/entities/trip/queries';
import { Truncate } from '@/shared/ui/truncate';
import { ReceiptStatusBadge } from './receipt-status-badge';
import { ContainerRevenue, RevenueBreakdown } from './revenue-breakdown';
import { DROP_SEPARATOR, type TripRow } from './trip-row';

/* -------------------------------------------------------------------------- */
/* The trips table                                                             */
/*                                                                            */
/* Rebuilt on one rule: alignment encodes the kind of value. Text starts,      */
/* figures end, status centres. The table this replaces aligned tank, distance */
/* and fee three different ways, so the eye had no column to follow down, and  */
/* mixed four padding scales between the header and the body.                  */
/*                                                                            */
/* Nine columns, and no tenth: at permission 4 the Distance cell's second line */
/* becomes REVENUE and the fee moves into its popover. An extra column crushed */
/* the route and vehicle cells on a laptop, and revenue is the number people   */
/* come to this page for while `fee` is only an input to it — for Watanya not  */
/* even money, but a band from 1 to 15.                                        */
/* -------------------------------------------------------------------------- */

export interface TripsDesktopTableProps {
  rows: TripRow[];
  loading: boolean;
  showRevenue: boolean;
  onDelete: (id: number) => void;
  onOpenReceipt: (id: number) => void;
  onOpenMap: (id: number) => void;
  onDeleteParent: (parentId: number, count: number) => void;
  onOpenReceiptBatch: (parentId: number) => void;
  emptyAction?: React.ReactNode;
}

/** Column count, for the expanded row's colSpan. */
const COLUMNS = 9;

export function TripsDesktopTable({
  rows,
  loading,
  showRevenue,
  onDelete,
  onOpenReceipt,
  onOpenMap,
  onDeleteParent,
  onOpenReceiptBatch,
  emptyAction,
}: TripsDesktopTableProps) {
  const { t } = useTranslation();
  const [expanded, setExpanded] = React.useState<string | null>(null);

  if (!loading && rows.length === 0) {
    return <EmptyState title={t('trips.empty.title')} action={emptyAction} />;
  }

  return (
    <Card className="overflow-hidden">
      <div className="w-full overflow-x-auto">
        <table className="w-full caption-bottom border-collapse text-sm">
          <thead>
            <tr className="border-b bg-muted/40 text-[10.5px] uppercase tracking-wider text-muted-foreground">
              <Th className="w-9" srOnly>
                {t('trips.columns.expand', { defaultValue: 'Expand' })}
              </Th>
              <Th>{t('trips.columns.receipt')}</Th>
              <Th className="hidden md:table-cell">{t('trips.columns.date')}</Th>
              <Th className="hidden lg:table-cell">{t('trips.columns.company')}</Th>
              <Th className="hidden lg:table-cell">{t('trips.columns.route')}</Th>
              <Th className="hidden md:table-cell">{t('trips.columns.vehicleDriver')}</Th>
              <Th align="end" className="hidden xl:table-cell">
                {t('trips.columns.tank')}
              </Th>
              <Th align="end" className="hidden lg:table-cell">
                {t('trips.columns.distanceFee')}
              </Th>
              <Th align="center" className="hidden md:table-cell">
                {t('trips.columns.status')}
              </Th>
              <Th align="end">{t('trips.columns.actions')}</Th>
            </tr>
          </thead>
          <tbody>
            {loading && rows.length === 0
              ? Array.from({ length: 8 }).map((_, i) => <SkeletonRow key={i} />)
              : rows.map((row) => (
                  <Row
                    key={row.key}
                    row={row}
                    showRevenue={showRevenue}
                    isExpanded={expanded === row.key}
                    onToggle={() => setExpanded((k) => (k === row.key ? null : row.key))}
                    onDelete={onDelete}
                    onOpenReceipt={onOpenReceipt}
                    onOpenMap={onOpenMap}
                    onDeleteParent={onDeleteParent}
                    onOpenReceiptBatch={onOpenReceiptBatch}
                  />
                ))}
          </tbody>
        </table>
      </div>
    </Card>
  );
}

/* -------------------------------------------------------------------------- */
/* Header cell                                                                 */
/* -------------------------------------------------------------------------- */

function Th({
  children,
  align = 'start',
  className,
  srOnly,
}: {
  children: React.ReactNode;
  align?: 'start' | 'end' | 'center';
  className?: string;
  srOnly?: boolean;
}) {
  return (
    <th
      scope="col"
      className={cn(
        'h-10 whitespace-nowrap px-3 font-semibold',
        align === 'start' && 'text-start',
        align === 'end' && 'text-end',
        align === 'center' && 'text-center',
        className,
      )}
    >
      {srOnly ? <span className="sr-only">{children}</span> : children}
    </th>
  );
}

/** One body cell, on the single padding scale the whole table uses. */
function Td({
  children,
  align = 'start',
  className,
}: {
  children?: React.ReactNode;
  align?: 'start' | 'end' | 'center';
  className?: string;
}) {
  return (
    <td
      className={cn(
        'px-3 py-2.5 align-middle',
        align === 'start' && 'text-start',
        align === 'end' && 'text-end',
        align === 'center' && 'text-center',
        className,
      )}
    >
      {children}
    </td>
  );
}

/* -------------------------------------------------------------------------- */
/* Row                                                                         */
/* -------------------------------------------------------------------------- */

function Row({
  row,
  showRevenue,
  isExpanded,
  onToggle,
  onDelete,
  onOpenReceipt,
  onOpenMap,
  onDeleteParent,
  onOpenReceiptBatch,
}: {
  row: TripRow;
  showRevenue: boolean;
  isExpanded: boolean;
  onToggle: () => void;
} & Pick<
  TripsDesktopTableProps,
  'onDelete' | 'onOpenReceipt' | 'onOpenMap' | 'onDeleteParent' | 'onOpenReceiptBatch'
>) {
  const { t } = useTranslation();
  const { head, containers, isGroup } = row;

  return (
    <>
      <tr
        onClick={onToggle}
        className={cn(
          'cursor-pointer border-b transition-colors hover:bg-muted/40',
          isExpanded && 'bg-muted/30',
        )}
      >
        <Td align="center">
          <ChevronRight
            aria-hidden
            className={cn(
              'h-4 w-4 text-muted-foreground transition-transform',
              isExpanded && 'rotate-90',
            )}
          />
        </Td>

        <Td>
          <div className="flex items-center gap-2">
            {isGroup && (
              <span
                className="inline-flex shrink-0 items-center gap-1 rounded bg-accent px-1.5
                           text-[10px] font-semibold text-accent-foreground"
                title={t('trips.mobile.containers', { count: containers.length })}
              >
                <Layers className="h-3 w-3" />
                {containers.length}
              </span>
            )}
            {/* A group has no receipt of its own — each container carries
                one, and showing the first child's number would present one
                trip's paperwork as the whole group's. The numbers themselves
                are one click away in the expanded list. */}
            {row.receiptNo ? (
              <span className="font-mono text-[13px] font-medium tabular-nums">
                #{row.receiptNo}
              </span>
            ) : (
              <span className="whitespace-nowrap text-[12.5px] text-muted-foreground">
                {t('trips.mobile.receiptCount', { count: containers.length })}
              </span>
            )}
          </div>
        </Td>

        <Td className="hidden whitespace-nowrap font-mono text-[12.5px] tabular-nums md:table-cell">
          {format(row.date, 'd MMM yyyy')}
        </Td>

        <Td className="hidden max-w-[130px] lg:table-cell">
          <Truncate className="text-[13px]">{row.company}</Truncate>
        </Td>

        <Td className="hidden max-w-[230px] lg:table-cell">
          <Route origin={row.origin} drops={row.drops} />
        </Td>

        <Td className="hidden max-w-[180px] md:table-cell">
          <VehicleDriver trip={head} />
        </Td>

        <Td align="end" className="hidden whitespace-nowrap font-mono text-[12.5px] tabular-nums xl:table-cell">
          {formatNumber(row.litres, 0)} L
        </Td>

        <Td align="end" className="hidden lg:table-cell">
          <DistanceMoney row={row} showRevenue={showRevenue} />
        </Td>

        <Td align="center" className="hidden md:table-cell">
          {isGroup ? (
            <span className="text-xs text-muted-foreground">—</span>
          ) : (
            <ReceiptStatusBadge trip={head} />
          )}
        </Td>

        <Td align="end">
          <RowActions
            row={row}
            onDelete={onDelete}
            onOpenReceipt={onOpenReceipt}
            onOpenMap={onOpenMap}
            onDeleteParent={onDeleteParent}
            onOpenReceiptBatch={onOpenReceiptBatch}
          />
        </Td>
      </tr>

      {isExpanded && (
        <tr className="border-b bg-muted/20">
          <td colSpan={COLUMNS + 1} className="px-3 py-3">
            <Expanded row={row} showRevenue={showRevenue} onOpenReceipt={onOpenReceipt} onOpenMap={onOpenMap} />
          </td>
        </tr>
      )}
    </>
  );
}

/* -------------------------------------------------------------------------- */
/* Cells                                                                       */
/* -------------------------------------------------------------------------- */

/** Origin to destination on one line. Two stacked lines read as two unrelated
 *  places rather than a journey, and cost a second line of height to do it. */
function Route({ origin, drops }: { origin: string; drops: string[] }) {
  const to = drops.join(DROP_SEPARATOR);
  return (
    <div className="flex items-center gap-1.5 text-[13px]">
      <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-success" aria-hidden />
      <Truncate dir="auto">{origin}</Truncate>
      <span className="shrink-0 text-muted-foreground" aria-hidden>
        →
      </span>
      <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-destructive" aria-hidden />
      <Truncate dir="auto">{to}</Truncate>
    </div>
  );
}

function VehicleDriver({ trip }: { trip: Trip }) {
  return (
    <div className="min-w-0 space-y-0.5">
      <div className="flex items-center gap-1.5">
        <Truck className="h-3.5 w-3.5 shrink-0 text-muted-foreground" aria-hidden />
        <Truncate className="font-mono text-[12.5px]" dir="auto">
          {trip.car_no_plate}
        </Truncate>
      </div>
      <div className="flex items-center gap-1.5 text-[11.5px] text-muted-foreground">
        <User className="h-3 w-3 shrink-0" aria-hidden />
        <Truncate dir="auto">{trip.driver_name}</Truncate>
      </div>
    </div>
  );
}

/**
 * Distance over money.
 *
 * Below permission 4 the second line is the fee, exactly as it always was.
 * At permission 4 it is revenue, pressable, with the fee inside the breakdown.
 */
function DistanceMoney({ row, showRevenue }: { row: TripRow; showRevenue: boolean }) {
  const { t } = useTranslation();
  const canSee = showRevenue && row.revenue != null;

  return (
    <div className="space-y-0.5">
      {/* A furthest-drop figure for a multi-drop trip, not a total, and
          labelled so nobody reads it as one. */}
      <div
        className="whitespace-nowrap font-mono text-[12.5px] tabular-nums"
        title={row.kmIsMax ? t('trips.mobile.maxDistanceHint') : undefined}
      >
        {row.kmIsMax
          ? t('trips.mobile.maxDistance', { km: formatNumber(row.km, 1) })
          : `${formatNumber(row.km, 1)} km`}
      </div>
      {canSee ? (
        <Popover>
          <PopoverTrigger asChild>
            <button
              type="button"
              onClick={(e) => e.stopPropagation()}
              aria-label={t('trips.revenue.breakdownLabel')}
              className="w-full whitespace-nowrap rounded text-end font-mono text-[12.5px]
                         font-semibold tabular-nums text-money underline decoration-dotted
                         underline-offset-4 hover:bg-money/10 focus-visible:outline-none
                         focus-visible:ring-2 focus-visible:ring-ring"
            >
              {formatCurrency(row.revenue!)}
            </button>
          </PopoverTrigger>
          <PopoverContent
            align="end"
            className="w-72 bg-popover text-popover-foreground shadow-lg"
            onClick={(e) => e.stopPropagation()}
          >
            <RevenueBreakdown containers={row.containers} />
          </PopoverContent>
        </Popover>
      ) : (
        <div className="whitespace-nowrap font-mono text-[12.5px] font-semibold tabular-nums text-money">
          {formatCurrency(row.fee)}
        </div>
      )}
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Expanded                                                                    */
/* -------------------------------------------------------------------------- */

function Expanded({
  row,
  showRevenue,
  onOpenReceipt,
  onOpenMap,
}: {
  row: TripRow;
  showRevenue: boolean;
  onOpenReceipt: (id: number) => void;
  onOpenMap: (id: number) => void;
}) {
  const { t } = useTranslation();

  if (!row.isGroup) {
    return (
      <dl className="grid grid-cols-2 gap-x-8 gap-y-2 text-[12.5px] sm:grid-cols-4">
        <Field label={t('trips.fields.driver')}>{row.head.driver_name}</Field>
        <Field label={t('trips.fields.vehicle')}>{row.head.car_no_plate}</Field>
        <Field label={t('trips.columns.tank')}>{formatNumber(row.litres, 0)} L</Field>
        <Field label={t('trips.fields.gasType')}>{row.head.gas_type || '—'}</Field>
      </dl>
    );
  }

  // Every container with its own revenue. Repeating the parent's figure on each
  // child would be a lie: containers differ in volume, destination and earnings.
  return (
    <div>
      <p className="mb-2 flex items-center gap-1.5 text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
        <Layers className="h-3 w-3" aria-hidden />
        {t('trips.mobile.containers', { count: row.containers.length })}
      </p>
      {/* A list, not a table. The drop-off is Arabic and the receipt number is
          Latin digits; side by side in a squeezed cell they read in opposite
          directions and the name truncated on every row. The name now owns its
          line and everything measurable sits underneath it. */}
      <ul className="divide-y">
        {row.containers.map((c, i) => (
          <li key={c.ID} className="py-2 first:pt-0 last:pb-0">
            <div className="flex items-baseline gap-2">
              <span className="shrink-0 rounded border px-1 font-mono text-[10px] text-muted-foreground">
                {i + 1}
              </span>
              <Truncate className="text-[13px] font-medium" dir="auto">
                {c.drop_off_point}
              </Truncate>
            </div>

            <div className="mt-1 flex flex-wrap items-center justify-between gap-x-5 gap-y-1 ps-7">
              <span className="flex items-center gap-4 text-[12px] text-muted-foreground">
                <span className="font-mono tabular-nums">#{c.receipt_no || '—'}</span>
                <span className="font-mono tabular-nums">
                  {formatNumber(c.tank_capacity || 0, 0)} L
                </span>
                {/* Each container's OWN distance. The row above shows the
                    trip's furthest drop; these are the individual drops that
                    the furthest one is the maximum of. */}
                <span className="font-mono tabular-nums">
                  {formatNumber(c.mileage || c.distance || 0, 0)} km
                </span>
                <ReceiptStatusBadge trip={c} compact />
              </span>

              <span className="flex items-center gap-2">
                {showRevenue && <ContainerRevenue container={c} />}
                <IconButton
                  label={t('trips.actions.manageReceipts')}
                  onClick={() => onOpenReceipt(c.ID)}
                >
                  <ImageIcon className="h-3.5 w-3.5" />
                </IconButton>
                <IconButton label={t('trips.actions.viewOnMap')} onClick={() => onOpenMap(c.ID)}>
                  <Map className="h-3.5 w-3.5" />
                </IconButton>
              </span>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="min-w-0">
      <dt className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">
        {label}
      </dt>
      <dd className="mt-0.5 font-medium">
        <Truncate dir="auto">{children}</Truncate>
      </dd>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Actions                                                                     */
/* -------------------------------------------------------------------------- */

function IconButton({
  children,
  label,
  onClick,
  danger,
}: {
  children: React.ReactNode;
  label: string;
  onClick: () => void;
  danger?: boolean;
}) {
  return (
    <Button
      variant="ghost"
      size="icon"
      aria-label={label}
      title={label}
      className={cn('h-7 w-7', danger && 'text-destructive hover:text-destructive')}
      onClick={(e) => {
        e.stopPropagation();
        onClick();
      }}
    >
      {children}
    </Button>
  );
}

function RowActions({
  row,
  onDelete,
  onOpenReceipt,
  onOpenMap,
  onDeleteParent,
  onOpenReceiptBatch,
}: { row: TripRow } & Pick<
  TripsDesktopTableProps,
  'onDelete' | 'onOpenReceipt' | 'onOpenMap' | 'onDeleteParent' | 'onOpenReceiptBatch'
>) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { head, containers, isGroup, parentId } = row;
  // The ONLY trip edit route is trips/multi-container/:parentId/edit. There is
  // no trips/:id/edit, so a standalone trip has nowhere to go and gets no edit
  // action rather than a link to a 404.
  const editPath =
    parentId != null ? `/trips/multi-container/${parentId}/edit` : null;

  // Intent: the edit page mounts the parent's containers; the map dialog
  // mounts the trip details. Warm each when the cursor reaches its control,
  // so the click opens onto data already in cache.
  const warmEdit = () => {
    warmTripForm(queryClient, 'trip-edit');
    if (parentId != null) prefetchParentContainers(queryClient, parentId);
  };
  const warmMap = () => prefetchTripDetails(queryClient, head.ID);

  return (
    <div className="flex items-center justify-end gap-1">
      {isGroup && parentId != null && (
        <IconButton
          label={t('trips.actions.viewReceiptBatch')}
          onClick={() => onOpenReceiptBatch(parentId)}
        >
          <ImageIcon className="h-3.5 w-3.5" />
        </IconButton>
      )}
      {!isGroup && (
        <>
          <IconButton label={t('trips.actions.manageReceipts')} onClick={() => onOpenReceipt(head.ID)}>
            <ImageIcon className="h-3.5 w-3.5" />
          </IconButton>
          <span {...intentProps(warmMap)} className="contents">
            <IconButton label={t('trips.actions.viewOnMap')} onClick={() => onOpenMap(head.ID)}>
              <Map className="h-3.5 w-3.5" />
            </IconButton>
          </span>
        </>
      )}
      {editPath && (
        <Button
          variant="ghost"
          size="icon"
          asChild
          className="h-7 w-7"
          onClick={(e) => e.stopPropagation()}
          {...intentProps(warmEdit)}
        >
          <Link to={editPath} aria-label={t('common.edit')} title={t('common.edit')}>
            <Edit3 className="h-3.5 w-3.5" />
          </Link>
        </Button>
      )}
      <IconButton
        danger
        label={t('common.delete')}
        onClick={() =>
          isGroup && parentId != null
            ? onDeleteParent(parentId, containers.length)
            : onDelete(head.ID)
        }
      >
        <Trash2 className="h-3.5 w-3.5" />
      </IconButton>
    </div>
  );
}

function SkeletonRow() {
  return (
    <tr className="border-b">
      {Array.from({ length: COLUMNS + 1 }).map((_, i) => (
        <td key={i} className="px-3 py-2.5">
          <Skeleton className="h-4 w-full" />
        </td>
      ))}
    </tr>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import {
  AlertCircle,
  Archive,
  Building2,
  CheckCircle2,
  Clock,
  Filter,
  MapPinOff,
  UserMinus,
  X,
} from 'lucide-react';
import { cn } from '@/shared/lib/cn';
import { Button } from '@/shared/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { SearchableSelect } from '@/shared/ui/searchable-select';
import type {
  MissingDataFilter,
  ReceiptStatusFilter,
} from '@/entities/trip/schemas';

/* -------------------------------------------------------------------------- */
/* Company filter                                                              */
/*                                                                             */
/* Wraps SearchableSelect so the trips toolbar gets a single-line picker that  */
/* matches the SelectableSelect pattern used elsewhere — empty string means    */
/* "all companies".                                                            */
/* -------------------------------------------------------------------------- */

interface CompanyFilterProps {
  value: string;
  onChange: (value: string) => void;
  companies: string[];
}

export function TripsCompanyFilter({ value, onChange, companies }: CompanyFilterProps) {
  const { t } = useTranslation();

  const options = React.useMemo(
    () => [
      { value: '', label: t('trips.filters.allCompanies') },
      ...companies.map((c) => ({ value: c, label: c })),
    ],
    [companies, t],
  );

  return (
    <div className="inline-flex h-9 min-w-[180px] items-center">
      <SearchableSelect
        options={options}
        value={value}
        onChange={(v) => onChange(String(v))}
        placeholder={t('trips.filters.allCompanies')}
        className="h-9 text-xs"
      />
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Missing-data filter — popover with three checkbox-like options              */
/* -------------------------------------------------------------------------- */

const MISSING_OPTIONS: Array<{
  value: Exclude<MissingDataFilter, ''>;
  labelKey: string;
  icon: React.ComponentType<{ className?: string }>;
}> = [
  { value: 'driver', labelKey: 'trips.filters.missingDriver', icon: UserMinus },
  { value: 'route', labelKey: 'trips.filters.missingRoute', icon: MapPinOff },
  { value: 'any', labelKey: 'trips.filters.missingAny', icon: AlertCircle },
];

interface MissingDataFilterProps {
  value: MissingDataFilter;
  onChange: (value: MissingDataFilter) => void;
}

export function TripsMissingDataFilter({ value, onChange }: MissingDataFilterProps) {
  const { t } = useTranslation();
  const [open, setOpen] = React.useState(false);
  const active = value !== '';
  const activeMeta = MISSING_OPTIONS.find((o) => o.value === value);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant={active ? 'default' : 'outline'}
          size="sm"
          className="h-9 gap-1.5"
        >
          <Filter className="h-3.5 w-3.5" />
          <span className="hidden sm:inline">
            {active && activeMeta
              ? t(activeMeta.labelKey)
              : t('trips.filters.missingData')}
          </span>
          {active && (
            <span className="inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-primary-foreground px-1 text-[10px] font-semibold text-primary">
              1
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-56 p-2">
        <div className="flex items-center justify-between px-2 py-1.5">
          <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
            {t('trips.filters.missingData')}
          </p>
          {active && (
            <button
              type="button"
              onClick={() => {
                onChange('');
                setOpen(false);
              }}
              className="inline-flex items-center gap-0.5 text-[11px] text-muted-foreground hover:text-foreground"
            >
              <X className="h-3 w-3" />
              {t('common.clear')}
            </button>
          )}
        </div>
        <ul className="space-y-0.5">
          {MISSING_OPTIONS.map((opt) => {
            const selected = opt.value === value;
            const Icon = opt.icon;
            return (
              <li key={opt.value}>
                <button
                  type="button"
                  onClick={() => {
                    onChange(selected ? '' : opt.value);
                    setOpen(false);
                  }}
                  className={cn(
                    'flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm transition-colors',
                    selected
                      ? 'bg-accent text-accent-foreground'
                      : 'hover:bg-accent/60',
                  )}
                >
                  <Icon className="h-3.5 w-3.5 text-muted-foreground" />
                  <span className="flex-1 text-start">{t(opt.labelKey)}</span>
                  {selected && (
                    <CheckCircle2 className="h-3.5 w-3.5 text-primary" />
                  )}
                </button>
              </li>
            );
          })}
        </ul>
      </PopoverContent>
    </Popover>
  );
}

/* -------------------------------------------------------------------------- */
/* Receipt-status filter — segmented control (all / pending / garage / office) */
/* -------------------------------------------------------------------------- */

interface ReceiptStatusControlProps {
  value: ReceiptStatusFilter;
  onChange: (value: ReceiptStatusFilter) => void;
}

const RECEIPT_STATUS_OPTIONS: Array<{
  value: ReceiptStatusFilter;
  labelKey: string;
  /** Shown below sm, where the full wording wraps inside its own chip. */
  shortKey: string;
  icon?: React.ComponentType<{ className?: string }>;
}> = [
  { value: '', labelKey: 'trips.filters.allReceipts', shortKey: 'trips.filters.short.all' },
  { value: 'pending', labelKey: 'trips.receiptStatus.pending', shortKey: 'trips.filters.short.pending', icon: Clock },
  { value: 'in_garage', labelKey: 'trips.receiptStatus.inGarage', shortKey: 'trips.filters.short.garage', icon: Archive },
  { value: 'in_office', labelKey: 'trips.receiptStatus.inOffice', shortKey: 'trips.filters.short.office', icon: Building2 },
];

export function TripsReceiptStatusControl({
  value,
  onChange,
}: ReceiptStatusControlProps) {
  const { t } = useTranslation();

  return (
    <div
      // Height is auto, not h-9. Fixed height plus wrapping labels is what
      // burst this control open: the words wrapped inside each chip, the chip
      // grew past its parent, and the whole thing looked broken.
      className="inline-flex max-w-full flex-wrap items-center gap-0.5 rounded-md border bg-muted/40 p-0.5"
      role="tablist"
      aria-label={t('trips.filters.receiptStatus')}
    >
      {RECEIPT_STATUS_OPTIONS.map((opt) => {
        const Icon = opt.icon;
        const active = opt.value === value;
        return (
          <button
            key={opt.value || 'all'}
            type="button"
            role="tab"
            aria-selected={active}
            onClick={() => onChange(opt.value)}
            className={cn(
              'inline-flex h-7 shrink-0 items-center gap-1.5 whitespace-nowrap rounded px-2.5',
              'text-xs font-medium transition-colors',
              active
                ? 'bg-background text-foreground shadow-sm'
                : 'text-muted-foreground hover:text-foreground',
            )}
          >
            {Icon && <Icon className="h-3 w-3 shrink-0" />}
            <span className="sm:hidden">{t(opt.shortKey)}</span>
            <span className="hidden sm:inline">{t(opt.labelKey)}</span>
          </button>
        );
      })}
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* URL serialization                                                           */
/*                                                                             */
/* Single-letter codes keep the URL short. Inverse parsers default to ''/all. */
/* -------------------------------------------------------------------------- */

export function serializeMissing(value: MissingDataFilter): string | null {
  if (value === '') return null;
  return value[0]; // 'd' / 'r' / 'a'
}

export function parseMissing(raw: string | null): MissingDataFilter {
  if (raw === 'd') return 'driver';
  if (raw === 'r') return 'route';
  if (raw === 'a') return 'any';
  return '';
}

export function serializeReceiptStatus(value: ReceiptStatusFilter): string | null {
  if (value === '') return null;
  if (value === 'pending') return 'p';
  if (value === 'in_garage') return 'g';
  if (value === 'in_office') return 'o';
  return null;
}

export function parseReceiptStatus(raw: string | null): ReceiptStatusFilter {
  if (raw === 'p') return 'pending';
  if (raw === 'g') return 'in_garage';
  if (raw === 'o') return 'in_office';
  return '';
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  MoreHorizontal,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { cn } from '@/shared/lib/cn';

interface TripsPaginationProps {
  page: number;
  pages: number;
  total: number;
  limit: number;
  onPageChange: (page: number) => void;
  /**
   * Intent prefetch: fired when the user hovers/focuses/touches a page
   * control, BEFORE clicking it. The page passes a warmer that fetches that
   * page's exact query, so the click renders from cache. Optional — pages
   * that haven't wired a warmer paginate exactly as before.
   */
  onIntendPage?: (page: number) => void;
  onLimitChange: (limit: number) => void;
  loading?: boolean;
  className?: string;
}

const LIMIT_OPTIONS = [10, 25, 50, 100];

/**
 * Server-side pagination strip.
 *
 *   - Per-page selector (10 / 25 / 50 / 100)
 *   - Page numbers with ellipsis for long ranges
 *   - Jump-to-page input (lg+ only, when pages > 5)
 *   - Mobile collapses to "page X of Y" + prev/next
 *
 * All chevrons RTL-flip via Tailwind's `rtl:rotate-180` so Arabic users get
 * the expected direction without a separate component.
 */
export function TripsPagination({
  page,
  pages,
  total,
  limit,
  onPageChange,
  onIntendPage,
  onLimitChange,
  loading,
  className,
}: TripsPaginationProps) {
  const { t } = useTranslation();
  const [jumpValue, setJumpValue] = React.useState('');

  // One intent-spread per target page. Cheap to repeat: the warmer dedupes.
  const intend = (target: number) =>
    onIntendPage && target >= 1 && target <= pages && target !== page
      ? {
          onPointerEnter: () => onIntendPage(target),
          onFocus: () => onIntendPage(target),
          onTouchStart: () => onIntendPage(target),
        }
      : {};

  // Don't render at all when there's nothing to paginate AND results fit in
  // the smallest page size — keeps short-list pages clean.
  if (pages <= 1 && total <= LIMIT_OPTIONS[0]) return null;

  const startItem = total > 0 ? (page - 1) * limit + 1 : 0;
  const endItem = Math.min(page * limit, total);

  const handleJump = () => {
    const n = parseInt(jumpValue, 10);
    if (Number.isFinite(n) && n >= 1 && n <= pages) {
      onPageChange(n);
      setJumpValue('');
    }
  };

  return (
    <div
      className={cn(
        'flex flex-col gap-3 rounded-lg border bg-card p-3 sm:flex-row sm:items-center sm:justify-between',
        className,
      )}
    >
      {/* Left: results count + per-page selector */}
      <div className="flex items-center gap-3 text-xs text-muted-foreground">
        <span className="tabular-nums">
          <span className="font-medium text-foreground">{startItem}</span>–
          <span className="font-medium text-foreground">{endItem}</span>{' '}
          {t('trips.pagination.of')}{' '}
          <span className="font-medium text-foreground">{total}</span>
        </span>
        <div className="hidden items-center gap-1.5 sm:flex">
          <span>·</span>
          <span>{t('trips.pagination.perPage')}:</span>
          <Select
            value={String(limit)}
            onValueChange={(v) => onLimitChange(Number(v))}
            disabled={loading}
          >
            <SelectTrigger className="h-7 w-[70px] text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {LIMIT_OPTIONS.map((opt) => (
                <SelectItem key={opt} value={String(opt)}>
                  {opt}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Right: page navigation */}
      <div className="flex items-center gap-1.5">
        {pages > 5 && (
          <div className="hidden items-center gap-1.5 lg:flex">
            <span className="text-xs text-muted-foreground">
              {t('trips.pagination.goTo')}:
            </span>
            <Input
              type="number"
              min={1}
              max={pages}
              value={jumpValue}
              onChange={(e) => setJumpValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleJump();
              }}
              placeholder={String(page)}
              className="h-7 w-16 text-xs"
            />
            <Button
              size="sm"
              variant="ghost"
              className="h-7 px-2 text-xs"
              disabled={!jumpValue || loading}
              onClick={handleJump}
            >
              {t('trips.pagination.go')}
            </Button>
            <span className="text-xs text-muted-foreground">·</span>
          </div>
        )}

        <div className="flex items-center gap-0.5">
          <Button
            size="icon"
            variant="ghost"
            className="hidden h-8 w-8 sm:inline-flex"
            disabled={page === 1 || loading}
            onClick={() => onPageChange(1)}
            {...intend(1)}
            aria-label={t('trips.pagination.firstPage')}
          >
            <ChevronsLeft className="h-4 w-4 rtl:rotate-180" />
          </Button>
          <Button
            size="icon"
            variant="ghost"
            className="h-8 w-8"
            disabled={page === 1 || loading}
            onClick={() => onPageChange(page - 1)}
            {...intend(page - 1)}
            aria-label={t('trips.pagination.previousPage')}
          >
            <ChevronLeft className="h-4 w-4 rtl:rotate-180" />
          </Button>
          <div className="hidden items-center gap-0.5 sm:flex">
            {getPageNumbers(page, pages).map((entry, i) =>
              entry === 'ellipsis' ? (
                <span
                  key={`e-${i}`}
                  className="inline-flex h-8 w-8 items-center justify-center text-muted-foreground"
                >
                  <MoreHorizontal className="h-4 w-4" />
                </span>
              ) : (
                <Button
                  key={entry}
                  size="icon"
                  variant={entry === page ? 'default' : 'ghost'}
                  className="h-8 w-8 text-xs tabular-nums"
                  onClick={() => onPageChange(entry)}
                  {...intend(entry)}
                  disabled={loading}
                >
                  {entry}
                </Button>
              ),
            )}
          </div>
          <span className="px-2 text-xs tabular-nums sm:hidden">
            {page} / {pages}
          </span>
          <Button
            size="icon"
            variant="ghost"
            className="h-8 w-8"
            disabled={page === pages || loading}
            onClick={() => onPageChange(page + 1)}
            {...intend(page + 1)}
            aria-label={t('trips.pagination.nextPage')}
          >
            <ChevronRight className="h-4 w-4 rtl:rotate-180" />
          </Button>
          <Button
            size="icon"
            variant="ghost"
            className="hidden h-8 w-8 sm:inline-flex"
            disabled={page === pages || loading}
            onClick={() => onPageChange(pages)}
            {...intend(pages)}
            aria-label={t('trips.pagination.lastPage')}
          >
            <ChevronsRight className="h-4 w-4 rtl:rotate-180" />
          </Button>
        </div>
      </div>
    </div>
  );
}

/**
 * Compute which page numbers to show, with 'ellipsis' markers for long ranges.
 * Output stays under ~7 entries to keep the bar visually quiet.
 */
function getPageNumbers(current: number, total: number): Array<number | 'ellipsis'> {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  if (current <= 4) {
    return [1, 2, 3, 4, 5, 'ellipsis', total];
  }
  if (current >= total - 3) {
    return [1, 'ellipsis', total - 4, total - 3, total - 2, total - 1, total];
  }
  return [1, 'ellipsis', current - 1, current, current + 1, 'ellipsis', total];
}

import * as React from 'react';

import { groupTrips, type Trip, type TripListItem } from '@/entities/trip/schemas';
import { useIsMobile } from '@/shared/hooks/use-media-query';
import { usePermissions } from '@/shared/hooks/use-permissions';
import { PERMISSION_LEVELS } from '@/shared/config/constants';
import { toRow, type TripRow } from './trip-row';
import { TripsDesktopTable } from './trips-desktop-table';
import { TripsMobileList } from './trips-mobile-list';

/* -------------------------------------------------------------------------- */
/* Trips list                                                                  */
/*                                                                            */
/* A switch, and nothing else. Both surfaces render the same TripRow model     */
/* (see trip-row.ts), so the only difference between them is presentation —    */
/* which is what stops them disagreeing about what a row means. This file used */
/* to be a thousand lines carrying two full implementations that had already   */
/* drifted apart.                                                              */
/* -------------------------------------------------------------------------- */

export interface TripsTableProps {
  trips: Trip[];
  loading: boolean;

  onDelete: (id: number) => void;
  onOpenReceipt: (id: number) => void;
  onOpenMap: (id: number) => void;

  onDeleteParent: (parentId: number, count: number) => void;
  onOpenReceiptBatch: (parentId: number) => void;

  /** Usually the "Add trip" link. */
  emptyAction?: React.ReactNode;
}

export function TripsTable({
  trips,
  loading,
  onDelete,
  onOpenReceipt,
  onOpenMap,
  onDeleteParent,
  onOpenReceiptBatch,
  emptyAction,
}: TripsTableProps) {
  const isMobile = useIsMobile();

  // Permission 4 sees money. The backend omits those fields below that level,
  // so this only decides whether the UI offers them — a caller without the
  // permission never receives a figure that some layer above must remember to
  // strip.
  const { atLeast } = usePermissions();
  const showRevenue = atLeast(PERMISSION_LEVELS.ADMIN);

  const rows = React.useMemo<TripRow[]>(() => {
    const items: TripListItem[] = groupTrips(trips);
    return items
      .map(toRow)
      .filter((row): row is TripRow => row !== null)
      // Newest first, then by receipt — the server's ordering, so a page
      // boundary does not reshuffle rows the user was looking at.
      .sort(
        (a, b) =>
          b.date.localeCompare(a.date) ||
          (b.head.receipt_no ?? '').localeCompare(a.head.receipt_no ?? ''),
      );
  }, [trips]);

  const shared = {
    rows,
    loading,
    showRevenue,
    onDelete,
    onOpenReceipt,
    onOpenMap,
    onDeleteParent,
    onOpenReceiptBatch,
    emptyAction,
  };

  return isMobile ? <TripsMobileList {...shared} /> : <TripsDesktopTable {...shared} />;
}

import * as React from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useTranslation } from 'react-i18next';
import { Eye, EyeOff, Loader2 } from 'lucide-react';
import {
  userCreateSchema,
  userUpdateSchema,
  type User,
} from '@/entities/user/schemas';
import { Button } from '@/shared/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/shared/ui/dialog';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/shared/ui/form';
import { Input } from '@/shared/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';

interface UserFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  user?: User | null;
  onSubmit: (data: any) => Promise<void>;
  loading?: boolean;
}

export function UserFormDialog({
  open,
  onOpenChange,
  user,
  onSubmit,
  loading,
}: UserFormDialogProps) {
  const { t } = useTranslation();
  const [showPassword, setShowPassword] = React.useState(false);
  const isEdit = !!user;

  const form = useForm<any>({
    resolver: zodResolver(isEdit ? userUpdateSchema : userCreateSchema),
    defaultValues: {
      name: '',
      email: '',
      phone: '',
      permission: '1',
      password: '',
    },
  });

  // Reset form when user changes or modal opens
  React.useEffect(() => {
    if (open) {
      form.reset({
        name: user?.name || '',
        email: user?.email || '',
        phone: user?.phone || '',
        permission: user?.permission?.toString() || '1',
        password: '',
      });
      setShowPassword(false);
    }
  }, [open, user, form]);

  const handleSubmit = async (values: any) => {
    // If editing, we need to pass the ID
    const payload = isEdit ? { ...values, id: user.ID } : values;

    // Clean empty password on update
    if (isEdit && !payload.password) {
      delete payload.password;
    }

    try {
      await onSubmit(payload);
      onOpenChange(false);
    } catch (err) {
      // Error is handled by mutation or caller
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {isEdit ? t('users.dialog.editTitle') : t('users.dialog.createTitle')}
          </DialogTitle>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-1 py-2">
            <FormField
              control={form.control}
              name="name"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('users.fields.name')} *</FormLabel>
                  <FormControl>
                    <Input {...field} placeholder="John Doe" />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="grid grid-cols-1 gap-x-4 sm:grid-cols-2">
              <FormField
                control={form.control}
                name="email"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('users.fields.email')} *</FormLabel>
                    <FormControl>
                      <Input {...field} type="email" placeholder="john@example.com" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="phone"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('users.fields.phone')}</FormLabel>
                    <FormControl>
                      <Input {...field} placeholder="+201..." />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="permission"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>{t('users.fields.permission')}</FormLabel>
                  <Select onValueChange={field.onChange} value={field.value}>
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="1">{t('users.permissions.user')}</SelectItem>
                      <SelectItem value="2">{t('users.permissions.manager')}</SelectItem>
                      <SelectItem value="3">{t('users.permissions.admin')}</SelectItem>
                      <SelectItem value="4">{t('users.permissions.superAdmin')}</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="password"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>
                    {t('users.fields.password')}{' '}
                    {isEdit && (
                      <span className="text-[10px] text-muted-foreground">
                        ({t('users.dialog.passwordOptional')})
                      </span>
                    )}
                  </FormLabel>
                  <FormControl>
                    <div className="relative">
                      <Input
                        {...field}
                        type={showPassword ? 'text' : 'password'}
                        autoComplete="new-password"
                      />
                      <Button
                        type="button"
                        variant="ghost"
                        size="icon"
                        className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? (
                          <EyeOff className="h-4 w-4 text-muted-foreground" />
                        ) : (
                          <Eye className="h-4 w-4 text-muted-foreground" />
                        )}
                      </Button>
                    </div>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <DialogFooter className="pt-6">
              <Button type="button" variant="ghost" onClick={() => onOpenChange(false)}>
                {t('common.cancel')}
              </Button>
              <Button type="submit" disabled={loading}>
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {isEdit ? t('common.save') : t('common.create')}
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

import * as React from 'react';
import { useTranslation } from 'react-i18next';
import {
  Calendar,
