  return (
    <div className="space-y-6">
      {/* Stats Summary */}
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard
          label={t('users.stats.total')}
          value={stats.total}
          icon={UsersIcon}
          tone="primary"
