      2: t('users.permissions.manager'),
      3: t('users.permissions.admin'),
      4: t('users.permissions.superAdmin'),
    }[permission] || t('common.unknown');

  const variant = (
    {
      1: 'secondary',
      2: 'outline',
      3: 'default',
      4: 'destructive',
    } as const
  )[permission] || 'outline';

  return <Badge variant={variant}>{label}</Badge>;
}

