import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { toast } from 'sonner';
import { Loader2, MessageCircle, QrCode, RefreshCw } from 'lucide-react';

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { Skeleton } from '@/shared/ui/skeleton';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import {
  useWhatsAppQrCode,
  useWhatsAppReconnect,
  useWhatsAppStatus,
} from '@/entities/whatsapp/queries';

export function WhatsAppGatewayCard() {
  const { t } = useTranslation();
  const [qrOpen, setQrOpen] = useState(false);

  const statusQuery = useWhatsAppStatus({ refetchInterval: qrOpen ? 5_000 : 30_000 });
  const reconnect = useWhatsAppReconnect();

  const status = statusQuery.data;
  const loggedIn = status?.is_logged_in ?? false;
  const connected = status?.is_connected ?? false;

  const qrQuery = useWhatsAppQrCode(qrOpen && !loggedIn);

  const [qrUrl, setQrUrl] = useState<string | null>(null);
  useEffect(() => {
    if (!qrQuery.data) {
      setQrUrl(null);
      return;
    }
    const url = URL.createObjectURL(qrQuery.data);
    setQrUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [qrQuery.data]);

  useEffect(() => {
    if (qrOpen && loggedIn) {
      setQrOpen(false);
      toast.success(t('settings.whatsappLinked', 'WhatsApp linked successfully'));
    }
  }, [qrOpen, loggedIn, t]);

  const badge = statusQuery.isLoading ? (
    <Skeleton className="h-5 w-24 rounded-full" />
  ) : statusQuery.isError || !status ? (
    <Badge variant="destructive">{t('settings.whatsappUnreachable', 'Unreachable')}</Badge>
  ) : connected && loggedIn ? (
    <Badge variant="success">{t('settings.whatsappConnected', 'Connected')}</Badge>
  ) : loggedIn ? (
    <Badge variant="warning">{t('settings.whatsappDisconnected', 'Disconnected')}</Badge>
  ) : (
    <Badge variant="destructive">{t('settings.whatsappLoggedOut', 'Logged out')}</Badge>
  );

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between gap-2">
          <CardTitle className="flex items-center gap-2">
            <MessageCircle className="h-4 w-4" />
            {t('settings.whatsappTitle', 'WhatsApp Gateway')}
          </CardTitle>
          {badge}
        </div>
        <CardDescription>
          {t(
            'settings.whatsappDescription',
            'Delivers PetroApp fuel alerts and Falcon notifications.',
          )}
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {status && loggedIn && (
          <p className="text-sm text-muted-foreground" dir="ltr">
            {status.jid}
          </p>
        )}
        <div className="flex flex-wrap gap-2">
          {status && !connected && (
            <Button
              variant="outline"
              onClick={() => reconnect.mutate()}
              disabled={reconnect.isPending}
            >
              {reconnect.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <RefreshCw className="mr-2 h-4 w-4" />
              )}
              {t('settings.whatsappReconnect', 'Reconnect')}
            </Button>
          )}
          {status && !loggedIn && (
            <Button onClick={() => setQrOpen(true)}>
              <QrCode className="mr-2 h-4 w-4" />
              {t('settings.whatsappShowQr', 'Show QR code')}
            </Button>
          )}
        </div>
      </CardContent>

      <Dialog open={qrOpen} onOpenChange={setQrOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{t('settings.whatsappQrTitle', 'Link WhatsApp')}</DialogTitle>
            <DialogDescription>
              {t(
                'settings.whatsappQrDescription',
                'Scan with your phone: WhatsApp → Settings → Linked devices → Link a device. The code refreshes automatically.',
              )}
            </DialogDescription>
          </DialogHeader>
          <div className="flex min-h-64 items-center justify-center p-2">
            {qrUrl ? (
              <img
                src={qrUrl}
                alt={t('settings.whatsappQrTitle', 'Link WhatsApp')}
                className="h-64 w-64 rounded-md bg-white p-2"
              />
            ) : qrQuery.isError ? (
              <p className="text-sm text-destructive">
                {t('settings.whatsappServiceError', 'Failed to reach the WhatsApp service')}
              </p>
            ) : (
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            )}
          </div>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

import * as React from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useTranslation } from 'react-i18next';
import { Loader2 } from 'lucide-react';
import {
  createZoneSchema,
  updateZoneSchema,
  type Zone,
  type CreateZonePayload,
  type UpdateZonePayload,
} from '@/entities/zone/schemas';
import { Button } from '@/shared/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/shared/ui/dialog';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/shared/ui/form';
import { Input } from '@/shared/ui/input';
import { Switch } from '@/shared/ui/switch';
import { ZoneMapPicker } from '../zone-map-picker';

interface ZoneFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  zone?: Zone | null;
  otherZones?: Zone[];
  onSubmit: (data: CreateZonePayload | UpdateZonePayload) => Promise<void>;
  loading?: boolean;
}

export function ZoneFormDialog({
  open,
  onOpenChange,
  zone,
  otherZones = [],
  onSubmit,
  loading,
}: ZoneFormDialogProps) {
  const { t } = useTranslation();
  const isEdit = !!zone;

  const form = useForm<CreateZonePayload>({
    resolver: zodResolver(isEdit ? updateZoneSchema : createZoneSchema),
    defaultValues: {
      name: '',
      lat: 0,
      lng: 0,
      radius_m: 100,
      active: true,
    },
  });

  React.useEffect(() => {
    if (open) {
      form.reset({
        name: zone?.name || '',
        lat: zone?.lat || 0,
        lng: zone?.lng || 0,
        radius_m: zone?.radius_m || 100,
        active: zone?.active ?? true,
      });
    }
  }, [open, zone, form]);

  const handleSubmit = async (values: CreateZonePayload) => {
    try {
      await onSubmit(values);
      onOpenChange(false);
    } catch {
      // Handled by parent
    }
  };

  const handleMapPositionChange = React.useCallback(
    (lat: number, lng: number) => {
      form.setValue('lat', Number(lat.toFixed(6)), { shouldValidate: true, shouldDirty: true });
      form.setValue('lng', Number(lng.toFixed(6)), { shouldValidate: true, shouldDirty: true });
    },
    [form]
  );

  const watchedLat = form.watch('lat');
  const watchedLng = form.watch('lng');
  const watchedRadius = form.watch('radius_m');

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {isEdit ? t('zones.dialog.editTitle', 'Edit Zone') : t('zones.dialog.createTitle', 'Create Zone')}
          </DialogTitle>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6 py-2">
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <FormField
                control={form.control}
                name="name"
                render={({ field }) => (
                  <FormItem className="sm:col-span-2">
                    <FormLabel>{t('zones.fields.name', 'Zone Name')} *</FormLabel>
                    <FormControl>
                      <Input {...field} placeholder={t('zones.fields.namePlaceholder', 'e.g. Headquarters')} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="lat"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('zones.fields.lat', 'Latitude')} *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        step="0.000001"
                        {...field}
                        onChange={(e) => field.onChange(e.target.value ? Number(e.target.value) : 0)}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="lng"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('zones.fields.lng', 'Longitude')} *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        step="0.000001"
                        {...field}
                        onChange={(e) => field.onChange(e.target.value ? Number(e.target.value) : 0)}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="radius_m"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{t('zones.fields.radius', 'Radius (meters)')} *</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        step="1"
                        min="1"
                        {...field}
                        onChange={(e) => field.onChange(e.target.value ? Number(e.target.value) : 0)}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="active"
                render={({ field }) => (
                  <FormItem className="flex flex-row items-center justify-between rounded-lg border p-3 shadow-sm sm:mt-6">
                    <div className="space-y-0.5">
                      <FormLabel>{t('zones.fields.active', 'Active')}</FormLabel>
                    </div>
                    <FormControl>
                      <Switch
                        checked={field.value}
                        onCheckedChange={field.onChange}
                      />
                    </FormControl>
                  </FormItem>
                )}
              />
            </div>

            <div className="space-y-2">
              <FormLabel>{t('zones.fields.mapPicker', 'Pick on Map')}</FormLabel>
              <div className="text-sm text-muted-foreground mb-2">
                {t('zones.fields.mapHelper', 'Click on the map or drag the marker to set the location.')}
              </div>
              <ZoneMapPicker
                lat={watchedLat || 0}
                lng={watchedLng || 0}
                radius_m={watchedRadius || 100}
                onPositionChange={handleMapPositionChange}
                otherZones={otherZones}
              />
            </div>

            <DialogFooter className="pt-4">
              <Button type="button" variant="ghost" onClick={() => onOpenChange(false)}>
                {t('common.cancel', 'Cancel')}
              </Button>
              <Button type="submit" disabled={loading}>
                {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {isEdit ? t('common.save', 'Save') : t('common.create', 'Create')}
              </Button>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

import * as React from 'react';
import { MapView } from '@/shared/ui/map-view';
import type { MapMarker, MapCircle } from '@/shared/lib/maps/types';
import type { Zone } from '@/entities/zone';

interface ZoneMapPickerProps {
  lat: number;
  lng: number;
  radius_m: number;
  onPositionChange: (lat: number, lng: number) => void;
  otherZones?: Zone[];
}

export function ZoneMapPicker({
  lat,
  lng,
  radius_m,
  onPositionChange,
  otherZones = [],
}: ZoneMapPickerProps) {
  const hasPosition = lat !== 0 || lng !== 0;

  const handleMapClick = React.useCallback(
    (newLat: number, newLng: number) => {
      onPositionChange(newLat, newLng);
    },
    [onPositionChange]
  );

  const handleMarkerDragEnd = React.useCallback(
    (id: string, newLat: number, newLng: number) => {
      if (id === 'active-zone') {
        onPositionChange(newLat, newLng);
      }
    },
    [onPositionChange]
  );

  const markers: MapMarker[] = React.useMemo(() => {
    if (!hasPosition) return [];
    return [
      {
        id: 'active-zone',
        lat,
        lng,
        color: '#dc2626', // Red pin for active
        draggable: true,
        affectsBounds: true,
      },
    ];
  }, [lat, lng, hasPosition]);

  const circles: MapCircle[] = React.useMemo(() => {
    const list: MapCircle[] = [];

    // Other zones (faint)
    otherZones.forEach((z) => {
      list.push({
        id: `other-${z.id}`,
        lat: z.lat,
        lng: z.lng,
        radius_m: z.radius_m,
        color: '#9ca3af', // Gray
        fillOpacity: 0.1,
      });
    });

    // Active zone (if set)
    if (hasPosition) {
      list.push({
        id: 'active-zone-circle',
        lat,
        lng,
        radius_m,
        color: '#dc2626',
        fillOpacity: 0.2,
      });
    }

    return list;
  }, [lat, lng, radius_m, hasPosition, otherZones]);

  return (
    <div className="h-[400px] w-full rounded-md border overflow-hidden">
      <MapView
        markers={markers}
        circles={circles}
        onMapClick={handleMapClick}
        onMarkerDragEnd={handleMarkerDragEnd}
        centerFallback={hasPosition ? [lat, lng] : [30.0444, 31.2357]}
        liveUpdates={true}
      />
    </div>
  );
}

